window.__D("text/zohar-hebrew-translation/c038",{"p":[[9522012697,"<p>וַיֹּאמֶר אֱלֹהִים הִנֵּה נָתַתִּי לָכֶם אֶת כָּל עֵשֶׂב זרֵעַ זֶרַע - כְּנֶגֶד הַדַּרְגָּה שֶׁל בִּינָה שֶׁנִּקְרֵאת אֱלֹהִים. שֶׁכֵּיוָן שֶׁהָאֵם הָעֶלְיוֹנָה רָאֲתָה אוֹתָם שְׁלֵמִים, נָתְנָה לָהֶם תַּפְנוּקִים מִלְמַעְלָה לְהִתְקַיֵּם בָּעוֹלָם.</p>\n<p>בֹּא רְאֵה, לְאָדָם הָרִאשׁוֹן נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא כָּל עֵשֶׂב זֹרֵעַ זֶרַע, וְלֹא נָתַן לוֹ רְשׁוּת לֶאֱכֹל בְּהֵמוֹת וְעוֹפוֹת הַשָּׁמַיִם, מִשּׁוּם שֶׁגָּלוּי לְפָנָיו שֶׁהָיָה עָתִיד לְהִתְפַּתּוֹת בְּאוֹתוֹ נָחָשׁ שֶׁהוּא (בראשית ג) עָרוּם מִכֹּל חַיַּת הַשָּׂדֶה. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אַרְחִיק אוֹתוֹ מִמֶּנּוּ, וְלֹא יִהְיֶה לוֹ עֵסֶק עִמּוֹ וְלֹא עִם הַבְּהֵמוֹת וְלֹא עִם הָעוֹפוֹת, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הֵרִים לָאָדָם מִכְשׁוֹל מִלְּפָנָיו אוּלַי יִתְקַיֵּם בָּעוֹלָם.</p>\n<p>אֲבָל כְּשֶׁבָּא נֹחַ, שֶׁנִּקְרָא צַדִּיק, מַה כָּתוּב בּוֹ? (בראשית ח) וַיִּבֶן נֹחַ מִזְבֵּחַ לַה'. הֲרֵי פֵּרַשְׁנוּ אוֹתוֹ הַמִּזְבֵּחַ שֶׁבּוֹ הִקְרִיב אָדָם הָרִאשׁוֹן. וּמָה הַטַּעַם וַיִּבֶן? מִשּׁוּם שֶׁרִשְׁעֵי הָעוֹלָם עָשׂוּ בָהּ פְּגָם, בָּא נֹחַ וְהִקְרִיב אוֹתוֹ מִזְבֵּחַ לְבַעְלָהּ. זֶהוּ שֶׁכָּתוּב וַיַּעַל עֹלֹת בַּמִּזְבֵּחַ, חָסֵר.</p>\n<p>כְּשֶׁרָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנִּקְרַב אוֹתוֹ מִזְבֵּחַ וְהִקְרִיב אוֹתָם בְּהֵמוֹת טְהוֹרוֹת, נָתַן לוֹ רְשׁוּת לֶאֱכֹל כָּל הַבְּהֵמוֹת, מָה הַטַּעַם? מִשּׁוּם שֶׁהוּא הֶחֱזִיק בְּאוֹתוֹ בְּרִית עֵץ הַחַיִּים וְקֵרַב אוֹתוֹ לְעֵץ הַדַּעַת, וְעָשָׂה יִחוּד כְּבָרִאשׁוֹנָה, אֶלָּא שֶׁאַחַר כָּךְ הִתְפַּתָּה שֶׁרָצָה לִבְדֹּק אֶת אוֹתוֹ הַחֵטְא וְלֹא לִדְבֹּק בּוֹ, אֲפִלּוּ כָּךְ לֹא נִצַּל מִמֶּנּוּ וְהִצִּיב אוֹתוֹ כֶּרֶם. ס</p>\n<p>תָּא חֲזֵי, אָדָם דְּזַמִּין לְאִתְפַּתָאַה בְּאִילָנֵי לָא יָהַב לֵיהּ אִילָנֵי וְאַרְחֶקִינְהוּ מִנֵּיהּ דְּהָא לָא אִדְכָּר לוֹן אֶלָּא דְּאִיהוּ עָבַד גַּרְמֵיהּ חוֹל וְנָצִיב הַהוּא כַּרְמָא דְּאִקְרֵי בֵּית יִשְׂרָאֵל. בְּקַדְמִיתָא אִשְׁתְּלִים בֵּיהּ וְחַפְיָא עָלֵיהּ (ואשתזיב) אִשְׁתֵּזִיב בָּהּ. וּמַאן אִיהִי בֵּית יִשְׂרָאֵל דָא תֵּיבָה דְּאִקְרֵי אֲרוֹן הַבְּרִית.</p>\n<p>וְהַשְׁתָּא כַּד בָּעָא לְמִבְדַּק, מָה כְּתִיב (בראשית ט) וַיֵּשְׁתְ מִן הַיָּיִן, כְּמָה דְאַתְּ אָמֵר, וַתִּקַּח מִפִּרְיוֹ. לְבָתָר וַיִתְגָּל בְּתוֹךְ אֲהֹלֹה. גָלֵי הַהוּא פִּרְצָה בְּקַדְמִיתָא בְּגוֹ מַשְׁכְּנֵיהּ בְּגוֹ לְגוֹ. וְאִי לָאו הַהוּא מַדְבְּחָא דְאַגִינָת עָלֵיהּ מִשׁוּם דְאִתְדַבָּק בָּהּ בְּקַדְמִיתָא הֲוָה נִתְפָּס מִיָד. וְעִם כָּל דָּא כַּד לָא עֲבַד לֵיהּ אֶלָּא לְמִבְדַּק, כָּסֵי עָלֵיהּ אוֹרַיְיתָא וְלָא פַרְסְמֵיה כְּמָה דְפִרְסֵם לְאָדָם. וְהַהוּא מַדְבְּחָא הוּא כַּפָּרָה עָלֵיהּ.</p>\n<p>בֹּא רְאֵה, מִזְבֵּחַ שֶׁל בֵּית עוֹלָמִים הָיָה שְׁלֹשִׁים וּשְׁתַּיִם עַל שְׁלֹשִׁים וּשְׁתַּיִם אַמָּה, וְהִיא רְמוּזָה בִּשְׁלֹשִׁים וּשְׁנַיִם נְתִיבוֹת פְּלִיאוֹת חָכְמָה, שֶׁהֲרֵי חָכְמָה תַחְתּוֹנָה נִקְרֵאת. עָלָה אַמָּה נִכְנַס אַמָּה - זֶהוּ יְסוֹד, כְּנֶגֶד (צדיק) צֶדֶק שֶׁלְּמַעְלָה, שֶׁהֲרֵי כְּמוֹ שֶׁיֵּשׁ בָּהּ אֶת כָּל הַדְּרָגוֹת וְכֻלָּם נִרְאִים בָּהּ, שֶׁהֲרֵי נִקְרֵאת מַרְאָה.</p>\n<p>עָלָה חָמֵשׁ וְכָנַס אַמָּה - זֶהוּ סוֹבֵב, כְּנֶגֶד אוֹתָהּ דַּרְגָּה שֶׁנִּדְבָּק בָּהּ, שֶׁהִיא סוֹבֶבֶת אֶת אוֹתוֹ הַמִּזְבֵּחַ. זֶהוּ שֶׁכָּתוּב (שיר ב) וִימִינוֹ תְּחַבְּקֵנִי, שֶׁהֲרֵי מִיסוֹד עַד אוֹתָהּ דַּרְגָּה חָמֵשׁ דְּרָגוֹת הֵן.</p>\n<p>עָלָה שָׁלֹשׁ וְכָנַס אַמָּה - אֵלּוּ קְרָנוֹת, כְּנֶגֶד אוֹתָן שָׁלֹשׁ דְּרָגוֹת שֶׁרָאוּ לָהּ מֵהֶם הַתֹּקֶף הָעֶלְיוֹן וְשֶׁפַע, וּמִשּׁוּם כָּךְ דָּוִד שֶׁנִּמְשַׁח בְּקֶרֶן, נִמְשְׁכָה מַלְכוּתוֹ, מִשּׁוּם שֶׁהוּא בְּאוֹתָן קַרְנוֹת הַמִּזְבֵּחַ, תֹּקֶף הַמִּזְבֵּחַ הָעֶלְיוֹן.</p>\n<p>בֹּא רְאֵה, אַרְבַּע קְרָנוֹת אַמָּה עַל אַמָּה יֵשׁ בַּמִּזְבֵּחַ, מִשּׁוּם שֶׁהִיא כִּסֵּא דָוִד, יוֹם הָרְבִיעִי לָתֵת לָהּ שֶׁפַע מֵאוֹתָן שָׁלֹשׁ אַמּוֹת לְאוֹתָן אַרְבַּע קְרָנוֹת.</p>\n<p>וּכְשֶׁהָיוּ מַקְרִיבִים הַכֹּהֲנִים מֵהַצַּד שֶׁל חֶסֶד עוֹלַת הַתָּמִיד אֵצֶל הַמִּזְבֵּחַ, הָיוּ מַקְרִיבִים אוֹתוֹ לְאוֹתוֹ הַמָּקוֹם שֶׁנִּקְרָא מִזְבֵּחַ (מלכות). וּכְשֶׁהָיוּ עוֹשִׂים מַתָּנוֹת מִדַּם הָעוֹלָה, הָיוּ עוֹלִים וְהָיוּ הוֹלְכִים בְּאוֹתוֹ הַסּוֹבֵב שֶׁהוּא הַדַּרְגָּה שֶׁלָּהֶם וְחֵלֶק אֲבִיהֶם, וְנוֹתְנִים שְׁתֵּי מַתָּנוֹת שֶׁהֵן אַרְבַּע כְּנֶגֶד אוֹתוֹ מָקוֹם שֶׁנִּקְרָא עוֹלָה.</p>\n<p>וּכְנֶגֶד שְׁתֵּי מַתָּנוֹת שֶׁל אוֹתוֹ בְּכוֹר שֶׁנּוֹטֵל שְׁנֵי חֲלָקִים. זֶהוּ שֶׁכָּתוּב (בראשית כה) וְיַעֲקֹב אִישׁ תָּם יֹשֵׁב אֹהָלִים, רַחֲמִים וְדִין, וְלָקַח אוֹתוֹ צַדִּיק שְׁנֵי חֲלָקִים שֶׁלּוֹ. זֶהוּ שֶׁכָּתוּב (דברי הימים א ה) נִתְּנָה בְּכֹרָתוֹ לִבְנֵי יוֹסֵף, וּשְׁנֵי חֲלָקִים שֶׁל אָבִיו, וְלָקְחָה הַכֹּל כֹּל הַזֹּאת, וּמְמַלֵּא אוֹתוֹ מָקוֹם שֶׁנִּקְרָא יָם. זֶהוּ שֶׁכָּתוּב (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם. זֶה מִזְבַּח הָעוֹלָה הָיָה אֶצְלוֹ.</p>\n<p>תֵּשַׁע אַמּוֹת הַלָּלוּ כְּנֶגֶד תֵּשַׁע דְּרָגוֹת שֶׁיֵּשׁ עַד הַצַּדִּיק הַתְּשִׁיעִי שֶׁל הַכֹּל, טוֹב וַדַּאי, וְהִיא כְּבִנְיַן אוֹצָר, רְחָבָה מִלְּמַטָּה וּקְצָרָה מִלְמַעְלָה. זֶהוּ שֶׁכָּתוּב (בראשית ב) וַיִּבֶן ה' אֱלֹהִים אֶת הַצֵּלָע אֲשֶׁר לָקַח מִן הָאָדָם לְאִשָּׁה. וְהַמִּזְבֵּחַ הָעֶלְיוֹן הַזֶּה הוּא אִשְׁתּוֹ שֶׁל אָדָם שֶׁלְּמַעְלָה, וְלָכֵן נִקְרָא מִזְבַּח הָעוֹלָה, כְּמוֹ שֶׁנֶּאֱמַר (יהושע ג) אֲרוֹן הַבְּרִית, וְזוֹ כְּנֶסֶת יִשְׂרָאֵל, וְנִקְרֵאת מִזְבֵּחַ.</p>\n<p>מָה הַטַּעַם נִקְרֵאת כָּךְ? מִשּׁוּם שֶׁכַּאֲשֶׁר בְּנֵי הָעוֹלָם אֵין מַעֲשֵׂיהֶם כְּשֵׁרִים, הִיא זוֹבַחַת אוֹתָם. זֶהוּ שֶׁכָּתוּב (ויקרא כו) וְהִכֵּיתִי אֶתְכֶם אַף (גם) אֲנִי, שֶׁהֲרֵי כָּל כְּלֵי הַקְּרָב שֶׁל הַמֶּלֶךְ נִמְסְרוּ בְיָדָהּ. זֶהוּ שֶׁכָּתוּב (שיר א) הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה שִׁשִּׁים גִּבֹּרִים סָבִיב לָהּ. וְלָכֵן הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לְיִשְׂרָאֵל תּוֹרָה שְׁלֵמָה לִזְכּוֹת בָּהּ לְחַיֵּי עוֹלָם וּלְהִנָּצֵל מִדִּין אוֹתוֹ הַמִּזְבֵּחַ, מַה שֶּׁאֵין רְשׁוּת לְאִישׁ אַחֵר לִקְרַב אֵלֶיהָ.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי רָאִינוּ שֶׁמֹּשֶׁה קָרַב אֵלֶיהָ שִׁבְעָה יָמִים בַּהַתְחָלָה - בּא רְאֵה, כָּתוּב (שיר ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. הַפָּסוּק הַזֶּה נֶאֱמַר עַל כְּנֶסֶת יִשְׂרָאֵל, כְּשֶׁהִיא שׁוֹרָה בָּאָרֶץ הַקְּדוֹשָׁה בְּכָל אוֹתָם שִׁבְעָה יָמִים כֻּלָּם בִּשְׁלֵמוּת. זֶהוּ שֶׁכָּתוּב (ויקרא ח) שִׁבְעַת יָמִים יְמַלֵּא אֶת יֶדְכֶם, וְלָכֵן נִקְרָאִים שִׁבְעַת יְמֵי הַמִּלּוּאִים דַּוְקָא.</p>\n<p>וּמֹשֶׁה שֶׁהוּא לֵוִי, מִצַּד זֶה הוּא קָרַב בַּתְּחִלָּה לַמִּזְבֵּחַ הַזֶּה. זֶהוּ שֶׁכָּתוּב שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי. מַה זֶּה רֹאשִׁי? אֶלָּא בָּרֹאשׁ, כְּשֶׁנִּדְבֶּקֶת מִזְבֵּחַ הַזּוֹ בְּאוֹתָהּ עוֹלָה, שְׂמֹאלוֹ הִיא נִקְרֵאת בַּתְּחִלָּה. וְעִם כָּל זֶה הֵעִירוּ הַחֲבֵרִים, בְּחָלוּק לָבָן שֶׁאֵין בּוֹ אִמְרָא שִׁמֵּשׁ, זֶהוּ שֶׁכָּתוּב (בראשית ל) מַחְשּׁף הַלָּבָן אֲשֶׁר עַל הַמַּקְלוֹת. מִשּׁוּם שֶׁאַף עַל גַּב שֶׁהוּא מִצַּד הַדִּין, הִתְלַבֵּשׁ בְּחֶסֶד וְקָרַב אֵלֶיהָ, וְהֵעִיר חֶסֶד עֶלְיוֹן בָּעוֹלָם.</p>\n<p>וּמַה הִקְרִיב? פַּר בְּרֹאשׁ תָּמִיד שֶׁל שַׁחַר עוֹלָה וַדַּאי, וְאַחַר כָּךְ הִקְרִיב פַּר חַטָּאת, לָתֵת שָׁלוֹם בֵּין אוֹתוֹ פַּר חַטָּאת וְאַהֲרֹן שֶׁחָטָא לָהּ כְּשֶׁעָשָׂה עֵגֶל, וְזוֹ כְּנֶסֶת יִשְׂרָאֵל, וְהַחַטָּאת הִיא כְּנֶגְדָּהּ. וְזֶה פַּר כֹּהֵן מָשִׁיחַ כְּשֶׁהוּא חָטָא אֶל הַמִּזְבֵּחַ, מַה שֶּׁאֵין בְּאִישׁ אַחֵר, אֶלָּא נְקֵבָה לְחַטָּאת, וְאַחַר כָּךְ מַקְרִיב עוֹלָה אֵלֶיהָ. כֵּיוָן שֶׁהֻקְרְבָה עוֹלָה לַמִּזְבֵּחַ הַזֶּה, אָז מִלּוּאִים הִיא. מִלּוּאִים לְמַעְלָה מִלּוּאִים לְמַטָּה. וְכָל הָעוֹלָמוֹת בְּשִׂמְחָה, שֶׁהֲרֵי הַגְּבִירָה הִתְחַבְּרָה עִם בַּעְלָהּ, וְאָז מַקְרִיב לְאוֹתוֹ מִזְבֵּחַ אֶת אֵיל הַמִּלֻּאִים. וְנוֹתֵן מֵאוֹתוֹ דָם עַל תְּנוּךְ אֹזֶן אַהֲרֹן כְּדֵי שֶׁתִּהְיֶה רַכָּה לִשְׁמֹעַ בְּרַכּוּת, וְלֹא בְקֹשִׁי. וִיקַבֵּל דִּבְרֵי תוֹרָה, שֶׁלֹּא לְהַפְרִיד בֵּין תּוֹרָה שֶׁבְּעַל פֶּה מִתּוֹרָה שֶׁבִּכְתָב, וּלְהַשְׁלִים כָּל הָעוֹלָמוֹת, וְכֵן לְבָנָיו.</p>\n<p>וְצִוָּה אוֹתָם שֶׁיֵּשְׁבוּ בְּאוֹתוֹ הַשַּׁעַר שֶׁל אוֹתוֹ הָאֹהֶל, לִשְׁמֹר אוֹתוֹ מָקוֹם שֶׁלֹּא יִקְרַב עָרֵל וְטָמֵא, וְיִשְׁתַּלְּמוּ כָּל שִׁבְעַת הַיָּמִים הָעֶלְיוֹנִים, וְיַעֲלוּ בְּאוֹתָהּ דַּרְגַּת הַחֶסֶד שֶׁהִיא שְׁבִיעִי מִמַּטָּה לְמַעְלָה, שֶׁהֲרֵי הֵם בַּתְּחִלָּה נִדְבְּקוּ בְּאוֹתוֹ פֶּתַח אֹהֶל מוֹעֵד, וְאַחַר כָּךְ הִתְעַלּוּ לְמַעְלָה.</p>\n<p>וְאַחַר כָּךְ מַה כָּתוּב? וִימִינוֹ תְּחַבְּקֵנִי. זֶהוּ שֶׁכָּתוּב (ויקרא ט) וַיְהִי בַּיּוֹם הַשְּׁמִינִי קָרָא מֹשֶׁה לְאַהֲרֹן, וְצִוָּה אוֹתוֹ לָקַחַת אוֹתוֹ עֵגֶל שֶׁחָטָא בּוֹ וְיַקְרִיבוֹ לְאוֹתוֹ מִזְבֵּחַ, וְהוּא הָיָה מִתְבַּיֵּשׁ לְהַקְרִיב אֵלֶיהָ, שֶׁפָּחַד מִשַּׁלְהֲבוֹתֶיהָ. אָמַר לוֹ מֹשֶׁה (שם), קְרַב אֶל הַמִּזְבֵּחַ וַעֲשֵׂה אֶת חַטָּאתְךְ - בַּתְּחִלָּה, וְתֵן מֵאוֹתוֹ דָם עַל אוֹתָם קְרָנוֹת, מִשּׁוּם שֶׁחָטָא בַּתְּחִלָּה אֶצְלָם וּמָנַע מֵהֶם בְּרָכוֹת, וְאַחַר כָּךְ (שם) וְאֶת הַדָּם יָצַק אֶל יְסוֹד הַמִּזְבֵּחַ, לָצֶקֶת בָּהּ אוֹתוֹ יְסוֹד. מַה זֶּה יָצַק? כְּמוֹ שֶׁנֶּאֱמַר (מלכים א ז) וַיַּעַשׂ אֶת הַיָּם מוּצָק.</p>\n<p>וְאַחַר כָּךְ הִקְרִיב לְאוֹתוֹ מִזְבֵּחַ אוֹתָהּ עוֹלָה, וְעָשָׂה בַּתְּחִלָּה רֹאשׁ, וְאַחַר כָּךְ רֶגֶל, וְאַחַר הִקְרִיב עַל יִשְׂרָאֵל שְׂעִיר עִזִּים, שֶׁהֲרֵי מֵאוֹתוֹ הַצַּד שֶׁל צַד הָרָע נִדְבְּקוּ בָּעֲבוֹדָה זָרָה.</p>\n<p>וְאַחַר כָּךְ עֵגֶל וְכֶבֶשׁ לְעוֹלָה. בֹּא רְאֵה, בַּהַתְחָלָה עֵגֶל לְחַטָּאת. כֵּיוָן שֶׁהִקְרִיב אוֹתוֹ בִּשְׁלֵמוּת אֶל אִמּוֹ, אַחַר כָּךְ הִקְרִיב אוֹתוֹ לְאָבִיו. זֶהוּ שֶׁכָּתוּב לְעֹלָה. אַחַר כָּךְ, שׁוֹר וָאַיִל לִשְׁלָמִים, שֶׁהִנֵּה שָׁלוֹם בְּכָל הָעוֹלָמוֹת. וְשׁוֹר זֶה שֶׁל צַד הַשְּׂמֹאל. וְאֵילוֹ שֶׁל יִצְחק לֹא עוֹשִׂים דִּין אֶלָּא לִשְׁלָמִים, שָׁלוֹם לְמַעְלָה שָׁלוֹם לְמַטָּה,</p>\n<p>אָז הַקָּדוֹשׁ בָּרוּךְ הוּא פָּתַח עֲלֵיהֶם, (תהלים קלג) הִנֵּה מַה טּוֹב וּמַה נָּעִים שֶׁבֶת אַחִים גַּם יָחַד. שֶׁבֶת אַחִים - יָמִין וּשְׂמֹאל, מֹשֶׁה וְאַהֲרֹן. גַּם - לְהַכְלִיל אֶת כְּנֶסֶת יִשְׂרָאֵל. יָחַד - צַדִּיק, הַכֹּל בְּיִחוּד שָׁלֵם (משלם). וְאָז מַה כָּתוּב? כַּשֶּׁמֶן הַטּוֹב עַל הָרֹאשׁ יֹרֵד עַל הַזָּקָן. כֵּיוָן שֶׁהִתְחַבְּרוּ זָכָר וּנְקֵבָה שָׁלֵם, מִשּׁוּם כָּךְ כַּשֶּׁמֶן הַטּוֹב עַל הָרֹאשׁ, בַּהַתְחָלָה הָעַתִּיק שֶׁל הַכֹּל, רֹאשׁ כָּל הָרָאשִׁים. יֹרֵד עַל הַזָּקָן - זֶה חֶסֶד וּגְבוּרָה וְתִפְאֶרֶת, שֶׁכֻּלָּם נִקְרְאוּ זָקֵן. (בראשית כד) וְאַבְרָהָם זָקֵן. (שם כז) וַיְהִי כִּי זָקֵן יִצְחָק (גבורה). (שם מח) וְעֵינֵי יִשְׂרָאֵל (תפארת) כָּבְדוּ מִזֹּקֶן. עַל פִּי מִדּוֹתָיו - זֶה צַדִּיק, וְהוּא פִּי מִדּוֹתָיו.</p>\n<p>וְאַחַר כָּךְ, כְּטַל חֶרְמוֹן שֶׁיֹּרֵד עַל הַרְרֵי צִיּוֹן - אֵלּוּ שִׁבְעָה הָרִים שֶׁנִּקְרְאוּ הַרְרֵי צִיּוֹן. כִּי שָׁם צִוָּה ה' אֶת הַבְּרָכָה - כֵּיוָן שֶׁהִתְחַבְּרוּ. חַיִּים עַד הָעוֹלָם - זֶה עֵץ הַחַיִּים בְּאוֹתוֹ עוֹלָם. וְכָל זֶה מִשּׁוּם אוֹתָם קָרְבָּנוֹת שֶׁמְּעוֹרְרִים טוֹב לְמַעְלָה וּלְמַטָּה.</p>\n<p>וְאַחַר כָּךְ הַכֹּהֲנִים שֶׁמִּצַּד הַחֶסֶ\"ד קְרֵבִים לְאוֹתוֹ מִזְבֵּחַ, מַה שֶּׁאֵין רְשׁוּת לְאִישׁ אַחֵר לִקְרַב, וְנִשְׁחָטִים שְׁחִיטַת הַקְּדָשִׁים בִּצְפוֹן הַמִּזְבֵּחַ, מִשּׁוּם שֶׁבְּצַד צָפוֹן שֶׁיֵּשׁ בָּהּ כְּשֶׁקְּרֵבָה גְבוּרָה אֵלֶיהָ, עוֹשָׂה אֶת אוֹתָן נְקָמוֹת, מִשּׁוּם כָּךְ עוֹשִׂים הַכֹּהֲנִים שָׁלוֹם בָּעוֹלָם, שֶׁלֹּא יִשָּׂרֵף הָעוֹלָם בְּשַׁלְהֲבוֹת הַמִּזְבֵּחַ, וְאָז יוֹרְדִים חַיִּים לָעוֹלָם. זֶהוּ שֶׁכָּתוּב (מלאכי ב) בְּרִיתִי הָיְתָה אִתּוֹ הַחַיִּים וְהַשָּׁלוֹם. מָה הַטַּעַם חַיִּים? מִשּׁוּם שֶׁהוּא עוֹשֶׂה שָׁלוֹם.</p>\n<p>וְכֹהֲנִים עוֹשִׂים שָׁלוֹם בַּקָרְבָּן. מַהוּ הַקָרְבָּן? לָבָן וֶאָדם, חֵלֶב וְדָם. חֵלֶב כְּנֶגֶד אוֹתָהּ דַּרְגָּה שֶׁל יֹפִי שֶׁל הַכֹּל. חֵלֶב הָאָרֶץ תַּרְגּוּמוֹ יְפִי הָאָרֶץ. וְדָם כְּנֶגֶד אוֹתָהּ הַדַּרְגָּה שֶׁנִּקְרֵאת נֶפֶשׁ, שֶׁכָּתוּב (ירמיה נא) נִשְׁבַּע ה' צְבָאוֹת בְּנַפְשׁוֹ ((עמוס ו) נשבע ה' בנפשו). וּבֶן אָדָם, כְּשֶׁמַּקְרִיב דָּם זֶה, כְּאִלּוּ מַקְרִיב נַפְשׁוֹ. זֶהוּ שֶׁכָּתוּב (ויקרא יז) כִּי הַדָּם הוּא בַּנֶּפֶשׁ יְכַפֵּר.</p>\n<p>וּמִשּׁוּם כָּךְ הִזְהִירָה אוֹתָם הַתּוֹרָה, מִי שֶׁיֹּאכַל מֵאוֹתוֹ חֵלֶב וְדָם שֶׁמִּמֶּנּוּ מַקְרִיבִים לַמִּזְבֵּחַ, יִכְלֶה מֵהַמִּזְבֵּחַ הַהוּא. זֶהוּ שֶׁכָּתוּב וְנִכְרְתָה הַנֶּפֶשׁ הַהִיא מֵעַמֶּיהָ. מָה הַטַּעַם? מִשּׁוּם שֶׁהָיָה לוֹ לְהַקְרִיב אֶת אוֹתוֹ חֵלֶב עַל הַמִּזְבֵּחַ, וְאוֹתוֹ דָם בַּיְסוֹד, לְהַכְלִיל מִדַּת יוֹם בְּלַיְלָה וּמִדַּת לַיְלָה בְּיוֹם. וּבְעוֹלַת הַתָּמִיד שֶׁהִיא כְּלָלוּת שֶׁל הַכֹּל, לְכַפֵּר עַל כָּל יִשְׂרָאֵל עַל עֲשֵׂה וְעַל לֹא תַעֲשֶׂה הַנִּתָּק לַעֲשֵׂה. מָה הַטַּעַם? מִשּׁוּם שֶׁהָאֳנִיָּה (מקום) הַזּוֹ דַּרְגָּה שֶׁל עוֹלָה עֲשֵׂה הִיא, וְעוֹשִׂים לָהּ מַתָּנוֹת לְהַכְלִיל לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא כֹּל וּלְיִשְׂרָאֵל.</p>\n<p>וּלְאֵיזְהִ מָקוֹם נוֹתְנִים אוֹתָן מַתָּנוֹת? אַחַת בְּקֶרֶן מִזְרָחִית צְפוֹנִית לְעוֹרֵר הַמִּזְרָח, שֶׁהוּא רַחֲמִים. וּלְעוֹרֵר הַצָּפוֹן בְּשִׂמְחָה אֵלָיו שֶׁל הַמִּזְבֵּחַ הַהוּא, וְאַחַר כָּךְ בְּקֶרֶן מַעֲרָבִית דְּרוֹמִית, לְהַכְלִיל אוֹתוֹ מִזְבֵּחַ שֶׁנִּקְרָא מַעֲרָב בְּדָרוֹם שֶׁהוּא חֶסֶד, וְלָכֵן הַכֹּל מַתָּנָה אַחַת. זֶהוּ שֶׁכָּתוּב (שיר ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. שְׂמֹאלוֹ - שֶׁל מִזְרָח שֶׁהוּא צָפוֹן. תַּחַת לְרֹאשִׁי - בַּתְּחִלָּה. וְאַחַר כָּךְ וִימִינוֹ תְּחַבְּקֵנִי - שֶׁהוּא חֶסֶד.</p>\n<p>דָּבָר אַחֵר, מָה הַטַּעַם שֶׁלֹּא נוֹתְנִים מַתָּנָה בְּקֶרֶן דְּרוֹמִית מִזְרָחִית, צְפוֹנִית מַעֲרָבִית? שֶׁהֲרֵי אוֹתָהּ קֶרֶן דְּרוֹמִית מִזְרָחִית הִיא בַּתְּחִלָּה, כְּשֶׁעוֹלִים הַכֹּהֲנִים בְּאוֹתוֹ כֶבֶשׁ, שֶׁבַּדָּרוֹם הַצַּד וְהַחֵלֶק שֶׁלָּהֶם שֶׁהוּא חֶסֶד. וְאוֹמְרִים, כָּל פִּנּוֹת שֶׁאַתָּה פּוֹנֶה, אֵינוֹ אֶלָּא דֶּרֶךְ יָמִין לַמִּזְבֵּחַ, כְּדֵי לְחַבֵּר צַד הַמִּזְרָח לְאוֹתוֹ מִזְבֵּחַ, וְהָיָה לוֹ לַכֹּהֵן לָתֵת מַתָּנָה בַּתְּחִלָּה בְּאוֹתָהּ קֶרֶן דְּרוֹמִית מִזְרָחִית, שֶׁהֲרֵי הוּא רִאשׁוֹן לְאוֹתָן דְּרָגוֹת, וְלֹא עוֹד, אֶלָּא שֶׁהִתְעוֹרֵר אֵלֶיהָ חֶסֶד בַּתְּחִלָּה. הֲרֵי הֵעִירוּ הַחֲבֵרִים וְאָמְרוּ, מִשּׁוּם שֶׁכָּתוּב (ויקרא ד) אֶל יְסוֹד מִזְבַּח הָעֹלָה - מִן יְסוֹד לְמִזְבְּחָהּ שֶׁל עוֹלָם (ס\"א עלה). כְּלוֹמַר, קָרֵב יְסוֹד שֶׁהוּא צַדִּיק אֶצְלָהּ. וְקֶרֶן דְּרוֹמִית מִזְרָחִית לֹא הָיָה לָהּ יְסוֹד.</p>\n<p>בֹּא רְאֵה, כָּתוּב בִּיהוּדָה (בראשית לז) לְכוּ וְנִמְכְּרֶנּוּ לַיִּשְׁמְעֵאלִים. וּבִגְלַל שֶׁהוּא חָטָא אֶל אוֹתוֹ הַיְסוֹד וְהִפְרִידוֹ מֵאוֹתָהּ אֶרֶץ עֶלְיוֹנָה וְנָתַן עֵצָה לִמְכֹּר אוֹתוֹ, מִשּׁוּם כָּךְ בְּאוֹתוֹ חֵלֶק שֶׁלּוֹ לֹא הָיָה לוֹ יְסוֹד.</p>\n<p>וְכָךְ שָׁנִינוּ, מֶה הָיָה חֶלְקוֹ שֶׁל יְהוּדָה? הַר הַבַּיִת וּלְשָׁכוֹת וַעֲזָרוֹת. וּמֶה הָיָה בְּחֶלְקוֹ שֶׁל בִּנְיָמִין, שֶׁהוּא צַדִּיק לְמַטָּה? אוּלָם וְהֵיכָל וּבֵית קֹדֶשׁ הַקְּדָשִׁים. וּרְצוּעָה יוֹצֵאת מֵחֶלְקוֹ שֶׁל יְהוּדָה שֶׁהִיא כְּלַפֵּי מִזְרָח, שֶׁהֲרֵי גַּם דִּגְלוֹ הָיָה מִמִּזְרָח, וְנִכְנְסָה לְחֶלְקוֹ שֶׁל בִּנְיָמִין, וְעָלֶיהָ נִבְנָה הַמִּזְבֵּחַ, שֶׁהֲרֵי הַמִּזְבֵּחַ חֶלְקוֹ שֶׁל יְהוּדָה הָיָה, כְּפִי שֶׁבֵּאַרְנוּ (בראשית כט) וַתַּעֲמֹד מִלֶּדֶת, שֶׁעָמַד הַכִּסֵּא עַל עַמּוּדָיו, וְהוּא תּוֹמֵךְ הָרְבִיעִי (מלכות), כְּנֶגֶד כְּנֶסֶת יִשְׂרָאֵל שֶׁהִיא רְבִיעִית, וְכָתוּב בָּהּ (תהלים קיח) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה. וְדָוִד, בְּנוֹ אָחַז בְּאוֹתוֹ מִזְבֵּחַ, כְּמוֹ שֶׁבֵּאַרְנוּ בְּסוֹד הָאֱמוּנָה,</p>\n<p>וּבִנְיָמִין הַצַּדִּיק מִצְטַעֵר עָלָיו לְקָרֵב אוֹתָהּ אֵלָיו. זֶהוּ שֶׁכָּתוּב (דברים לג) חוֹפֵף עָלָיו כָּל הַיּוֹם. מִשּׁוּם כָּךְ זָכָה בִּנְיָמִין הַצַּדִּיק לְמַטָּה, וְנַעֲשָׂה מְאָרֵחַ לַגְּבוּרָה, זֶהוּ שֶׁכָּתוּב וּבֵּין כְּתֵפָיו שָׁכֵן, שֶׁהוּא חֶלְקוֹ בַּמַּעֲרָב,</p>\n<p>וְעַכְשָׁו שְׁכִינָה בֵּין שְׁנֵי צַדִּיקִים. צַדִּיק לְמַעְלָה - יוֹסֵף הַצַּדִּיק, לְמַטָּה - בִּנְיָמִין. זֶהוּ בַּעַל הַגְּבִירָה, וְזֶה הַמְאָרֵחַ. לָכֵן כָּתוּב (תהלים קיג) מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת, זֶה עוֹלָם שֶׁמִּתְכַּלֶּה (ס\"א שמתגלה), זוֹ שְׁכִינָה תַּחְתּוֹנָה שֶׁהִיא עֲקֶרֶת הַבַּיִת. עִקַּר הָעוֹלָם הַזֶּה רָחֵל בֵּין שִׁנֵי צַדִּיקִים לְמַעְלָה וּלְמַטָּה.</p>\n<p>לָכֵןֹ נִקְרָא בֵּית הַמִּקְדָּשׁ בֵּית עוֹלָמִים. הַמִּזְבֵּחַ שֶׁל בֵּית עוֹלָמִים הָיָה בִּירֻשָּׁתוֹ שֶׁל בִּנְיָמִין, אֲבָל כְּשֶׁשָּׁרְתָה שְׁכִינָה בִּירֻשָּׁתוֹ שֶׁל יוֹסֵף בְּשִׁילֹה, לֹא קוֹרֵא לָהּ בֵּית עוֹלָמִים, שֶׁהֲרֵי עוֹלַם הוֹד הוּא לְמַעְלָה וּלְמַטָּה. אֵם הַבָּנִים שְׂמֵחָה - זוֹ שְׁכִינָה, וְלָכֵן הַלְלוּיָהּ.</p>\n<p>בֹּא רְאֵה, כְּשֶׁנִּמְכַּר אוֹתוֹ צַדִּיק לְמִצְרַיִם, בִּנְיָמִין אָחִיו הָיָה צַדִּיק לְמַטָּה, וְנָטַל מְקוֹמוֹ שֶׁלֹּא לְהִפָּגֵם, וּלְאוֹתָם עֲשָׂרָה בָנִים שֶׁהָיוּ לוֹ קָרָא לָהֶם עַל שְׁמוֹ שֶׁל אוֹתוֹ צַדִּיק, כְּמוֹ שֶׁפֵּרְשׁוּ הַחֲבֵרִים. בֶּלַע - עַל שֵׁם שֶׁנִּבְלַע בֵּין הָאֻמּוֹת.</p>\n<p>לָכֵן שָׁנִינוּ, הַיְסוֹד הָיָה מְהַלֵּךְ עַל פְּנֵי כָּל הַמַּעֲרָב וְעַל פְּנֵי כָּל הַצָּפוֹן, אוֹכֵל בַּמִּזְרָח חֲצִי אַמָּה וּבַדָּרוֹם חֲצִי אַמָּה, מִשּׁוּם שֶׁחֶלְקוֹ שֶׁל בִּנְיָמִין הָיָה בַּמַּעֲרָב, לָכֵן יֵשׁ לוֹ יְסוֹד, שֶׁהֲרֵי הוּא הָיָה שַׁלִּיט אֶל אוֹתוֹ צַדִּיק יְסוֹד עוֹלָם, אֲבָל בַּחֵלֶק שֶׁל יְהוּדָה שֶׁהוּא מִזְרָח, לֹא הָיָה לוֹ יְסוֹד, שֶׁהֲרֵי הוּא הִרְחִיקוֹ מִמֶּנּוּ, שֶׁנָּתַן עֵצָה לְמָכְרוֹ לַמִּצְרִים.</p>\n<p>בֹּא רְאֵה, סֵדֶר הַדְּגָלִים הֲרֵי הוּא סְבִיב אוֹתוֹ מִזְבַּח הָעוֹלָה שֶׁנִּקְרָא מִשְׁכָּן. יְהוּדָה וְהַסְּמוּכִים לוֹ בַּמִּזְרָח. וּמִי הַסְּמוּכִים? יִשָּׂשכָר שֶׁמֵּגֵן עָלָיו בְּכֹחַ הַתּוֹרָה. וְאַחַר כָּךְ זְבוּלוּן שֶׁסָּמוּךְ לְיִשָּׂשכָר, שֶׁנָּתַן לָהֶם מְלַאי וְכֹחַ לְהִתְעַסֵּק בַּתּוֹרָה. אֶפְרַיִם וּמְנַשֶּׁה וּבִנְיָמִין לַמַּעֲרָב. רְאוּבֵן וְהַסְּמוּכִים לוֹ בַּדָּרוֹם. דָּן וְשֶׁסְּמוּכִים לוֹ בַּצָּפוֹן.</p>\n<p>וּבֹא וּרְאֵה, כָּתוּב בְּאוֹתוֹ צַדִּיק (בראשית לז) וְהוּא נַעַר אֶת בְּנֵי בִלְהָה, וְכָתוּב בִּבְנֵי לֵאָה וַיִּשְׂנְאוּ אֹתוֹ. לָכֵן שָׁנִינוּ, הַיְסוֹד הַזֶּה הָיָה מְהַלֵּךְ עַל פְּנֵי כָּל הַמַּעֲרָב, שֶׁהֲרֵי חֵלֶק אָחִיו שֶׁשָּׁמַר אוֹתוֹ מָקוֹם וְשֶׁל בָּנָיו הָיָה. וְעַל פְּנֵי כָל הַצָּפוֹן, מִשּׁוּם שֶׁאֵלּוּ שֶׁהָיוּ שְׁרוּיִים בַּצָּפוֹן לֹא הָיוּ שׂוֹנְאִים אוֹתוֹ.</p>\n<p>אוֹכֵל בַּמִּזְרָח חֲצִי אַמָּה, מִשּׁוּם שֶׁיְּהוּדָה עָשָׂה חֲצִי הַצָּלָה. אָמַר (שם) מַה בֶּצַע, וְלֹא הִשְׁאִיר (אותם) לַהֲרֹג אוֹתוֹ. וּבַדָּרוֹם חֲצִי אַמָּה, מִשּׁוּם שֶׁרְאוּבֵן אָמַר לְהַצִּיל אוֹתוֹ מִיָּדָם. וְגַם גָּד שֶׁהָיָה חוֹנֶה שָׁם, לֹא הָיָה שׂוֹנֵא אוֹתוֹ.</p>\n<p>בֹּא רְאֵה בַּמָּה עֲקֻמִּים הֵם בְּנֵי אָדָם שֶׁלֹּא רוֹצִים לְהִשְׁתַּדֵּל בְּדֶרֶךְ הַחַיִּים שֶׁהוֹרִישׁ הַקָּדוֹשׁ בָּרוּךְ הוּא לְבָנָיו, וְהִזְהִיר אוֹתָם עָלֶיהָ וְאָמַר (יהושע א) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה, שֶׁאֵין לְךְ רְשׁוּת לְהַפְרִיד יוֹם מִלַּיְלָה. וְלָכֵן יְהוּדָה, אַף עַל פִּי שֶׁחֶלְקוֹ וְגוֹרָלוֹ הָיָה מַעֲרָב, שֶׁהוּא לַיְלָה, כְּשֶׁהָיָה שׁוֹרֶה סְבִיב אוֹתוֹ הַמִּשְׁכָּן, נִדְבַּק בַּמִּזְרָח שֶׁהוּא יוֹם. וְהַקָּדוֹשׁ בָּרוּךְ הוּא רָמַז לוֹ וְאָמַר לוֹ (דברים ל) וּבָחַרְתָּ בַּחַיִּים. שֶׁלֹּא לְהַפְרִיד יוֹם מִלַּיְלָה. וּמִי שֶׁמַּפְרִיד אוֹתָם גּוֹרֵם לְמָוֶת,</p>\n<p>וּבְאוֹתוֹ חֵטְא מֵתוּ בָנָיו, מִשּׁוּם שֶׁהִשְׁחִיתוּ דַרְכָּם וְלֹא חִבְּרוּ יוֹם עִם לַיְלָה, מִשּׁוּם שֶׁלֹּא הִשְׁתַּדְּלוּ כָּרָאוּי לְחַבֵּר לָבָן עִם אָדם כְּדֵי לְכַפֵּר אוֹתוֹ חֵטְא שֶׁלּוֹ, שֶׁהִפְרִידָם בַּתְּחִלָּה. כְּשֶׁמָּכַר אֶת אוֹתוֹ צַדִּיק שֶׁנִּקְרָא יוֹם, שֶׁהִפְרִידוֹ מִכְּנֶסֶת יִשְׂרָאֵל שֶׁנִּקְרֵאת לַיְלָה. רָמַז לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְקָרֵב מִזְרָח בְּמַעֲרָב, וְאָמַר לוֹ, (במדבר ב) וְהַחֹנִים קֵדְמָה מִזְרָחָה דֶּגֶל מַחֲנֵה יְהוּדָה, לְקָרֵב מִזְרָח לַמַּעֲרָב לָתֵת לוֹ שֶׁפַע בְּרָכוֹת מִלְמַעְלָה.</p>\n<p>וּבְנֵי יוֹסֵף וּבִנְיָמִין, אַף עַל גַּב שֶׁבִּנְיָמִין הָיָה נִדְבָּק בַּמִּזְרָח, רָמַז לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לַחֲנוֹת בַּמַּעֲרָב לְקָרֵב כְּנֶסֶת יִשְׂרָאֵל לַצַּדִּיק הַכֹּל בְּדֶרֶךְ יָשָׁר. זֶהוּ שֶׁכָּתוּב (הושע יד) כִּי יְשָׁרִים דַּרְכֵי ה' וְצַדִּקִים יֵלְכוּ בָם. וּרְאוּבֵן שֶׁנִּדְבַּק בְּצַד הַחֶסֶד, יַחֲנֶה בַדָּרוֹם. וְדָן, כְּדֵי לְכַפֵּר עַל אוֹתוֹ חֵטְא הָעֵגֶל שֶׁיְּקַבְּלוּ בָנָיו, וְהוּא מִצַּד הַצָּפוֹן, יַחֲנֶה בַצָּפוֹן לְכַפֵּר עַל אוֹתוֹ חֵטְא.</p>\n<p>מִשּׁוּם כָּךְ כָּתוּב בַּיָּם שֶׁעָשָׂה שְׁלֹמֹה עֲשָׂרָה עַל עֲשָׂרָה, (מלכים א ז) וְחוּט שְׁלֹשִׁים בָּאַמָּה יִסּוֹב. הַכֹּל בְּסוֹד הַחָכְמָה. כָּתוּב בּוֹ (שם) עֹמֵד עַל שְׁנֵי עָשָׂר בָּקָר שְׁלֹשָׁה פֹנִים צָפוֹנָה וּשְׁלֹשָׁה פֹנִים יָמָּה וּשְׁלֹשָׁה פֹּנִים נֶגְבָּה וּשְׁלֹשָׁה פֹּנִים מִזְרָחָה וְהַיָּם עֲלֵיהֶם מִלְמָעְלָה. אוֹתוֹ יָם שֶׁל חָכְמָה נִתְקַן בָּהֶם.</p>\n<p>בֹּא רְאֵה, כְּשֶׁהָיוּ עוֹשִׂים הַכֹּהֲנִים אֶת אוֹתָהּ חַטָּאת, לְכַפֵּר עַל עֲבֵרוֹת שֶׁל לֹא תַעֲשֶׂה זֶה הָיָה, שֶׁיֵּשׁ בָּהֶם כָּרֵת. וְעוֹלָה בָּאָה עַל מִי שֶׁלֹּא עוֹשֶׂה מִצְווֹת עֲשֵׂה, וּמֵאוֹתוֹ צַד בָּאָה הָעוֹלָה שֶׁהִיא זָכָר, וְכָתוּב (שמות כ) זָכוֹר אֶת יוֹם הַשַּׁבָּת - מִצְוַת עֲשֵׂה, וְלָכֵן אָנוּ מַקְרִיבִים בְּשַׁבָּת שְׁנֵי כְבָשִׂים, שֶׁל מוּסַף עוֹלָה, מִשּׁוּם שֶׁבְּאוֹתוֹ שֶׁל הַיָּמִין נִתּוֹסֵף לְאוֹתוֹ צַדִּיק אוֹר מֵהָעַתִּיק הַקָּדוֹשׁ. כְּשֶׁנִּדְבָּק עִם כְּנֶסֶת יִשְׂרָאֵל שֶׁהִיא שָׁמוֹר, לֹא תַעֲשֶׂה.</p>\n<p>מִשּׁוּם כָּךְ יֵשׁ בְּשַׁבָּת עֲשֵׂה וְלֹא תַעֲשֶׂה שֶׁיֵּשׁ בּוֹ כָּרֵת, שֶׁהֲרֵי מִי שֶׁעוֹשֶׂה פְגָם בְּאוֹתוֹ מָקוֹם שֶׁנִּקְרָא לֹא תַעֲשֶׂה, וּמַפְרִיד אֶת הַזִּוּוּג שֶׁלָּהֶם, נִכְרֶתֶת מִשָּׁם נַפְשׁוֹ, וּמִיהוּ? מִי שֶׁעוֹשֶׂה מַעֲשִׂים שֶׁל חֹל בְּשַׁבָּת, בַּקֹּדֶשׁ שֶׁנִּדְבָּק בְּשַׁבָּת בְּשַׁבָּתוֹן, וְכָל הָעוֹלָמוֹת בְּחֶדְוָה בְּאוֹרָה. אֲבָל מִי שֶׁלֹּא עוֹשֶׂה אֶלָּא בִּשְׁגָגָה, מַקְרִיב חַטָּאת כְּנֶגֶד אוֹתָהּ דַּרְגַּת מִזְבֵּחַ.</p>\n<p>וּבְרֹאשׁ חֹדֶשׁ בְּהִתְחַדְּשׁוּת הַלְּבָנָה אָנוּ מַקְרִיבִים (במדבר כח) פָּרִים בְּנֵי בָקָר שְׁנַיִם, שֶׁהֲרֵי מִצַּד שֶׁל פָּרָה אֲדֻמָּה תְּמִימָה בָּאוּ, וְהֵם לְמַעְלָה לְהַשְׁלִים אֶת הַפְּגָם שֶׁלָּהּ וְלָתֵת לָהּ שֶׁפַע אֶחָד עַל שְׁנַיִם מֵאוֹתוֹ מָקוֹם שֶׁנִּקְרָא עוֹלָה, וְנוֹסָף בְּאוֹתוֹ זְמַן אוֹר לַלְּבָנָה. וְאַיִל אֶחָד - לְהַקְרִיב לָהּ אֵילוֹ שֶׁל יִצְחָק, (שיר ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי,</p>\n<p>כְּבָשִׂים בְּנֵי שָׁנָה שִׁבְעָה, לְחַבֵּק אוֹתָהּ בְּיָמִין, וְשִׁבְעָה זְכָרִים נִקְרָבִים עִמָּהּ, תְּמִימִים שְׁלֵמִים בַּכֹּל, וְאָנוּ מַקְרִיבִים שְׂעִיר עִזִּים אֶחָד לְחַטָּאת. שֶׁחַטָּאת הַזּוֹ בָּאָה מִצַּד זֶה שֶׁל פַּר הַחַטָּאת, שֶׁכָּתוּב שָׁמוֹר, וְשָׁמוֹר לֹא תַעֲשֶׂה הוּא, וְאָנוּ מַקְרִיבִים שְּׂעִיר חַטָּאת שֶׁבָּא עַל לֹא תַעֲשֶּׂה. בַּמּוּסָף שֶׁלָּהּ בְּרֹאשׁ חֹדֶשׁ, שֶׁבָּא לְכַפָּרָה עַל טֻמְאַת מִקְדָּשׁ וְקָדָשָׁיו, שֶׁכָּתוּב (יחזקאל מג) וְלֹא יְטַמְּאוּ עוֹד בֵּית יִשְׂרָאֵל שֵׁם קָדְשִׁי, שֶׁלֹּא יִתְקָרֵב לִכְנֶסֶת יִשְׂרָאֵל עָרֵל וְטָמֵא.</p>\n<p>אֲבָל מוּסָף שֶׁל שַׁבָּת אֵין לְהַקְרִיב, מִשּׁוּם שֶׁהֲרֵי הִתְגַּלָּה הָעַתִּיק הַקָּדוֹשׁ, וּמֵאִיר בְּאוֹתוֹ רָצוֹן לְכָל הָעוֹלָמוֹת, וְהַכֹּל נִמְצָא בְּהֶאָרָה, שֶׁהֲרֵי שַׁבָּת הִיא בְּלִי דִין כְּלָל, וְלֹא שׁוֹלֵט הַנָּחָשׁ הֶעָקֹם. וְכֹהֲנִים מִצַּד הַחֶסֶ\"ד שׁוֹחֲטִים אוֹתוֹ בִּצְפוֹן הַמִּזְבֵּחַ, וַאֲפִלּוּ יִשְׂרָאֵל יְכוֹלִים לַעֲשׂוֹת, פְּרָט לָזֶה שֶׁאֵין לָהֶם רְשׁוּת לִקְרַב לְאוֹתוֹ מִזְבֵּחַ לְהַקְרִיב, אֲבָל לִשְׁחֹט מֻתָּר.</p>\n<p>וּבַצָפוֹן הוּא מְקוֹמוֹ שֶׁל אוֹתוֹ שָׂעִיר, שֶׁהֲרֵי שָׂעִיר יוֹנֵק מִצָּפוֹן, וְאָנוּ מַקְרִיבִים דָּם לַמִּזְבֵּחַ, וְעוֹשִׂים אַרְבַּע מַתָּנוֹת עַל אַרְבַּע קְרָנוֹת כְּדֵי לְהַקִּיפוֹ מִכָּל הַצְּדָדִים, שֶׁלֹּא יִתְקָרֵב מִי שֶׁלֹּא רָאוּי לִקְרַב לְקֹדֶשׁ הַקְּדָשִׁים. וְחַטָּאת זוֹ שֶׁעוֹשֶׂה מִמֶּנָּה הִיא קֹדֶשׁ הַקְּדָשִׁים, שֶׁלֹּא יִתְעוֹרֵר צַד הַטֻּמְאָה מִמֶּנּוּ בָּעוֹלָם.</p>\n<p>וּבֹא וּרְאֵה, בָּעוֹלָה שְׁתֵּי מַתָּנוֹת שֶׁהֵן אַרְבַּע, סוֹד הַיִּחוּד שֶׁמִּתְיַחֵד עוֹלָה בַּמִּזְבֵּחַ. אֲבָל חַטָּאת אַרְבַּע מַתָּנוֹת, שֶׁאֵינָם אֶלָּא לִשְׁמֹר וּלְהַקִּיף אוֹתָם גִּבּוֹרִים שֶׁהֵם מִצַּד הַגְּבוּרָה, לְאוֹתוֹ מַטָּה כִּסֵּא קָדוֹשׁ, וּלְהַשְׁלִים אוֹתוֹ פְגָם שֶׁעָשׂוּ בָהּ. וּמִי שֶׁגָּרַם לִבְנֵי אָדָם לַעֲשׂוֹת אוֹתוֹ חֵטְא, בָּא מִצַּד הַשָּׂעִיר, לָכֵן חַטָּאת יָחִיד שְׂעִירָה, וְחַטָּאת נָשִׂיא שָׂעִיר, וְחַטָּאת כֹּהֵן מָשִׁיחַ פַּר. הַכֹּל מִצַּד שְׂמֹאל.</p>\n<p>וְלִפְעָמִים מַקְרִיב יָחִיד כִּשְׂבָּה כְּנֶגֶד כְּנֶסֶת יִשְׂרָאֵל וְכָל שְׁאָר הַמִּצְווֹת. אֶלָּא בַּעֲבוֹדָה זָרָה שֶׁל צִבּוּר מַקְרִיבִים פַּר לְעוֹלָה וְשָׂעִיר לְחַטָּאת, וְאוֹתוֹ חַטָּאת הוּא חָסֵר בְּלִי אָלֶ\"ף, מִשּׁוּם שֶׁהוּא חִסָּרוֹן גָּדוֹל, שֶׁהֲרֵי חַטָּאת הוּא לָשׁוֹן שֶׁל חִסָּרוֹן, שֶׁכָּתוּב (מלכים א כא) וְהָיִיתִי אֲנִי וּבְנִי שְׁלֹמֹה חַטָּאִים. וְכָל אֶחָד עֵז בַּת שְׁנָתוֹ, מִצַּד הַשְּׂמֹאל. וְאוֹתוֹ הַפָּר דּוֹרוֹן הוּא לְמַעְלָה לַצַּדִּיק, שֶׁהִפְרִידוּ אוֹתוֹ אָרוֹן מֵאוֹתָהּ בְּרִית, וְשָׂעִיר לְחַטָּאת כְּנֶגֶד כְּנֶסֶת יִשְׂרָאֵל שֶׁמָּנְעוּ מִמֶּנָּה בְּרָכוֹת. וְעִם כָּל זֶה, כְּשֶׁיָּחִיד חָטָא בְּכָל מִצְווֹת שֶׁל לֹא תַעֲשֶׂה שֶׁיֵּשׁ בָּהֶם כָּרֵת, צָרִיךְ לְהַקְרִיב שְׂעִירַת עִזִּים לְכַתְּחִלָּה, אֶלָּא כְּשֶׁאֵין לוֹ שֶׁיַּקְרִיב כִּשְׂבָּה.</p>\n<p>וּבֹא וּרְאֵה, כְּנֶסֶת יִשְׂרָאֵל הִיא רְבִיעִית לַיָּמִים, וְלָכֵן צְרִיכָה אַרְבַּע מַתָּנוֹת, וְעוֹלֶה אוֹתוֹ רֵיחַ נִיחוֹחַ מֵאוֹתָם כְּבָשִׂים, וְאָז יֵשׁ נַחַת רוּחַ לִכְנֶסֶת יִשְׂרָאֵל וְלֹא עוֹשָׂה נְקָמוֹת, שֶׁהֲרֵי זֶה הָיָה בְּשׁוֹגֵג.</p>\n<p>(במדבר כח) וּבַחֹדֶשׁ הָרִאשׁוֹן - שֶׁהוּא אַרְבָּעָה עַל עֶשֶׂר עוֹשִׂים פֶּסַח, כְּדֵי שֶׁיִּהְיֶה זוֹכֵר לָנוּ לְעוֹלָם אוֹתוֹ פֶּסַח שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל. שֶׁהִכָּה אֶת אוֹתוֹ טָלֶה, וְהוֹצִיא הַשְּׁכִינָה וְיִשְׂרָאֵל מִמָּקוֹם טָמֵא, וְהִתְחַבֵּר אַרְבָּעָה עִם עָשׂוֹר, כְּנֶסֶת יִשְׂרָאֵל הִתְחַבְּרָה בֶּעָשׂוֹר שֶׁהוּא צַדִּיק, וְרָמוּז מְקוֹמוֹ בְּעֶשֶׂר, וְאָז פֶּסַח לַה'.</p>\n<p>וְלָכֵן מִי שֶׁהוּא טָהוֹר וְסֻלְּקָה מִמֶּנּוּ אוֹתָהּ עָרְלָה, וְיֵרָאֶה רֹשֶׁם קָדוֹשׁ שֶׁל צַדִּיק, שֶׁהוּא י' בּוֹ, וְלֹא הִקְרִיב פֶּסַח לַה', כְּנֶסֶת יִשְׂרָאֵל לַצַּדִּיק, שֶׁהוּא רָאוּי לִקְרַב לַמִּקְדָּשׁ וְלֹא עָרֵל וְטָמֵא. שֶׁאִם לֹא הִקְרִיב, יֵשׁ בּוֹ כָּרֵת.</p>\n<p>וּמָה הַטַּעַם? שֶׁהֲרֵי בְּכָל הַתּוֹרָה אֵין כָּרֵת אֶלָּא עַל מִצְווֹת לֹא תַעֲשֶׂה, מָה (ומה) הַטַּעַם בְּפֶסַח וּמִילָה, שֶׁהֵם מִצְווֹת עֲשֵׂה, יֵשׁ כָּרֵת? אֶלָּא מִשּׁוּם שֶׁהַדַּרְגָּה גּוֹרֶמֶת שֶׁהִיא כְּנֶסֶת יִשְׂרָאֵל שֶׁהִיא פֶּסַח, וְנִקְרֵאת (נקראת) מִצְווֹת לֹא תַעֲשֶׂה, צְרִיכָה לְהִתְחַבֵּר עִם עֲשֵׂה וּלְהַכְלִיל בּוֹ מִדַּת לַיְלָה עִם יוֹם. וּמִיהוּ,? זֶה צַדִּיק, שֶׁהִיא מִילָה וּמִצְוַת עֲשֵׂה, וְנִכְלָל בְּמִצְוַת לֹא תַעֲשֶׂה מִדַּת יוֹם בְּלַיְלָה. וְאִם לֹא נִמּוֹל בֶּן אָדָם, לֹא רָאוּי לְהַקְרִיב אוֹתָם,</p>\n<p>לָכֵן עוֹמֶדֶת מִצְוַת לֹא תַעֲשֶׂה עָלָיו, וְדָנָה אוֹתוֹ בְּכָרֵת, שֶׁלֹּא תִכָּנֵס נַפְשׁוֹ לַמִּקְדָּשׁ. וְכֵן בְּפֶסַח צְרִיכָה כְּנֶסֶת יִשְׂרָאֵל לְהִתְחַבֵּר עִם בַּעְלָהּ. וְאִם בֶּן אָדָם לֹא עוֹשֶׂה וְלֹא מַקְרִיב פֶּסַח לַה', הִיא עוֹמֶדֶת עָלָיו וְדָנָה אוֹתוֹ, וְלֹא מוֹצִיאָה אוֹתוֹ מִתַּחַת יַד פַּרְעֹה, וְנִכְרֶתֶת נַפְשׁוֹ מִמָּקוֹם קָדוֹשׁ, וְנִשְׁאֶרֶת בִּמְקוֹם טֻמְאָה בְּמִצְרַיִם, שֶׁהֲרֵי אִם לֹא עָשׂוּ יִשְׂרָאֵל שְׁתֵּי מִצְווֹת אֵלּוּ, לֹא יָצְאוּ מִשָּׁם.</p>\n<p>וְלָכֵן כָּתוּב (דברים טז) שָׁמוֹר אֶת חֹדֶשׁ הָאָבִיב וְעָשִׂיתָ פֶּסַח לַה' אֱלֹהֶיךְ. שָׁמוֹר - כְּלָלוּת שֶׁל נְקֵבָה, לֹא תַעֲשֶׂה. אֶת - כְּלָלוּת שֶׁל הַכֹּל. חֹדֶשׁ הָאָבִיב - שֶׁהֲרֵי בְּאוֹתָהּ שָׁעָה שְׂעוֹרָה אָבִיב, וּמַקְרִיבִים מִמֶּנּוּ עֹמֶר עֲשִׂירִית הָאֵיפָה מִמָּחֳרַת הַשַּׁבָּת הִיא, וְסוֹפְרִים שִׁבְעָה שָׁבוּעוֹת שְׁלֵמִים לַעֲלוֹת לְמַעְלָה, וּלְקַבֵּל מֵאוֹתָם חֲמִשִּׁים יָמִים עֶלְיוֹנִים שֶׁל הָאֵם הָעֶלְיוֹנָה תּוֹרָה שֶׁנִּקְרֵאת לֶחֶם, שֶׁכָּתוּב (משלי ט) לְכוּ לַחֲמוּ בְלַחְמִי.</p>\n<p>וְאָנוּ מַקְרִיבִים בְּיוֹם הַחֲמִשִּׁים שֶׁנִּתְּנָה בּוֹ תּוֹרָה שְׁתֵּי הַלֶּחֶם, תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה, וְיוֹרֵד חֶסֶד שֶׁל הָעַתִּיק הַקָּדוֹשׁ שֶׁל הָאֵם הָעֶלְיוֹנָה (בינה) בְּאוֹתָם שִׁבְעָה שָׁבוּעוֹת שְׁלֵמִים בַּכֹּל, וְכָל אַחַת מֵאוֹתָן שֶׁבַע דְּרָגוֹת כְּלוּלָה בְּשִׁבְעָה, כְּפִי שֶׁבֵּאַרְנוּ בְּסוֹד הָאֱמוּנָה.</p>\n<p>לָכֵן שָׁמוֹר אֶת חֹדֶשׁ הָאָבִיב וְעָשִׂיתָ פֶּסַח לַה'. הַקְרֵב אוֹתָם בְּיִחוּד, שֶׁהֲרֵי בּוֹ הוֹצִיאֲךְ מִמִּצְרַיִם לַיְלָה, וְתַשְׁלִים אֶת הַדַּרְגָּה הַזּוֹ שֶׁנִּקְרֵאת לֵיל שִׁמּוּרִים, וְתַקְרִיב זָכָר אֵלֶיהָ וְתִקָּרֵא לַיְלָה שָׁלֵם. וּבֹא תִרְאֶה, נַעֲרָה בְתוּלָה, עַד שֶׁלֹּא קָרַב אֵלֶיהָ זָכָר, נִקְרֵאת נַעַר. אַחַר כָּךְ נִקְרֵאת נַעֲרָה. זֶהוּ שֶׁכָּתוּב (דברים כב) וְנָתְנוּ לַאֲבִי הַנַּעֲרָה, שְׁלֵמָה דַּוְקָא. וְזֶהוּ כְּשֶׁנִּמְצֵאת שְׁלֵמָה, וְלֹא הִתְקָרֵב מִי (למי) שֶׁלֹּא רָאוּי. אַף כָּאן, בַּתְּחִלָּה לֵיל שִׁמּוּרִים, אַחַר כָּךְ הַלַּיְלָה הַזֶּה לַה', כְּשֶׁמִּתְקָרֵב זֶה לְזֹאת,</p>\n<p>וְלָכֵן לֹא רָאוּי לְהִתְקָרֵב לְאוֹתוֹ פֶּסַח עָרֵל וְטָמֵא. וְדָמָהּ טָעוּן מַתָּנָה אַחַת דַּוְקָא, כְּמוֹ שֶׁנֶּאֱמַר (שיר ו) אַחַת הִיא יוֹנָתִי תַמָּתִי אַחַת הִיא לְאִמָּהּ. הִיא שׁוֹמֶרֶת אֶת בָּנֶיהָ יִשְׂרָאֵל שֶׁלֹּא יִתְטַמְּאוּ בְּמִנְהֲגֵיהֶם, מִשּׁוּם כָּךְ שִׁבְטֵי יָהּ יָצְאוּ מִשָּׁם, וְהִתְחַבְּרָה יוֹ\"ד בְּהֵ\"א, וְלֹא בְּמָקוֹם אַחֵר, כְּמוֹ שֶׁעָשׂוּ הֵם.</p>\n<p>אֲבָל כְּשֶׁיָּצְאוּ מִבָּבֶל, נִטְמְאוּ שָׁם וְטִמְּאוּ הַמִּקְדָּשׁ, מִשּׁוּם כָּךְ הַנָּחָשׁ שָׁלַט בָּהֶם, וְלֹא נִמְצָא שִׁלְטוֹן לְיִשְׂרָאֵל בְּאוֹתוֹ זְמַן, מִשּׁוּם שֶׁטִּמְּאוּ אֶת הַמִּקְדָּשׁ בְּנָשִׁים נָכְרִיּוֹת. מִכָּאן, מִי שֶׁמְּטַמֵּא אֶת עַצְמוֹ לְמַטָּה, הוּא טָמֵא לְמַעְלָה. וּמִי שֶׁמְּקַדֵּשׁ עַצְמוֹ לְמַטָּה, מְקֻדָּשׁ לְמַעְלָה. וְעַל כָּךְ הָיוּ רְאוּיִים שֶׁיֵּעָשֶׂה לָהֶם נֵס בְּאוֹתָהּ שָׁעָה שֶׁיָּצְאוּ מִבָּבֶל כְּאוֹתָהּ שָׁעָה שֶׁיָּצְאוּ מִמִּצְרַיִם, אֶלָּא שֶׁגָּרַם הַחֵטְא.</p>\n<p>וּבַחֲמִשָּׁה עָשָׂר לַחֹדֶשׁ הָרִאשׁוֹן הַחֵלֶק שֶׁל אַבְרָהָם, שֶׁהוּא רִאשׁוֹן וְאָחוּז בְּדַרְגַּת חֶסֶד, אָנוּ מַקְרִיבִים לַקָּדוֹשׁ-בָּרוּךְ-הוּא שְׁנֵי פָרִים, לְהוֹסִיף שְׁנֵי חֲלָקִים לְדַרְגַּת חֶסֶד מֵהָעַתִּיק הַקָּדוֹשׁ. אַיִל אֶחָד כְּנֶגֶד דַּרְגַּת יִצְחָק, וְצָרִיךְ אַיִל, לָשׁוֹן שֶׁל תַּקִּיפוּת, מִשּׁוּם שֶׁחֶלְקוֹ חֹזֶק הַמַּיִם. וְצָרִיךְ שֶׁתַּסְכִּים אוֹתָהּ דַּרְגַּת הַגְּבוּרָה עִם חֶסֶד עֶלְיוֹן לַעֲשׂוֹת חֶסֶד עִם כָּל יִשְׂרָאֵל, וּלְהִפָּרַע מֵאוֹתָם שֶׁמְּצִיקִים לָהֶם, וּלְהַקִּיפוֹ צַד הַמַּיִם. זֶהוּ שֶׁכָּתוּב (בראשית ל) מַחְשּף הַלָּבָן.</p>\n<p>שִׁבְעָה כְּבָשִׂים תְּמִימִים - כְּנֶגֶד כָּל הַדְּרָגוֹת שֶׁיִּשְׁתַּלְּמוּ בוֹ. וְכֵן בְּכָל יוֹם וָיוֹם שִׁבְעָה כְבָשִׂים, בַּיּוֹם הָרִאשׁוֹן שֶׁל כָּל שִׁבְעַת הַיָּמִים הָעֶלְיוֹנִים, כָּל אֶחָד נִתְקָן בְּסוֹד שֶׁל שֶׁבַע, וְיִהְיוּ שֶׁבַע שַׁבָּתוֹת תְּמִימוֹת לְקַבֵּל אֶת הָאוֹר הָעֶלְיוֹן שֶׁל הַתּוֹרָה. שְׂעִיר חַטָּאת לְכַפֵּר עַל טֻמְאַת הַמִּקְדָּשׁ, וְלֹא תִהְיֶה רְשׁוּת לְאוֹתוֹ שָׂעִיר לְעַרְבֵּב וְלֹא לְהַסְטִין עַל יִשְׂרָאֵל.</p>\n<p>(במדבר כח) וּבְיוֹם הַבִּכּוּרִים בְּהַקְרִיבְכֶם מִנְחָה חֲדָשָׁה - כְּנֶגֶד דַּרְגַּת יַעֲקֹב, שֶׁהֲרֵי אָז נִתְקַן הָעוֹלָם וְהִתְחַדֵּשׁ, וְאָנוּ מוֹנִים שִׁבְעָה שָׁבוּעוֹת כְּדֵי לְחַבֵּר הַכֹּל בַּיּוֹבֵל הָעֶלְיוֹן, שֶׁנּוֹתֶנֶת לַבֵּן הַבְּכוֹר הַזֶּה עֲטָרָה שֶׁל תּוֹרָה שֶׁנִּכְלֶלֶת בְּאַרְבָּעִים וְתִשְׁעָה פָנִים, וְיָצְאָה מֵחָכְמָה הָעֶלְיוֹנָה בְּאוֹתָם חֲמִשִּׁים שַׁעֲרֵי בִינָה, וְנִתְּנָה לַבֵּן הַבְּכוֹר הַזֶּה עַל יְדֵי מֹשֶׁה שֶׁאָחוּז גַּם בְּדַרְגָּה זוֹ. זֶהוּ שֶׁכָּתוּב (שיר ג) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה, בַּמֶּלֶךְ שֶׁהַשָּׁלוֹם כֻּלּוֹ שֶׁלּוֹ. (והרי) שֶׁהֲרֵי בֵּאַרְנוּ שֶׁדַּרְגָּה זוֹ שְׁלֵמָה מִכָּל הַצְּדָדִים, וְשָׁלֵם נִקְרָא בְּסוֹד הָאֱמוּנָה, שֶׁכָּתוּב (בראשית כה) וְיַעֲקֹב אִישׁ תָּם. בְּיוֹם חֲתֻנָּתוֹ - זֶה כְּשֶׁנִּתְּנָה (תורה). וּבְיוֹם שִׂמְחַת לִבּוֹ - כְּשֶׁנִּבְנָה בֵּית הַמִּקְדָּשׁ.</p>\n<p>בֹּא רְאֵה, כָּתוּב (שמות יט) בַּחֹדֶשׁ הַשְּׁלִישִׁי, שֶׁהִתְחַבְּרָה דַרְגָּה זוֹ שֶׁנִּקְרֵאת שְׁלִישִׁי בַּחֹדֶשׁ, וְהִיא חֲתֻנָּתוֹ, עַל זֶה כָּתוּב (שם) וַיִּחַן שָׁם יִשְׂרָאֵל נֶגֶד הָהָר. דַּרְגָּה זוֹ הַבֵּן הַבְּכוֹר. נֶגֶד הָהָר - כְּנֶגֶד אוֹתוֹ הַר שֶׁנּוֹדַע שֶׁהוּא קָטָן מִכָּל הֶהָרִים שֶׁלְּמַעְלָה, שֶׁהוּא רָם וְנִשָּׂא כְּשֶׁמִּתְחַבֵּר לְמַעְלָה, וְנִקְרָא הַר סִינַי. שֶׁהֲרֵי שִׁבְעָה הָרִים וְשִׁבְעָה יָמִים וְשֶׁבַע אֲרָצוֹת בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בְּעוֹלָם, שֶׁהֵם כְּנֶגֶד שִׁבְעָה יָמִים עֶלְיוֹנִים, וְלֹא בָחַר מִכֻּלָּם לָתֵת תּוֹרָה אֶלָּא בְּהַר סִינַי, שֶׁהוּא הַסּוֹד שֶׁל כְּנֶסֶת יִשְׂרָאֵל, וְגַם בְּיָם כִּנֶּרֶת, שֶׁבָּא מִשָּׁם תְּכֵלֶת, שֶׁדּוֹמֶה לְכִסֵּא הַכָּבוֹד.</p>\n<p>כְּנֶסֶת יִשְׂרָאֵל כִּנֶּרֶת זֶה הַצַּדִּיק, וְזֶהוּ יָם כִּנֶּרֶת, כְּפִי שֶׁפֵּרְשׁוּ הַחֲבֵרִים. כִּנּוֹר הָיָה תָלוּי לְמַעְלָה מִמִּטָּתוֹ שֶׁל דָּוִד, וּבְשָׁעָה שֶׁרוּחַ צְפוֹנִית מְנַשֶּׁבֶת בּוֹ, מְנַגֵּן מֵאֵלָיו, וְדָוִד קָם לַעֲסֹק בַּתּוֹרָה בַּחֲצוֹת הַלַּיְלָה לְהִתְחַבֵּר עִם כְּנֶסֶת יִשְׂרָאֵל. וּבְאֶרֶץ יִשְׂרָאֵל הַשְּׁבִיעִית שֶׁל הַכֹּל, הַנְּקֻדָּה הָאֶמְצָעִית שֶׁל אֶרֶץ הַתַּחְתּוֹנָה בָּחַר הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהִיא כְּנֶגֶד הַנְּקֻדָּה הָעֶלְיוֹנָה.</p>\n<p>מָה הַטַּעַם בּוֹ בְּהַר סִינַי שֶׁלְּמַעְלָה לָתֵת בּוֹ תּוֹרָה שֶׁבִּכְתָב, וְסִימָנִיךְ בְּאָרוֹן זֶה לָתֵת בּוֹ בְּרִית? מִשּׁוּם שֶׁבְּאָרוֹן זֶה מֻנָּחִים כָּל הַגְּנָזִים הַטּוֹבִים, וְתוֹרָה שֶׁבִּכְתָב, שֶׁנִּקְרֵאת בְּרִית, מֻנַּחַת בּוֹ, וְכָל כְּלֵי הַקְּרָב שֶׁל הַמֶּלֶךְ נִמְסְרוּ בְיָדֶיהָ, וְכָל הָעוֹלָמוֹת שֶׁלְּמַטָּה יוֹנְקִים מִמֶּנָּה. אִם זָכוּ יִשְׂרָאֵל לִשְׁמֹר הַתּוֹרָה, אָז נוֹתֶנֶת לָהֶם כָּל טוּב הָעוֹלָם, וְאִם לֹא, אָז מְיַסֶּרֶת אוֹתָם. זֶהוּ שֶׁכָּתוּב (ויקרא כו) וְיִסַּרְתִּי אֶתְכֶם אַף אָנִי. זוֹ כְּנֶסֶת יִשְׂרָאֵל. וּכְשֶׁתְּחַבֵּר בְּ\"אָנִי\" דָּלֶ\"ת שֶׁלָּהּ, נִקְרֵאת אֲדנָ\"י, וְדָן אֶת הָעוֹלָם.</p>\n<p>לָכֵן כָּתוּב (דברים ד) וְזאת הַתּוֹרָה אֲשֶׁר שָׂם מֹשֶׁה. בְּ\"זֹאת\" נִתְּנָה תּוֹרָה. בֹּא רְאֵה, תּוֹרָה שֶׁבִּכְתָב נִקְרֵאת צַדִּיק, וּמֻנַּחַת בְּזאת, שֶׁבְּרִית זוֹ מֻנַּחַת בּוֹ, שֶׁכָּתוּב אֲרוֹן הַבְּרִית, מִשּׁוּם שֶׁמֻּנַּחַת בּוֹ בְּרִית שֶׁהוּא צַדִּיק. וְלָכֵן וְזֹאת הַתּוֹרָה, הִתְחַבֵּר וָא\"ו עִם זֹאת, וְאָז - אֲשֶׁר שָׂם מֹשֶׁה, סַם הַחַיִּים לָעוֹלָם, שֶׁהֲרֵי עֵץ הַחַיִּים נִדְבַּק בָּהּ. וּכְשֶׁמַּעֲשֵׂי בְּנֵי אָדָם אֵינָם כְּשֵׁרִים, מִסְתַּלֵּק וָא\"ו מִ\"זֹּאת\", וְאָז כָּתוּב (ויקרא יד) זֹאת תִּהְיֶה תּוֹרַת הַמְּצֹרָע, וְזֶהוּ חָשׁוּב כַּמֵּת.</p>\n<p>וְכָתוּב (במדבר יט) זאת הַתּוֹרָה אָדָם כִּי יָמוּת בְּאֹהֶל. הִסְתַּלְּקָה ו' מִזֹּאת, וְעוֹשֶׂה הָאֹהֶל הַזֶּה נְקָמוֹת. הַיְנוּ מַה שֶּׁכָּתוּב (שם) זֹאת חֻקַּת הַתּוֹרָה אֲשֶׁר צִוָּה ה'. מִשּׁוּם שֶׁלֹּא הִתְחַבְּרָה ו' עִם ה', גָּרְמוּ שֶׁטִּמְּאוּ הַמִּקְדָּשׁ וְגָרְמוּ לָהֶם מִיתָה, שֶׁהֲרֵי מִי שֶׁמַּפְרִידָם גּוֹרֵם מִיתָה לְנַפְשׁוֹ,</p>\n<p>עַד שֶׁבָּאָה פָּרָה וְכִפְּרָה עַל בְּנָהּ, וְעוֹשִׂים מִמֶּנָּה הַזָּאָה עַל טְמֵאֵי מֵתִים. זֹאת הַתּוֹרָה, שֶׁלֹּא הִתְחַבֵּר לָהּ וָא\"ו עַד שֶׁעָשׂוּ הַזָּאָה לְאוֹתָם כְּלֵי מִדְיָן, וְאַחַר כָּךְ (דברים ד) וְזֹאת הַתּוֹרָה אֲשֶׁר שָׂם וְגוֹמֵר. חַיִּים נִדְבְּקוּ בָהּ,</p>\n<p>(שם לג) וְזאת הַבְּרָכָה. בְּרָכָה נִדְבְּקָה בָּ\"זֹּאת\" הַזּוֹ. אֲבָל כָּל מָקוֹם שֶׁתִּמְצָא בַתּוֹרָה \"זֹאת הַתּוֹרָה\" בְּלִי וָא\"ו, זֶה בִּגְלַל חֵטְא. (ויקרא יג) זֹאת תּוֹרַת נֶגַע צָרַעַת. (שם יד) זאת התורה לכל נגע הצרעת. (במדבר ה) זאת תּוֹרַת הַקְּנָאֹת. מִשּׁוּם שֶׁטִּמְּאוּ אֶת עַצְמָם וְטִמְּאוּ הַמִּקְדָּשׁ. (ויקרא ו) זֹאת תּוֹרַת הָעֹלָה, לֹא כָתוּב בּוֹ וָא\"ו, עַד שֶׁיַּעֲשׂוּ לָהּ בְּנֵי אַהֲרֹן שְׁלֵמוּת לְחַבֵּר אֶת זאת לְבַעְלָהּ.</p>\n<p>(שם ו) וְזאת תּוֹרַת הַמִּנְחָה - לֹא בָא עַל חֵטְא, שֶׁהֲרֵי הִיא נְדָבָה, אוֹ שֶׁבָּאָה עִם עוֹלָה, וְהָעוֹלָה הֲרֵי עוֹשָׂה שְׁלֵמוּת. (שם) זֹאת תּוֹרַת הַחַטָּאת - בָּא עַל חֵטְא שֶׁטִּמְּאוּ אֶת \"זאת\". (ויקרא ז) וְזֹאת תּוֹרַת הָאָשָׁם - מִשּׁוּם שֶׁלֹּא עָשׂוּ כָּל כָּךְ פְּגָם, וְלָכֵן בָּאָה זָכָר וְלֹא נְקֵבָה. (שם) וְזאת תּוֹרַת זֶבַח הַשְּׁלָמִים, מִשּׁוּם שֶׁבָּאָה לְשָׁלוֹם, מִתְחַבֵּר עִמָּהּ וָא\"ו. (שם) זֹאת הַתּוֹרָה לָעֹלָה (ו) לַמִּנְחָה וְלַחַטָּאת - בִּגְלַל חַטָּאת שֶׁיֵּשׁ בַּפָּסוּק, וְחוֹטֵא אֶחָד יְאַבֵּד טוֹבָה הַרְבֵּה,</p>\n<p>זֶה פֵּרַשְׁנוּ בְּכָל מָקוֹם - וָא\"ו מוֹסִיף עַל עִנְיָן רִאשׁוֹן. וְזֹאת הַתּוֹרָה אֲשֶׁר שָׂם וְגוֹמֵר, מָה הַטַּעַם וָא\"ו, הֲרֵי לֹא אָמַר זאת בַּתְּחִלָּה? לָמָּה כָּתוּב וְזאת? מִשּׁוּם סַם הַחַיִּים שֶׁנִּדְבַּק בָּהּ.</p>\n<p>(דברים לג) וְזֹאת הַבְּרָכָה - בִּשְׁבִיל בְּרָכָה, אַף עַל גַּב שֶׁלֹּא כָתוּב זֹאת בַּתְּחִלָּה, אוֹ דִּבֵּר עַל מַה שֶּׁיָּבֹא, אֲבָל בְּכֻלָּם מָה הַטַּעַם לֹא כָתוּב וְזאת? מִשּׁוּם שֶׁלֹּא נִדְבָּק וָא\"ו. וְזֶהוּ שֶׁכָּתוּב (ויקרא ז) וְזֹאת תּוֹרַת הָאָשָׁם, מִשּׁוּם שֶׁכָּתוּב לְמַעְלָה (שם ו) וְזֹאת תּוֹרַת הַחַטָּאת, וָא\"ו מוֹסִיף עַל עִנְיָן רִאשׁוֹן,</p>\n<p>מִשּׁוּם כָּךְ נִתְּנָה תּוֹרָה בְּ\"זאת\". וּמִשּׁוּם כָּךְ כָּתוּב (שם כו) אַף אֲנִי אֶעֱשֶׂה זֹאת, אֲסַלֵּק מִמֶּנָה וָא\"ו וְתַעֲשֶׂה בָהֶם נְקָמוֹת, וְכָל הַקָּרְבָּנוֹת בָּאִים לְקָרֵב אֶת הַ\" את\" לְמַעְלָה בַּשְּׁלִישִׁי הַזֶּה, וְאָנוּ מַקְרִיבִים בְּיוֹם זֶה שְׁנֵי פָרִים בְּמוּסָף, לְהוֹסִיף לָהּ שְׁנֵי חֲלָקִים. אַיִל אֶחָד לְחַבֵּר לָהּ הַכֹּחַ שֶׁל גְּבוּרָה, שִׁבְעָה כְבָשִׂים כְּנֶגֶד כָּל הַדְּרָגוֹת שֶׁיִּשְׂמְחוּ בַּהִלּוּלָא הַזּוֹ, שְׂעִיר עִזִּים לְכַפֵּר עַל שֶׁטִּמְּאוּ הַמִּקְדָּשׁ הָרְשָׁעִים שֶׁלְּמַטָּה.</p>\n<p>(במדבר כט) וּבַחֹדֶשׁ הַשְּׁבִיעִי - כְּנֶגֶד דַּרְגַּת יִצְחָק שֶׁיִּתְחַבֵּר עִם כְּנֶסֶת יִשְׂרָאֵל בִּשְׁנֵי פָרִים. זֶהוּ שֶׁכָּתוּב (בראשית ח) וַתָּנַח הַתֵּבָה בַּחֹדֶשׁ הַשְּׁבִיעִי בְּשִׁבְעָה עָשָׂר, שֶׁהִתּוֹסְפָה כְּנֶסֶת יִשְׂרָאֵל, שֶׁהִיא שְׁבִיעִית עַל עֶשֶׂר סְמוּכָה לַעֲשָׂרָה. מִשּׁוּם כָּךְ פַּר אֶחָד, לְהוֹסִיף לוֹ כֹּחַ הָאִמָּא הָעֶלְיוֹנָה לָדוּן אֶת הָעוֹלָם. אֲבָל שְׁנַיִם לֹא, מִשּׁוּם שֶׁהָעוֹלָם לֹא יָכוֹל לִסְבֹּל אֶת הַדִּין הַקָּשֶׁה. אַיִל אֶחָד - הַגְּבוּרָה שֶׁלּוֹ, לָשׁוֹן שֶׁל תַּקִּיפוּת, (תהלים כב) אֱיָלוּתִי לְעֶזְרָתִי חוּשָׁה, וְהָאַיִל הַזֶּה תִּמְצָא בְּכָל הַמּוּסָפִים, שֶׁמּוֹסִיפִים כֹּחַ וּגְבוּרָה עֲלֵיהֶם, פְּרָט לְשַׁבָּת שֶׁיֵּשׁ בָּהּ מְנוּחָה וְאֵין בָּהּ דִּין כְּלָל, שֶׁמִּתְגַּלֶּה הָעַתִּיק הַקָּדוֹשׁ שִׂמְחָה וְטוֹבוֹת לְכָל הָעֶלְיוֹנִים (עולמים).</p>\n<p>(במדבר כח) כְּבָשִׂים בְּנֵי שָׁנָה - לָתֵת כֹּחַ לְכָל הַדְּרָגוֹת. שְׂעִיר עִזִּים - שֶׁלֹּא תֵרָאֶה טֻמְאָה בַּמִּקְדָּשׁ בְּיוֹם הַדִּין, וּבְיוֹם זֶה מִתְחַבֶּרֶת הַגְּבוּרָה הָעֶלְיוֹנָה בַּדִּין הַתַּחְתּוֹן שֶׁל רֹאשׁ חֹדֶשׁ לָדוּן אֶת הָעוֹלָם. בֹּא רְאֵה, גְּבוּרָה דִּין הַקָּשֶׁה, כְּנֶסֶת יִשְׂרָאֵל דִּין הָרָפֶה, אַךְ חוֹבַת הַיּוֹם פַּר אֶחָד כְּדֵי שֶׁהָעוֹלָם יוּכַל לִסְבֹּל,</p>\n<p>וְלָכֵן בְּרֹאשׁ חֹדֶשׁ שְׁנֵי פָרִים, שֶׁהִיא כַּפָּרָה. בַּעֲשָׂרָה לַחֹדֶשׁ כְּנֶגֶד דַּרְגַּת מֹשֶׁה. בַּמּוּסָף שֶׁלּוֹ פַּר בֶּן בָּקָר אֶחָד, שֶׁלֹּא נוֹסָף בּוֹ דִּין כָּל כָּךְ, הֱיוֹת שֶׁאוֹתוֹ יוֹם הוּא שֶׁל כַּפָּרָה. אַיִל אֶחָד תַּקִּיף לִשְׁבֹּר אֶת הָרְשָׁעִים שֶׁל הָעוֹלָם, וְצָרִיךְ לַעֲשׂוֹת נַחַת לְשַׁכֵּךְ הָרֹגֶז. כְּבָשִׂים שִׁבְעָה לְהוֹסִיף לְכָל הַדְּרָגוֹת. שְׂעִיר עִזִּים אֶחָד הִתּוֹסֵף כָּאן בְּחוֹבַת הַיּוֹם לְכַפֵּר עַל טֻמְאַת הַמִּקְדָּשׁ, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה יְכַפֵּר עַל הַכֹּל וְלֹא תִשָּׁאֵר טֻמְאָה בָּעוֹלָם.</p>\n<p>מִשּׁוּם כָּךְ אֶחָד בַּיּוֹם, לְכַפֵּר קֹדֶשׁ הַקְּדָשִׁים פַּעַם אַחַת בְּשָׁנָה, כְּדֵי שֶׁלֹּא תִמָּצֵא שָׁם טֻמְאָה כָּל כָּךְ, וְאֶחָד בַּחוּץ לַמִּזְבֵּחַ הַחִיצוֹן שֶׁלֹּא תִמָּצֵא טֻמְאָה בָּעוֹלָם.</p>\n<p>בַּחֲמִשָּׁה עָשָׂר לַחֹדֶשׁ כְּנֶגֶד דַּרְגַּת אַהֲרֹן שֶׁאָחוּז בְּהוֹד, וְהִתְעַלָּה גַּם בְּחֶסֶד. וְלָכֵן בִּזְמַן זֶה אֲפִלּוּ עִם כָּל אֻמּוֹת הָעוֹלָם עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא חֶסֶד, מִשּׁוּם שֶׁמִּתּוֹסֵף חֶסֶד שֶׁל אַהֲרֹן עִם חֶסֶד שֶׁל אַבְרָהָם, וְהֵם מַקְרִיבִים בּוֹ בְּשִׁבְעָה יָמִים קָרְבְּנוֹת עוֹלוֹת, כְּדֵי שֶׁיִּשְׂמְחוּ כָּל הָעוֹלָם בְּשִׂמְחַת יִשְׂרָאֵל.</p>\n<p>שִׁבְעִים פָּרִים כְּנֶגֶד שִׁבְעִים אֻמּוֹת עוֹבְדֵי כוֹכָבִים וּמַזְּלוֹת הָעוֹלָם, וּבַיּוֹם הָרִאשׁוֹן פָּרִים שְׁלֹשָׁה עָשָׂר, לְהַרְאוֹת שֶׁאֵינָם כְּדָאִים לְהִתְקַיֵּם בָּעוֹלָם אֶלָּא בְּטוּבוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיֵּשׁ בּוֹ שְׁלֹשׁ עֶשְׂרֵה מִדּוֹת שֶׁל רַחֲמִים.</p>\n<p>אֵילִים שְׁנַיִם, שֶׁתִּהְיֶה תַקִּיפוּת לְאוֹתָהּ דַּרְגָּה שֶׁל חֶסֶד עֶלְיוֹן עַל אֶחָד שְׁנַיִם מִמַּה שֶּׁמַּקְרִיבִים בְּכָל הַמּוּסָפִים, מִשּׁוּם שֶׁחַג זֶה הוּא כְּנֶגֶד דַּרְגַּת אַהֲרֹן, שֶׁאָחוּז בְּדַרְגָּה שִׁשִּׁית. וְנִקְרָא יוֹם הַשִּׁשִּׁי. יוֹמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶלֶף שָׁנִים.</p>\n<p>וּבְאוֹתוֹ יוֹם עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהוֹסִיף עַל כָּל אֶחָד שְׁנַיִם חֶסֶד לְעַמּוֹ. זֶהוּ שֶׁכָּתוּב (שמות טז) וְהָיָה בַּיּוֹם הַשִּׁשִּׁי וְהֵכִינוּ אֵת אֲשֶׁר יָבִיאוּ, אָז - וְהָיָה מִשְׁנֶה עַל אֲשֶׁר יִלְקְטוּ יוֹם יוֹם, וּבְכָל הַדְּרָגוֹת שֶׁלְּמַעְלָה נוֹסָפוֹת בְּרָכוֹת.</p>\n<p>וּבְאוֹתוֹ יוֹם יָבֹא מֶלֶךְ הַמָּשִׁיחַ וְיִקָּרֵא חַג הָאָסִיף, שֶׁיְּכַנֵּס הַקָּדוֹשׁ בָּרוּךְ הוּא בּוֹ הַגָּלוּת שֶׁל עַמּוֹ. זֶהוּ שֶׁכָּתוּב (ישעיה יא) וְהָיָה בַּיּוֹם הַהוּא יוֹסִיף ה' שֵׁנִית יָדוֹ לִקְנוֹת אֶת שְׁאָר עַמּוֹ. וְיִקָּרֵא חַג הַסֻּכּוֹת, שֶׁכָּל שֶׁבַע הַדְּרָגוֹת מְכַסּוֹת עַל יִשְׂרָאֵל כְּמוֹ סֻכָּה, וְלָכֵן כָּל עַנְנֵי הַכָּבוֹד הוֹלְכִים עִם יִשְׂרָאֵל בַּמִּדְבָּר בִּזְכוּת אַהֲרֹן,</p>\n<p>וְלָכֵן אַרְבָּעָה עָשָׂר כְּבָשִׂים שֶׁבְּכָל יוֹם. וּבְשִׁבְעָה יָמִים - הֲרֵי שִׁבְעָתַיִם, וְיָאִיר שִׁבְעָתַיִם אוֹר הַשֶּׁמֶשׁ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא יְרַחֵם עַל הָעוֹלָם. וּשְׂעִיר עִזִּים אֶחָד לְחַטָּאת - לְכַפֵּר עַל טֻמְאַת הַמִּקְדָּשׁ שֶׁטִּמְּאוּ אֻמּוֹת הָעוֹלָם עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת. בַּיּוֹם הַשֵּׁנִי כְּנֶגֶד דַּרְגַּת יִצְחָק. בַּיּוֹם הַשְּׁלִישִׁי כְּנֶגֶד דַּרְגַּת יַעֲקֹב. בַּיּוֹם הָרְבִיעִי כְּנֶגֶד דַּרְגַּת יוֹסֵף. בַּיּוֹם הַחֲמִישִׁי כְּנֶגֶד דַּרְגַּת מֹשֶׁה. בַּיּוֹם הַשִּׁשִּׁי כְּנֶגֶד דַּרְגַּת אַהֲרֹן.</p>\n<p>וּבֹא וּרְאֵה, בְּחַג זֶה וּבְחַג הַמַּצּוֹת שִׁבְעָה יָמִים שֶׁכְּלוּלִים בָּהֶם כָּל הַיָּמִים שֶׁלְּמַעְלָה, מַה שֶּׁאֵין כֵּן בִּשְׁאָר חַגִּים שֶׁמַּקְרִיבִים בָּהֶם מוּסָף, אֶלָּא הַיְנוּ מַה שֶּׁפֵּרַשְׁנוּ בְּסוֹד הָאֱמוּנָה, (בראשית ל) מַחְשּף הַלָּבָן אֲשֶׁר עַל הַמַּקְלוֹת, שֶׁלְּכָל אוֹתָם שִׁבְעָה שֶׁבַע דְּרָגוֹת מַקִּיפוֹת אוֹתָם בְּצַד הַחֶסֶד, הֶחָג שֶׁל הַמַּצּוֹת כְּנֶגֶד אַבְרָהָם שֶׁבָּא מֵחֶסֶד, לָכֵן כָּל הַדְּרָגוֹת שָׁם, שֶׁהֲרֵי אֶת כָּל הַדְּרָגוֹת מַקִּיף יַעֲקֹב הַשָּׁלֵם לַצַּד שֶׁל חֶסֶד. הֶחָג הַזֶּה כְּנֶגֶד דַּרְגָּתוֹ שֶׁל אַהֲרֹן שֶׁאָחוּז בְּחֶסֶד, כֻּלָּם עִמּוֹ.</p>\n<p>דָּבָר אַחֵר - מִשּׁוּם שֶׁכָּל הַדְּרָגוֹת וְכָל הַצַּדִּיקִים, כְּשֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, הַקָּדוֹשׁ בָּרוּךְ הוּא הִתְגַּלָּה שָׁם בַּכְּתָרִים שֶׁלּוֹ, וְעָתִיד לַעֲשׂוֹת כֵּן בִּזְמַן בִּיאַת הַמָּשִׁיחַ. מִשּׁוּם כָּךְ כָּל הַכְּתָרִים רְמוּזִים כָּאן וְכָאן, וְנוֹטְלִים עַל אֶחָד שְׁנַיִם שֶׁבַע בְּרָכוֹת כָּאן מִשָּׁם.</p>\n<p>וְשָׁם עַל אֶחָד שִׁבְעָה מִשְּׁאָר הַמּוּסָפִים, זֶהוּ שֶׁכָּתוּב (מיכה ז) כִּימֵי צֵאתְךְ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת. כְּיוֹם צֵאתְךְ הָיָה לוֹ לוֹמַר! מַה זֶּה כִּימֵי? שֶׁכָּל הַיָּמִים הָעֶלְיוֹנִים הִזְדַּמְּנוּ לְשָׁם וְהִזְדַּמְּנוּ לְכָאן, מִשּׁוּם כָּךְ נִפְלָאוֹת, נ' פְּלָאוֹת, חֲמִשִּׁים פְּלָאוֹת, שֶׁהֲרֵי חֲמִשִּׁים שַׁעֲרֵי בִינָה פָּתַח הַקָּדוֹשׁ בָּרוּךְ הוּא לְהוֹצִיא אוֹתָם מִשָּׁם, וְלָכֵן מֻזְכֶּרֶת בַּתּוֹרָה חֲמִשִּׁים פְּעָמִים יְצִיאַת מִצְרַיִם, כְּנֶגֶד חֲמִשִּׁים שְׁעָרִים, כָּךְ יַעֲשֶׂה לִימוֹת הַמָּשִׁיחַ.</p>\n<p>וּמַה זֶּה אַרְאֶנּוּ? אֶלָּא אַרְאֶנּוּ אֶת אוֹתוֹ הַזָּקֵן שֶׁרָאָה בָּרִאשׁוֹנָה, שֶׁכָּתוּב (שמות יד) וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדלָה, וְאָז עֲתִיד לִרְאוֹת אֶת הַפֻּרְעָנוּת שֶׁל אֱדוֹם</p>\n<p>דָּבָר אַחֵר - שֶׁבִּשְׁבִיל שִׁבְעַת הַצַּדִּיקִים עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲבִיר אֶת כָּל אֻמּוֹת הָעוֹלָם, וְלֹא יִשָּׁאֵר בָּעוֹלָם אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ וְיִשְׂרָאֵל גּוֹי אֶחָד. מִשּׁוּם כָּךְ כָּאן שִׁבְעָה יָמִים. בֹּא רְאֵה שֶׁמִּשּׁוּם כָּךְ מִתְמַעֲטִים וְהוֹלְכִים, וּבַיּוֹם הַשְּׁמִינִי שׁוֹלְטִים יִשְׂרָאֵל לְבַדָּם בָּעוֹלָם וּמַקְרִיבִים פַּר אֶחָד, אַיִל אֶחָד, סוֹד הַיִּחוּד.</p>\n<p>שִׁבְעָה כְבָשִׂים - כְּנֶגֶד שֶׁבַע דְּרָגוֹת. שְׂעִיר עִזִּים - אַף עַל גַּב שֶׁבְּאוֹתוֹ זְמַן יַעֲבִירֶנּוּ הַקָּדוֹשׁ בָּרוּךְ הוּא מִן הָעוֹלָם, עִם כָּל זֶה יִשָּׁאֵר מִמֶּנּוּ שֶׁלֹּא יִתְבַּטְּלוּ מִפְּרִיָּה וּרְבִיָּה. וּבְאוֹתוֹ זְמַן יֵצְאוּ מַיִם חַיִּים מֵחָכְמָה הָעֶלְיוֹנָה, (זכריה יד) חֶצְיָם אֶל הַיָּם הַקַּדְמוֹנִי - זֶה חֶסֶד עֶלְיוֹן, וְחֶצְיָם אֶל הַיָּם הָאַחֲרוֹן - זוֹ גְבוּרָה תַּחְתּוֹנָה וּגְבוּרָה עֶלְיוֹנָה. בַּקַּיִץ וּבַחֹרֶף - בְּצַד הָאֵשׁ וּבְצַד הַמַּיִם. שֶׁלֹּא יִשָּׁאֵר דִּין בָּעוֹלָם, אֶלָּא הַכֹּל רַחֲמִים וְחַיִּים וְחֵרוּת בָּעוֹלָם.</p>\n<p>וּבֹא רְאֵה, בֶּחָג הַזֶּה עוֹשִׂים נִסּוּךְ הַמַּיִם, שֶׁפַע שֶׁל חֶסֶד בְּאוֹתָם שִׁיתִים מִשֵּׁשֶׁת יְמֵי בְרֵאשִׁית, וְכָל שִׁבְעַת הַיָּמִים הָעֶלְיוֹנִים מְקַבְּלִים מֵאוֹתָם מַיִם חַיִּים שֶׁיּוֹצְאִים מִירוּשָׁלַיִם הָעֶלְיוֹנָה הַטְּמִירָה. וּבְאֵיזֶה מָקוֹם רָמוּז עַל אוֹתָם מַיִם חַיִּים? בְּאוֹתָם שִׁיתִים,</p>\n<p>וַחֲסִידִים וְצַדִּיקִים שְׂמֵחִים בַּהִלּוּלָא הַזּוֹ, מִשּׁוּם שֶׁרוֹמֵז לְאוֹתוֹ הַטּוֹב שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת כְּשֶׁיַּעֲבִיר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַטֻּמְאָה מִן הָאָרֶץ, שֶׁיֵּרְדוּ אוֹתָם מַיִם טְהוֹרִים בְּאוֹתָם הַשִּׁיתִים בְּאוֹתוֹ מִזְבֵּחַ עֶלְיוֹן, יָם הָאַחֲרוֹן, וְהֵם שְׁלֹשָׁה לֻגִּים מַיִם, שְׁמוֹנֶה עֶשְׂרֵה בֵּיצִים, כְּנֶגֶד צַדִּיק שֶׁנִּקְרָא חַי הָעוֹלָמִים, וְעַל יָדוֹ הַמַּיִם יוֹרְדִים בְּאוֹתָם שִׁיתִים.</p>\n<p>וּבֹא וּרְאֵה, כְּשֶׁהִלֵּל הַזָּקֵן הָיָה שָׂמֵחַ בַּהִלּוּלָא הַזּוֹ, אָמַר, אִם אֲנִי כָּאן - הַכֹּל כָּאן, וְאִם אֵין אֲנִי כָּאן - מִי כָּאן? הָיָה רוֹמֵז וְאוֹמֵר, אִם שְׁכִינָה שֶׁנִּקְרֵאת אֲנִי שׁוֹרָה כָּאן - הַכֹּל כָּאן, אוֹתוֹ מָקוֹם שֶׁנִּקְרָא כֹּל שֶׁבָּהּ לְהִזְדַּוֵּג בָּהּ. וְאִם אֵין אֲנִי כָּאן - מִי כָּאן? שֶׁהֲרֵי לֹא חָשׁוּב טוֹב שָׁלֵם, מִשּׁוּם שֶׁשְּׁכִינָה לֹא שׁוֹרָה בָּאָרֶץ הַקְּדוֹשָׁה.</p>\n<p>אֲבָל כְּשֶׁיִּשְׁתַּלְּמוּ אוֹתָם פָּרִים, אָז כָּתוּב (ישעיה יב) וּשְׁאַבְתֶּם מַיִם בְּשָׂשׂוֹן מִמַּעַיְנֵי הַיְשׁוּעָה. מִי הֵם? שִׁשָּׁה מַעְיָנוֹת שֶׁמְּרִיקִים בַּיְשׁוּעָה הַזֹּאת, וְאָז הָעוֹלָם כֻּלּוֹ בְּחֶדְוָה, מִשּׁוּם שֶׁשְּׁכִינָה יוֹצֵאת מִתּוֹךְ אוֹתָהּ טֻמְאַת שְׁאָר הָעַמִּים, מִשּׁוּם כָּךְ (במדבר כט) בַּיּוֹם הַשְּׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם.</p>\n<p>בֹּא רְאֵה, עֶשֶׂר נְטִיעוֹת, עֲרָבָה וְנִסּוּךְ הַמַּיִם - הֲלָכָה לְמֹשֶׁה מִסִּינַי, שְׁאָר הַדְּבָרִים שֶׁל הַתּוֹרָה - תּוֹרָה, וְכָאן הֲלָכָה. מָה הַטַּעַם? אֶלָּא מִשּׁוּם שֶׁמָּקוֹם זֶה שֶׁנִּקְרָא הַר סִינַי, תּוֹרָה שֶׁבְּעַל פֶּה לִמְּדָה אֶת מֹשֶׁה לִקְשֹׁר קִשְׁרֵי הָאֱמוּנָה.</p>\n<p>אוֹתָן עֶשֶׂר נְטִיעוֹת שֶׁנָּטַע הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁאָחַז אוֹתָן בְּאוֹתוֹ מָקוֹם שֶׁנִּקְרָא עֶרֶב שְׁבִיעִית, וְיַעֲשׂוּ פְרִי בְּאוֹתוֹ בֵּית סֵאָה, כְּדֵי שֶׁיָּבא מָזוֹן לָעוֹלָם בַּשְּׁבִיעִית הַזּוֹ, שֶׁאֵין לָהֶם מָזוֹן אֶלָּא מֵאוֹתָהּ שָׁנָה שִׁשִּׁית שֶׁזּוֹרְעִים בָּהּ זְרָעִים. זֶהוּ שֶׁכָּתוּב (הושע י) זִרְעוּ לָכֶם לִצְדָקָה וְקִצְרוּ לְפִי חֶסֶד. מַה שֶּׁזּוֹרְעִים יִהְיֶה לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא צְדָקָה שְׁלֵמָה, וְאָז וְקִצְרוּ לְפִי חֶסֶד, אָז יִהְיֶה טוֹב הָעֶלְיוֹן. וּמִי הוּא לְפִי חֶסֶד? זֶה אַבְרָהָם.</p>\n<p>בֹּא רְאֵה, לְמַטָּה שִׁבְעָה מַעֲשִׂים יֵשׁ בֵּינֵיהֶם. זְרִיעָה - כְּנֶגֶד הָאֵם הָעֶלְיוֹנָה, זֶהוּ שֶׁכָּתוּב (בראשית מו) הֵא לֶם זֶרַע. קְצִירָה - כְּנֶגֶד דַּרְגַּת אַבְרָהָם, זֶהוּ שֶׁכָּתוּב (ו) קִצְרוּ לְפִי חֶסֶד. דִּישָׁה בְּחָרוּץ - כְּנֶגֶד דַּרְגַּת יִצְחָק, שֶׁעוֹשֶׂה דִּין וּמַפְרִיד תֶּבֶן מֵאוֹתוֹ בָּר. דִּין מַפְרִיד מִמֶּנּוּ, וְעוֹשֶׂה דִּין בְּרִשְׁעֵי הָעוֹלָם, וְאָז הוּא (תהלים לה) כְּמֹץ לִפְנֵי רוּחַ.</p>\n<p>וְרוּחַ הַזּוֹ זוֹ הַדַּרְגָּה שֶׁל יַעֲקֹב, שֶׁכָּתוּב (בראשית מה) וַתְּחִי רוּחַ יַעֲקֹב, וּכְנֶגְדוֹ זוֹרֶה. וְאוֹתוֹ הַמֹּץ נִתָּן לָאֵשׁ לְמַאֲכָל. טוֹחֵן - כְּנֶגֶד דַּרְגַּת מֹשֶׁה. לָשׁ - כְּנֶגֶד דַּרְגַּת אַהֲרֹן. אוֹפֶה - כְּנֶגֶד דַּרְגַּת צַדִּיק, וְנַעֲשֶׂה לֶחֶם בְּיָדוֹ שֶׁל צַדִּיק בְּאוֹתוֹ אוֹר שֶׁיֵּשׁ בְּצִיּוֹן. זֶהוּ שֶׁכָּתוּב (תהלים קלו) נֹתֵן לֶחֶם לְכָל בָּשָׂר. בַּתְּחִלָּה לְ\"כָל\", וְאַחַר כָּךְ לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא בָּשָׂר. וּמַה זֶּה לֶחֶם? זֶה הַקִּיּוּם.</p>\n<p>וּבַשָּׁנָה הַשְּׁבִיעִית הַזּוֹ לֹא עוֹשִׂים מְלָאכָה, אֶלָּא אוֹכְלִים אוֹתוֹ לֶחֶם שֶׁנִּתַּן לָהֶם בַּשָּׁנָה הַשִּׁשִּׁית, וְכָל הָעוֹלָמוֹת נָחִים בְּחֶדְוָה. וְכָל הָעֲנִיִּים וְהָעֲשִׁירִים, כֻּלָּם שָׁוִים בְּמָקוֹם זֶה, שֶׁהֲרֵי כָּל הַתַּחְתּוֹנִים נִזּוֹנִים מִשָּׁנָה הַשְּׁבִיעִית הַזּוֹ.</p>\n<p>וְאִם אָדָם עוֹשֶׂה סְחוֹרָה בְּאוֹתָם פֵּרוֹת, הַמָּקוֹם הַזֶּה שֶׁל עֲנִיּוּת מוֹנֵעַ מִמֶּנּוּ בְּרָכוֹת, וְלָכֵן מוֹנֵעַ מִמֶּנּוּ בְּרָכוֹת. וְצָרִיךְ אָדָם לְהַרְאוֹת שֶׁלָּאָרֶץ הַקְּדוֹשָׁה הַזּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא יֵשׁ נַחַת עִם בַּעְלָהּ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתֵן לֶחֶם לַכֹּל הַזֶּה, וְ\"כֹל\" לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא (בראשית ב) בָּשָׂר מִבְּשָׂרִי, וְאֵין לָהּ אוֹר מִשֶּׁלָּהּ, אֶלָּא אוֹתָם סְפִיחֵי הַשִּׁשִּׁית שֶׁנִּזְרְעוּ בָהּ מִמֵּילָא.</p>\n<p>וְצָרִיךָ אָדָם בְּאוֹתוֹ עֶרֶב שְׁבִיעִית לַעֲשׂוֹת מְלֶאכֶת הָאָרֶץ בְּאוֹתָן עֶשֶׂר נְטִיעוֹת שֶׁהִשְׁתַּלְּמוּ בָהּ, שֶׁתִּתְיַחֵד הָאָרֶץ הַזּוֹ עִמָּהֶם וְלֹא תִפָּרֵד מֵהֶם, וְאַף הִיא תִּקָּרֵא נְטִיעָה, נְטִיעָה שֶׁנָּטַע הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּדֵי שֶׁלֹּא יִמָּנַע מִמֶּנָּה אוֹתוֹ טוּב שֶׁיֵּשׁ לָהּ עִם בַּעְלָהּ מְנוּחָה בַּשְּׁבִיעִית.</p>\n<p>וְלָכֵן נִבְרָא אָדָם בַּיּוֹם הַשִּׁשִּׁי, וְהִזְדַּוְּגָה עִמּוֹ בַּת זוּגוֹ לְהִתְעַנֵּג בְּשַׁבָּת, וְעַכְשָׁו הִזְדַּוְּגָה צֶדֶק עִם שִׁשִּׁי לָתֵת אוֹר לְהַר סִינַי הַזֶּה.</p>\n<p>וּבֹא וּרְאֵה, הַר חוֹרֵב נִקְרָא כְּשֶׁמִּזְדַּוֵּג עִמּוֹ וָא\"ו, וְאִם בְּנֵי אָדָם מַפְרִידִים וָא\"ו מִמֶּנָּה, נִקְרָא חֶרֶב לַה', שֶׁהֲרֵי כָּתוּב חֶרֶב, וְעוֹשָׂה נְקָמוֹת, לָכֵן הֲלָכָה לְמֹשֶׁה מִסִּינַי תּוֹרָה שֶׁבְּעַל פֶּה, שֶׁיִּכְלְלוּ אוֹתָהּ עִם אוֹתָם עֶשֶׂר נְטִיעוֹת עֶרֶב שְׁבִיעִית, וְיָבֹא מָזוֹן לָעוֹלָם בַּשְּׁבִיעִית, שֶׁהוּא מָקוֹם שֶׁאֵין לוֹ אוֹר אֶלָּא מַה שֶּׁנִּתָּן לוֹ מֵאוֹתוֹ וָא\"ו.</p>\n<p>וּבֹא וּרְאֵה, כְּשֶׁעָשׂוּ יִשְׂרָאֵל אֶת הָעֵגֶל, וְהִפְרִידוּ הַבְּרָכוֹת מֵהַר חוֹרֵב הַזֶּה, שֶׁהִפְרִידוּ מִמֶּנּוּ וָא\"ו וְקִצְּצוּ בַּנְּטִיעוֹת, בְּאוֹתָן נְטִיעוֹת מַה כָּתוּב? (שמות לג) וַיִּתְנַצְּלוּ בְנֵי יִשְׂרָאֵל אֶת עֶדְיָם מֵהַר חוֹרֵב. אוֹתוֹ תַכְשִׁיט עֶלְיוֹן, תְּפִלִּין שֶׁל רֹאשׁ וּזְרוֹעַ שֶׁשָּׂמִים בְּיָד כֵּהָה הֵסִירוּ מֵהֶם, וּמֵאֵיזֶה מָקוֹם נִתַּן לָהֶם? מֵהַר חוֹרֵב, כְּשֶׁהִזְדַּוֵּג עִמָּהּ וָא\"ו. וְכָעֵת (משלי טז) (ו) נִרְגָּן מַפְרִיד אַלּוּף, וְעוֹרְרוּ עֲלֵיהֶם אֶת הַחֶרֶב.</p>\n<p>מִשּׁוּם כָּךְ, בְּנֵי לֵוִי שֶׁעָשׂוּ לְוָיָה לְמָקוֹם זֶה, נִפְרְעוּ מֵהֶם, זֶהוּ שֶׁכָּתוּב (שמות לב) וַיַּעֲמֹד מֹשֶׁה בְּשַׁעַר הַמַּחֲנֶה וַיֹּאמֶר מִי לַה' אֵלָי, וַיֵּאָסְפוּ אֵלָיו כָּל בְּנֵי לֵוִי. שֶׁהֲרֵי לֹא עָשׂוּ פֵרוּד, אֶלָּא לְוָיָה.</p>\n<p>וְאָמַר לָהֶם מֹשֶׁה, כֹּה אָמַר ה' עִבְרוּ וָשׁוּבוּ מִשַּׁעַר לָשַׁעַר בַּמַּחֲנֶה. מִשּׁוּם שֶׁהַ\"כֹּה\" הַזֹּאת נָתְנָה לָהֶם רְשׁוּת לַעֲשׂוֹת דִּינִים. וּמִיהוּ כֹּה? זֶה הַר חוֹרֵב, וְלָכֵן הָרְגוּ מֵהֶם כִּשְׁלֹשֶׁת אַלְפֵי אִישׁ. שְׁלֹשֶׁת לֹא נֶאֱמַר, אֶלָּא כִּשְׁלֹשֶׁת, כְּנֶגֶד אוֹתָן שָׁלֹשׁ דְּרָגוֹת שֶׁהָיוּ מְמַלְּאוֹת אֶת הַבְּאֵר הַזּוֹ. זֶהוּ שֶׁכָּתוּב (בראשית כט) וְהִנֵּה שָׁם שְׁלֹשָׁה עֶדְרֵי צֹאן רֹבְצִים עָלֶיהָ, מִשּׁוּם שֶׁהֵם גָּרְמוּ שֶׁיִּסְתַּלְּקוּ מִמֶּנָּה, וַהֲרֵי בֵּאֲרוּהָ.</p>\n<p>מִשּׁוּם כָּךְ צִוְּתָה תּוֹרָה שֶׁבְּעַל פֶּה הַ את אֶת מֹשֶׁה עַל אוֹתָן עֶשֶׂר נְטִיעוֹת וַעֲרָבָה, שֶׁיַּקִּיפוּ אֶת הַמִּזְבֵּחַ הַזֶּה עִם אוֹתָם עַרְבֵי נַחַל, כְּנֶגֶד שְׁתֵּי דְרָגוֹת שֶׁמַּקִּיפִים לְמַעְלָה, שֶׁהֵם נֵצַח וְהוֹד, וְאָז יַעֲשׂוּ נִסּוּךְ הַמַּיִם אוֹתָם מַים חַיִּים שֶׁבָּאִים עַל יְדֵי צַדִּיק, וְלֹא יִמְנְעוּ מִמִּזְבֵּחַ הַזֶּה הַטּוֹב הָעֶלְיוֹן.</p>\n<p>וּבֹא וּרְאֵה, כָּל שְׁאָר יְמוֹת הַשָּׁנָה עוֹשִׂים בַּמִּזְבֵּחַ הַזֶּה נִסּוּךְ הַיַּיִן, רוֹמֵז לַדִּין שֶׁנִּכְנָס בָּהּ לָדוּן אֶת הָעוֹלָם. אֲבָל בֶּחָג עוֹשִׂים אַף בְּמַיִם חַיִּים, שֶׁהֲרֵי חַיִּים וְאוֹר נוֹסָף בְּאוֹתוֹ זְמַן, (ישעיה יא) כִּי מָלְאָה הָאָרֶץ דֵּעָה אֶת ה' כַּמַּיִם לַיָּם מְכַסִּים.</p>\n<p>עָשֶׂר פְּעָמִים נִמְנוּ יִשְׂרָאֵל: אַחַת בִּירִידָתָם לְמִצְרַיִם, שֶׁכָּתוּב (בראשית מו) כָּל הַנֶּפֶשׁ לְבֵית יַעֲקֹב הַבָּאָה מִצְרַיְמָה וְגוֹמֵר. וְאַחַת בַּעֲלִיָּתָם, שֶׁכָּתוּב (שמות יב) כְּשֵׁשׁ מֵאוֹת אֶלֶף. וּשְׁתַּיִם בְּחֻמַּשׁ הַפְּקוּדִים. וּשְׁתַּיִם בִּימֵי שָׁאוּל, אַחַת בְּבֶזֶק וְאַחַת בַּטְּלָאִים. וְאַחַת בִּימֵי דָוִד, (שמואל ב כד) וַיִּתֵּן יוֹאָב אֶת מִסְפַּר מִפְקַד הָעָם אֶל הַמֶּלֶךְ. וְאַחַת בִּימֵי עֶזְרָא, (עזרא ב) כָּל הַקָּהָל כְּאֶחָד. וְאַחַת לֶעָתִיד לָבא, (ירמיה לג) עֹד תַּעֲברְנָה הַצּאן עַל יְדֵי מוֹנֶה.</p>\n<p>אַשְׁרֵי אָדָם מָצָא חָכְמָה - זֶה אָדָם הָעֶלְיוֹן שֶׁהִשְׁרָה עָלָיו הַטּוֹב שֶׁל הָעַתִּיק (כתר), אֵימָתַי. כְּשֶׁמַּגִּיעָה הַחָכְמָה, כְּמוֹ שֶׁנֶּאֱמַר (משלי יח) מָצָא אִשָּׁה מָצָא טוֹב וַיָּפֶק רָצוֹן מֵה'. זֶה הָרָצוֹן שֶׁל הָעַתִּיק. וּמַהִי הַחָכְמָה הַזּוֹ? זוֹ חָכְמָה זְעִירָה שֶׁהִיא גְדוֹלָה בְּהִתְחַבְּרוּת לְמַעְלָה.</p>\n<p>מָצָא, מַה זֶּה מָצָא? כְּמוֹ שֶׁנִּמְצֵאת בַּכֹּל. וְאָדָם יָפִיק תְּבוּנָה - שֶׁצָּרִיךְ לְעַיֵּן וּלְהִסְתַּכֵּל וּלְהוֹצִיא מֵהָעֹמֶק הָעֶלְיוֹן תְּבוּנָה לְהָאִיר לַחָכְמָה הַזּוֹ, וְעַל יְדֵי מִי הִיא נְאוֹרָה? עַל יְדֵי הָאָדָם הָעֶלְיוֹן שֶׁמֵּפִיק רָצוֹן מִלְמַעְלָה לְהָאִיר לָהּ: רִבִּי בִנְיָמִן לֵוִי, מַצָאתִי כָתוּב שֵׁם בֵּן י\"ב אוֹתִיּוֹת יְהַ יְהַ וְהַ וְהַ וָה יִה: תֹּה\"וּ בְמִסְפָּר קָטָן עִם ג' אוֹתִיּוֹת גִימַטְרִיָּא ש' ש\"ד שד\"י. בּהוּ בְמִסְפָּר קָטָן גִימַטְרִיָּא צְבָאוֹת כָּזֶה ב' ב\"ה בֹהוּ. חֹשֶׁךְ בְּמִסְפָּר קָטָן עִם הַכּוֹלֵל גִימַטְרִיָּא אֱלֹהִים. רוּחַ בְּמִסְפָּר קָטָן עִם הַכּוֹלֵל בְּגִימַטְרִיָּא יהו\"ה בְמִסְפָּר קָטָן. רַעַשׁ בְּמִסְפָּר קָטָן עִם הַכּוֹלֵל גִימַטְרִיָּא בהוּ. קוֹל דְּמָמָה דַקָּה בְמִסְפָּר קַטָן עִם הַכּוֹלֵל יהו\"ה וְי\"ב יוֹתֵר כְּנֶגֶד שֵׁם י\"ב הַנִמְסָר לְאֵלִיָּהוּ בַמֵעַרָה. וְכֵן דַקָּה בְמִסְפָּר קָטָן עִם הַשְׁלֹשָׁה אוֹתִיּוֹת גִימַטְרִיָּא יב\"ק. גלעד\"ן</p>"],[9522012698,"<p>לְמָה בֵּי\"ת דּוֹמָה? לָאָדָם שֶׁנּוֹצַר בְּחָכְמָה, שֶׁסָּתוּם מִכָּל צַד וּפָתוּחַ מִלְפָנָיו, וְהָאָלֶ\"ף פְּתוּחָה מֵאַחֲרָיו. רוֹצֶה לוֹמַר, כִּי הִיא פְּתוּחָה לְקַבֵּל מִן הַכֶּתֶר, וְיֵשׁ לָהּ פֶּתַח לְהַשְׁפִּיעַ לַאֲחֵרִים: ע\"כ.</p>"],[9522012699,"<p>וּמִנַּיִן לָנוּ שֶׁשָּׁמַיִם הֵם הַקָּדוֹשׁ בָּרוּךְ הוּא? שֶׁכָּתוּב (מלכים א ח) וְאַתָּה תִּשְׁמַע הַשָּׁמַיִם. הַאִם שְׁלֹמֹה מִתְפַּלֵּל אֶל הַשָּׁמַיִם שֶׁיִּשְׁמְעוּ תְפִלָּתוֹ? אֶלָּא שֶׁנִּקְרָא שְׁמָן עַל שְׁמוֹ. וְלָמָּה נִקְרָא שָׁמַיִם? אֶלָּא שֶׁהוּא עָגֹל כְּמוֹ רֹאשׁ, וּמְלַמֵּד, הַמַּיִם מִימִינוֹ וְאֵשׁ מִשְּׂמֹאלוֹ וְהוּא בָּאֶמְצַע, שָׂא מַיִם, מֵאֵשׁ וּמִמַּיִם, וּמַכְנִיס בֵּינֵיהֶם שָׁלוֹם. בָּא הָאֵשׁ וּמָצָא מִצִּדּוֹ מִדַּת הָאֵשׁ. בָּא מַיִם וּמָצָא מִצִּדּוֹ מִדַּת הַמַּיִם, וְהַיְנוּ (איוב כה) עֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו. מָהֵם הַשָּׁמַיִם? מְלַמֵּד שֶׁגִּבֵּל הַקָּדוֹשׁ בָּרוּךְ הוּא אֵשׁ וּמַיִם וּטְפָחָן זֶה בָּזֶה, וְעָשָׂה מֵהֶן רֹאשׁ לִדְבָרָיו, שֶׁנֶּאֱמַר (תהלים קיט) רֹאשׁ דְּבָרְךְ אֱמֶת: ע\"כ.</p>"],[9522012700,"<p>וְהָאָרֶץ הָיְתָה תֹהוּ (בראשית א). בִּזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה בַּקְּלִפּוֹת הָאֵלֶּה, הָיָה בּוֹנֶה עוֹלָמוֹת וּמַחֲרִיבָן, וַהֲרֵי הֵקִימוּ שֶׁאֵין הַשְׁפָּעָה בְּכָל הָעוֹלָמוֹת, וְנָהָר שֶׁהוּא צַדִּיק יֶחֱרַב וְיָבֵשׁ בִּשְׁנֵי הָעוֹלָמוֹת, בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>וְיֵשׁ מִי שֶׁאוֹמֵר שֶׁעָלָה בְּמַחֲשַׁבְתּוֹ לִבְנוֹת עוֹלָמוֹת וּלְהַחֲרִיבָן, וְאָמַר זֶה מוֹעִיל לִי וְזֶה לֹא מוֹעִיל לִי. אֵלֶּה שֶׁנֶּאֱמַר בָּהֶם אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ - מוֹעִילִים לִי, וְהָאֲחֵרִים שֶׁנֶּאֱמַר בָּהֶם וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ, שֶׁמַּרְאֶה עַל עוֹלָמוֹת שֶׁעָלָה בִרְצוֹנוֹ לִבְנוֹתָם וְלֹא עָשָׂה אוֹתָם - עֲלֵיהֶם נֶאֱמַר תֹּהוּ וָבהוּ.</p>\n<p>וּבִזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בַּקְּלִפּוֹת הַלָּלוּ, נֶאֱמַר בּוֹ (איכה ב) סַכֹּתָ בֶּעָנָן לָךְ מֵעֲבוֹר תְּפִלָּה. תֹּהוּ וָחֹשֶׁךְ, עֲלֵיהֶם נֶאֱמַר (שמות יד) וַיְהִי הֶעָנָן וְהַחֹשֶׁךְ, וְאֵלּוּ קְלִפּוֹת הָאֱגוֹז. הַמֹּחַ מִבִּפְנִים שֶׁתָּלוּי (של שלש) לְאַרְבָּעָה צְדָדִים זֶה יְהֹוָ\"ה, שֶׁהוּא לֹא מְקַבֵּל טֻמְאָה, כְּמוֹ שֶׁנֶּאֱמַר (ירמיה כג) הֲלוֹא כֹה דְבָרִי כָּאֵשׁ נְאֻם ה'. מָה אֵשׁ לֹא מְקַבֶּלֶת טֻמְאָה, כָּךְ שְׁמוֹ לֹא מְקַבֵּל טֻמְאָה.</p>\n<p>וּבִזְמַן שֶׁמִּתְגַּבְּרוֹת הַקְּלִפּוֹת הַלָּלוּ וְנִשְׁבָּרוֹת מֵהָאֱגוֹז, הַתְּפִלָּה, שֶׁהִיא שְׁכִינָה, אֲדנָ\"י, עוֹלָה לְבַעְלָהּ שֶׁהוּא יְהֹוָ\"ה, וּמַעֲלָה הַכֹּל. שֶׁבִּזְמַן שֶׁהוּא מִתְכַּסֶּה מִמֶּנָּה בַּקְּלִפּוֹת הַלָּלוּ, הִיא נִקְרֵאת עֲנִיָּה יְבֵשָׁה, וְאֵין לָהּ אֶלָּא מַה שֶּׁנּוֹתְנִים עֲבָדִים בַּחֲשַׁאי.</p>\n<p>וּבְאוֹתוֹ זְמַן שֶׁמִּתְפַּשֵּׁט הַקָּדוֹשׁ בָּרוּךְ הוּא מִן הַקְּלִפּוֹת הַלָּלוּ, נֶאֱמַר (ישעיה ל) וְלֹא יִכָּנֵף עוֹד מוֹרֶיךְ וְהָיוּ עֵינֶיךְ רֹאוֹת אֶת מוֹרֶיךְ. וּמַה שֶּׁהָיְתָה יְבֵשָׁה, נֶאֱמַר בָּהּ (שם ו) מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ, וְנִקְרֵאת הַבְּרָכָה שֶׁלּוֹ, הַקָּרְבָּן שֶׁלּוֹ, עוֹלָה שֶׁלּוֹ שֶׁשּׂוֹרֵף כָּל הַקְּלִפּוֹת הַלָּלוּ.</p>\n<p>וְעוֹלָה אֶל הַקְּטֹרֶת הַקִּשּׁוּר שֶׁלּוֹ, הָעוֹלָה שֶׁלּוֹ, שֶׁכָּתוּב (ויקרא ו) זֹאת תּוֹרַת הָעֹלָה. הִיא הָעֹלָה - בִּתְפִלַּת שַׁחֲרִית, הִיא הָעֹלָה - אֵלָיו בִּתְפִלַּת מִנְחָה בְּכַמָּה רֵיחוֹת וּבְשָׂמִים שֶׁל גַּן עֵדֶן, שֶׁהִיא גַּן הַתּוֹרָה. זֶהוּ שֶׁכָּתוּב (שיר ד) גַּן נָעוּל אֲחֹתִי כַלָּה. סְתוּמָה שֶׁלֹּא נִפְתַּחַת אֶלָּא רַק לְבַעְלָהּ.</p>\n<p>וּכְשֶׁיָּבֹא בַּעְלָהּ, (תהלים נא) אֲדנָי שְׂפָתַי תִּפְתָּח, שֶׁהוּא דֶּלֶת עֶלְיוֹנָה נִפְתַּחַת אֵלָיו כְּתָרִים (בשני) עַמּוּדֵי אֱמֶת (נצח והוד) וּמְקַבֶּלֶת אוֹתוֹ בִּשְׁתֵּי זְרוֹעוֹת. זֶהוּ שֶׁכָּתוּב (שיר ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי.</p>\n<p>יְהֹוָ\"ה יוֹרֵד אֵלֶיהָ, וְזֶהוּ סוֹד אָמֵ\"ן גִּימַטְרִיָּא יאהדונה\"י, שֶׁהוּא חִבּוּר שְׁנֵי שֵׁמוֹת בְּאוֹתִיּוֹת, וְלָכֵן גָּדוֹל הָעוֹנֶה אָמֵן יוֹתֵר מֵהַמְבָרֵךְ, בִּזְמַן שֶׁהֵם שְׁנַיִם בְּרֹאשׁ הַצַּדִּיקִים.</p>\n<p>אֲבָל כְּשֶׁהֵם בְּרֹאשׁ הָרְשָׁעִים, כְּנֶסֶת יִשְׂרָאֵל אוֹמֶרֶת לָהֶם, (שם א) אַל תִּרְאֻנִי שֶׁאֲנִי שְׁחַרְחֹרֶת, מֵאֵלֶּה שֶׁשּׁוֹרִים לְפַתּוֹת לִבְנֵי אָדָם, כְּמוֹ שֶׁהָיוּ מְפַתִּים אֶת יִשְׂרָאֵל בָּעֵגֶל בְּשֵׁשׁ הַשָּׁעוֹת. זֶהוּ שֶׁכָּתוּב (שמות לב) וַיַּרְא הָעָם כִּי בֹּשֵׁשׁ מֹשֶׁה לָרֶדֶת מִן הָהָר, וּבֵאֲרוּהָ, מַה זֶּה בֹּשֵׁשׁ? אֶלָּא בְּשֵׁשׁ שָׁעוֹת עָשׂוּ אֶת הָעֵגֶל, כְּדֵי לְהַפְרִידָם מִשֶּׁבַע. זֶה שֶׁכָּתוּב אַךְ בַּיּוֹם הָרִאשׁוֹן תַּשְׁבִּיתוּ שְׂאֹר. אַךְ - חִלֵּק בֵּין שֵׁשׁ לְשֶׁבַע.</p>\n<p>וְלָכֵן אָמְרָה כְּנֶסֶת יִשְׂרָאֵל, שֶׁשְּׁזָפַתְנִי הַשָּׁמֶשׁ. גָּרְמוּ שֶׁהִסְתַּלֵּק מִמֶּנִּי ו' (תפארת), שֶׁהוּא הַשֵּׁשׁ, וְאוֹר הַשֵּׁשׁ שֶׁהָיָה מֵאִיר בַּסֵּתֶר שֶׁל שֵׁשׁ תֵּבוֹת, שֶׁהֵם שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד, בְּנֵי אִמִּי נִחֲרוּ בִּי, נִחַר גְּרוֹנָם שֶׁבִּטְּלוּ קְרִיאַת שְׁמַע, שֶׁנֶּאֱמַר בָּהּ (תהלים קמט) רוֹמְמוֹת אֵל בִּגְרוֹנָם, וְלָכֵן שָׂמֻנִי נֹטֵרָה אֶת הַכְּרָמִים, שֶׁהֵם שְׁאָר אֻמּוֹת עֵרֶב רַב. וְלָכֵן כַּרְמִי שֶׁלִּי לֹא נָטָרְתִּי, וְלָכֵן אוֹתָם עֵרֶב רַב מַצְלִיחִים בַּכֹּל.</p>\n<p>כָּתְנוֹת עוֹר חֲשׁוּכֵי הָעֵינַיִם, שֶׁנֶּאֱמַר בָּהֶם (בראשית כז) וַתִּכְהֶיןָ עֵינָיו מֵרְאוֹת, לְהִסְתַּכֵּל עַל אוֹתָם שֶׁנֶּאֱמַר בָּהֶם (יחזקאל א) נִפְתְּחוּ הַשָּׁמַיִם וָאֶרְאֶה מַרְאוֹת אֱלֹהִים, שֶׁהֵם חָמֵשׁ פְּעָמִים אוֹר שֶׁבְּמַעֲשֵׂה בְרֵאשִׁית, כָּתְנוֹת אוֹר הֵם.</p>\n<p>וְהָאָרֶץ הָיְתָה תֹהוּ. וְהָאָרֶץ - הֲרֵי אֶחָד, תֹּהוּ - שְׁנַיִם, בּהוּ - שְׁלֹשָׁה. חֹשֶׁךְ - אַרְבָּעָה. תְּהוֹם - חֲמִשָּׁה. וְאַרְבָּעָה הֵם שֶׁכְּלוּלִים בַּגּוּף, וְהֵם אַרְבָּעָה יְסוֹדוֹת שֶׁהֵם קְלִפּוֹת הָאֱגוֹז, וְלָכֵן וְהָאָרֶץ הָיְתָה תֹהוּ. וּבֵאֲרוּהָ הָיְתָה - מִקֹּדֶם לָכֵן, שֶׁכָּךְ דֶּרֶךְ הַקְּלִפּוֹת שֶׁקּוֹדְמוֹת לַמֹּחַ. וְרוּחַ אֱלֹהִים - זוֹ רוּחוֹ שֶׁל מָשִׁיחַ, מִיָּד שֶׁתְּהֵא מְרַחֶפֶת עַל פְּנֵי מֵי הַתּוֹרָה, מִיָּד תִּהְיֶה גְּאֻלָּה. זֶהוּ שֶׁכָּתוּב וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר.</p>"],[9522012701,"<p>אָמַר רַבִּי בְּרַכְיָה, מַה זֶּה שֶׁכָּתוּב וְהָאָרֶץ הָיְתָה תֹהוּ? מַה מַּשְׁמִיעַ הָיְתָה? שֶׁכְּבָר הָיְתָה, וּמַה זֶּה תֹּהוּ? דָּבָר הַמַּתְהֶה אֶת בְּנֵי אָדָם. וּמַה זֶּה בֹּהוּ? דָּבָר שֶׁיֵּשׁ בּוֹ מַמָּשׁ, שֶׁכָּתוּב בּהוּ - בּוֹ הוּא, עַל שֵׁם מַה שֶּׁכָּתוּב (קהלת ז) גַּם אֶת זֶה לְעֻמּת זֶה עָשָׂה הָאֱלֹהִים. בָּרָא בהוּ וְשָׂם מְקוֹמוֹ בְּשָׁלוֹם. בָּרָא תֹהוּ וְשָׂם מְקוֹמוֹ בְּרָע. בֹהוּ בְּשָׁלוֹם, שֶׁכָּתוּב (איוב כה) עֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו. מְלַמֵּד שֶׁמִּיכָאֵל שַׂר יְמִינוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא - מַיִם וּבָרָד, וְגַבְרִיאֵל שַׂר שְׂמֹאלוֹ - אֵשׁ. וְשָׂם שָׁלוֹם בֵּינֵיהֶם מַכְרִיעַ, וְהַיְנוּ שֶׁכָּתוּב עֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו.</p>\n<p>וּמִנַּיִן לָנוּ שֶׁבּהוּ שָׁלוֹם? שֶׁכָּתוּב (ישעיה מה) עֹשֶׂה שָׁלוֹם וּבוֹרֵא רָע, הָא כֵיצַד? רָע מִתֹּהוּ, וְשָׁלוֹם מִבֹּהוּ. בָּרָא תֹהוּ וְשָׂם מְקוֹמוֹ בְּרָע, שֶׁנֶּאֱמַר עֹשֶׂה שָׁלוֹם וּבוֹרֵא רָע. בָּרָא בהוּ וְשָׂם מְקוֹמוֹ בְּשָׁלוֹם, שֶׁנֶּאֱמַר עֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו:</p>\n<p>וַיְשַׁלְּחֵהוּ ה' אֱלֹהִים, מִיָּד (ולמשיח) אֶת הַמָּשִׁיחַ שֶׁהָיָה בְּגַן עֵדֶן, כְּמוֹ שֶׁנֶּאֱמַר בּוֹ (בראשית ג) וַיְשַׁלְּחֵהוּ (וגו') מִגַּן עֵדֶן, מֵעִדּוּנוֹ, וְלָמָּה? לַעֲבֹד אֶת הָאֲדָמָה, שֶׁהִיא שְׁכִינָה. בִּגְלַל זֶה וַיְשַׁלְּחֵהוּ, מִיָּד שֶׁיֵּצֵא מִשָּׁם. וַיַּשְׁכֵּן מִקֶּדֶם - לַגָּן - אֶת הַכְּרוּבִים, מָשִׁיחַ בֶּן דָּוִד וּמָשִׁיחַ בֶּן יוֹסֵף שֶׁמּוֹשֵׁךְ רוּחַ הַמָּשִׁיחַ, שֶׁנֶּאֱמַר בּוֹ וְרוּחַ אֱלֹהִים, זֶה שִׁילֹ\"ה, אוֹתוֹ שֶׁנֶּאֱמַר בּוֹ (במדבר יא) וְאָצַלְתִּי מִן הָרוּחַ, שֶׁכָּךְ עוֹלֶה שִׁילֹה כְּחֶשְׁבּוֹן מֹשֶׁה. וַיַּשְׁכֵּן מִקֶּדֶם, שֶׁמַּקְדִּים שִׁילֹה לִשְׁנֵיהֶם, כְּדֵי שֶׁתִּהְיֶה מְרַחֶפֶת עַל פְּנֵי הַתּוֹרָה, וְהַגְּאֻלָּה תְּלוּיָה בּוֹ, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>וְאֵת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת, מִיָּד יִהְיֶה בְיָדוֹ, וּמַהוּ? הַמַּטֶּה. מטטרו\"ן מִתְהַפֵּךְ מִמַּטֶּה לְנָחָשׁ וּמִנָּחָשׁ לְמַטֶּה. וְעוֹד, מַטֶּה זוֹ שְׁכִינָה תַּחְתּוֹנָה, וְאִם זָכוּ יִשְׂרָאֵל - כְּלַפֵּי חֶסֶד, לְיָמִין, וְיֵצְאוּ בְרַחֲמִים. וְאִם לָאו - מַטֶּה כְּלַפֵּי חוֹבָה, לְצַד הַגְּבוּרָה, שֶׁשָּׁם הַנָּחָשׁ אֵל אַחֵר שֶׁמְּבַקֵּשׁ לִשְׁפֹּךְ דָּם, וְנֶהֱרָג מָשִׁיחַ וְרַבִּים מִיִּשְׂרָאֵל,</p>\n<p>וְלָכֵן נֶאֱמַר (רות ג) שִׁכְבִי עַד הַבּקֶר, שֶׁהוּא בֹּקֶר שֶׁל אַבְרָהָם שֶׁיִּהְיֶה מַטֶּה כְּלַפֵּי חֶסֶד. וּבִגְלַל זֶה וְאֵת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת, וְהַכֹּל כְּדֵי לִשְׁמֹר אֶת דֶּרֶךְ עֵץ הַחַיִּים, שֶׁהִיא תּוֹרָה, שֶׁנֶּאֱמַר בָּהּ (משלי ג) עֵץ חַיִּים הִיא,</p>\n<p>וְהִיא תּוֹרָה שֶׁבְּעַל פֶּה. אִם זָכָה אָדָם - הִיא סַם חַיִּים שֶׁלּוֹ, וְאִם לָאו - הִיא מִתְהַפֶּכֶת לוֹ לְסַם הַמָּוֶת. וַהֲרֵי פֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה כָּךְ, כְּמוֹ שֶׁהַמַּטֶּה שֶׁהִתְהַפֵּךְ לְנָחָשׁ וּמִנָּחָשׁ לְמַטֶּה. וּבְאוֹתוֹ זְמַן יִמָּחוּ מִן הָעוֹלָם כָּל אוֹתָם שֶׁנֶּאֱמַר בָּהֶם (שמות ז) וַיַּעֲשׂוּ כֵן חַרְטֻמֵּי מִצְרַיִם בְּלָטֵיהֶם:</p>"],[9522012702,"<p>יָשַׁב רַבִּי בוֹן וְדָרַשׁ, מַהוּ שֶׁכָּתוּב (ישעיה מה) יוֹצֵר אוֹר וּבוֹרֵא חֹשֶׁךְ? אֶלָּא אוֹר שֶׁיֵּשׁ בּוֹ מַמָּשׁ כָּתוּב בּוֹ יְצִירָה, חֹשֶׁךְ שֶׁאֵין בּוֹ מַמָּשׁ כָּתוּב בּוֹ בְּרִיאָה, כְּמוֹ שֶׁנֶּאֱמַר (עמוס ד) יוֹצֵר הָרִים וּבֹרֵא רוּחַ. אִם תִּרְצֶה אֹמַר, אוֹר שֶׁיֵּשׁ בּוֹ מַמָּשׁ כָּתוּב בּוֹ עֲשִׂיָּה, שֶׁכָּתוּב וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר, וְאֵין הֲוָיָה אֶלָּא עֲשִׂיָּה, וְקוֹרֵא בּוֹ יְצִירָה. חֹשֶׁךְ שֶׁלֹּא הָיָה בּוֹ עֲשִׂיָּה אֶלָּא הַבְדָּלָה וְהַפְרָשָׁה, קוֹרֵא בּוֹ בְּרִיאָה, כְּמוֹ שֶׁאַתָּה אוֹמֵר הִבְרִיא פְלוֹנִי וְכוּ'. אָמַר רַבִּי בְּרַכְיָה, מַהוּ שֶׁכָּתוּב וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר, וְלֹא אָמַר וְהָיָה? מָשָׁל לְמֶלֶךְ שֶׁהָיָה לוֹ חֵפֶץ נָאֶה וְהִקְצָהוּ, עַד שֶׁזִּמֵּן לוֹ מָקוֹם וְשָׂמָהוּ שָׁם. זֶהוּ שֶׁכָּתוּב יְהִי אוֹר וַיְהִי אוֹר, שֶׁכְּבָר הָיָה:</p>"],[9522012703,"<p>שְׁבִיעִי הָיָה בְּמִזְרָחוֹ שֶׁל עוֹלָם, וּמִשָּׁם בָּא זַרְעָם שֶׁל יִשְׂרָאֵל, כִּי חוּט הַשִּׁדְרָה מָשׁוּךְ מִן הַמֹּחַ שֶׁל אָדָם וּבָא לָאַמָּה, וּמִשָּׁם הוּא הַזֶּרַע, שֶׁכָּתוּב (ישעיה מג) מִמִּזְרָח אָבִיא זַרְעֶךְ. כְּשֶׁיִּשְׂרָאֵל טוֹבִים - מִזֶּה הַמָּקוֹם אָבִיא זַרְעֶךְ, יִתְחַדֵּשׁ לְךְ זֶרַע חָדָשׁ.</p>\n<p>וּכְשֶׁיִּשְׂרָאֵל רָעִים - מִן הַזֶּרַע שֶׁכְּבָר בָּא לָעוֹלָם, שֶׁכָּתוּב (קהלת א) דּוֹר הֹלֵךְ וְדוֹר בָּא. דּוֹר שֶׁכְּבָר בָּא. וּמַהוּ מִמַּעֲרָב אֲקַבְּצֶךָּ? מֵאוֹתָהּ מִדָּה שֶׁנּוֹטָה תָּמִיד לַמַּעֲרָב. וְלָמָּה נִקְרָא מַעֲרָב? מִפְּנֵי שֶׁשָּׁם מִתְעָרֵב כָּל הַזֶּרַע.</p>\n<p>מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְבֶן מֶלֶךְ שֶׁהָיְתָה לוֹ כַּלָּה נָאָה וּצְנוּעָה בְּחַדְרוֹ, וְהָיָה לוֹקֵחַ מִבֵּית אָבִיו עֹשֶׁר וּמֵבִיא לָהּ תָּמִיד, וְלוֹקַחַת הַכֹּל וּמַצְנַעַת אוֹתוֹ תָּמִיד וּמְעָרֶבֶת הַכֹּל. לְסוֹף יָמִים בִּקֵּשׁ לִרְאוֹת מָה אָסַף וּמַה קִּבֵּץ. הַיְנוּ שֶׁכָּתוּב (ישעיה מג) וּמִמַּעֲרָב אֲקַבְּצֶךָּ. וּמַה הוּא בֵּית אָבִיו? שֶׁכָּתוּב מִמִּזְרָח אָבִיא זַרְעֶךְ. מְלַמֵּד שֶׁמִּמִּזְרָח מֵבִיא, וְזוֹרֵעַ בַּמַּעֲרָב, וְאַחַר כָּךְ הוּא מְקַבֵּץ מַה שֶּׁזָּרַע: ע\"כ.</p>"],[9522012704,"<p>זַיִ\"ן, מַה מַּעֲשֵׂהוּ? כְּמִנְיַן יְמוֹת הַשָּׁבוּעַ, לְלַמֶּדְךְ שֶׁכָּל יוֹם יֵשׁ לוֹ כֹּחַ. וּמַה מַּעֲשֵׂהוּ כָּאן? לְלַמֶּדְךְ שֶׁכְּשֵׁם שֶׁיֵּשׁ חָכְמָה גְּדוֹלָה בָּאֹזֶן לְאֵין תַּכְלִית, כָּךְ יֵשׁ הַכֹּחַ הַהוּא בְּכָל הָאֵבָרִים. וְאֵיזֶה אֵבָרִים? שֶׁבַע שֶׁיֵּשׁ בָּאָדָם, שֶׁכָּתוּב (בראשית ט) כִּי בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם:</p>"],[9522012705,"<p>נִשְׁמַת הַזָּכָר מִן הַזָּכָר, וְנִשְׁמַת הַנְּקֵבָה מִן הַנְּקֵבָה, וְהַיְנוּ שֶׁהָלַךְ הַנָּחָשׁ אַחֲרֵי חַוָּה. אָמַר: הוֹאִיל וְנִשְׁמָתָהּ מִן הַצָּפוֹן, אֲסִיתֶנָּה מְהֵרָה. וּמָה הַהֲסָתָה שֶׁהָיְתָה? מִשּׁוּם שֶׁבָּא עָלֶיהָ. שָׁאֲלוּ תַּלְמִידָיו: אֵיךְ הָיָה הַמַּעֲשֶׂה? אָמַר לָהֶם: סמא\"ל הָרָשָׁע קָשַׁר עִם כָּל צִבְאוֹת מַעְלָה עַל רַבּוֹ, מִשּׁוּם שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא וּרְדוּ בִדְגַת הַיָּם וּבְעוֹף הַשָּׁמַיִם. אָמַר, הֵיאַךְ אוּכַל לְהַחֲטִיאוֹ וּלְגָרְשׁוֹ מִלְּפָנָיו? יָרַד עִם כָּל חֵילוֹתָיו וּבִקֵּשׁ לוֹ בָּאָרֶץ חָבֵר כְּמוֹתוֹ. וּמִי הוּא? נָחָשׁ, וְהָיָה לוֹ דְּמוּת גָּמָל. רָכַב עָלָיו וּבָא לוֹ אֵצֶל הָאִשָּׁה.</p>\n<p>אָמַר לָהּ: אַף כִּי אָמַר אֱלֹהִים לֹא תֹאכְלוּ מִכֹּל עֵץ הַגָּן. אָמַר, אֲבַקֵּשׁ יוֹתֵר וְאוֹסִיף, כְּדֵי שֶׁתִּגְרַע הִיא. אָמְרָה: לֹא מְנָעָנוּ אֶלָּא - מֵעֵץ הַדַּעַת אֲשֶׁר בְּתוֹךְ הַגָּן אָמַר אֱלֹהִים לֹא תֹאכְלוּ מִמֶּנּוּ וְלֹא תִגְּעוּ בּוֹ פֶּן תְּמֻתוּן. וְהוֹסִיפָה שְׁנֵי דְבָרִים. אָמְרָה, מִפְּרִי הָעֵץ אֲשֶׁר בְּתוֹךְ הַגָּן אָמַר אֱלֹהִים לֹא תֹאכְלוּ, וְלֹא נֶאֱמַר לָהּ אֶלָּא מֵעֵץ הַדַּעַת. וְאָמְרָה, לֹא תִגְּעוּ בּוֹ פֶּן תְּמֻתוּן.</p>\n<p>מֶה עָשָׂה סמא\"ל הָרָשָׁע? הָלַךְ וְנָגַע בָּאִילָן, וְהָיָה הָאִילָן צוֹוֵחַ וְאוֹמֵר: (תהלים לו) אַל תְּבוֹאֵנִי רֶגֶל גַּאֲוָה וְיַד רְשָׁעִים אַל תְּנִדֵנִי, אַל תִּגַּע בִּי, שֶׁנֶּאֱמַר וְיַד רְשָׁעִים אַל תְּנִדֵנִי. הָלַךְ וְאָמַר לָאִשָּׁה: הֲרֵי נָגַעְתִּי בָּאִילָן וְלֹא מַתִּי, אַף אַתְּ תִּגְּעִי בָּאִילָן וְלֹא תָמוּתִי. הָלְכָה הָאִשָּׁה וְנָגְעָה בָּאִילָן, וְרָאֲתָה מַלְאַךְ הַמָּוֶת בָּא כְּנֶגְדָּהּ. אָמְרָה: אוּלַי עַכְשָׁו אֲנִי מֵתָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה לוֹ אִשָּׁה אַחֶרֶת וְנוֹתְנָהּ לָאָדָם, אֶלָּא הֲרֵינִי גּוֹרֶמֶת לוֹ שֶׁיֹּאכַל עִמִּי. אִם נָמוּת - נָמוּת שְׁנֵינוּ, וְאִם נִחְיֶה - נִחְיֶה שְׁנֵינוּ. וְלָקְחָה מִפִּרְיוֹ וְנָתְנָה גַּם לְבַעְלָהּ.</p>\n<p>נִתְפַּקְּחוּ עֵינֵי שְׁנֵיהֶם וְקָהוּ שִׁנָּיו. אָמַר לָהּ: מַה שֶׁהֶאֱכַלְתִּנִי שֶׁקָּהוּ שִׁנַּי? כָּךְ קָהוּ שִׁנֵּי כָּל הַבְּרִיּוֹת. יָשַׁב לוֹ בְּדִין אֱמֶת, שֶׁנֶּאֱמַר (שם ט) יָשַׁבְתָּ לְכִסֵּא שׁוֹפֵט צֶדֶק. קָרָא לָאָדָם וְאָמַר לוֹ: לָמָּה בָּרַחְתָּ מִפָּנַי? אָמַר לוֹ: אֶת קֹלְךְ שָׁמַעְתִּי בַּגָּן, וְרָעֲדוּ עַצְמוֹתַי, וָאִירָא כִּי עֵירֹם אָנֹכִי וָאֵחָבֵא. כִּי עֵירֹם אָנֹכִי - מִפֹּעֲלִי. כִּי עֵירֹם אָנֹכִי - מִצִּוּוּיִי, כִּי עֵירֹם אָנֹכִי - מִמַּעֲשַׂי, וָאֵחָבֵא.</p>\n<p>מֶה הָיָה לְבוּשׁוֹ שֶׁל אָדָם? עוֹר שֶׁל צִפֹּרֶן, וְהִפְשִׁיטוֹ מֵעָלָיו. רָאָה עַצְמוֹ עָרֹם, שֶׁנֶּאֱמַר מִי הִגִּיד לְךְ כִּי עֵירֹם אָתָּה. אָמַר אָדָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא: רִבּוֹנוֹ שֶׁל עוֹלָם, כְּשֶׁהָיִיתִי לְבַדִּי שֶׁמָּא חָטָאתִי לָךְ, אֶלָּא הָאִשָּׁה שֶׁהֵבֵאתָ לִי הִיא הִדִּיחָה אוֹתִי מִדְּבָרֶיךְ, שֶׁנֶּאֱמַר הָאִשָּׁה אֲשֶׁר נָתַתָּה עִמָּדִי הִוא נָתְנָה לִּי מִן הָעֵץ.</p>\n<p>אָמַר לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא: לֹא דַּיֵּךְ שֶׁחָטָאת, אֶלָּא שֶׁהֶחֱטֵאת לָאָדָם? אָמְרָה לְפָנָיו: רִבּוֹנוֹ שֶׁל עוֹלָם, הַנָּחָשׁ הִשִּׁיאַנִי לַחֲטֹא לְפָנֶיךְ. הֵבִיא שְׁלָשְׁתָּם וְגָזַר עֲלֵיהֶם גְּזֵרוֹת דִּין. תִּשְׁעָה וּשְׁלֹשִׁים קְלָלוֹת וּמָוֶת, וְהִפִּיל סמא\"ל וְאֶת הַכַּת שֶׁלּוֹ מִמְּקוֹם קְדֻשָּׁתָם מִן הַשָּׁמַיִם, וְקִצֵּץ רַגְלָיו שֶׁל נָחָשׁ, וְאֵרְרוּ מִכָּל חַיָּה וּמִכָּל בְּהֵמָה, וּפָקַד עָלָיו שֶׁיִּהְיֶה מַפְשִׁיט אֶת עוֹרוֹ אַחַר שֶׁבַע שָׁנִים: ע\"כ.</p>"],[9522012706,"<p>וּבְלוֹא מְחִיר יַיִן וְחָלָב (ישעיה נה). מַהוּ יַיִן וְחָלָב? מָה עִנְיַן זֶה אֵצֶל זֶה? אֶלָּא מְלַמֵּד שֶׁהַיַּיִן הוּא פַּחַד, וְחָלָב הוּא חֶסֶד. וּמִפְּנֵי מָה הִזְכִּיר יַיִן תְּחִלָּה? מִפְּנֵי שֶׁהוּא קָרוֹב אֵלֵינוּ יוֹתֵר. יַיִן וְחָלָב עוֹלֶה עַל דַּעְתְּךְ? אֶלָּא אֱמֹר, דְּמוּת יַיִן וְחָלָב: ע\"כ.</p>"],[9522012707,"<p>רַבִּי חִיָּיא אָמַר, מֵעוֹלָם זֶה הָיוּ, וּגְבָרִים גִּבּוֹרִים שֶׁל צַד הָרָע הָיוּ, שֶׁכָּתוּב (בראשית ו) אַנְשֵׁי הַשֵּׁם. אַנְשֵׁי שֵׁם לֹא כָתוּב, אֶלָּא אַנְשֵׁי הַשֵּׁם. כְּמוֹ זֶה כָּתוּב (תהלים כה) זְכֹר רַחֲמֶיךְ ה' וַחֲסָדֶיךְ כִּי מֵעוֹלָם הֵמָּה. מֵעוֹלָם וַדַּאי לָקַח אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהֵם הָאָבוֹת הָרִאשׁוֹנִים לִהְיוֹת מֶרְכָּבָה קְדוֹשָׁה לְמַעְלָה. אָמַר רַבִּי יִצְחָק, מֵעוֹלָם - זוֹהִי מִטָּתוֹ שֶׁלִּשְׁלֹמֹה, שֶׁכָּתוּב וְכוּ': ע\"כ.</p>"],[9522012708,"<p>וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר. וְאָמַר רַבִּי יוֹחָנָן, שְׁנֵי אוֹרוֹת הַגְּדוֹלִים הָיוּ, שֶׁכָּתוּב וַיְהִי אוֹר, וְעָלָיו נֶאֱמַר כִּי טוֹב. וְלָקַח הַקָּדוֹשׁ בָּרוּךְ הוּא הָאֶחָד וּגְנָזוֹ לַצַּדִּיקִים לֶעָתִיד לָבא, שֶׁכָּתוּב (תהלים לא) מָה רַב טוּבְךְ אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךְ פָּעַלְתָּ לַחוֹסִים בָּךְ נֶגֶד בְּנֵי אָדָם.</p>\n<p>מְלַמֵּד שֶׁאוֹר הָרִאשׁוֹן אֵין כָּל בְּרִיָּה יְכוֹלָה לְהִסְתַּכֵּל בּוֹ, שֶׁכָּתוּב וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב, וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה וְהִנֵּה טוֹב מְאֹד. רָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת כָּל אֲשֶׁר עָשָׂה, רָאָה טוֹב מְאֹד מַזְהִיר וּבָהִיר. וְלָקַח מֵאוֹרוֹ הַטּוֹב, וְכָלַל שְׁלֹשִׁים וּשְׁתַּיִם נְתִיבוֹת הַחָכְמָה, וּנְתָנוֹ לָעוֹלָם הַזֶּה,</p>\n<p>וְהַיְנוּ שֶׁכָּתוּב (משלי ד) כִּי לֶקַח טוֹב נָתַתִּי לָכֶם תּוֹרָתִי אַל תַּעֲזבוּ. הֱוֵי אוֹמֵר: אוֹצָרָהּ שֶׁל תּוֹרָה שֶׁבְּעַל פֶּה. וְאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אִם יִשְׁמְרוּ זֹאת הַמִּדָּה בָּעוֹלָם הַזֶּה, שֶׁ את הַמִּדָּה נֶחְשֶׁבֶת בִּכְלַל הָעוֹלָם הַזֶּה, וְהִיא תּוֹרָה שֶׁבְּעַל פֶּה, יִזְכּוּ לְחַיֵּי הָעוֹלָם הַבָּא שֶׁהוּא הַטּוֹב הַגָּנוּז. וּמָה הוּא עֻזּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא?</p>\n<p>שֶׁכָּתוּב (חבקוק ג) וְנֹגַהּ כָּאוֹר תִּהְיֶה. עָתִיד הַנֹּגַהּ שֶׁנִּלְקַח מֵהָאוֹר הָרִאשׁוֹן לִהְיוֹת כָּאוֹר, אִם יְקַיְּמוּ בָנַי הַתּוֹרָה וְהַמִּצְוָה אֲשֶׁר כָּתַבְתִּי לְהוֹרוֹתָם. וְכָתוּב (משלי א) שְׁמַע בְּנִי מוּסַר אָבִיךְ וְאַל תִּטֹּשׁ תּוֹרַת אִמֶּךְ,</p>\n<p>וְכָתוּב (חבקוק ג) וְקַרְנַיִם מִיָּדוֹ לוֹ, וְשָׁם חֶבְיוֹן עֻזֹּה. וּמַהוּ חֶבְיוֹן עֻזֹּהּ? אֶלָּא אוֹתוֹ הָאוֹר שֶׁגָּנַז וְהֶחְבִּיא, שֶׁנֶּאֱמַר צָפַנְתָּ לִּירֵאֶיךְ. וְזֶה שֶׁנִּשְׁאָר לָנוּ - פָּעַלְתָּ לַחוֹסִים בָּךְ, אוֹתָם שֶׁחוֹסִים בְּצִלְּךְ בָּעוֹלָם הַזֶּה וְשׁוֹמְרִים תּוֹרָתְךְ וּמְקַיְּמִים מִצְווֹתֶיךְ, וּמְקַדְּשִׁים שִׁמְךְ הַגָּדוֹל וּמְיַחֲדִים בַּסֵּתֶר וּבַגָּלוּי, שֶׁנֶּאֱמַר נֶגֶד בְּנֵי אָדָם.</p>\n<p>אָמַר רַבִּי רְחוּמַאי, מְלַמֵּד שֶׁהִיא אוֹרָה לְיִשְׂרָאֵל, וְתוֹרָה אוֹרָה, שֶׁנֶּאֱמַר (משלי ו) כִּי נֵר מִצְוָה וְתוֹרָה אוֹר. וְאָמַר נֵר - זוֹ מִצְוָה, וּמִצְוָה - זוֹ תּוֹרָה שֶׁבְּעַל פֶּה. אוֹר - זֶה תּוֹרָה שֶׁבִּכְתָב. אֶלָּא מִתּוֹךְ שֶׁכְּבָר נִתְקַיֵּם הָאוֹר, קוֹרֵא לוֹ אוֹר. מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְאָדָם צָנוּעַ בְּסִפֵּי הַבַּיִת, אַף עַל פִּי שֶׁיּוֹם הוּא וְאוֹר גָּדוֹל בָּעוֹלָם, אֵין אָדָם רוֹאֶה בְּתוֹךְ בֵּיתוֹ אֶלָּא אִם כֵּן הִכְנִיס בּוֹ נֵר. נֵר - תּוֹרָה שֶׁבְּעַל פֶּה. אַף עַל פִּי שֶׁהִיא נֵר, צְרִיכָה לָהּ תּוֹרָה לְפָרֵק קֻשְׁיוֹתֶיהָ וּלְבָאֵר סוֹדוֹתֶיהָ,</p>\n<p>וּמִי הוּא? יִרְאַת ה', זֶה הָאוֹר הָרִאשׁוֹן. שֶׁאָמַר רַבִּי מֵאִיר, מַהוּ שֶׁכָּתוּב וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר, וְלֹא אָמַר לוֹ וַיְהִי כֵן? מְלַמֵּד שֶׁהָאוֹר הַהוּא גָּדוֹל, וְאֵין כָּל בְּרִיָּה יְכוֹלָה לְהִסְתַּכֵּל בּוֹ, גְּנָזוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לָצַּדִּיקִים לֶעָתִיד לָבא,</p>\n<p>וְהִיא מִדַּת כָּל סְחוֹרָה שֶׁבָּעוֹלָם, וְהוּא כֹּחַ אֶבֶן יְקָרָה שֶׁקּוֹרִין סֹחָרֶת וְדָר. וְעַל מָה הִיא מִדַּת דָּר? אֶלָּא מְלַמֵּד שֶׁלָּקַח הַקָּדוֹשׁ בָּרוּךְ הוּא מִזִּיוָהּ אַחַת מֵאַלְפַּיִם, וּבָנָה מִמֶּנָּה אֶבֶן יְקָרָה נָאָה וּמְקֻשֶּׁטֶת, וְכָלַל בָּהּ כָּל הַמִּצְווֹת. בָּא אַבְרָהָם וּבִקֵּשׁ כֹּחוֹ לָתֵת לוֹ, נָתְנוּ לוֹ אֶבֶן יְקָרָה זוֹ וְלֹא רָצָה אוֹתָהּ. זָכָה וְנָטַל מִדָּתוֹ, שֶׁנֶּאֱמַר (מיכה ז) תִּתֵּן אֱמֶת לְיַעֲקֹב חֶסֶד לְאַבְרָהָם.</p>\n<p>בָּא יִצְחָק וּבִקֵּשׁ כֹּחוֹ, וְנָתְנוּ לוֹ וְלֹא רָצָה בָּהּ. זָכָה וְנָטַל מִדָּתוֹ, שֶׁהָיָה מִדַּת הַגְּבוּרָה, דְּהַיְנוּ הַפַּחַד, שֶׁכָּתוּב (בראשית לא) וַיִּשָּׁבַע יַעֲקֹב בְּפַחַד אָבִיו יִצְחָק. בָּא יַעֲקֹב וְרָצָה בָּהּ וְלֹא נְתָנוּהוּ לוֹ. אָמַר לוֹ, הוֹאִיל וְאַבְרָהָם מִלְמַעְלָה וְיִצְחָק לְמַטָּה, אַתָּה תִהְיֶה בָּאֶמְצַע וְתִכְלֹל שְׁלָשְׁתָּם, שֶׁכָּתוּב תִּתֵּן אֱמֶת לְיַעֲקֹב.</p>\n<p>וּמַהוּ הָאֶמְצַע? הַיְנוּ שָׁלוֹם, וַהֲרֵי כָּתוּב תִּתֵּן אֱמֶת לְיַעֲקֹב? אֱמֶת וְשָׁלוֹם הֵם אֶחָד, כְּמוֹ שֶׁנֶּאֱמַר (אסתר ט) דִּבְרֵי שָׁלוֹם וֶאֱמֶת, (ישעיה לט) כִּי יִהְיֶה שָׁלוֹם וֶאֱמֶת בְּיָמָי, וְהַיְנוּ שֶׁכָּתוּב (שם נח) וְהַאֲכַלְתִּיךְ נַחֲלַת יַעֲקֹב אָבִיךְ. דְּהַיְנוּ נַחֲלָה גְּמוּרָה שֶׁיֵּשׁ לוֹ הַחֶסֶד וְהַפַּחַד וְהָאֱמֶת וְהַשָּׁלוֹם.</p>\n<p>וּלְפִיכָךְ אָמַר (תהלים קיח) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה. אֶבֶן מָאֲסוּ - אַבְרָהָם וְיִצְחָק, שֶׁבָּנוּ אֶת הָעוֹלָם, הָיְתָה עַתָּה לְרֹאשׁ פִּנָּה. וְלָמָּה מָאֲסוּ בָּהּ, וַהֲלֹא נֶאֱמַר (בראשית כו) עֵקֶב אֲשֶׁר שָׁמַע אַבְרָהָם בְּקֹלִי וַיִּשְׁמֹר מִשְׁמַרְתִּי מִצְותַי חֻקּוֹתַי וְתוֹרֹתַי? מַה זֶּה מִשְׁמַרְתִּי? אָמְרָה מִדַּת חֶסֶד: שֶׁכָּל יְמֵי הֱיוֹת אַבְרָהָם בָּעוֹלָם לֹא הֻצְרַכְתִּי אֲנִי לַעֲשׂוֹת מְלַאכְתִּי, שֶׁהֲרֵי אַבְרָהָם עָמַד שָׁם בִּמְקוֹמִי. וַיִּשְׁמֹר מִשְׁמַרְתִּי - בְּמִדָּה זוֹ הָיְתָה מְלַאכְתִּי, שֶׁאֲנִי מְזַכֶּה אֶת הָעוֹלָם כֻּלּוֹ, וַאֲפִלּוּ נִתְחַיְּבוּ אֲנִי מְזַכֶּה אוֹתָם.</p>\n<p>וְעוֹד מְשִׁיבָם וּמֵבִיא בִּלְבָבָם לַעֲשׂוֹת רְצוֹן אֲבִיהֶם. כָּל זֶה עָשָׂה אַבְרָהָם, וְכָתוּב (שם כא) וַיִּטַּע אֵשֶׁל בִּבְאֵר שָׁבַע. סִדֵּר לַחְמוֹ וּמֵימָיו לְכָל בָּאֵי עוֹלָם, וְהָיָה מְזַכֶּה וּמְדַבֵּר עַל לִבָּם: לְמִי אַתֶּם עוֹבְדִים? עִבְדוּ אֶת ה' אֱלֹהֵי הַשָּׁמַיִם וְהָאָרֶץ! וְהָיָה דּוֹרֵשׁ לָהֶם, עַד שֶׁהָיוּ בָּאִים וְשָׁבִים.</p>\n<p>וּמִנַּיִן לָנוּ שֶׁאַף הַחַיָּבִים הָיָה מְזַכֶּה? שֶׁנֶּאֱמַר (שם יח) הַמֲכַסֶּה אֲנִי מֵאַבְרָהָם, וְאַבְרָהָם הָיוֹ יִהְיֶה וְגוֹמֵר. אֶלָּא אֲזַכֵּהוּ שֶׁיְּבַקֵּשׁ עֲלֵיהֶם רַחֲמִים וְיִזְכֶּה. וְכִי אֶפְשָׁר לוֹמַר שֶׁלֹּא יָדַע הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא יָכְלוּ לְהִנָּצֵל? אֶלָּא זְכוּתוֹ הוּא אָמַר. מִכָּאן אָמְרוּ, בָּא לִטָּהֵר - מְסַיְּעִין אוֹתוֹ. בָּא לִטָּמֵא - פּוֹתְחִים לוֹ. מַה זֶּה פּוֹתְחִים לוֹ? אוֹתָם הַפְּתוּחִים תָּמִיד.</p>\n<p>מִצְותַי חֻקּוֹתַי וְתוֹרֹתַי - אָמַר, הוֹאִיל וְלֹא חָפַצְתִּי בָהּ, אֶשְׁמֹר מִצְותֶיהָ. מַה זֶּה תּוֹרֹתַי? אֶלָּא אֲפִלּוּ הוֹרָאוֹת וּפִלְפּוּלִים שְׁמוּרִים לְמַעְלָה הוּא יְדָעָם וּפִלְפֵּל וְקִיְּמָם.</p>\n<p>וּמַה זֶּה מִשָּׁם רוֹעֶה אֶבֶן יִשְׂרָאֵל? הֱוֵי אוֹמֵר, צֶדֶק הָעֶלְיוֹן. וּמַהוּ הָאוֹר הַגָּדוֹל הַצָּפוּן? וְהַיְנוּ סֹחָרֶת. וְהָאֶבֶן שֶׁדָּרָה לְמַטָּה הֵימֶנָּה נִקְרֵאת דָּר, וּמַה הוּא? מִיָּדוֹ לוֹ, הַיְנוּ חָמֵשׁ אֶצְבָּעוֹת שֶׁל יַד יָמִין: ע\"כ מההשמטות.</p>"],[9522012709,"<p>שֶׁבַע צוּרוֹת קְדוֹשׁוֹת יֵשׁ לוֹ לַקָּדוֹשׁ-בָּרוּךְ-הוּא, וְכֻלָּן כְּנֶגְדָּן בָּאָדָם, שֶׁנֶּאֱמַר (בראשית א) בְּצֶלֶם אֱלֹהִים בָּרָא אֹתוֹ, זָכָר וּנְקֵבָה בָּרָא אֹתָם. וְאֵלּוּ הֵן: שׁוֹק יָמִין וּשְׂמֹאל, יַד יָמִין וּשְׂמֹאל, גּוּף וּבְרִית - הֲרֵי שֵׁשׁ. וַהֲרֵי אָמַרְתָּ שֶׁבַע? שֶׁבַע הֵם בְּאִשְׁתּוֹ, (שם ב) וְהָיוּ לְבָשָׂר אֶחָד.</p>\n<p>מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְמֶלֶךְ שֶׁעָלָה בְּלִבּוֹ לִטַּע בְּגַנּוֹ תִּשְׁעָה אִילָנוֹת זְכָרִים, וְהָיוּ כֻלָּם דְּקָלִים. אָמַר, כְּשֶׁיִּהְיוּ כֻלָּם מִין אֶחָד, אֵי אֶפְשָׁר לְהִתְקַיֵּם. מֶה עָשָׂה? נָטַע אֶתְרוֹג בֵּינֵיהֶם, וְהוּא אֶחָד מֵאוֹתָם הַתִּשְׁעָה שֶׁעָלָה בְּלִבּוֹ לִהְיוֹת זְכָרִים. וְאֶתְרוֹג מַה נִּהְיָה? נְקֵבָה, וְהַיְנוּ שֶׁכָּתוּב (ויקרא כג) פְּרִי עֵץ הָדָר כַּפֹּת תְּמָרִים:</p>\n<p>זָכָר וּנְקֵבָה בְּרָאָם (בראשית ה). אֶפְשָׁר לוֹמַר כֵּן? וַהֲרֵי כָּתוּב (שם א) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ בְּצֶלֶם אֱלֹהִים בָּרָא אֹתוֹ וְגוֹמֵר, וְאַחַר כָּךְ (שם) אֶעֱשֶׂה לּוֹ עֵזֶר כְּנֶגְדּוֹ. וַיִּקַּח אַחַת מִצַּלְעֹתָיו וַיִּסְגֹּר בָּשָׂר תַּחְתֶּנָּה. אֶלָּא אֱמֹר, שֶׁכָּתוּב יְצִירָה, וְכָתוּב בָּהֶן עֲשִׂיָּה, וְכָתוּב בָּהֶן בְּרִיאָה. עֲשִׂיָּה, שֶׁכָּתוּב זָכָר וּנְקֵבָה בָּרָא אֹתָם, בְּעֵת הִרְכִּיב הַנְּשָׁמָה עַל הַגּוּף וְאָסַף הַכֹּל. וּמִנַּיִן לָנוּ שֶׁיְצִירָה זוֹ הִיא לְשׁוֹן אִסּוּף הוּא שֶׁכָּתוּב (שם ב) וַיִּצֶר ה' אֱלֹהִים וְגוֹ' כָּל חַיַּת הַשָּׂדֶה וְאֵת כָּל עוֹף הַשָּׁמַיִם וַיָּבֵא אֶל הָאָדָם, וְהַיְנוּ שֶׁכָּתוּב עַל הָאָדָם - זָכָר וּנְקֵבָה בָּרָא אֹתָם. וַיְבָרֶךְ אֹתָם.</p>\n<p>בְּצֶלֶם אֱלֹהִים בָּרָא אֹתוֹ. בְּכָל אֵבָרָיו וּבְכָל חֲלָקָיו, וַהֲרֵי אָמוּר, וָא\"ו לְמַה הוּא דּוֹמֶה? (תהלים קד) לְעֹטֶה אוֹר כַּשַּׂלְמָה, וַהֲרֵי וָא\"ו אֵינָהּ אֶלָּא שֵׁשׁ קְצָווֹת. אָמַר לוֹ, בְּרִית מִילָה וְזִוּוּגוֹ שֶׁל אָדָם חֲשׁוּבִים אֶחָד. שְׁתֵּי יָדָיו שְׁלֹשָׁה. רֹאשׁוֹ וְגוּפוֹ חֲמִשָּׁה. שְׁתֵּי שׁוֹקָיו שִׁשָּׁה. וּכְנֶגְדָּם כְּמוֹתָם בַּשָּׁמַיִם, שֶׁכָּתוּב (קהלת ז) גַּם אֶת זֶה לְעֻמַּת זֶה עָשָׂה הָאֱלֹהִים. וְהַיְנוּ יָמִים, (שמות לא) כִּי שֵׁשֶׁת יָמִים עָשָׂה ה' אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ, וְלֹא אָמַר בְּשֵׁשֶׁת יָמִים, מְלַמֵּד שֶׁכָּל יוֹם וָיוֹם יֵשׁ לוֹ כֹּחוֹ:</p>\n<p>וַיֹּאמֶר אֱלֹהִים פְּרוּ וּרְבוּ וְגוֹמֵר. מִצְוָה זוֹ לְהִתְעַסֵּק בָּעוֹלָם הַזֶּה בִּפְרִיָּה וּרְבִיָּה וְלַעֲשׂוֹת תּוֹלָדוֹת, שֶׁיִּתְפַּשֵּׁט הַשֵּׁם הַקָּדוֹשׁ לְכָל הַצְּדָדִים, וְלִלְקֹט רוּחוֹת וּנְשָׁמוֹת, שֶׁיִּהְיֶה כְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה וּלְמַטָּה. שֶׁכָּל מִי שֶׁלֹּא מִתְעַסֵּק בִּפְרִיָּה וּרְבִיָּה, מַקְטִין אֶת הַדְּמוּת שֶׁל רִבּוֹנוֹ שֶׁלֹּא יִמָּצֵא בָּעוֹלָם הַזֶּה, וְגוֹרֵם שֶׁלֹּא תִשְׁרֶה שְׁכִינָה בָּעוֹלָם הַזֶּה. כְּמוֹ שֶׁמִּתּוֹסְפוֹת רוּחוֹת וּנְשָׁמוֹת, כָּךְ מִתּוֹסֵף לָרֶדֶת (נ\"א: דגמא) לָעוֹלָם הַזֶּה כְּבוֹד הַמֶּלֶךְ, שֶׁכָּתוּב (משלי יד) בְּרָב עָם הַדְרַת מֶלֶךְ וּבְאֶפֶס לְאֹם מְחִתַּת רָזוֹן.</p>\n<p>הַדְרַת מֶלֶךְ - זֶה זִיו כְּבוֹד הַמֶּלֶךְ שֶׁמִּתּוֹסֵף לָרֶדֶת לָעוֹלָם הַזֶּה. מְחִתַּת רָזוֹן - זֶה הַקְטָנַת דְּמוּת הַמֶּלֶךְ שֶׁמַּקְטִין מֵהָעוֹלָם הַזֶּה, כָּךְ מַקְטִין גַּם לְמַעְלָה, שֶׁהֲרֵי אוֹתוֹ זִיו לֹא יוֹרֵד, וְנֶחְשָׁב עַל אוֹתוֹ אָדָם כְּאִלּוּ שָׁפַךְ דָּמִים, שֶׁגָּרַע הַדְּמוּת שֶׁלְּמַטָּה כְּמוֹ שֶׁלְּמַעְלָה, שֶׁכָּתוּב (בראשית ט) כִּי בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם. וְהוּא מַקְטִין צֶלֶם אֱלֹהִים לְמַטָּה וְהַדְּמוּת וּדְיוֹקָן לְמַעְלָה, וְלָכֵן צָרִיךְ אָדָם לְהִתְעַסֵּק בִּפְרִיָּה וּרְבִיָּה וְלַעֲשׂוֹת צֶלֶם אֱלֹהִים לְהַגְדִּיל כְּבוֹד ה' בְּכָל הַצְּדָדִים: ע\"כ מההשמטות.</p>\n<p>מִצְוָה זוֹ לְקַיֵּם מִצְוַת פְּרִיָּה וּרְבִיָּה לְקַיֵּם בֵּן וּבַת, מִשּׁוּם שֶׁאָב שָׁם י', וְאֵם שָׁם ה', בֵּן שָׁם ו', בַּת שָׁם ה', וְאָב וָאֵם שֶׁיֵּשׁ לָהֶם בֵּן וּבַת, גַּם ה' לֹא שׁוֹרֶה עֲלֵיהֶם. וּכְמוֹ זֶה בְּמַעֲשֵׂה בְרֵאשִׁית אָמַר (בראשית א) פְּרוּ וּרְבוּ, פְּרוּ מִצַּד הַיָּמִין, וּרְבוּ מִצַּד הַשְּׂמֹאל, שֶׁבּוֹ בָּרָא אֱלֹהִים הַכֹּל, וּבָרָא זֶה עַמּוּד הָאֶמְצָעִי, אֵת הָאָרֶץ - זוֹ שְׁכִינָה. וְלָמָּה צָרִיךְ אַרְבַּע, בְּאָב וָאֵם בֵּן וּבַת? מִשּׁוּם שֶׁהֲרֵי הִתְקַדְּשׁוּ וְהִתְבָּרְכוּ בְּשָׁלֹשׁ קְדֻשּׁוֹת וְשֶׁבַע בְּרָכוֹת שֶׁהֵם י', צְרִיכוֹת לִהְיוֹת אַרְבַּע אוֹתִיּוֹת שֶׁשּׁוֹרוֹת עֲלֵיהֶם עֲשָׂרָה, לִהְיוֹת אָדָם רְשׁוּת הַיָּחִיד לַאֲדוֹנוֹ, שֶׁרָחְבּוֹ אַרְבָּעָה וְגָבְהוֹ עֲשָׂרָה.</p>\n<p>וּמִי שֶׁמִּתְעַסֵּק בַּתּוֹרָה וּבַמִּצְוָה בְּיִרְאָה וּבְאַהֲבַת אֲדוֹנוֹ, בִּמְקוֹם יִרְאָה שְׁרוּיָה שָׁם י', בִּמְקוֹם אַהֲבָה שְׁרוּיָה שָׁם ה', בִּמְקוֹם תּוֹרָה שְׁרוּיָה ו', וּבִמְקוֹם מִצְוָה שְׁרוּיָה ה', בִּמְקוֹם הַמַּחֲשָׁבָה שֶׁנֶּאֱמַר בָּהּ (שמואל ב יט) וְזֹאת תּוֹרַת הָאָדָם, כָּלוּל מֵהַכֹּל, שׁוֹרָה בּוֹ יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, (תהלים קכז) אִם ה' לֹא יִבְנֶה בַיִת שָׁוְא עָמְלוּ בוֹנָיו בּוֹ. מַה זֶּה שָׁוְא עָמְלוּ בוֹנָיו בּוֹ? אֵלּוּ סמא\"ל וְנָחָשׁ: ע\"כ מההשמטות.</p>"],[9522012710,"<p>יָשַׁב רַבִּי בְּרֶכְיָה וְדָרַשׁ, מַה זֶּה שֶׁאָנוּ אוֹמְרִים כָּל יוֹם הָעוֹלָם הַבָּא, וְלֹא יוֹדְעִים מָה אָמַר, הָעוֹלָם הַבָּא מְתֻרְגָּם עָלְמָא דְאָתֵי (העולם הבא), מְלַמֵּד שֶׁקֹּדֶם שֶׁנִּבְרָא הָעוֹלָם עָלָה בְמַחֲשָׁבָה לִבְרֹא אוֹר גָּדוֹל לְהָאִיר, וְנִבְרָא אוֹר גָּדוֹל שֶׁאֵין כָּל בְּרִיָּה יְכוֹלָה לִשְׁלֹט בּוֹ. צָפָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁאֵינָם יְכוֹלִים לְסָבְלוֹ, לָקַח שְׁבִיעִי וְשָׂם לָהֶם בִּמְקוֹמוֹ, וְהַשְּׁאָר גְּנָזוֹ לַצַּדִּיקִים לֶעָתִיד לָבא. אָמַר, אִם יִזְכּוּ בְּזֶה הַשְּׁבִיעִי וְיִשְׁמְרוּהוּ - אֶתֵּן לָהֶם זֶה לְעוֹלָם אַחֲרוֹן, וְהַיְנוּ שֶׁכָּתוּב הָעוֹלָם הַבָּא, שֶׁכְּבָר בָּא מִקֹּדֶם שֵׁשֶׁת יְמֵי בְרֵאשִׁית. זֶהוּ שֶׁכָּתוּב (תהלים לא) מָה רַב טוּבְךְ אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךְ פָּעַלְתָּ לַחוֹסִים בָּךְ נֶגֶד בְּנֵי אָדָם: ע\"כ מההשמטות.</p>"],[9522012711,"<p>שְׁמִינִי מַה הוּא? יֵשׁ לוֹ לַקָּדוֹשׁ- בָּרוּךְ-הוּא צַדִּיק אֶחָד בָּעוֹלָם וְחָבִיב לוֹ, מִפְּנֵי שֶׁמְּקַיֵּם כָּל הָעוֹלָם כֻּלּוֹ, וְהוּא יְסוֹדוֹ, וְהוּא מְכַלְכְּלוֹ וּמַצְמִיחוֹ וּמְגַדְּלוֹ וּמְשַׂמְּחוֹ, אָהוּב וְחָבִיב לְמַעְלָה, נוֹרָא וְאַדִּיר לְמַטָּה, מְתֻקָּן וּמְקֻבָּל לְמַעְלָה, מְתֻקָּן וּמְקֻבָּל לְמַטָּה, וְהוּא יְסוֹד הַנְּפָשׁוֹת כֻּלָּם.</p>\n<p>אָמַרְתָּ שְׁמִינִי, וְאָמַרְתָּ יְסוֹד הַנְּפָשׁוֹת כֻּלָּם, וַהֲרֵי כָּתוּב וּבַיּוֹם הַשְּׁבִיעִי שָׁבַת וַיִּנָּפַשׁ? כֵּן שְׁבִיעִי הוּא אֶלָּא מִשּׁוּם שֶׁמַּכְרִיעַ בֵּינֵיהֶם, וְיֶשְׁנָם שָׁלֹשׁ לְמַטָּה וְשָׁלֹשׁ מִמַּעַל, וְהוּא שֶׁמַּכְרִיעַ בֵּינֵיהֶם.</p>\n<p>וּמָה הַטַּעַם נִקְרָא שְׁבִיעִי? וְכִי הוּא בַּשְּׁבִיעִי? לֹא, אֶלָּא מִפְּנֵי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שָׁבַת בְּשַׁבָּת בְּאוֹתָהּ הַמִּדָּה, שֶׁכָּתוּב (שמות לא) כִּי שֵׁשֶׁת יָמִים עָשָׂה ה' אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ וּבַיּוֹם הַשְּׁבִיעִי שָׁבַת וַיִּנָּפַשׁ. מְלַמֵּד שֶׁכָּל יוֹם וָיוֹם יֵשׁ לוֹ מַאֲמָר אֶחָד שֶׁהוּא אָדוֹן לוֹ, לֹא מִפְּנֵי שֶׁהוּא נִבְרָא בּוֹ, אֶלָּא מִפְּנֵי שֶׁהוּא פּוֹעֵל בָּעוֹלָם פְּעֻלָּה הַמְּסוּרָה לוֹ בְּיָדוֹ. פָּעָלוּ כֻלָּם פְּעֻלָּתָם וְקִיְּמוּ מַעֲשֵׂיהֶם לְבַד - בָּא יוֹם הַשְּׁבִיעִי וּפָעַל פְּעֻלָּתוֹ. שָׂמְחוּ כֻלָּם, אַף הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלֹא עוֹד אֶלָּא שֶׁגָּדְלָה נִשְׁמָתוֹ, שֶׁכָּתוּב וּבַיּוֹם הַשְּׁבִיעִי שָׁבַת וַיִּנָּפַשׁ.</p>\n<p>וּמַהִי שְׁבִיתָה זוֹ? שֶׁאֵין בָּהּ מְלָאכָה, וְהִיא מְנוּחָה, שֶׁכָּתוּב שָׁבַת. מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְמֶלֶךְ שֶׁהָיוּ לוֹ שִׁבְעָה גַנּוֹת, וּבַגַּן הָאֶמְצָעִי מַעְיָן נָאֶה נוֹבֵעַ מִמְּקוֹר מַיִם חַיִּים, שְׁלֹשָׁה מִימִינוֹ וּשְׁלֹשָׁה מִשְּׂמֹאלוֹ, וּמִיָּד שֶׁפּוֹעֵל בָּעוֹלָם אָז מִתְמַלֵּא, וּשְׂמֵחִים כֻּלָּם וְאוֹמְרִים: לְצָרְכֵּנוּ הוּא מִתְמַלֵּא. וְהוּא מַשְׁקֶה אוֹתָם וּמְגַדְּלָם, וְהֵם מַמְתִּינִים וְשׁוֹבְתִים, וְהוּא מַשְׁקֶה אֶת הַשִּׁבְעָה.</p>\n<p>וַהֲרֵי כָּתוּב (ישעיה מג) מִמִּזְרָח אָבִיא זַרְעֶךְ, וְהִנֵּה אֶחָד מֵהֶם מַשְׁקֶה אוֹתוֹ? אֶלָּא אֱמֹר, הוּא מַשְׁקֶה אֶת הַלֵּב, וְהַלֵּב מַשְׁקֶה אַחַר כֵּן כֻּלָּם. וּמַהִי מִדָּה שְׁבִיעִית? הֱוֵי אוֹמֵר, זוֹ מִדַּת טוּבוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>מָה הַטַּעַם אָמַר אֶת שַׁבְּתֹתַי וְלֹא אָמַר אֶת שַׁבַּתִּי? מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְמֶלֶךְ שֶׁהָיָה לוֹ כַּלָּה נָאָה, וְכָל שָׁבוּעַ וְשָׁבוּעַ מַזְמִינָהּ יוֹם אֶחָד לִהְיוֹת עִמּוֹ, וְהַמֶּלֶךְ יֵשׁ לוֹ בָּנִים נָאִים וְאוֹהֲבָם, אָמַר לָהֶם: הוֹאִיל וְכֵן, שִׂמְחוּ אַתֶּם גַּם כֵּן בְּיוֹם שִׂמְחָתִי, כִּי אֲנִי בְּשֶׁלָּכֶם אֲנִי מִשְׁתַּדֵּל, וְאַתֶּם גַּם כֵּן הַדְּרוּ אוֹתוֹ.</p>\n<p>וּמַה זֶּה זָכוֹר וְשָׁמוֹר? זָכוֹר לַזָּכָר, וְשָׁמוֹר לַנְּקֵבָה. מָה הַטַּעַם (ויקרא יט) וּמִקְדָּשִׁי תִּירָאוּ? שִׁמְרוּ עַצְמְכֶם מֵהִרְהוּר, כִּי מִקְדָּשִׁי קָדוֹשׁ הוּא. לָמָּה? (שם כ) אֲנִי ה' מְקַדִּשְׁכֶם, אֲנִי ה' בְּכָל צַד: ע\"כ מההשמטות.</p>"],[9522012712,"<p>שָׁנִינוּ, עַמּוּד אֶחָד מִן הָאָרֶץ עַד לָרָקִיעַ וְצַדִּיק שְׁמוֹ עַל שֵׁם הַצַּדִּיקִים, וּכְשֶׁיִּשְׂרָאֵל צַדִּיקִים - מִתְגַּבֵּר, וְאִם לָאו - מִתְחַלֵּשׁ, וְהוּא סוֹבֵל כָּל הָעוֹלָם, שֶׁכָּתוּב (משלי י) וְצַדִּיק יְסוֹד עוֹלָם, וְאִם חַלָּשׁ, לֹא יוּכַל לְהִתְקַיֵּם הָעוֹלָם: ע\"כ.</p>"],[9522012713,"<p>רַבִּי חֲנִינָא פֵּרַשׁ כָּל אֶחָד עַל עָמְדוֹ. שָׂשׂוֹן - אֶחָד. שִׂמְחָה - שְׁתַּיִם. חָתָן - שָׁלֹשׁ. כַּלָּה - אַרְבַּע. גִּילָה, דִּיצָה, אַהֲבָה, אַחֲוָה, שָׁלוֹם וְרֵעוּת - עֶשֶׂר, כְּנֶגֶד עֲשָׂרָה מַאֲמָרוֹת שֶׁבָּהֶם נִבְרָא הָעוֹלָם: ע\"כ מההשמטות.</p>"],[9522012714,"<p>ס\"א יּצִּר טוב וְיֵצֶר רָע שֶׁהוּא חֶדְוָה וּמֵבִיא אוֹתָהּ אֵלָיו, וּלְמַעְלָה צַד הַצָּפוֹן מַמָּשׁ, שֶׁהוּא חֶדְוָה בְּלִי זֻהֲמָה שֶׁהַיֵּצֶר הָרָע אָחוּז בּוֹ (בה). בַּתְּחִלָּה, שֶׁכָּתוּב (שיר ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי, וְאַחַר כָּךְ וִימִינוֹ תְּחַבְּקֵנִי, וְנִתֶּנֶת בֵּין יָמִין לִשְׂמֹאל (ושמאל) (להזון), וְלָכֵן וַיִּיצֶר ה' אֱלֹהִים, שֵׁם מָלֵא לְגַבֵּי שְׁנֵי צְדָדִים אֵלּוּ. אֶת הָאָדָם וְכוּ': ע\"כ מההשמטות.</p>"],[9522012715,"<p>אָמַר לוֹ, לְכָה דוֹדִי נֵצֵא הַשָּׂדֶה, לְכוּ לַקָּדוֹשׁ-בָּרוּךְ-הוּא לְטַיֵּל, וְאַל אֵשֵׁב תָּמִיד בְּמָקוֹם אֶחָד. וּמַה זֶּה לֵב? אָמַר לוֹ, אִם כֵּן, בֶּן זוֹמָא מִבַּחוּץ וְאַתָּה עִמּוֹ. לֵ\"ב הוּא (והוא) שְׁלֹשִׁים וּשְׁתַּיִם, וְהָיוּ סְתוּמִים וּבָהֶם נִבְרָא הָעוֹלָם. וּמַהוּ לֵ\"ב? אָמַר לוֹ, שְׁלֹשִׁים וּשְׁתַּיִם נְתִיבוֹת.</p>\n<p>מָשָׁל לְמֶלֶךְ שֶׁהָיָה יוֹשֵׁב בְּחַדְרֵי חֲדָרִים, וּמִנְיַן הַחֲדָרִים שְׁלֹשִׁים וּשְׁנַיִם, וּלְכָל אֶחָד מִן הַחֲדָרִים יֵשׁ נָתִיב, נָאֶה לְמֶלֶךְ זֶה לְהִכָּנֵס (הכל) בְּחַדְרוֹ עַל דֶּרֶךְ נְתִיבוֹת. אָמַר, לֹא נָאֶה לוֹ שֶׁלֹּא לְגַלּוֹת פְּנִינָיו וּמִשְׁכְּנוֹתָיו וּגְנָזָיו וַחֲמוּדוֹתָיו? אָמַרְתָּ לֹא. מֶה עָשָׂה? נָגַע בַּבַּת וְכָלַל בָּהּ כָּל הַנְּתִיבוֹת וּמַלְבּוּשֶׁיהָ, וְהָרוֹצֶה לְהִכָּנֵס (ס\"א להסתכל בעיניה) בִּפְנִים, יִסְתַּכֵּל הֵנָּה. וּנְשָׂאָהּ לַמֶּלֶךְ. גַּם נִתְּנָה לוֹ בְּמַתָּנָה, וְלִפְעָמִים קוֹרֵא אוֹתָהּ בְּאַהֲבָתוֹ (בת) אֲחוֹתִי, כִּי מִמָּקוֹם אֶחָד הָיוּ, וְלִפְעָמִים קוֹרֵא אוֹתָהּ בִּתִּי, כִּי בִתּוֹ הִיא, וְלִפְעָמִים קוֹרֵא אוֹתָהּ אִמִּי.</p>\n<p>וְעוֹד, כִּי אֵין דִּין אִם אֵין חָכְמָה, שֶׁהֲרֵי נֶאֱמַר (מלכים א ה) וַה' נָתַן חָכְמָה לִשְׁלֹמֹה. וְאַחַר כָּךְ דָּן אֶת הַדִּין עַל מַתְכֻּנְתּוֹ, שֶׁכָּתוּב (שם ג) וַיִּשְׁמְעוּ כָּל יִשְׂרָאֵל אֶת הַמִּשְׁפָּט וְגוֹמֵר, כִּי רָאוּ כִּי חָכְמַת אֱלֹהִים בְּקִרְבּוֹ וְגוֹמֵר.</p>\n<p>וּמֶה חָכְמָה נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׁלֹמֹה? שְׁלֹמֹה נָשָׂא שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁאָנוּ אוֹמְרִים, כָּל שְׁלֹמֹה שֶׁבְּשִׁיר הַשִּׁירִים קֹדֶשׁ לְבַד מֵאֶחָד. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, הוֹאִיל וְשִׁמְךְ כִּשְׁמִי, אַשִּׂיא לְךְ בִּתִּי, וַהֲרֵי נְשׂוּאָה הִיא. אָמַר לוֹ, בְּמַתָּנָה נְתָנָהּ לוֹ הַשֵּׁם, וַה' נָתַן חָכְמָה לִשְׁלֹמֹה, וְלֹא פֵרַשׁ. וְהֵיכָן פֵּרַשׁ? לְפָנָיו, כִּי רָאוּ כִּי חָכְמַת אֱלֹהִים בְּקִרְבּוֹ לַעֲשׂוֹת מִשְׁפָּט. (ומה זה משפט? אלא כל זמן שאדם עושה משפט, חכמת אלהים בקרבו) וּמַה זֶּה לַעֲשׂוֹת מִשְׁפָּט? הֱוֵי אוֹמֵר, שֶׁאוֹתָהּ חָכְמָה שֶׁנְּתָנָהּ אֱלֹהִים וְשֶׁהִיא עִמּוֹ בְּחַדְרוֹ, הִיא בְּקִרְבּוֹ. זאת עוֹזַרְתּוֹ וּמְקָרַבְתּוֹ, וְאִם לָאו - מְרַחַקְתּוֹ, וְלֹא עוֹד אֶלָּא מְיַסַּרְתּוֹ, שֶׁכָּתוּב (ויקרא כו) וְיִסַּרְתִּי אֶתְכֶם אַף אָנִי: ע\"כ מההשמטות.</p>"],[9522012716,"<p>אָמַר רַבִּי רְחוּמַאי, כָּבוֹד וְלֵב הֲרֵי הֵם אֶחָד, אֶלָּא שֶׁכָּבוֹד נִקְרָא עַל שֵׁם מַעְלָה, וְלֵב נִקְרָא עַל שֵׁם פְּעֻלַּת מַטָּה, וְהַיְנוּ כְּבוֹד הַשֵּׁם, וְהַיְנוּ לֵב הַשָּׁמַיִם. מַה הוּא (ישעיה ו) מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ? אֶלָּא כָּל אוֹתָהּ אֶרֶץ שֶׁנִּבְרֵאת בְּיוֹם רִאשׁוֹן, שֶׁהִיא לְמַעְלָה כְּנֶגֶד אֶרֶץ יִשְׂרָאֵל, מְלֵאָה מִכְּבוֹד הַשֵּׁם, וּמַה הֵם? חֲכָמִים, שֶׁכָּתוּב (משלי יג) כָּבוֹד חֲכָמִים יִנְחָלוּ, וְכָתוּב (יחזקאל ג) בָּרוּךְ כְּבוֹד ה' מִמְּקוֹמוֹ.</p>\n<p>וּמֶה הָיָה הַכָּבוֹד הַזֶּה? מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְמֶלֶךְ שֶׁהָיְתָה לוֹ גְּבִירָה בְּחַדְרוֹ שֶׁכָּל חַיָּלָיו מִשְׁתַּעְשְׁעִין בָּהּ, וְהָיוּ לָהּ בָּנִים, וּבָאִים כָּל הַיּוֹם לִרְאוֹת פְּנֵי הַמֶּלֶךְ וּמְבָרְכִין אוֹתוֹ. אָמְרוּ לוֹ: אָנָה אִמֵּנוּ? אָמַר לָהֶם: לֹא תוּכְלוּ לִרְאוֹתָהּ עַתָּה. אָמְרוּ: בְּרוּכָה תְּהֵא בְּכָל מָקוֹם שֶׁהִיא.</p>\n<p>וּמַה שֶּׁכָּתוּב מִמְּקוֹמוֹ, מִכְּלָל שֶׁאֵין יוֹדֵעַ אֶת מְקוֹמוֹ. מָשָׁל לִגְבִירָה שֶׁבָּאָה מִמָּקוֹם רָחוֹק וְלֹא יָדְעוּ מֵאַיִן בָּאָה. עַד שֶׁרָאוּ שֶׁהִיא אֵשֶׁת חַיִל נָאָה וַהֲגוּנָה בְּכָל מַעֲשֶׂיהָ, אָמְרוּ: זאת וַדַּאי מִן הָאוֹר נִלְקְחָה, כִּי בְמַעֲשֶׂיהָ הֵאִירָה אֶת הָעוֹלָם. שָׁאֲלוּ אוֹתָהּ: מֵאַיִן אַתְּ? אָמְרָה לָהֶם: מִמְּקוֹמִי. אָמְרוּ: אִם כֵּן, גְּדוֹלִים אַנְשֵׁי מְקוֹמֵךְ, בְּרוּכָה תִּהְיִי וּמְבֹרָךְ מְקוֹמֵךְ.</p>\n<p>וְכִי אֵין כְּבוֹד ה' אֶחָד מִצִּבְאוֹתָיו לֹא גָרַע, לָמָּה מְבָרְכִים אוֹתוֹ? אֶלָּא מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְאִישׁ שֶׁהָיָה לוֹ גַּן נָאֶה, וְחוּץ לַגָּן בְּקָרוֹב מִמֶּנּוּ חֲתִיכַת שָׂדֶה, וְאִם הִשְׁקָה הַגָּן בִּתְחִלַּת שַׁקְיוּתוֹ - הָלְכוּ לָהֶם הַמַּיִם עַל כָּל הַגָּן, אַךְ אוֹתָהּ חֲתִיכָה שֶׁל שָׂדֶה שֶׁהִיא אֵינָהּ דְּבוּקָה, אַף עַל פִּי שֶׁהַכֹּל אֶחָד הוּא, לְפִיכָךְ פָּתַח לָהּ מָקוֹם וְהִשְׁקָה אוֹתָהּ לְבַדָּהּ: ע\"כ מההשמטות.</p>"],[9522012717,"<p>עֵל יַמִּים יְסָדָהּ (תהלים כד) - אֵלּוּ חַכְמֵי יִשְׂרָאֵל הַגְּדוֹלִים שֶׁיִּסְּדוּ תּוֹרָה וְחָכְמָה שֶׁנִּקְרֵאת הַיָּם הַגָּדוֹל, וְכֵן הוּא אוֹמֵר, (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם. וְעַל נְהָרוֹת - אֵלּוּ הַתַּלְמִידִים שֶׁהֵם הַגְּדוֹלִים מֵהַנָּהָר, וְכֵן הָרַב גָּדוֹל מִן הַתַּלְמִידִים, וְהֵם מְחַדְּדִים אֶת הָרַב בְּקֻשְׁיוֹתֵיהֶן, וְהוּא מְתָרֵץ לָהֶם כָּל הַקֻּשְׁיוֹת וְאֵינוֹ מִתְרַשֵּׁל, כְּמוֹ הַנְּהָרוֹת שֶׁנִּמְשָׁכִים לַיָּם וְאֵינוֹ מָלֵא, שֶׁנֶּאֱמַר כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם. וְהָרְאָיָה - אָמְרוּ אַחֲרֵי כֵן, מִי יַעֲלֶה בְּהַר ה', כִּי אֵין מַעֲשֶׂה בְּלֹא חָכְמָה, כִּי הַתַּלְמוּד מֵבִיא לִידֵי מַעֲשֶׂה:</p>"],[9522012718,"<p>שְׁכִינָה נִקְרֵאת אוֹת בְּרִית מִצַּד שֶׁל צַדִּיק יְסוֹד עוֹלָם. זאת אוֹת הַבְּרִית - בְּסִינַי. (בין) הָעַמּוּד הָאֶמְצָעִי, וּבֵין בְּנֵי יִשְׂרָאֵל - נֵצַח הוֹד. אוֹת - זֶה צַדִּיק. הִיא - זוֹ שְׁכִינָה. (שמות לא) כִּי שֵׁשֶׁת יָמִים עָשָׂה ה' אֶת הַשָּׁמַיִם - מִכֶּתֶר עַד הָעַמּוּד הָאֶמְצָעִי, שֶׁאֵין שֵׁשׁ בְּכָל מָקוֹם אֶלָּא מִצַּד הָאוֹת ו', וְאֵין שְׁבִיעִי אֶלָּא מִצַּד הָאוֹת י', עֲטָרָה עַל רֹאשׁוֹ. הַחָכְמָה הָעֶלְיוֹנָה הִיא אוֹת, הַחָכְמָה הַתַּחְתּוֹנָה הִיא אוֹת, וְתִקְּנוּ לָמוּל לִשְׁמֹנָה שֶׁשָּׁם הִיא חָכְמָה עַד הַיְסוֹד, לְקַבֵּל בָּהֶם י' קְטַנָּה לְהַעֲלוֹתָהּ עַד הַכֶּתֶר לִהְיוֹת עֲטָרָה עַל רֹאשָׁם, וְתִקְּנוּ לָשִׂים הָעָרְלָה בִּכְלִי וְעָפָר, לְקַיֵּם וְנָחָשׁ עָפָר לַחְמוֹ: ע\"כ מההשמטות.</p>"],[9522012719,"<p>'אהניאל \"ברקיאל \"גדיאל \"דומיאל \"הדריאל \"ודרגזיה \"זהריאל \"חניאל \"טהריאל \"יעזריאל \"כרעיאל \"למדיאל \"מלכיאל \"נהריאל \"סניה \"ענאל \"פתחיאל \"צוריאל \"קנאל \"רמיאל \"שעריאל \"תבכיאל: סדר תשר\"ק \"תפוריא \"שכניאל \"רנאל \"קמריה \"צוריה \"פסיסיה \"עיריאל \"סמכיאל \"נריאל \"מדוניה \"לסניה \"כמסריה \"יריאל \"טסמסיה \"חניאל \"זכראל \"ודריאל \"הניאל \"דנבאל \"גדיאל \"בדאל \"אדירירון אדני על כולהו וכו': (עד כאן מההשמטות)</p>"],[9522012720,"<p>וַיַּחֲלוֹם וְהִנֵּה סֻלָּם מֻצָּב אַרְצָה (בראשית כח). וְהִנֵּה סֻלָּם - זוֹ תְפִלָּה. מֻצָּב אַרְצָה - שֶׁמִּתְפַּלְלִים בְּנֵי אָדָם לוֹ בָּאָרֶץ, שֶׁהִיא שְׁכִינָה, וּמַגִּיעַ לַשָּׁמַיִם שֶׁהוּא הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁנֶּאֱמַר בּוֹ (מלכים א ח) וְאַתָּה תִּשְׁמַע הַשָּׁמַיִם, וְסוֹד הַדָּבָר - (תהלים ח) ה' אֲדנֵנוּ מָה אַדִּיר שִׁמְךְ בְּכָל הָאָרֶץ וְגוֹמֵר.</p>\n<p>וּבַזְּמַן שֶׁמּוֹדִיעַ לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ שֶׁעוֹלָה בְּאוֹתָהּ הַתְּפִלָּה, מִיָּד - וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְיֹרְדִים בּוֹ. בּוֹ - בְּאוֹתוֹ אָדָם. כֻּלָּם פּוֹתְחִים כַּנְפֵיהֶם לְקַבֵּל שְׁכִינָה בְּאוֹתָהּ תְּפִלָּה. זֶהוּ שֶׁכָּתוּב (יחזקאל א) וְכַנְפֵיהֶם פְּרֻדוֹת מִלְמָעְלָה. וְזֶה עֹלִים, שְׁכִינָה עַל כַּנְפֵיהֶם, וְיֹרְדִים בּוֹ. מַה זֶּה בּוֹ? בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יוֹרֵד עֲלֵיהֶם לְקַבֵּל שְׁכִינָתוֹ, וּמְיַחֵד הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתוֹ הָאִישׁ בִּתְפִלָּתוֹ,</p>\n<p>שֶׁשְּׁכִינָה הִיא מִצְוָה כְּלוּלָה בְּשֵׁם יהו\"ה, הִיא הַחַיָּה שֶׁלּוֹ, וּמִצְוָה בְּלִי מַחֲשָׁבָה אֵין לָהּ עֲלִיָּה. וּמַחֲשָׁבָה הִיא אָדָם, יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, תִּפְאֶרֶת מִצְוָה, הַמַּלְכוּת כְּלוּלָה מֵאַרְבַּע חַיּוֹת הַמֶּרְכָּבָה, כְּלוּלָה מֵאַרְבַּע אוֹתִיּוֹת, הִיא הַנְּקֵבָה שֶׁלּוֹ, הַפָּנִים שֶׁלּוֹ, פְּנֵי הָרַחֲמִים, עֲבוּרָהּ אָמַרְתִּי (שמות לג) אִם אֵין פָּנֶיךְ הֹלְכִים וְגוֹמֵר.</p>\n<p>וּמִצַד הַצַּדִּיק נִקְרֵאת אֲחוֹרָיו, חַיָּה כְּלוּלָה שְׁמוֹנֶה עֶשְׂרֵה חֻלְיוֹת שֶׁאֲחוֹרֵי הָאָדָם, שֶׁדּוֹמֶה לַשִּׁדְרָה שֶׁבָּהּ שְׁמוֹנֶה עֶשְׂרֵה חֻלְיוֹת, הִיא אָחוֹר לְמַעֲשֵׂה בְרֵאשִׁית, וְקָדַם לַמַּחֲשָׁבָה, שֶׁנֶּאֱמַר בָּהּ עָלָה בְּמַחֲשָׁבָה, מַה שֶּׁאֵין כֵּן בְּאָדָם שֶׁל אָחוֹר, שֶׁל עֵץ הַדַּעַת טוֹב וָרָע, שֶׁהוּא אָחוֹר לְמַעֲשֵׂה בְרֵאשִׁית וְקָדַם לַפֻּרְעָנוּת.</p>\n<p>קָמוּ תַנָּאִים וְאָמוֹרָאִים וְאָמְרוּ, רוֹעֶה הַנֶּאֱמָן, בָּרוּךְ אַתָּה לְאֵל עֶלְיוֹן, הוּא יָקִים לְךְ בַּקָּשָׁתְךְ בַּכֹּל. קָם זָקֵן עֶלְיוֹן בֵּינֵיהֶם וְאָמַר, רוֹעֶה הַנֶּאֱמָן, בְּךְ הִתְקַיֵּם פָּסוּק זֶה שֶׁנֶּאֱמַר (ישעיה סב) וְאַל תִּתְּנוּ דֳמִי לוֹ, שֶׁהֲרֵי עֶלְיוֹנִים וְתַחְתּוֹנִים מְקַנְּנִים בְּצַלְמְךְ, מַחֲנוֹת הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהֵם מֵהַיְשִׁיבָה הָעֶלְיוֹנָה, וּמַחֲנוֹת הַגְּבִירָה שֶׁהֵם מֵהַיְשִׁיבָה הַתַּחְתּוֹנָה, עָלֶיךְ נֶאֱמַר וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְיֹרְדִים בּוֹ.</p>\n<p>בְּךְ עוֹלִים מַחֲנוֹת הַשְּׁכִינָה בִּתְפִלָּה, וְיוֹרְדִים מַחֲנוֹת הַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׁכִינָתוֹ בְּכַמָּה שִׁירִים וְנִגּוּנִים שֶׁל תְּפִלָּה. אַתָּה הוּא הַקָּרוֹב לַקָּדוֹשׁ-בָּרוּךְ- הוּא בִּתְפִלָּתְךְ, שֶׁהִיא קָרְבָּן לַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ בְּאֵיזֶהוּ מְקוֹמָן, בְּצַו אֶת בְּנֵי יִשְׂרָאֵל וְכוּ'. שֶׁתִּקְּנוּ בַּעֲלֵי הַמִּשְׁנָה קָרְבְּנוֹת הַתְּפִלָּה מִצַּד הַיָּמִין, שֶׁשָּׁם כֹּהֵן אִישׁ חֶסֶד,</p>\n<p>וְתִקְּנוּ זְמִירוֹת שֶׁהֵם שִׁיר הַלְוִיִּם אַחֲרֵיהֶם מִצַּד הַגְּבוּרָה, וְהוֹד דַּרְגָּה שֶׁל דָּוִד נִקְשְׁרָה בִּשְׂמֹאל שֶׁל גְּבוּרָה. וְאַהֲרֹן דַּרְגָּתוֹ בְּהוֹד נִקְשָׁר בְּחֶסֶד, זֶהוּ שֶׁכָּתוּב (תהלים טז) נְעִמוֹת בִּימִינְךְ נֶצַח.</p>\n<p>שְׁמַע יִשְׂרָאֵל שֶׁל הַיִּחוּד כּוֹלֵל בָּרְכוּ וּקְדֻשָּׁה, שֶׁהוּא קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ, וּבְרָכָה מִצַּד הַיָּמִין, זֶהוּ שֶׁכָּתוּב (במדבר ו) דַּבֵּר אֶל אַהֲרֹן וְאֶל בָּנָיו לֵאמֹר כֹּה תְבָרֲכוּ אֶת בְּנֵי יִשְׂרָאֵל. וּקְדֻשָּׁה מִצַּד הַלְוִיִּם עַמּוּד הָאֶמְצָעִי, הַקֶּשֶׁר שֶׁל יָמִין וּשְׂמֹאל, וְהוּא קֶשֶׁר שֶׁל תְּפִלִּין שֶׁל רֹאשׁ, שֶׁהוּא הָאֵם הָעֶלְיוֹנָה. תְּפִלִּין עַל רֹאשׁוֹ כְּמוֹ שֶׁבֵּאֲרוּהוּ בַּעֲלֵי הַמִּשְׁנָה, תְּפִלִּין שֶׁל רִבּוֹן הָעוֹלָם מַה כָּתוּב בָּהֶן? וְהוּא קֶשֶׁר שֶׁל תְּפִלִּין שֶׁל יָד, שְׁכִינָה תַּחְתּוֹנָה. וְזֶה שֶׁבֵּאֲרוּ בַּעֲלֵי הַמִּשְׁנָה, הֶרְאָהוּ לְמֹשֶׁה קֶשֶׁר שֶׁל תְּפִלִּין.</p>\n<p>שׁ' שֶׁלְּךְ מֹשֶׁה, כּוֹלֵל שְׁלֹשׁ פְּנֵי הָאָבוֹת לְמַעְלָה שֶׁתִּקְּנוּ שָׁלֹשׁ תְּפִלּוֹת, שֶׁסִּימָנָם: \"שַׁחֲרִית \"מִנְחָה \"עַרְבִית. מ\"ה שֶׁלְּךְ תְּפִלַּת הַשַּׁבָּת, שֶׁנֶּאֱמַר בָּהּ (בראשית א) וּרְדוּ בִּדְגַת הַיָּם וּבְעוֹף הַשָּׁמַיִם וּבַבְּהֵמָה וּבְכָל הָאָרֶץ,</p>\n<p>וְנִכְלְלָה מֶרְכָּבָה הַתַּחְתּוֹנָה שֶׁל אַהֲרֹן דָּוִד וּשְׁלֹמֹה, וְאָדָם הָרִאשׁוֹן לְמַעְלָה, וּבַת זוּגוֹ לְמַטָּה, אֵם כָּל חַי, שֵׁהוּא צַדִּיק חַי הָעוֹלָמִים. וְלָכֵןֹ, אַהֲרֹן אַף עַל גַּב שֶׁהוּא יָמִין, בֵּאֲרוּהוּ רַבּוֹתֵינוּ, אַהֲרֹן שׁוֹשְׁבִין הַגְּבִירָה הָיָה. רוֹעֶה הַנֶּאֱמָן, יַעֲקֹב הוּא הַכּוֹלֵל שְׁלֹשֶׁת הָאָבוֹת, שֶׁבּוֹ רוֹכֵב אָדָם הָרִאשׁוֹן, וְלֹא לְחִנָּם הֵקִימוּ בַּעֲלֵי הַמִּשְׁנָה, יָפְיוֹ שֶׁל יַעֲקֹב כְּיָפְיוֹ שֶׁל אָדָם הָרִאשׁוֹן.</p>\n<p>אָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה, רוֹעֶה הַנֶּאֱמָן, רָאִינוּ שֶׁכָּפַל הַקָּדוֹשׁ בָּרוּךְ הוּא שִׁמְךְ וְאָמַר מֹשֶׁה מֹשֶׁה, לִכְלֹל אוֹתְךְ בַּמֶּרְכָּבָה הָעֶלְיוֹנָה וּבַמֶּרְכָּבָה הַתַּחְתּוֹנָה, לְהַכְלִיל בְּךְ אָדָם הָרִאשׁוֹן מִצִּדּוֹ שֶׁל אַבְרָהָם, וּלְהַכְלִיל בְּךְ חַוָּה מִצַּד שֶׁל אַהֲרֹן דָּוִד וּשְׁלֹמֹה.</p>\n<p>לָמָּה לֹא כָפַל אֶת שֵׁם יַעֲקֹב כָּךְ? אָמַר לוֹ מְנוֹרָה הַקְּדוֹשָׁה, מִשּׁוּם שֶׁקָּרָא לוֹ יַעֲקֹב וְקָרָא לוֹ יִשְׂרָאֵל. יַעֲקֹב לְשׁוֹן לְשׁוֹן עָקֵב, שֶׁהַיְנוּ נְקֵבָה, שֶׁלָּמַדְנוּ, עֲקֵבוֹ שֶׁל אָדָם הָרִאשׁוֹן מַכְהֶה גַּלְגַּל חַמָּה. וְנִקְרָא יִשְׂרָאֵל, שֶׁשָּׁם רֹאשׁ זָכָר רֹאשׁ לַנְּקֵבָה, שֶׁהַיְנוּ עָקֵב. וְזֶהוּ שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לַנָּחָשׁ, (שם ג) הוּא יְשׁוּפְךְ רֹאשׁ וְאַתָּה תְּשׁוּפֶנּוּ עָקֵב, וְזֶה גָּרַם שְׁכִינָה בַּגָּלוּת, שֶׁנֶּאֱמַר בָּהּ (משלי כב) עֵקֶב עֲנָוָה יִרְאַת ה'.</p>\n<p>שָׂמַח רַבִּי שִׁמְעוֹן וְשָׂמְחוּ רָאשֵׁי הַיְשִׁיבָה וְאָמְרוּ לְפָנָיו, פֵּה הַשְּׁכִינָה, סִינַי, מִי יָכוֹל לַעֲמֹד (לפניו), שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ מְדַבְּרִים עִמּוֹ, וְשִׁשִּׁים רְבָבוֹת שֶׁל הַיְשִׁיבָה הַתַּחְתּוֹנִים מְדַבְּרִים עִמּוֹ, וְאַף שִׁשִּׁים רִבּוֹא שֶׁל הַיְשִׁיבָה הָעֶלְיוֹנָה כָּךְ מְדַבְּרִים עִמּוֹ. עַל פִּיךְ נֶאֱמַר וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְגוֹמֵר.</p>\n<p>דָּבָר אַחֵר וַיַּחֲלֹם וְהִנֵּה סֻלָּם. פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, סִינַ\"י זֶה סֻלָּם, וְהוּא קַ\"ל, וְסוֹד הַדָּבָר - (ישעיה יט) הִנֵּה ה' רֹכֵב עַל עָ\"ב קַ\"ל. עָב זֶה יוֹ\"ד הֵ\"י וָי\"ו הֵ\"י. וְעוֹד - יוֹ\"ד. יוֹ\"ד הֵ\"א. יוֹ\"ד הֵ\"א וָא\"ו. יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א - זֶה מֵאָה וּשְׁלֹשִׁים. הָאוֹתִיּוֹת הָרִאשׁוֹנוֹת עוֹלוֹת לְשִׁבְעִים וּשְׁנַיִם. הָאוֹתִיּוֹת שֶׁהֵן תּוֹלְדוֹתֵיהֶן עוֹלוֹת לְמֵאָה וּשְׁלֹשִׁים. עָ\"ב קַ\"ל מָאתַיִם וּשְׁתַּיִם כְּחֶשְׁבּוֹן בָּ\"ר. אַתָּה הוּא הַבֵּן, הָרוֹעֶה הַנֶּאֱמָן, עָלֶיךְ נֶאֱמַר (תהלים ב) נַשְּׁקוּ בַר. אַתָּה הוּא רַבָּן שֶׁל יִשְׂרָאֵל, גָּדוֹל לְמַטָּה, רַבָּן שֶׁל מַלְאֲכֵי הַשָּׁרֵת, בַּ\"ר לְמַעְלָה, בֵּן שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ,</p>\n<p>(חסר \"גם\" להשלים למאתים ארבעים וחמשה) עֲלֵיהֶם נֶאֱמַר לְגַבֵּי מָשִׁיחַ בֶּן יוֹסֵף (שמות ב) גַּם יְהֹוָ\"ה הֶעֱבִיר חַטָּאתְךְ לֹא תָמוּת. בַּ\"גַּם\" הַזֶּה הִתְכַּפֵּר דָּוִד, וְזֶהוּ שִׁעוּר שֶׁל הַחַלָּה, אַרְבָּעִים וְשָׁלֹשׁ בֵּיצִים וְתוֹסֶפֶת חֹמֶשׁ בֵּיצָה, רָמוּז (ויקרא ה) וַחֲמִשִׁתָיו יֹסֵף עָלָיו.</p>\n<p>אַשְׁרֵי הַתְּפִלָּה הַיּוֹצֵאת מִפִּיךְ, כְּמוֹ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יָרַד עַל הַר סִינַי וְנֶאֱמַר בּוֹ (דברים כט) כִּי אֶת אֲשֶׁר יֶשְׁנוֹ פֹּה עִמָּנוּ עֹמֵד הַיּוֹם (וגו') וְאֵת אֲשֶׁר אֵינֶנּוּ פֹּה עִמָּנוּ הַיּוֹם, כָּךְ כְּשֶׁאַתָּה מִשְׁתַּדֵּל בְּתוֹרָה וּבִתְפִלָּה, הַקָּדוֹשׁ בָּרוּךְ הוּא מְכַנֵּס עֶלְיוֹנִים וְתַחְתּוֹנִים, וְכָל הַנְּשָׁמוֹת הַלָּלוּ שֶׁהָיוּ וְשֶׁעֲתִידִין לִהְיוֹת, וְכָל מַחֲנוֹת הַמַּלְאָכִים, וְיוֹרֵד בְּצַלְמְךְ לְקַבֵּל תְּפִלָּתְךְ וְתוֹרָתְךְ, מִשּׁוּם שֶׁמַּחֲשַׁבְתְּךְ לְיַחֵד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא עִם שְׁכִינָתוֹ בְּכָל הַמַּחֲנוֹת שֶׁלּוֹ לְמַעְלָה וּלְמַטָּה,</p>\n<p>בְּתוֹרָתְךְ וּבִתְפִלָּתְךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מְצָרֵף מַחֲשָׁבָה טוֹבָה לְמַעֲשֶׂה, וּכְמוֹ שֶׁהוּא אָמַר אָנֹכִי, וְהֵם אָמְרוּ (שמות כד) נַעֲשֶׂה וְנִשְׁמָע. כָּךָ הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה לְכָל הַמַּחֲנוֹת, וְהֵם שׁוֹתְקִים וְשׁוֹמְעִים לִדְבָרְךְ, מִשּׁוּם שֶׁרְצוֹנְךְ בָּהֶם לְיַחֵד הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ בְּכָל הַמַּחֲנוֹת שֶׁלּוֹ. וְכָל מַה שֶּׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִבְטִיחַ וְהוֹדָה לַעֲשׂוֹת לְךְ חָכְמָה מִכַּמָּה טוֹבוֹת שֶׁאֵין לָהֶם סוֹף, כֻּלָּם אוֹמְרִים נַעֲשֶׂה וְנִשְׁמָע.</p>\n<p>וּמִשּׁוּם זֶה אָמְרוּ (תהלים קג) בָּרְכוּ ה' (כל) מַלְאָכָיו גִּבֹּרֵי כֹחַ וְגוֹמֵר, וְהֶחֱזִיק בְּךְ, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ וְכָל הַמַּחֲנוֹת שֶׁלּוֹ וְשֶׁל שְׁכִינָתוֹ הִסְכִּימוּ לַעֲשׂוֹת כָּל רְצוֹנְךְ, וְיוֹתֵר מִדַּאי הוּא כָּתוּב עַל יָדְךְ, וְלֹא נָפַל דָּבָר קָטָן מִכְּתִיבַת יָדְךְ שֶׁלֹּא הִתְקַיֵּם. אַשְׁרֵי הָאִישׁ שֶׁאֲדוֹנוֹ מַחֲשִׁיב אוֹתוֹ כְּגוּפוֹ וְעוֹשֶׂה לוֹ כָּבוֹד כִּדְמוּתוֹ לִהְיוֹת שׁוֹקֵל דִּבְרֵי פִיו בְּתוֹרָה וּבִתְפִלָּה כְּמוֹ לִמּוּד בְּהַר סִינַי, וְאֵין אֶחָד שֶׁפּוֹתֵחַ פִּיו לְקַטְרֵג, אֶלָּא עֶלְיוֹנִים וְתַחְתּוֹנִים בְּהַסְכָּמָה אַחַת בְּרָצוֹן אֶחָד: ע\"כ מההשמטות.</p>"],[9522012721,"<p>וַיִּזְכֹּר אֱלֹהִים אֶת רָחֵל. בְּשָׂרָה כָּתוּב פְּקִידָה, וּבְרָחֵל כָּתוּב זְכִירָה, לָמָּה? מִשּׁוּם שֶׁזָּכוֹר נִרְשַׁם בְּיַעֲקֹב שֶׁהוּא בְּרִית שָׁלוֹם כְּשֶׁנַּעֲשָׂה יוֹסֵף, וּבַמֶּה? כְּשֶׁנָּטַל שׁוֹר עִמּוֹ שֶׁלֹּא יֶחֱזַק אוֹתוֹ הַצַּד הָאַחֵר, וְלָכֵן נִקְרָא יוֹסֵף בְּכוֹר, שֶׁאוֹתוֹ שׁוֹר שֶׁנָּטַל בְּכוֹר שׁוֹרוֹ וַדַּאי, וְאוֹתוֹ שׁוֹר שׁוֹר תָּם, וְיַעֲקֹב אִישׁ תָּם רִבּוֹן וְשַׁלִּיט, בַּעַל הַבַּיִת שֶׁאוֹתוֹ שׁוֹר תָּם שׁוֹרֶה בְתוֹכוֹ: רעיא מהימנא פתח רבי שמעון השייךָּ לדף קס\"ה ע\"א אצל ויַעֲקֹב הלךָּ תמצא בחלק ג' דף רכ\"ה ע\"ב</p>"],[9522012722,"<p>לִי הַכֶּסֶף וְלִי הַזָּהָב. מַה זֶּה לִי הַכֶּסֶף וְלִי הַזָּהָב? מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְמֶלֶךְ שֶׁהָיוּ לוֹ שְׁנֵי אוֹצָרוֹת, אֶחָד שֶׁל כֶּסֶף וְאֶחָד שֶׁל זָהָב, שָׂם שֶׁל כֶּסֶף בִּימִינוֹ, וְשֶׁל זָהָב בִּשְׂמֹאלוֹ. אָמַר, זֶה יִהְיֶה מְזֻמָּן וְקַל לְהוֹצָאָה. וְעוֹשֶׂה דְבָרָיו בְּנַחַת, וְהוּא יִהְיֶה דָבֵק עִם הָעֲנִיִּים וּמַנְהִיגָם בְּנַחַת, כְּאוֹתָהּ שֶׁאָמַרְנוּ יְמִינְךְ ה' נֶאְדָּרִי בַּכֹּחַ. וְאִם שָׂמֵחַ אָדָם בְּחֶלְקוֹ - טוֹב,</p>\n<p>וְאִם לָאו - יְמִינְךְ ה' תִּרְעַץ אוֹיֵב. מַה זֶּה יְמִינְךְ ה' תִּרְעַץ אוֹיֵב? אָמַר לוֹ, זֶה הַזָּהָב, שֶׁכָּתוּב לִי הַכֶּסֶף וְלִי הַזָּהָב. וְלָמָּה נִקְרָא שְׁמוֹ זָהָב? שֶׁבּוֹ כְּלוּלוֹת שָׁלֹשׁ מִדּוֹת. הַז' - שֶׁבַע מִדּוֹת, הַה' - חָמֵשׁ אֲחָדוֹת אַחֲרוֹנוֹת (אחרונה), הַב' - חָכְמָה וּבִינָה. וְנִקְרֵאת נְשָׁמָה זוֹ עַל שֵׁם אֲצִילוּת, חָמֵשׁ סְפִירוֹת אַחֲרוֹנוֹת, וְחָמֵשׁ שֵׁמוֹת לַנְּשָׁמָה (נר\"ן ח\"י הסימן נפש רוח נשמה חיה יחידה) - רוּחַ חַיָּה יְחִידָה נְשָׁמָה נֶפֶשׁ.</p>\n<p>מַה מַּעֲשֵׂהוּ? כִּסֵּא הִיא ה', לְז', שֶׁכָּתוּב כִּי גָבהַּ מֵעַל גָּבֹהַּ שֹׁמֵר וּגְבהִים עֲלֵיהֶם, וּב' הִיא קִיּוּמָם, כְּמוֹ שֶׁנֶּאֱמַר בִּבְרֵאשִׁית. וּמַה מַּעֲשֵׂהוּ כָּאן? מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְאֶחָד שֶׁהָיָה לוֹ בַּת טוֹבָה וּנְעִימָה וּשְׁלֵמָה וְנָאָה, וְהִשִּׂיאָהּ לְבֶן מֶלֶךְ, וְהִלְבִּישָׁהּ וְעִטְּרָהּ וְקִשְּׁטָהּ, וּנְתָנָהּ לוֹ עִם מָמוֹן רַב. אָמַר, אֶפְשָׁר לְמֶלֶךְ זֶה לָשֶׁבֶת חוּץ מִבֵּיתוֹ? אָמַרְתָּ לֹא. אֶפְשָׁר לוֹ לָשֶׁבֶת כָּל הַיּוֹם תָּמִיד עִמָּהּ? אָמַרְתָּ לֹא. הָא כֵּיצַד? שָׂם חַלּוֹן בֵּינוֹ לְבֵינָהּ, וְכָל שָׁעָה שֶׁצְּרִיכָה הַבַּת לְאָבִיהָ אוֹ הָאָב לְבִתּוֹ, מִתְחַבְּרִים יַחַד בַּחַלּוֹן. זֶהוּ שֶׁכָּתוּב כָּל כְּבוּדָּה בַת מֶלֶךְ פְּנִימָה מִמִּשְׁבְּצוֹת זָהָב לְבוּשָׁהּ (ע\"כ). (וכתוב) (וויהם כסף) וְאַדְנֵיהֶם נְחֹשֶׁת, שֶׁהֵם כְּלֵי שִׁמּוּשׁ שֶׁהַמִּשְׁכָּן יִשְׁתַּמֵּשׁ בָּהֶם.</p>\n<p>אֲבָל כָּאן בִּלְבוּשֵׁי הַכָּבוֹד הַלָּלוּ לֹא צָרִיךְ לְהִשְׁתַּמֵּשׁ בָּהֶם אִישׁ אַחֵר פְּרָט כֹּהֵן (מהכהן) הַגָּדוֹל, שֶׁשֶּׁמֶן מִשְׁחַת קֹדֶשׁ עַל רֹאשׁוֹ, שֶׁכָּתוּב (ועשית) בִּגְדֵי קֹדֶשׁ לְאַהֲרֹן אָחִיךְ לְכָבוֹד וּלְתִפְאָרֶת, בְּאוֹתָם לְבוּשִׁים דּוֹמֶה לְגָוֶן עֶלְיוֹן: ע\"כ מההשמטות</p>"],[9522012723,"<p>מַהוּ פְּרִי עֵץ הָדָר? עֵץ הָאֶתְרוֹג. וּמַהוּ הָדָר? הָדָר עַל הַכֹּל, וְהַיְנוּ הָדָר שֶׁל שִׁיר הַשִּׁירִים, שֶׁכָּתוּב בּוֹ מִי זֹאת הַנִּשְׁקָפָה כְּמוֹ שָׁחַר. וְהַיְנוּ עַל שֵׁם נְקֵבָה, וְעַל שְׁמָהּ נִלְקְחָה נְקֵבָה מֵאָדָם שֶׁאִי אֶפְשָׁר לְהִתְקַיֵּם עוֹלָם הַתַּחְתּוֹן בְּלֹא נְקֵבָה. וּמָה הַטַּעַם נִקְרֵאת נְקֵבָה? עַל שֵׁם שֶׁנְּקָבֶיהָ רְחָבִים, וְיֵשׁ לָהּ נְקָבִים יְתֵרִים עַל הָאִישׁ, וּמַה הֵם הַנְּקָבִים: שָׁדַיִם וָרֶחֶם וּבֵית קִבּוּל הַוָּלָד.</p>\n<p>וּמַה שֶׁאָמְרוּ, שִׁיר הַשִּׁירִים שֶׁהוּא הָדָר לְכָל סִפְרֵי הַקֹּדֶשׁ - כֵּן. שֶׁאָמַר רַבִּי יוֹחָנָן, כָּל הַסְּפָרִים קֹדֶשׁ, וְשִׁיר הַשִּׁירִים קֹדֶשׁ קָדָשִׁים. וּמַהוּ קֹדֶשׁ קָדָשִׁים? אֶלָּא קֹדֶשׁ שֶׁהוּא קֹדֶשׁ לְקָדָשִׁים. וּמַה הֵם קָדָשִׁים? אֵלּוּ שֶׁכְּנֶגֶד שֵׁשׁ קְצָווֹת שֶׁבָּאָדָם, וְקֹדֶשׁ יִהְיֶה לָהֶם קֹדֶשׁ לְכֻלָּם.</p>\n<p>וּמַהוּ קֹדֶשׁ? זֶה אֶתְרוֹג, שֶׁהוּא הָדָר לַכֹּל. וְלָמָּה נִקְרָא שְׁמוֹ הָדָר? אַל תִּקְרֵי הָדָר אֶלָּא ה' דָּר, זֶה אֶתְרוֹג שֶׁהוּא נִפְרָד מֵאֶגֶד הַלּוּלָב, וְאֵין מִצְוַת לוּלָב קַיֶּמֶת אֶלָּא בּוֹ, וְהוּא גַּם כֵּן אָגוּד עִם הַכֹּל, שֶׁעִם כָּל אֶחָד הוּא, וְעִם כֻּלָּם יַחַד הוּא.</p>\n<p>וּמַהוּ הַלּוּלָב? כְּנֶגֶד חוּט הַשִּׁדְרָה. וַעֲנַף עֵץ עָבת - שֶׁעֲנָפָיו חוֹפִים אֶת רֻבּוֹ, וְאִם אֵין עֲנָפָיו חוֹפִים אֶת רֻבּוֹ - אֵינוֹ כְלוּם. מִפְּנֵי מָה? מָשָׁל לְאָדָם שֶׁבִּזְרוֹעוֹתָיו יָגֵן עַל רֹאשׁוֹ, הֲרֵי זְרוֹעוֹתָיו שְׁנַיִם וְרֹאשׁוֹ שְׁלֹשָׁה, וְהַיְנוּ עָנָף לִשְׂמֹאל, עָבֹת לְיָמִין, וְנִמְצָא עֵץ בָּאֶמְצַע. וְלָמָּה נֶאֱמַר בּוֹ עֵץ? שֶׁהוּא שֹׁרֶשׁ הָאִילָן.</p>\n<p>וּמַה זֶּה עַרְבֵי נָחַל? שׁוֹקֵי הָאָדָם שֶׁהֵם שְׁתַּיִם. וּמַהוּ לָשׁוֹן שֶׁל עַרְבֵי נָחַל? מִשּׁוּם שֶׁגָּדוֹל שֶׁבָּהֶם הוּא לַמַּעֲרָב, וּמִשָּׁם יוֹנֵק כֹּחוֹ, וְשֶׁל צָפוֹן הוּא קָטָן מִמֶּנּוּ מַהֲלַךְ חֲמֵשׁ מֵאוֹת שָׁנָה, וְהוּא בְּרוּחַ צְפוֹנִית מַעֲרָבִית, וּבוֹ פוֹעֵל וְנִקְרָא עַל שְׁמוֹ, וְהֵם שְׁנֵיהֶם עֵצִים.</p>\n<p>דָּבָר אַחֵר עַרְבֵי - שֶׁפְּעָמִים מְעָרְבִים פְּעֻלָּתָם זֶה עִם זֶה. מַה זֶּה עַרְבֵי נָחַל? נַחַל הוּא עַל שֵׁם הַמָּקוֹם שֶׁהֵם קְבוּעִים בּוֹ שֶׁשְּׁמוֹ נַחַל, כְּמוֹ שֶׁכָּתוּב כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם. מַהוּ יָם? הֱוֵי אוֹמֵר זֶה אֶתְרוֹג. וּמִנַּיִן לָנוּ שֶׁכָּל מִדָּה וּמִדָּה מֵאֵלּוּ הַשִּׁבְעָה נִקְרֵאת נַחַל? שֶׁנֶּאֱמַר וּמִמַּתָּנָה נַחֲלִיאֵל, אַל תִּקְרֵי נַחֲלִיאֵל אֶלָּא נַחֲלֵי אֵל.</p>\n<p>וְעוֹד שָׁם, מָה לֵּב, הָדָר פְּרִי הַגּוּף, אַף יִשְׂרָאֵל פְּרִי עֵץ הָדָר. מָה אִילַן תָּמָר, עֲנָפָיו סְבִיבָיו וְלוּלָבוֹ בָּאֶמְצַע, אַף יִשְׂרָאֵל נָטְלוּ גוּף הָאִילָן הַזֶּה שֶׁהוּא לִבּוֹ, וּכְנֶגֶד הַגּוּף חוּט הַשִּׁדְרָה בָּאָדָם שֶׁהוּא עִקַּר הַגּוּף. וּמַה לּוּלָב זֶה כָּתוּב לוֹ לֵב, אַף לֵב מָסוּר לוֹ. וּמַה לֵּב זֶה שְׁלֹשִׁים וּשְׁתַּיִם נְתִיבוֹת חָכְמָה בּוֹ, אַף בְּכָל נָתִיב מֵהֶן צוּרָה שׁוֹמֶרֶת, שֶׁנֶּאֱמַר לִשְׁמֹר אֶת דֶּרֶךְ עֵץ הַחַיִּים: ע\"כ מההשמטות</p>"],[9522012724,"<p>(שמות כ) וְכָל הָעָם רֹאִים אֶת הַקּוֹלֹת וְאֵת הַלַּפִּידִם. וְכִי רוֹאִים אֶת הַקּוֹלוֹת? אֶלָּא וְכָל הָעָם רֹאִים אֶת הַקּוֹלֹת, אוֹתָם קוֹלוֹת שֶׁנֶּאֱמַר (תהילים כט) קוֹל יְיָ עַל הַמָּיִם אֵל הַכָּבוֹד הִרְעִים. קוֹל יְיָ בַּכֹּחַ. וְאומֵר (ישעיה י) בְּכֹחַ יָדִי עָשִׂיתִי. וְאומֵר (שם מח) אַף יָדִי יָסְדָה אֶרֶץ. (תהליםכט) קול ה' בֶּהָדָר. וְאומֵר (שם קיא) הוד והדר פעלו וצדקתו. (שם כט) קול יי שבר ארזים, זה קשת שמשברת עצי ארזים ועצי בְרוֹשִׁים. (שם) קול יְיָ חֹצֵב לַהֲבוֹת אֵשׁ, זֶה שֶׁעוֹשֶׂה שָׁלוֹם בֵּין הָאֵשׁ וּבֵין הַמַּיִם, שֶׁחוֹצֵב כֹּחַ הָאֵשׁ וּמוֹנֵעַ אוֹתוֹ מִלִּלְחֹךְ הַמַּיִם גַּם מוֹנֵעַ מִלְּכַבּוֹתוֹ. (שם) קוֹל יְיָ יָחִיל מִדְבָּר, שֶׁנֶּאֱמַר (שם יח) וְעֹשֶׂה חֶסֶד לִמְשִׁיחוֹ לְדָוִד וּלְזַרְעוֹ עַד עוֹלָם. יוֹתֵר מִן הַמִּדְבָּר. (שם כט) קוֹל יְיָ יְחוֹלֵל אַיָּלוֹת וַיֶּחֱשּׁף יְעָרוֹת וּבְהֵיכָלוֹ כֻּלּוֹ אֹמֵר כָּבוֹד, שֶׁכָּתוּב (שיר השירים ב) הִשְׁבַּעְתִּי אֶתְכֶם בְּנוֹת יְרוּשָׁלם בִּצְבָאוֹת או בְּאַיְלוֹת הַשָּׂדֶה. הָא לָמַדְתָּ שֶׁבְּשֶׁבַע קוֹלוֹת נִתְּנָה הַתּוֹרָה, וּבְכֻלָּם נִגְלָה עֲלֵיהֶם אֲדוֹן הָעוֹלָם וְרָאוּם, וְהַיְנוּ שֶׁכָּתוּב (שמותב) וְכָל הָעָם רֹאִים אֶת הַקּוֹלֹת.</p>\n<p>כָּתוּב אֶחָד אוֹמֵר, (תהלים יח) וַיֵּט שָׁמַיִם וַיֵּרַד וַעֲרָפֶל תַּחַת רַגְלָיו. וְכָתוּב אֶחָד אוֹמֵר, (שמות כ) כִּי מִן הַשָּׁמַיִם דִּבַּרְתִי עִמָּכֶם. הָא כֵיצַד? אִשּׁוֹ הַגְּדוֹלָה הָיְתָה בָאָרֶץ שֶׁהוּא קול אֶחָד, וּשְׁאָר קוֹלוֹת הָיוּ בַשָּׁמַיִם, שֶׁכָּתוּב (דברים ד) מִן הַשָּׁמַיִם הִשְׁמִיעֲךְ אֶת קוֹלוֹ לְיַסְּרֶךָּ וְעַל הָאָרֶץ הֶרְאֲךְ אֶת אִשּׁוֹ הַגְּדוֹלָה וּדְבָרָיו שָׁמַעְתָּ מִתּוֹךָּ הָאֵשׁ. וּמַהִי גְּדוֹלָה? וּמֵאֵלּוּ הָיָה יוֹצֵא דִבּוּר מִתּוֹךָּ הָאֵשׁ, שֶׁנֶּאֱמַר וּדְבָרָיו שָׁמַעְתָּ מִתּוֹךָּ הָאֵשׁ.</p>\n<p>וּמָה (שם) וּתְמוּנָה אֵינְכֶם רֹאִים זוּלָתִי קול? כְּמוֹ שֶׁאָמַר לָהֶם מֹשֶׁה לְיִשְׂרָאֵל (שם) כִּי לֹא רְאִיתֶם כָּל תְּמוּנָה. תְּמוּנָה, וְלֹא כָל תְּמוּנָה. מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְמֶלֶךְ שֶׁהָיָה עוֹמֵד עַל עֲבָדָיו מְעֻטָּף בִּכְסוּת לְבָנָה, לֹא דַי לְאֵימַת הַמֶּלֶךְ שֶׁיִּסְתַּכְּלוּ בִלְבוּשָׁיו, וְעוֹד רָחוֹק הָיָה הַמֶּלֶךְ וְשָׁמְעוּ קוֹלוֹ, יְכוֹלִין לִרְאוֹת גְרוֹנוֹ? אָמַרְתָּ לֹא. הֲרֵי לָמַדְתָּ שֶׁרָאוּ תְמוּנָה וְלֹא כָל תְמוּנָה, וְהַיְנוּ שֶׁכָּתוּב, וּתְמוּנָה אֵינְכֶם רוֹאִים זוּלָתִי קול. וְכָתוּב (שם) קוֹל דְּבָרִים אַתֶּם שּמְעִים.</p>\n<p>כָּתוּב אֶחָד אוֹמֵר, וְכָל הָעָם רֹאִים אֶת הַקּוֹלֹת, וְכָתוּב אֶחָד אוֹמֵר קוֹל דְּבָרִים אַתֶּם שׁוֹמְעִים. הָא כֵיצַד? בַּתְּחִלָּה רוֹאִים אֶת הַקּוֹלוֹת. וּמָה רָאוּ? שִׁבְעָה קוֹלוֹת שֶׁאָמַר דָּוִד, וְלַסּוֹף שָׁמְעוּ הַדָּבָר יוֹצֵא מִבֵּין כֻּלָּם.</p>\n<p>וַהֲרֵי הֵם עֲשָׂרָה. שֶׁחֲכָמִים אָמְרוּ שֶׁכָּל הָאֲמִירוֹת כְּמִלָּה אַחַת, כֵּן כֻּלָּן כְּמִלָּה אַחַת נֶאֶמְרוּ. וְהָיוּ שִׁבְעָה מַאֲמָרוֹת בְּשִׁבְעָה קוֹלוֹת. וְעַל זֶה נֶאֱמַר, קוֹל דְּבָרִים אַתֶּם שּמְעִים וּתְמוּנָה אֵינְכֶם רֹאִים זוּלָתִי קול. הֲרֵי לָמַדְתָּ שֶׁכֻּלָּם כְּאֶחָד מִדִּבּוּר אֶחָד נֶאֶמְרוּ. וּבַעֲבוּר שֶׁלֹּא יִטְעוּ יִשְׂרָאֵל לוֹמַר, אֲחֵרִים יַעְזְרוּהוּ מִן הַמַּלְאָכִים, אַף קוֹלוֹ לְבַדּוֹ לֹא יוּכַל לִהְיוֹת חָזָק כָּל כָּךְ, בַּעֲבוּר כָּךְ חָזַר וּכְלָלָם.</p>\n<p>דָּבָר אַחֵר, שֶׁלֹּא יֹאמְרוּ הָעוֹלָם, הוֹאִיל וְהֵם עֲשָׂרָה מַאֲמָרוֹת לַעֲשָׂרָה מַלְאָכִים, שֶׁמָּא לֹא יוּכְלוּ לְדַבֵּר עַל פֶּה אֶחָד, כָּתוּב בּוֹ \"אָנֹכִי\", וְכָלַל כָּל הָעֲשָׂרָה. וּמָה הָעֲשָׂרָה מְלָכִים? שִׁבְעָה קוֹלוֹת וּשְׁלֹשָׁה מַאֲמָרִים. וּמָה אוֹמְרִים? שֶׁכָּתוּב (דבריםכו) וַייָ הֶאֱמִירְךְ הַיּוֹם. וּמָהֵם הַשְּׁלֹשָׁה? שֶׁכָּתוּב (משלי ד) רֵאשִׁית חָכְמָה קְנֵה חָכְמָה וּבְכָל קִנְיָנְךְ קְנֵה בִינָה. כְּמוֹ שֶׁנֶּאֱמַר (איוב לב) וְנִשְׁמַת שַׁדַּי תְּבִינֵם. נִשְׁמָתוֹ שֶׁל שַׁדַּי, הִיא תְבִינֵם. שְׁלִישִׁית מֶה הָיְתָה? כְּמוֹ שֶׁאָמַר לוֹ אוֹתוֹ גֶּבֶר זָקֵן לְאוֹתוֹ תִינוֹק, בַּמֻּפְלָא מִמְּךְ אַל תִּדְר!שׁ וּבַמְכֻסֶּה מִמְּךְ אַל תַּחְקֹר. בְּמַה שֶּׁהִרְשִׁיתִיךְ הִתְבּוֹנֵן, אֵין לְךְ עֵסֶק בַּנִּסְתָּרוֹת.</p>\n<p>שָׁנִינוּ, (משליכה) כְּבֹד אֱלהִים הַסְתֵּר דָּבָר. מָה הַדָּבָר, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קיט) רֹאשׁ דְּבָרְךְ אֱמֶת. (משלי כה) וּכְבֹד מְלָכִים חֲקֹר דָּבָר. מָה הַדָּבָר? שֶׁכָּתוּב (שם) דָּבָר דָּבֻר עַל אָפְנָיו. אַל תִּקְרֵי אָפְנָיו, אֶלָּא אוֹפַנָּיו: (עד כאן מההשמטות)</p>"],[9522012725,"<p>וְאֵלּוּ הֵן י\"ב מִצְווֹת: א - יִחוּד ה'. ב - לְיִרְאָה אֶת ה'. ג - לָדַעַת שֶׁיֵּשׁ דַּיָּן וְיֵשׁ שָׂכָר טוֹב וְכוּ'. ד - לְקַדֵּשׁ אֶת ה'. ה - לְהִתְפַּלֵּל בְּכָל יוֹם שַׁחֲרִית מִנְחָה עַרְבִית. ו - לַעֲסֹק בַּתּוֹרָה. ז - לָמוּל אֶת הַבֵּן. ח - קַדֶּשׁ לִי כָל בְּכוֹר. ט - תְּפִלִּין. י - צִיצִית. יא - מְזוּזָה. יב - לִמְסֹר נַפְשׁוֹ בִּדְבֵקוּת.</p>\n<p>אֵלּוּ הֵם י\"ב מִצְווֹת שָׁמוֹר: א - שֶׁלֹּא לָתֵת גְּדֻלָּה לַעֲבוֹדָה זָרָה. ב - שֶׁלֹּא לִבְנוֹת מִגְדָּל לַעֲבוֹדָה זָרָה. ג - אַל תִּפְנוּ וְגוֹ', (שלא) לְהַרְהֵר אַחֲרֵיהֶם. ד - לֹא תִשְׁתַּחֲוֶה לָהֶם. ה - שֶׁלֹּא לְהִכָּנַע, זֶהוּ לֹא תָעָבְדֵם. ו - שֶׁלֹּא לְהַחֲלִיף יִחוּד שֶׁל רִבּוֹנוֹ, זֶהוּ הַהֵימִיר. ז - שֶׁלֹּא לְהַרְהֵר, זֶהוּ לֹא תָתוּרוּ וְגוֹ'. ח - שֶׁלֹּא לִשְׁאֹל בְּאוֹב. ט - שֶׁלֹּא לִשְׁאֹל בְּיִדְּעוֹנִי. י - שֶׁלֹּא לִדְרשׁ אֶל הַמֵּתִים. יא - שֶׁלֹּא לַעֲשׂוֹת כְּשָׁפִים, זֶהוּ וְחֹבֵר חָבֶר. יב - וְשֵׁם אֱלֹהִים אֲחֵרִים שֶׁלֹּא תַזְכִּירוּ:</p>"],[9522012726,"<p>יָשַׁב רַבִּי בְּרֶכְיָה וְדָרַשׁ, מַהוּ שֶׁכָּתוּב (שמות כה) וְיִקְחוּ לִי תְּרוּמָה? כָּךְ אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אוֹתָהּ תְּרוּמָה תָּרִימוּ אוֹתָהּ בִּתְפִלּוֹתֵיכֶם, וּמִי הוּא אוֹתוֹ שֶׁנְּדָבוֹ לִבּוֹ לְהִמָּשֵׁךְ מִן הָעוֹלָם הַזֶּה - כַּבְּדוּהוּ, כִּי בוֹ אֲנִי שָׂמֵחַ שֶׁיּוֹדִיעַ שְׁמִי, וּמִמֶּנּוּ רָאוּי לָקַחַת אֶת תְּרוּמָתִי, שֶׁנֶּאֱמַר (שם) מֵאֵת כָּל אִישׁ אֲשֶׁר יִדְּבֶנּוּ לִבּוֹ תִּקְחוּ אֶת תְּרוּמָתִי, מֵאוֹתוֹ הַמִּתְנַדֵּב.</p>\n<p>שֶׁאָמַר רַבִּי רְחִימַאי, צַדִּיקִים וַחֲסִידִים שֶׁבְּיִשְׂרָאֵל שֶׁמְּרִימִין אוֹתִי עַל כָּל הָעוֹלָם בִּזְכֻיּוֹתֵיהֶן וּמֵהֶם מִתְפַּרְנֵס הַלֵּ\"ב, וְהַלֵּב מְפַרְנְסָן. וְכָל הַצּוּרוֹת הַקְּדוֹשׁוֹת הַמְמֻנּוֹת עַל הָאֻמּוֹת, וְיִשְׂרָאֵל קְדוֹשִׁים נָטְלוּ מִגּוּף הָאִילָן וּמִלִּבּוֹ. מַה לֵּב הָדָר, פְּרִי הַגּוּף - אַף יִשְׂרָאֵל נָטְלוּ עֵץ הָדָר.</p>\n<p>מָה אִילָן תָּמָר, עֲנָפָיו סְבִיבָיו וְלוּלָבוֹ בָּאֶמְצַע - אַף יִשְׂרָאֵל נָטְלוּ גּוּף הָאִילָן הַזֶּה, שֶׁהוּא לִבּוֹ. וּכְנֶגֶד הַגּוּף הוּא חוּט הַשִּׁדְרָה בָּאָדָם, שֶׁהוּא עִקַּר הַגּוּף, לָמָּה לוּלָב זֶה כָּתוּב לוֹ לֵב - אַף הַלֵּב מָסוּר ל\"וֹ. וּמַה לֵּ\"ב זֶה שְׁלֹשִׁים וּשְׁתַּיִם נְתִיבוֹת חָכְמָה בוֹ - אַף בְּכָל נָתִיב מֵהֶם צוּרָה שׁוֹמֶרֶת, שֶׁנֶּאֱמַר (בראשית ג) לִשְׁמֹר אֶת דֶּרֶךְ עֵץ הַחַיִּים.</p>\n<p>וּמַהוּ (שם) וַיַּשְׁכֵּן מִקֶּדֶם לְגַן עֵדֶן? וַיִּשְׁכֹּן בְּאוֹתָן נְתִיבוֹת שֶׁקָּדְמוּ לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא גַּן וְשֶׁקָּדַם לַכְּרוּבִים, שֶׁכָּתוּב (שם) וְאֶת הַכְּרֻבִים. וְשֶׁקָּדַם לְלַהַט, שֶׁכָּתוּב (שם) אֶת לַהַט הַחֶרֶב.</p>\n<p>וַהֲרֵי כָּתוּב שֶׁמַּיִם וְאֵשׁ קָדְמוּ, שֶׁכָּתוּב (שם א) יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם. וְכָתוּב וַיִּקְרָא אֱלֹהִים לָרָקִיעַ שָׁמָיִם. וּמִנַּיִן לָנוּ שֶׁשָּׁמַיִם הָיוּ אֵשׁ? שֶׁכָּתוּב (דברים ד) כִּי ה' אֱלֹהֶיךְ אֵשׁ אֹכְלָה הוּא. וּמִנַּיִן לָנוּ שֶׁשָּׁמַיִם הַקָּדוֹשׁ בָּרוּךְ הוּא? שֶׁכָּתוּב (מלכים א ח) וְאַתָּה תִשְׁמַע הַשָּׁמַיִם. הַאִם שְׁלֹמֹה מִתְפַּלֵּל אֶל הַשָּׁמַיִם שֶׁיִּשְׁמְעוּ תְפִלָּתוֹ? אֶלָּא שֶׁנִּקְרָא שְׁמָם עַל שְׁמוֹ, שֶׁכָּתוּב (מלכים א ח) הַשָּׁמַיִם וּשְׁמֵי הַשָּׁמַיִם לֹא יְכַלְכְּלוּךְ. הֲרֵי שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וַהֲרֵי אֵשׁ. וְאָמַרְתָּ קֶדֶם?</p>\n<p>אֶלָּא אֱמֹר, כֹּחָם קֶדֶם שֶׁל אוֹתָן הַצוּרוֹת שֶׁל הַמָּקוֹם הַהוּא. וּמַהוּ כֹחָם? כְּמוֹ שֶׁנֶּאֱמַר (שמואל א ב) אֵין קָדוֹשׁ כַּייָ כִּי אֵין בִּלְתֶּךְ וְאֵין צוּר כֵּאלֹהֵינוּ.</p>\n<p>יָשַׁב רַבִּי בְּרֶכְיָה וְדָרַשׁ, מַהוּ הַלּוּלָב שֶׁאָנוּ אוֹמְרִים? אֶלָּא לוֹ מָסַר הַלֵּב. וְהֵיאַךְ? אָמַר לוֹ, שְׁלֹשָׁה שָׂרִים הֵם, תל\"י וְגַלְגַּל וְל\"ב, וּלְכָל אֶחָד וְאֶחָד שְׁנֵים עָשָׂר. חָזְרוּ הַשְּׁלֹשָׁה מִנְיַן ל\"וֹ, וּבָהֶם נִתְקַיֵּם הָעוֹלָם, שֶׁכָּתוּב (משלי כה) וְצַדִּיק יְסוֹד עוֹלָם.</p>\n<p>שָׁנִינוּ, עַמּוּד אֶחָד מִן הָאָרֶץ עַד לָרָקִיעַ וְצַדִּיק שְׁמוֹ, עַל שֵׁם הַצַּדִּיקִים, וְנִתְגַּבֵּר. וְאִם לֹא - מִתְחַלֵּשׁ, וְהוּא סוֹבֵל כָּל הָעוֹלָם, שֶׁכָּתוּב וְצַדִּיק יְסוֹד עוֹלָם. וְאִם חַלָּשׁ, לֹא יוּכַל לְהִתְקַיֵּם הָעוֹלָם. הִלְכָּךְ אֲפִלּוּ אֵין בָּעוֹלָם אֶלָּא צַדִּיק אֶחָד, מַעֲמִיד אֶת הָעוֹלָם. לְפִיכָךְ קְחוּ תְרוּמָתִי מִמֶּנּוּ תְחִלָּה, וְאַחֲרָיו זאת הַתְּרוּמָה אֲשֶׁר תִּקְחוּ מֵאִתָּם, מֵאֵת הַנִּשְׁאָר. וּמַהוּ זָהָב וָכֶסֶף וּנְחֹשֶׁת?</p>\n<p>דָּבָר אַחֵר וְיִקְחוּ לִי תְּרוּמָה - וְיִקְחוּ לִי לְקַדֵּשׁ תְּרוּמָה, שֶׁהִיא יוֹ\"ד, וְהִיא עֲשִׂירִי. וּמִנַּיִן לָנוּ שֶׁעֲשִׂירִי קֹדֶשׁ? שֶׁכָּתוּב (ויקרא כז) הָעֲשִׂירִי יִהְיֶה קֹּדֶשׁ, לְקֹדֶשׁ. וּמַהוּ קֹדֶשׁ? שֶׁכָּתוּב (יחזקאל מד) וְרֵאשִׁית כָּל בִּכּוּרֵי כֹל וְכֹל תְּרוּמַת כֹּל מִכֹּל תְּרוּמוֹתֵיכֶם, שֶׁכָּתוּב (תהלים קיא) רֵאשִׁית חָכְמָה יִרְאַת ה', אֵין חָכְמָה אֶלָּא יִרְאַת הַשֵּׁם. (עד כאן מההשמטות)</p>"],[9522012727,"<p>יֵשׁ בְּצַוָּאַת רִבִּי אֱלִיעֶזֶר הַגָּדוֹל, קַרְקַע הַגָּן הוּא כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא גַּן עֵדֶן, נָטַל שֶׁלֶג מִתַּחַת כִּסֵּא הַכָּבוֹד, וּמִמֶּנָּה נַעֲשָׂה קַרְקַע הַגָּן, וְזֶהוּ קַרְקָעִיתוֹ שֶׁל גַּן עֵדֶן. וְאֵינוֹ נוֹגֵעַ עִם הָאָרֶץ הַזֹּאת, שֶׁהִיא לְמַעְלָה מִכָּל הָאֲרָצוֹת.</p>\n<p>רָקִיעַ שֶׁעַל גַּבֵּי הַגָּן הוּא כְעֵין כָּל הַגְּוָנִים, כְּמַעֲשֵׂה לִבְנַת הַסַּפִּיר. וּשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא חָקוּק בְּאֶמְצַע הָרָקִיעַ. וְאַרְבַּע טַבָּעוֹת בְּאַרְבָּעָה קְצוֹת הָרָקִיעַ, וְאַרְבָּעָה אוֹפַנִּים בְּכָל טַבַּעַת. וּבְאֶמְצַע הָרָקִיעַ עַמּוּד אֶחָד, וְעַמּוּד הַזֶּה נָעוּץ מִקַּרְקַע הַגָּן עַד שֶׁאוֹחֵז פְּנֵי כִסֵּא הַכָּבוֹד, וְהוּא מְכֻסֶּה מֵעֲנַן הַכָּבוֹד. וְהַמַּלְאָךְ גַּבְרִיאֵל לְבוּשׁ הַבַּדִּים עוֹמֵד עָלָיו. פַּעַם כֻּלָּם אוֹחֲזִים בְּטַבְּעוֹת הָרָקִיע! וְהָעַמּוּד חוֹזֵר וְהָרָקִיעַ סוֹבֵב, וְאוֹתִיּוֹת שֵׁם הַמְפֹרָשׁ בּוֹלְטוֹת וְנוֹצְצוֹת וְעוֹלוֹת וְיוֹרְדוֹת.</p>\n<p>קוֹל קוֹרֵא: הִתְנוֹדְדוּ מַחֲנוֹת צַדִּיקִים קְדוֹשִׁים, אַשְׁרֵיכֶם שֶׁזְּכִיתֶם לְכָךְ. מִי שָׁמַע כָּזֹאת, מִי רָאָה כָאֵלֶּה, בִּהְיוֹת כָּל נִגּוּן הָרָקִיעַ בְּנָסְעוֹ עַל יְדֵי הָאִישׁ לְבוּשׁ הַבַּדִּים, וְהוּא מִסְתַּלֵּק וְהָרָקִיעַ עוֹמֵד. וְהָעַמּוּד מְנַגֵּן, עוֹלֵה וְיוֹרֵד, עַד שֶׁנִּמְשָׁךְ אוֹר זֹהַר, אוֹר נֹעַם מִלְמַעְלָה בְּאוֹתוֹ הָעַמּוּד. וְהַצַּדִּיקִים עוֹמְדִים לְנֶגֶד הָאוֹר הַהוּא וְנֶהֱנִים מִמֶּנּוּ עַד חֲצוֹת הַלַּיְלָה.</p>\n<p>בַּחֲצִי הַלַּיְלָה כְּשֶׁבָּא הַקָּדוֹשׁ בָּרוּךְ הוּא לִכָּנֵס עִם הַצַּדִּיקִים, שׁוֹמְעִים קול סִבּוּב הָרָקִיעַ וְהָעַמּוּד מְנַגֵּן, וְקַרְקַע הַגָּן מִתְנַשֵּׂא, וְהַצַּדִּיקִים עוֹלִים מֵחֻפּוֹתֵיהֶם לִקְרַאת בּוֹרְאָם, וְכָל הַגָּן מִתְמַלֵּא מִכְּבוֹדוֹ. בְּאוֹתָהּ שָׁעָה מִזְדַּוְּגוֹת הָרוּחוֹת זְכָרִים וּנְקֵבוֹת כְּפִי שֶׁהָיוּ קֹדֶם שֶׁנִּבְרְאוּ, וּמֵאוֹתוֹ נֹעַם תַּאֲוָתָם לַחֲזוֹת בְּנֹעַם ה', כֻּלָּם עוֹשִׂים פֶּרִי, דְּהַיְנוּ רוּחוֹת לַגֵּרִים: (עד כאן מההשמטות)</p>"],[9522012728,"<p>מִצְוָה לְהַקְרִיב קָרְבָּן, שֶׁהוּא הִתְחַדְּשׁוּת שֶׁל הַלְּבָנָה בְּכָל חֹדֶשׁ וְחֹדֶשׁ, וּבַהִתְחַדְּשׁוּת שֶׁלָּהּ לְקָרֵב הָאַהֲבָה לְמַעְלָה וּלְמַטָּה וּלְהַעֲבִיר הַזֻּהֲמָא מִבֵּית הַמִּקְדָּשׁ, וְקָרְבָּן שֶׁל רֹאשׁ חֹדֶשׁ עוֹלֶה לְמַעְלָה כְּדֵי לְהַמְשִׁיךְ הֶאָרַת הַפָּנִים מִמָּקוֹר הָעֶלְיוֹן לְמַטָּה, שֶׁזֶּה נִצְרָךְ מִשּׁוּם מִעוּט וְהַקְטָנַת הַלְּבָנָה,</p>\n<p>וְהַשָּׂעִיר הַהוּא שֶׁל רֹאשׁ חֹדֶשׁ הֶעֱבִיר זֻהֲמָא וְהִרְחִיק אוֹתוֹ שֶׁלֹּא יְכַסֶּה אֶת הַלְּבָנָה, וְאָז הִמְשִׁיךְ הֶמְשֵׁכוּת אֶצְלָהּ מִמַּעְלָה לְמַטָּה וּמְאִירָה הַלְּבָנָה כְּמוֹ שֶׁנָּאֶה. מִפְּנֵי שֶׁהַשָּׂעִיר מְפַנֶּה הַזֻּהֲמָא תָּמִיד מֵהַמִּקְדָּשׁ, וְגוֹרֵם לְהַמְשִׁיךְ הָאוֹר מִלְמַעְלָה לְמַטָּה, וְקָרְבָּן זֶה עוֹלֶה לְמַעְלָה, וּמִפְּנֵי כֵן כָּתוּב בּוֹ (במדבר כט) חַטָּאת לַה', מִשּׁוּם הַזֻּהֲמָא הַהִיא שֶׁמְּכַסָּה אֶת הַלְּבָנָה, וְהוּא סוֹד שֶׁכָּתוּב (בראשית ד) לַפֶּתַח חַטָּאת רֹבֵץ.</p>\n<p>וְאִם תֹּאמַר, מַדּוּעַ כָּתוּב חַטָּאת לַה' - אֶלָּא וַדַּאי הַשָּׂעִיר הַהוּא מַעֲבִיר הַחַטָּאת הַהִיא וְגוֹרֵם לְהַמְשִׁיךְ הָאוֹר מִמַּעְלָה. וְזֶהוּ וּשְׂעִיר עִזִּים אֶחָד לְחַטָּאת לַה'. לְחַטָּאת - לְהַעֲבִיר לוֹ מִן הַמִּקְדָּשׁ. לַה' - לְהַמְשִׁיךְ הָאוֹר מִלְּמַעְלָה. שֶׁכַּאֲשֶׁר הַחַטָּאת מָעֳבֶרֶת, אוֹתוֹ אוֹר וְשִׂמְחָה יוֹרֵד מִמַּעְלָה לְמַטָּה. וְעַל זֶה עוֹלֶה קָרְבָּן זֶה לְמַעְלָה וְקָרְבָּן זֶה נִקְרָא כַפָּרָה, לְפַנּוֹת הַמִּקְדָּשׁ וּלְהַעֲבִיר הַזֻּהֲמָא:</p>"],[9522012729,"<p>שָׁנִינוּ, אָמַר רַבִּי יוֹסִי, חָקוּק הָיָה הַמַּטֶּה מִשְּׁנֵי צְדָדִים מֵהַשֵּׁם הַקָּדוֹשׁ, צַד אֶחָד שֶׁל רַחֲמִים וְדִין בְּאוֹתִיּוֹת חֲקוּקוֹת, וְצַד אֶחָד דִּין בְּדִין - נָחָשׁ עֲלֵי צוּר.</p>\n<p>בֹּא רְאֵה, כָּתוּב (שמותיד) וְאַתָּה הָרֵם אֶת מַטְּךְ וּנְטֵה אֶת יָדְךְ עַל הַיָּם. מַהוּ וּנְטֵה? כְּלוֹמַר, הַטֵּה בְּצַד אֶחָד שֶׁחָקוּק בְּרַחֲמִים וְדִין, וְכָתוּב וַיֵּט מֹשֶׁה אֶת יָדוֹ, וְלֹא כָתוּב וַיִּשְׁלַח מֹשֶׁה אֶת יָדוֹ. כְּלוֹמַר, הִטָּה מִצַּד אֶחָד.</p>\n<p>וְאִם תֹּאמַר שֶׁחָקוּק הָיָה מִזְּמַן קַדְמוֹן נָחָשׁ עֲלֵי צוּר, אֶלָּא בַּסְּנֶה נֶחְקַק, שֶׁכָּתוּב (שמות ד) וַיַּשְׁלִכֵהוּ אַרְצָה וַיְהִי לְנָחָשׁ. בַּשָּׁעָה הַהִיא נֶחְקַק נָחָשׁ עֲלֵי צוּר.</p>\n<p>וּבֹא רְאֵה, אָמַר רַבִּי יְהוּדָה, רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁשְּׁמוֹתָיו שֶׁהָיוּ חֲקוּקִים בַּמַּטֶּה יַעֲשׂוּ הָאוֹתוֹת, וְלָמַדְנוּ, שְׁנֵי אוֹתוֹת נַעֲשׂוּ בַיָּם. בַּצַּד הַהוּא שֶׁהִטָּה מֹשֶׁה בְּרַחֲמִים וְדִין קָרַע הַיָּם לְיִשְׂרָאֵל בִּשְׁנֵים עָשָׂר שְׁבִילִים, וְהֵשִׁיב בַּדִּין עַל הַמִּצְרִים וְהִטְבִּיעַ אוֹתָם בַּתְּהוֹם. זֶהוּ שֶׁכָּתוּב (שם יד) וַיָּשֶׁב ה' עֲלֵיהֶם אֶת מֵי הַיָּם.</p>\n<p>מֵאוֹתָהּ שָׁעָה רָצָה לְהוֹצִיא מַיִם. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: הַטֵּה הַמַּטֶּה מִצַּד אַחֵר וּשְׁנֵי אוֹתוֹת תַּעֲשֶׂה בּוֹ, כְּמוֹ שֶׁנַּעֲשָׂה מֵהַצַּד הָאַחֵר, אוֹת אֶחָד כָּאן וְאוֹת אֶחָד בִּמְרִיבָה. אֲבָל עַתָּה - (שמות יז) וְהִכִּיתָ בַצּוּר. בְּאֵיזֶה צוּר? בְּזֶה הַצּוּר, וְיַעֲלֶה נָחָשׁ שֶׁל זְמַן אַחֵר. אָמַר רַבִּי אֶלְעָזָר, מַהוּ שֶׁכָּתוּב (במדבר כ) קַח אֶת הַמַּטֶּה וְהַקְהֵל אֶת הָעֵדָה אַתָּה וְאַהֲרֹן אָחִיךְ וְדִבַּרְתֶּם? מַהוּ וְדִבַּרְתֶּם?</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, צִוָּה אוֹתוֹ עַל הַנָּחָשׁ, שֶׁהֲרֵי נַעֲשָׂה בַצּוּר. עַתָּה צָרִיךְ שֶׁיַּעֲשֶׂה בַנָּחָשׁ לְהַשְׁלִים שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאֵלּוּ הָאוֹתוֹת,</p>\n<p>מַשְׁמָע שֶׁכָּתוּב וְדִבַּרְתֶּם, וְכָתוּב (שם כא) וַיְדַבֵּר הָעָם בֵּאלֹהִים וּבְמֹשֶׁה. מַה כָּתוּב אַחֲרָיו? וַיְשַׁלַּח ה' בָּעָם אֵת הַנְּחָשִׁים הַשְּׂרָפִים וְגוֹ'. מַה נָּחָשׁ כֹּחוֹ בְּפִיו, אַף כָּאן בְּפִיו.</p>\n<p>וּמֹשֶׁה לֹא עָשָׂה כָּךְ, אֶלָּא הִכָּה, הִכָּה וְלֹא הִשְׁלִים הַשֵּׁם, אֶלָּא חָזַר כְּבָרִאשׁוֹנָה בַּשֵּׁם שֶׁל צוּר וְעָזַב שֵׁם שֶׁל נָחָשׁ. זֶהוּ שֶׁכָּתוּב וַיַּךְ, וְלֹא כָתוּב וַיְדַבֵּר, כְּמוֹ שֶׁנִּצְטַוָּה - וְדִבַּרְתֶּם. שֶׁשָּׁנִינוּ, צוּר לַעֲשׂוֹת, וְנָחָשׁ לְדַבֵּר. (שםכ) וַיַּךְ אֶת הַסֶּלַע בְּמַטֵּהוּ פַּעֲמָיִם. אֶחָד שֶׁעָבַר וְאֶחָד עַתָּה.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי אֶלְעָזָר, בְּאוֹתָהּ שָׁעָה נִשְׁאַר הַשֵּׁם, כְּלוֹמַר שֶׁלֹּא נִשְׁלַם בָּאוֹת הַהוּא, שֶׁעָזַב מֹשֶׁה הַנָּחָשׁ וְלֹא נִשְׁלַם כָּל הַשֵּׁם, שֶׁהֲרֵי בְּצַד אֶחָד נִשְׁלָם. בַּיָּם מִצַּד אַחֵר. הִתְחִיל בַּצּוּר וְלֹא נִשְׁלַם בַּנָּחָשׁ. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: עָשִׂיתָ שֶׁהִתְחִיל שְׁמִי וְלֹא נִשְׁלַם לַעֲשׂוֹת אוֹתוֹת, אַף אַתָּה תַתְחִיל וְלֹא תַשְׁלִים. (במדברכ) לָכֵן לֹא תָבִיאוּ, הִתְחַלְתָּ לְהוֹצִיא אוֹתָם - וְלֹא תַשְׁלִים לְהַכְנִיס אוֹתָם לָאָרֶץ. לָכֵן לֹא תָבִיאוּ. אָמַר רַבִּי אֶלְעָזָר, יָדַע לֵב שֶׁל מֹשֶׁה בָּרִאשׁוֹנָה, שֶׁהִתְיָרֵא כַּאֲשֶׁר רָאָה הַנָּחָשׁ, שֶׁכָּתוּב (שמות ד) וַיָּנָס מֹשֶׁה מִפָּנָיו. הַלֵּב רָאָה וְלֹא יָדַע.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, כָּתוּב (במדבר כא) וַיַּעַשׂ מֹשֶׁה נְחַשׁ נְחֹשֶׁת וַיְשִׂמֵהוּ עַל הַנֵּס. עַל נֵס לֹא כָתוּב, אֶלָּא עַל הַנֵּס. רָצָה לְתַקֵּן מַה שֶּׁחָסֵר. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, כָּתוּב (במדבר כז) לְהַקְדִּישֵׁנִי בַמַּיִם, בַּמַּיִם וְלֹא בְדָבָר אַחֵר. כְּשֵׁם שֶׁהִתְחַלְתָּ בְּמַיִם, רְצוֹנִי שֶׁיִּשְׁתַּלֵּם בִּשְׁמִי הַנֵּס בַּמַּיִם. אָמַר רַבִּי אֶלְעָזָר, מָקוֹם שֶׁחָסֵר לֹא שָׁלֵם, אֲבָל אַתָּה תַמְשִׁיךְ נֵס אֶחָד (כאן).</p>\n<p>אָמַר רַבִּי יְהוֹשֻׁעַ, כָּתוּב (במדבר כא) עֲשֵׂה לְךְ שָׂרָף. עֲשֵׂה לְךְ - לְתוֹעַלְתְּךְ. עֲשֵׂה לְךְ - תַּקֵּן מַה שֶּׁחִסַּרְתָּ. וְעִם כָּל זֶה לֹא תִקֵּן אֶלָּא הָרְאִיָּה, שֶׁהָיוּ רוֹאִים בַּנָּחָשׁ וְחַיִּים. אֲבָל לֹא נִקְדַּשׁ הַשֵּׁם בַּמַּיִם, וְנִשְׁאַר חָסֵר מֵהַשְּׁאָר.</p>\n<p>וְתִקַּנְתָּ בִּרְאִיָּה - (דברים לב) עֲלֵה אֶל הַר הָעֲבָרִים, וּרְאֵה, הִנְּךְ רוֹאֶה בְעֵינֶיךְ, (שם לא) וְשָׁמָּה לֹא תַעֲבֹר, (במדבר כז) וְרָאִיתָ אֹתָהּ וְנֶאֱסַפְתָּ אֶל עַמֶּיךְ. בּא וּרְאֵה שֶׁאֲפִלּוּ רְאִיָּה, כֵּיוָן שֶׁעָשָׂה רְאִיָּה, בָּזֶה הִשְׁלִים לְעַצְמוֹ הָרְאִיָּה, אֲבָל לֹא הִשְׁלִים אֶת הַשֵּׁם בַּמַּיִם כְּמוֹ שְׁאָר כָּל הַשֵּׁמוֹת.</p>\n<p>אָמַר רַבִּי יִצְחָק, בְּשָׁעָה שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא (במדבר כ) לָכֵן לֹא תָבִיאוּ, אָמַר מֹשֶׁה, הַנָּחָשׁ הַזֶּה הוּא לְתַקָּלָה בָּעוֹלָם הָיָה. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא כָּךְ - דִּין לַחַיָּבִים, וְחַיִּים לְבַעֲלֵי הָאֱמֶת. בְּאוֹתָהּ שָׁעָה שֶׁכָּתוּב (במדבר כ) וְרָאָה אֹתוֹ וָחָי, יָדַע מֹשֶׁה דְרָכָיו וְהִצְדִּיק עָלָיו אֶת הַדִּין.</p>\n<p>פָּתַח וְאָמַר, (דברים לב) הַצּוּר תָּמִים פָּעֳלוֹ. זֶהוּ הַצּוּר שֶׁאֲנַחְנוּ אוֹמְרִים (שם) אֵל אֱמוּנָה וְאֵין עָוֶל, שֶׁכָּתוּב וְרָאָה אֹתוֹ וָחָי, וְכָתוּב (שמואל ב כב) הָאֵל תָּמִים דַּרְכּוֹ.</p>\n<p>אָמַר רַבִּי חִיָּיא, וַהֲרֵי שָׁנִינוּ, אֵל - גְּזֵרַת רַחֲמִים הִיא, כְּמוֹ שֶׁנֶּאֱמַר (במדבר כג) אֵל מוֹצִיאָם מִמִּצְרָיִם, (שמות לד) אֵל רַחוּם וְחַנּוּן. אָמַר לוֹ, לֹא כָּךְ, שֶׁלָּמַדְנוּ, שׁוֹלֵט רַחֲמִים עַל הַדִּין. אֵל לְבַדּוֹ יְכֹלֶת הָיְתָה לוֹ וְהָרְשׁוּת הָיְתָה שֶׁלּוֹ. מָה הַיְכֹלֶת? שְׁלִיטָה שֶׁל אֵל, הִתְחַזְּקָה גְזֵרָה שֶׁלּוֹ, כְּמוֹ שֶׁנֶּאֱמַר (בראשית לא) יֵשׁ לְאֵל יָדִי, וּרְשׁוּת שֶׁלּוֹ יְכֹלֶת שֶׁל עַיִן רָעָה, כְּמוֹ שֶׁנֶּאֱמַר יֵשׁ לְאֵל יָדִי. אָמַר לוֹ, וַהֲרֵי כָּתוּב (דברים י) הָאֵל הַגָּדל הַגִּבֹּר. אֵל גָּדוֹל נוֹצֵחַ, אֵל לְבַדּוֹ נוֹצֵחַ. וְכָתוּב (שם לב) הַצּוּר תָּמִים פָּעֳלוֹ כִּי כָל דְּרָכָיו מִשְׁפָּט. זֶה צוּר (שם) אֵל אֱמוּנָה וְאֵין עָוֶל. זֶה נָחָשׁ עֲלֵי צוּר.</p>\n<p>נַחֲזֹר לַדְּבָרִים הָרִאשׁוֹנִים. וְכָתוּב (איוב ח) הַאֵל יְעַוֵּת מִשְׁפָּט, חַס וְשָׁלוֹם?! אָמַר רַבִּי אֶלְעָזָר, זֶהוּ שֶׁכָּתוּב (תהלים פה) אֶשְׁמְעָה מַה יְדַבֵּר הָאֵל וְגוֹ'.</p>\n<p>(שמות ד) וַיִּשְׁלַח יָדוֹ וַיַּחֲזֶק בּוֹ וַיְהִי לְמַטֶּה בְּכַפּוֹ, כְּמוֹ שֶׁנֶּאֱמַר (דברים כז) מַטֶּה מִשְׁפַּט. מַטֶּה כְלַפֵּי חֶסֶד. אָמַר רַבִּי יוֹסֵי, שְׁנֵי מַטּוֹת הָיוּ, אֶחָד שֶׁל מֹשֶׁה וְאֶחָד שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. מֵהֵיכָן לוֹמְדִים? שֶׁכָּתוּב (שמות ד) וּמַטֵּה הָאֱלֹהִים.</p>\n<p>שֶׁשָּׁנִינוּ, בְּשָׁעָה שֶׁהָיָה נוֹטֵל מֹשֶׁה הַמַּטֶּה בִרְשׁוּתוֹ, הָיָה כְאִלּוּ שֶׁלּוֹ. זֶהוּ שֶׁכָּתוּב (שם) וַיִּקַּח מֹשֶׁה אֶת מַטֵּה הָאֱלֹהִים בְּיָדוֹ. כֵּיוָן שֶׁאָמַר וַיִּקַּח מֹשֶׁה, אֵינִי יוֹדֵעַ שֶׁלְּקָחוֹ בְיָדוֹ? אֶלָּא מַהוּ בְּיָדוֹ? בִּרְשׁוּתוֹ, בִּיְכָלְתּוֹ.</p>\n<p>וְאָמַר רַבִּי יוֹסֵי, בִּרְשׁוּתוֹ שֶׁל מֹשֶׁה הָיָה עַד שֶׁהוּקַם הַמִּשְׁכָּן. כֵּיוָן שֶׁהוּקַם הַמִּשְׁכָּן, חָזַר הַמַּטֶּה לִפְנֵי הָעֵדוּת, וּמֹשֶׁה הָיָה נוֹטְלוֹ לַעֲשׂוֹת בּוֹ נִסִּים. זֶהוּ שֶׁכָּתוּב (במדברכ) וַיִּקַּח מֹשֶׁה אֶת הַמַּטֶּה מִלִּפְנֵי ה'. כֵּיוָן שֶׁלְּקָחוֹ הֲרֵי הוּא בִרְשׁוּתוֹ וּכְשֶׁלּוֹ הָיָה.</p>\n<p>אָמַר רַבִּי יְהוֹשֻׁעַ, אוֹתוֹ הַמַּטֶּה שֶׁל סְנַפִּירִינוֹן הָיָה, וּמִשֵּׁשֶׁת יְמֵי בְרֵאשִׁית נִבְרָא, כְּמוֹ שֶׁשָּׁנִינוּ, וְהַמִּכְתָּב, וְהַמַּטֶּה. רַבִּי יְהוּדָה אָמַר, שֶׁל עֵץ הָיָה.</p>\n<p>מִי שֶׁאָמַר שֶׁל סְנַפִּירִינוֹן הָיָה - שֶׁכָּתוּב (יחזקאל א) כְּמַרְאֵה אֶבֶן סַפִּיר דְּמוּת כִּסֵּא, וְכָתוּב (שמות ד) מַטֵּה הָאֱלֹהִים. וּמִי שֶׁאָמַר שֶׁל עֵץ הָיָה - שֶׁכָּתוּב (שם טו) וַיּוֹרֵהוּ ה' עֵץ וְגוֹ'</p>\n<p>שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט וְשָׁם נִסָּהוּ. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, מִכָּאן הֲרֵי חֹק וּמִשְׁפָּט לַעֲשׂוֹת נִסִּים, חֹק וּמִשְׁפָּט. נָחָשׁ עֲלֵי צוּר - שֶׁכָּתוּב (משלי ל) נָחָשׁ עֲלֵי צוּר. וְשָׁם נִסָּהוּ, מִשּׁוּם שֶׁכָּתוּב (שמות טו) וַיִּמְתְּקוּ הַמָּיִם. דָּבָר אַחֵר, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, מִכָּאן וּלְהָלְאָה חֹק וּמִשְׁפָּט, שֶׁלֹּא יְהֵא נִקְדָּשׁ אֶלָּא בְמַיִם שֶׁנִּמְתְּקוּ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, כָּתוּבּ כִּי מָרִים הֵם. מִכָּאן שָׁנִינוּ, יֵשׁ מַיִם עֲכוּרִים וְיֵשׁ מַיִם צְלוּלִים, יֵשׁ מַיִם מָרִים וְיֵשׁ מַיִם מְתוּקִים. וַיִּצְעַק אֶל ה' - לָמָּה צָעַק? מִכָּאן שֶׁהָיָה בְצַעַר בְּאוֹתָהּ שָׁעָה. אָמַר לוֹ: מֹשֶׁה, הַנָּחָשׁ שֶׁנֶּהְפַּךְ בַּסְּנֶה, עַכְשָׁו אֶצְטָרֵךְ לַחְקֹק אוֹתוֹ בַצּוּר. וּשְׁנֵיהֶם עָמְדוּ עַל הַמַּיִם הַמָּרִים. וְאוֹתָהּ שָׁעָה נֶחְקַק צוּר בַּנָּחָשׁ שֶׁהָיָה בּוֹ קֹדֶם. זֶהוּ שֶׁכָּתוּב (שם) שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט.</p>\n<p>כַּאֲשֶׁר בָּא רַבִּי אַבָּא, בָּאוּ שָׁאֲלוּ לְפָנָיו. אָמַר לָהֶם, יָפֶה אָמַר רַבִּי יְהוּדָה וְכָךְ הוּא, וַאֲנִי צָרִיךְ לְגַלּוֹת סוֹד הָעִנְיָן, וַהֲרֵי רָאִינוּ שֶׁרַבִּי יְהוּדָה גִלָּה אוֹתוֹ.</p>\n<p>אֶלָּא אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה: מֹשֶׁה, עַתָּה בְמִצְרַיִם הָיָה הַמַּטֶּה שֶׁל אַהֲרֹן לִדְחוֹת הַקַּשׁ הַשּׁוֹלֵט עַל יִשְׂרָאֵל בְּמִצְרַיִם. אֲבָל כְּשֶׁיָּצְאוּ מִמִּצְרַיִם, כַּמָּה מְקַטְרְגִים מְזֻמָּנִים עַל יִשְׂרָאֵל לִדְחוֹתָם בַּיָּם, כַּמָּה מַיִם מָרִים נִזְדַּמְּנוּ וְקִטְרְגוּ.</p>\n<p>בָּאוּ לַיָּם - בָּא רָהָב, שָׂרוֹ שֶׁל מִצְרַיִם וְשֶׁל יָם, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה: הָרֵם וּנְטֵה יָדְךְ. כֵּיוָן שֶׁאָמַר הָרֵם אֶת מַטְּךְ, מַהוּ וּנְטֵה אֶת יָדְךְ? אֶלָּא הָרֵם אֶת מַטְּךְ נֶגֶד רָהָב שָׂרוֹ שֶׁל מִצְרַיִם. בָּאוּ לְמָרָה - כַּמָּה מַיִם מָרִים נִזְדַּמְּנוּ אֶצְלָם וְנִצְטַעֵר מֹשֶׁה וְצָעַק, זֶהוּ שֶׁכָּתוּב (שמות טו) וַיִּצְעַק אֶל ה'.</p>\n<p>אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: מֹשֶׁה, הֲרֵי לְךְ עֵצָה בָזֶה - הַשְׁלֵךְ הַמַּטֶּה אֶצְלָם וְיִתְחַקֵּק נָחָשׁ עֲלֵי צוּר, שְׁנֵיהֶם בְּיַחַד, וְיִצּוֹלוּ. זֶהוּ שֶׁכָּתוּב (שם) וַיּוֹרֵהוּ ה' עֵץ וַיַּשְׁלֵךְ אֶל הַמַּיִם. עֵץ, כְּמוֹ שֶׁנֶּאֱמַר (קהלת יא) מָקוֹם שֶׁיִּפֹּל הָעֵץ, שֶׁהוּא עֵצָה, וַיַּשְׁלֵךְ אֶל הַמַּיִם. וְכָתוּב (שמות טו) שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט, נָחָשׁ עֲלֵי צוּר. וְשָׁם נִסָּהוּ, עִטְּרָהוּ בְנִסִּים. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: מִכָּאן וּלְהָלְאָה הֲרֵי לְךְ שֶׁיַּעֲמֹד אֵצֶל הַמַּיִם, הֲרֵי לְךְ לְהִתְקַדֵּשׁ שְׁמִי בַמַּיִם.</p>\n<p>כְּשֶׁבָּאוּ לְאֵילִם - בָּאוּ הַמַּיִם לְקַטְרֵג בָּהֶם. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: בַּמָּקוֹם הַזֶּה אֵין צָרִיךְ מַטֶּה. הֲרֵי יַעֲקֹב שֶׁהוּא אִילָן בְּשִׁבְעִים נֶפֶשׁ, וְהוּא שִׁבְעִים תְּמָרִים, וּשְׁתֵּים עֶשְׂרֵה עֵינֹת מַיִם, שְׁנֵים עָשָׂר שְׁבָטִים בְּשִׁבְעִים עַמּוּדִים וּשְׁנֵים עָשָׂר שְׁבָטִים, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה א) כִּי יֵבֹשׁוּ מֵאֵילִים אֲשֶׁר חֲמַדְתֶּם.</p>\n<p>מִיָּד - וַיַּחֲנוּ שָׁם עַל הַמַּיִם בַּמָּקוֹם הַזֶּה שֶׁנִּקְרָא אִילָן, וְהוּא אֵילִם. מִמַּשְׁמָע שֶׁכָּתוּב עַל הַמַּיִם, וּמִמַּשְׁמָע שֶׁכָּתוּב שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט, וְלֹא בְמָקוֹם אַחֵר, וְשָׁם שָׁלְטוּ בְנֵי יִשְׂרָאֵל עַל הַמַּיִם וְלֹא הֻצְרַךְ הַמַּטֶּה. מִכָּאן וּלְהָלְאָה הֻצְרַךְ הַמַּטֶּה בְּנָחָשׁ עֲלֵי צוּר אֵצֶל הַמַּיִם.</p>\n<p>בָּאוּ לְחוֹרֵב - בָּאוּ הַמַּיִם לְקַטְרֵג. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, (שמות יז) וְהִכִּיתָ בַצּוּר. הַמַּטֶּה נִצְרָךְ כָּאן, וְהִכִּיתָ לְאֵלּוּ בְּאוֹתוֹ צוּר, וְלֹא בְנָחָשׁ. אָמַר מֹשֶׁה, יוֹתֵר צָרִיךְ כָּאן, אֲנִי רוֹאֶה מַיִם שֶׁרוֹצִים לִשְׁטֹף. מַדּוּעַ? (שם) הִנְנִי עֹמֵד לְפָנֶיךְ שָּׁם עַל הַצּוּר בְּחֹרֵב וְהִכִּיתָ בַצּוּר.</p>\n<p>אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה: עֲדַיִן בִּמְרִיבָה עֲתִידִין הַמַּיִם לְקַטְרֵג יוֹתֵר, שֶׁהֵם מַיִם עֲכוּרִים, רָעִים וּזְדוֹנִים, וְיִזְדַּוְּגוּ בָהֶם יִשְׂרָאֵל בְּגָלוּי לְעֵינֵיהֶם. וְאוֹתָהּ שָׁעָה נִצְרַךְ הַמַּטֶּה וְהִתִּיר עֲלֵיהֶם הַנָּחָשׁ בְּגָלוּי לְעֵינֵיהֶם, וְיִתְקַדֵּשׁ שְׁמִי. זֶהוּ שֶׁכָּתוּב (במדבר כז) לְהַקְדִּישֵׁנִי בַמַּיִם לְעֵינֵיהֶם. מַהוּ לְעֵינֵיהֶם? דָּבָר שֶׁנִּזְדַּוְּגוּ בָהֶם בְּגָלוּי.</p>\n<p>בֹּא רְאֵה, כָּךְ רָאָה דָוִד, שֶׁכָּתוּב (תהליםקכד) לוּלֵי ה' שֶׁהָיָה לָנוּ בְּקוּם עָלֵינוּ אָדָם. זֶה פַּרְעֹה. (שם) אֲזַי עָבַר עַל נַפְשֵׁנוּ הַמַּיִם הַזֵּידוֹנִים, כְּמוֹ שֶׁאָמַרְנוּ. וְכָתוּב (שם) נַפְשֵׁנוּ כְּצִפּוֹר נִמְלְטָה מִפַּח יוֹקְשִׁים.</p>\n<p>אָמַר רַבִּי אַבָּא, מָה רָאָה מֹשֶׁה בְּאוֹתָהּ שָׁעָה שֶׁלֹּא עָשָׂה בַנָּחָשׁ? אֶלָּא יִשְׂרָאֵל הָיוּ דוֹחֲקִים לְמֹשֶׁה, תְּנָה לָנוּ מַיִם. נִתְיָעֵץ וְאָמַר, הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר לִי עֲמֹד בַּנָּחָשׁ, וַאֲנִי רוֹאֶה שֶׁאֵין גְּזֵרָה לַנָּחָשׁ בַּמַּיִם, אֶלָּא בֶעָפָר. אָמַר רַבִּי יְהוּדָה, מִכָּאן (בראשית ג) וְעָפָר תֹּאכַל כָּל יְמֵי חַיֶּיךְ, מַשְׁמָע שֶׁעָפָר יֹאכַל כָּל יָמָיו, אֲבָל לֹא בְמַיִם. וְיִשְׂרָאֵל דּוֹחֲקִים לִי, וְאַף עַל גַּב שֶׁיֵּעָשֶׂה נֵס, לֹא יֵעָשֶׂה בְמָקוֹם זֶה, אֶלָּא יֵחָקֵק בְּעָפָר וְלֹא בְמַיִם, שֶׁכָּתוּב (שמות ד) וַיַּשְׁלִכֵהוּ אַרְצָה וַיְהִי לְנָחָשׁ. וְצוּר בָּזֶה נֶחְקַק בַּמַּיִם בְּמָרָה, וּכְבָר עָשָׂה נֵס בָּזֶה שֶׁנַּעֲשָׂה בִזְמַן אַחֵר, שֶׁכָּתוּב (במדבר כ) וַיַּךְ אֶת הַסֶּלַע בְּמַטֵּהוּ פַּעֲמָיִם. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: מֹשֶׁה, (במדבר כ) יַעַן לֹא הֶאֱמַנְתֶּם בִּי לְהַקְדִּישֵׁנִי, שֶׁחֲשַׁבְתֶּם שֶׁלֹּא יָכוֹל הַנָּחָשׁ בְּמַיִם, (שם) לָכֵן לֹא תָבִיאוּ:</p>"],[9522012730,"<p>בַּסּוֹד שֶׁל שָׁמוֹר, דִּבּוּר, לַיְלָה. זוֹ הִיא תוֹרַת ה', תּוֹרָה שֶׁבְּעַל פֶּה. מֹשֶׁה קִבֵּל תּוֹרָה מִסִּינַי וּמְסָרָהּ לִיהוֹשֻׁעַ וְגוֹ', וַהֲרֵי הִתְעוֹרְרוּ עַל תּוֹרָה שֶׁבְּעַל פֶּה, שֶׁאִלּוּ תוֹרָה שֶׁבִּכְתָב הֲרֵי כָּתוּב, (דברים לא) וַיְצַו מֹשֶׁה אֶת הַלְוִיִּם נֹשְׂאֵי אֲרוֹן בְּרִית ה' לֵאמֹר. לָקֹחַ אֵת סֵפֶר הַתּוֹרָה הַזֶּה. וְזֶה הַלְוִיִּם רְאוּיִים לְכָךְ, לְזֶה שֶׁאָחוּז בַּשֶּׁמֶשׁ. וְהַמֶּלֶךְ שֶׁבָּא מִמֶּנּוּ - מֹשֶׁה, הֵאִיר לָהֶם לְיִשְׂרָאֵל אַרְבָּעִים שָׁנִים שֶׁמֶשׁ בַּיּוֹם, וְתוֹרַת ה' - זֵה עֶרֶב שַׁבָּת בְּסוֹד אֶחָד וְכוּ':</p>"],[9522012731,"<p>גּוֹרְסִים בַּזֹּהַר, מִי שֶׁאָחוּז בַּתּוֹרָה, סוֹמֶכֶת אוֹתוֹ וּמַחֲזִיקָה אוֹתוֹ עַל יְרֵכוֹ שֶׁלֹּא יִטֶּה לְיָמִין וְלִשְׂמֹאל. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לָהֶם תּוֹרָה לְגַלּוֹת לָהֶם סוֹדוֹת עֶלְיוֹנִים, עֲלֵיהֶם כָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם וְגוֹ'.</p>\n<p>וּבֹא רְאֵה, כַּאֲשֶׁר נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא תּוֹרָה לְיִשְׂרָאֵל, רָשַׁם אוֹתָהּ בְּסוֹד הַשֵּׁם הַקָּדוֹשׁ. אָמַר (שמות כ) אָנֹכִי ה' אֱלֹהֶיךְ - בְּסוֹד הַחֶסֶד שֶׁאַבְרָהָם אָחוּז בָּהּ, וּכְנֶגְדּוֹ מִצְווֹת עֲשֵׂה, וְסוֹד זֶה הַצִּוּוּי רִאשׁוֹן שֶׁצִּוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת אַבְרָהָם, וּמִצְוַת עֲשֵׂה הָיְתָה, שֶׁכָּתוּב (בראשית יב) לֶךְ לְךְ מֵאַרְצְךְ. וּמִשּׁוּם כָּךְ חֶשְׁבּוֹן מִצְווֹת עֲשֵׂה רמ\"ח, כְּחֶשְׁבּוֹן אַבְרָהָ\"ם.</p>\n<p>לֹא יִהְיֶה לְךְ אֱלֹהִים אֲחֵרִים וְגוֹ' (שמות כ) - בְּסוֹד הַגְּבוּרָה שֶׁאָחוּז בָּהּ יִצְחָק, שֶׁכָּל אֵלּוּ אֱלֹהִים אֲחֵרִים וְאֵלּוּ הַשָּׂרִים הַמְמֻנִּים - מִצִּדּוֹ יְנִיקָתָם, וְכֵן עֵשָׂו וְכָל אֵלּוּ הַמְמֻנִּים שֶׁלּוֹ. שֶׁהֲרֵי יִצְחָק אָחוּז בְּמִצְוַת לֹא תַעֲשֶׂה, וְהַצִּוּוּי הָרִאשׁוֹן שֶׁלּוֹ מִצְוַת לֹא תַעֲשֶׂה הָיְתָה, שֶׁכָּתוּב (בראשית כו) אַל תֵּרֵד מִצְרָיְמָה. וּמִצְוַת לֹא תַעֲשֶׂה מִצַּד שֶׁל הַדִּין בָּאָה, שֶׁהֲרֵי מַעֲנִישִׁים לוֹ לְבֶן אָדָם כַּאֲשֶׁר עוֹבֵר עָלֶיהָ.</p>\n<p>וּמִשּׁוּם כָּךְ חֶשְׁבּוֹן מִצְווֹת לֹא תַעֲשֶׂה בְּסוֹד שֶׁדַּרְגָּה שֶׁלּוֹ בְּסוֹד שֶׁל שס\"ה, כְּנֶגֶד יְמוֹת הַחַמָּה שֶׁמֵּאִיר מִצַּד הַגְּבוּרָה. זֶהוּ שֶׁכָּתוּב (שופטים ה) כְּצֵאת הַשֶּׁמֶשׁ בִּגְבֻרָתוֹ.</p>\n<p>לֹא תִשָּׂא - בְּסוֹד הַגְּבוּרָה, שֶׁתִּפְאֶרֶת שֶׁנִּקְרָא אֱמֶת, וְנִקְרָא בָהּ יַעֲקֹב שָׁלֵם וְיוֹנֵק שְׁנֵי חֲלָקִים - מִצְווֹת עֲשֵׂה וּמִצְווֹת לֹא תַעֲשֶׂה. זֶהוּ שֶׁכָּתוּב (בראשיתכה) וְיַעֲקֹב אִישׁ תָּם יֹשֵׁב אֹהָלִים. וְעוֹלֶה לְכָל הַצְּדָדִים - לְרַחֲמִים וּלְדִין, לְמִצְווֹת לֹא תַעֲשֶׂה וּלְמִצְווֹת עֲשֵׂה. וְנִקְרָא שָׁלֵם מִשּׁוּם שֶׁשְּׁבוּעָה מִשָּׁלֵם בָּאָה. וְעַל זֶה בְּסוֹד שֶׁל עֲשֵׂה וְלֹא תַעֲשֶׂה. וּכְמוֹ שֶׁהִיא לֹא תַעֲשֶׂה כַּאֲשֶׁר הִיא לְשֶׁקֶר, כָּךְ הִיא מִצְוַת עֲשֵׂה כַּאֲשֶׁר הִיא בֶּאֱמֶת, שֶׁכָּתוּב (ירמיה ד) וְנִשְׁבַּעְתָּ חַי ה' בֶּאֱמֶת בְּמִשְׁפָּט וּבִצְדָקָה, וְכָתוּב (דברים י) וּבִשְׁמוֹ תִּשָּׁבֵעַ.</p>\n<p>זָכוֹר אֵת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ (שמות כ) - בְּסוֹד הַבְּרִית, שֶׁהוּא יְסוֹד שֶׁאָחוּז בּוֹ יוֹסֵף. וְעַל זֶה נִקְרָא שַׁבָּת, שֶׁהֲרֵי יוֹסֵף נִקְרָא כֹּל, שַׁבָּת גַּם כֵּן כֹּ\"ל, שֶׁכָּל עֹנֶג וְתַפְנוּקִים יוֹצֵא מִמֶּנָּה לְקַיֵּם הָעוֹלָמוֹת כֻּלָּם (כלם). וְעַל זֶה שַׁבָּת - כְּלָלוּת (כלל) שֶׁל עֲשֵׂה וְלֹא תַעֲשֶׂה, מִשּׁוּם שֶׁיּוֹסֵף גַּם כֵּן בְּכוֹר שֶׁנּוֹטֵל שְׁנֵי חֲלָקִים.</p>\n<p>בֹּא וּרְאֵה, בַּעֲשֶׂרֶת הַדִּבְּרוֹת שֶׁבְּמִשְׁנֵה תוֹרָה כָּתוּב, (דברים כד) וְזָכַרְתָּ כִּי עֶבֶד הָיִיתָ בְּמִצְרַיִם וַיִּפְדְּךְ ה' אֱלֹהֶיךְ מִשָּׁם. כָּאן מְלַמֶּדֶת אוֹתָנוּ הַתּוֹרָה סוֹד עֶלְיוֹן, שֶׁהֲרֵי הַצַּדִּיק הַהוּא שֶׁנִּמְכַּר חַי לְעֶבֶד בְּמִצְרַיִם וְחִלְּלוּ (ויראו) אוֹתוֹ, לְעֻמָּתוֹ הוּא זָכוֹר אֵת יוֹם הַשַּׁבָּת. וּמִשּׁוּם כָּךְ אָמַר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל: בְּבַקָּשָׁה מִכֶּם הֱיוּ זוֹכְרִים הַצַּדִּיק הַהוּא שֶׁנִּמְכַּר עַל יְדֵיכֶם וְהָיָה לְעֶבֶד בְּמִצְרַיִם, וּבְאוֹתוֹ הַחֵטְא נִגְזַר עֲלֵיכֶם לְהִשְׁתַּעְבֵּד בָּכֶם בְּמִצְרַיִם וּלְכַפֵּר הַחֵטְא הַהוּא שֶׁמְּכַרְתֶּם אוֹתוֹ. שִׁמְרוּ אֶת יוֹם הַשַּׁבָּת וְיִתְכַּפֵּר לָכֶם, שֶׁהֲרֵי יוֹם הַשַּׁבָּת כְּנֶגְדּוֹ הוּא, כְּמוֹ שֶׁבֵּאַרְנוּ בְּסוֹד הָאֱמוּנָה.</p>\n<p>יוֹם רִאשׁוֹן כְּנֶגֶד אַבְרָהָם, הוּא שֶׁכָּתוּב (תהלים נב) חֶסֶד אֵל כָּל הַיּוֹם. יוֹם שֵׁנִי כְּנֶגֶד יִצְחָק, וּמִשּׁוּם כָּךְ יוֹשֵׁב הַקָּדוֹשׁ בָּרוּךְ הוּא לָדוּן הָעוֹלָם. יוֹם שְׁלִישִׁי כְּנֶגֶד יַעֲקֹב, שֶׁהוּא קַו אֶמְצָעִי, וּמִשּׁוּם כָּךְ כָּתוּב בּוֹ בְּמַעֲשֵׂה בְרֵאשִׁית יִקָּווּ הַמַּיִם.</p>\n<p>יוֹם רְבִיעִי כְּנֶגֶד דָּוִד, שֶׁכָּתוּב בּוֹ (בראשית א) יְהִי מְאֹרֹת, מְאֹרֹת חָסֵר. שֶׁהֲרֵי כְּנֶסֶת יִשְׂרָאֵל אֵין לָהּ אוֹר מִשֶּׁלָּהּ, אֶלָּא מַה שֶּׁנִּתָּן לָהּ עַל יְדֵי הַצַּדִּיק, כָּךְ גַּם דָּוִד כָּתוּב בּוֹ עָנִי וְאֶבְיוֹן, וְאֵין חַיִּים אֶלָּא מַה שֶּׁנִּתַּן לוֹ מִיָּמָיו שֶׁל אָדָם הָרִאשׁוֹן שִׁבְעִים שָׁנָה. יוֹם חֲמִישִׁי כְּנֶגֶד מֹשֶׁה. יוֹם שִׁשִּׁי כְּנֶגֶד אַהֲרֹן, וְאֵלּוּ שֵׁשֶׁת יְמֵי בְרֵאשִׁית שֶׁל מַעְלָה הֵם שֶׁרְמוּזִים בַּפָּסוּק (דברי הימים א כט) לְךְ ה' הַגְּדֻלָּ\"ה וְהַגְּבוּרָ\"ה וְהַתִּפְאֶרֶ\"ת וְהַנֵּצַ\"ח וְהַהוֹ\"ד כִּי כֹ\"ל, וְהֵם חֶלְקֵיהֶם שֶׁל הַצַּדִּיקִים.</p>\n<p>בְּסוֹד זֶה הַגְּדֻלָּ\"ה בְּסוֹד שֶׁל אַבְרָהָם. הַגְּבוּרָ\"ה - בְּסוֹד שֶׁל יִצְחָק, וְהַתִּפְאֶרֶ\"ת - בְּסוֹד שֶׁל יַעֲקֹב. הַנֵּצַ\"ח - חֶלְקוֹ שֶׁל מֹשֶׁה. הַהוֹ\"ד - חֶלְקוֹ שֶׁל אַהֲרֹן. כִּי כֹ\"ל - (כנגד) כְּנֶגְדּוֹ חֶלְקוֹ שֶׁל יוֹסֵף. הַמַּמְלָכָ\"ה - חֶלְקוֹ שֶׁל דָּוִד. וְיוֹסֵף נִקְרָא שַׁבָּת לְמַטָּה, כְּנֶגֶד צַדִּיק חַי הָעוֹלָמִים שֶׁנִּקְרָא שַׁבָּת לְמַעְלָה, וּמִשּׁוּם כָּךְ כָּתוּב (דברים ה) עַל כֵּן צִוְּךְ ה' אֱלֹהֶיךְ.</p>\n<p>בֹּא וּרְאֵה, כַּאֲשֶׁר רָצוּ יִשְׂרָאֵל לִכְבֹּשׁ לְאֶרֶץ כְּנַעַן, הִקִּיפוּ אוֹתָהּ שִׁשָּׁה יָמִים, (פעם) אַחַת בְּכָל יוֹם, כְּנֶגֶד אוֹתָם צַדִּיקֵי אֱמֶת שֶׁעֲלֵיהֶם עוֹמֵד הָעוֹלָם, וּבַיּוֹם הַשְּׁבִיעִי שֶׁבַע פְּעָמִים כְּנֶגֶד יוֹם הַשַּׁבָּת, שֶׁהוּא כְּנֶגֶד הַצַּדִּיק שֶׁהוּא זָן לָהֶם וּמְקַיֵּם אוֹתָם, שֶׁכָּתוּב (משלי ט) חָצְבָה עַמּוּדֶיהָ שִׁבְעָה, וְכָתוּב (שם י) וְצַדִּיק יְסוֹד עוֹלָם, הוּא יְסוֹד וְעִקָּר שֶׁל כָּל אֵלּוּ הַצַּדִּיקִים. וְאִם לֹא זְכוּתָם שֶׁל הַצַּדִּיקִים, לֹא הָיוּ יְכוֹלִים לִכְבֹּשׁ אוֹתָהּ. זֶהוּ שֶׁכָּתוּב (דבריםט) לֹא בְצִדְקָתְךְ וּבְיֹשֶׁר לְבָבְךְ וְגוֹ' וּלְמַעַן הָקִים אֶת הַדָּבָר אֲשֶׁר נִשְׁבַּע ה' לַאֲבֹתֶיךְ.</p>\n<p>כַּבֵּד אֶת אָבִיךְ (שמות כ), בְּסוֹד שֶׁל הַנֵּצַח שֶׁאָחוּז בָּהּ מֹשֶׁה וּמַשְׁפִּיעַ לָהּ. שֶׁהֲרֵי מֹשֶׁה הָיָה מְכַבֵּד לְהַקָּדוֹשׁ בָּרוּךְ הוּא בַּתּוֹרָה. בֹּא וּרְאֵה, אִם לֹא הַתּוֹרָה שֶׁנִּתְּנָה עַל יָדָיו שֶׁל מֹשֶׁה הַנָּבִיא הַגָּדוֹל, לֹא הָיוּ יוֹדְעִים בְּנֵי אָדָם לְהַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא הָיוּ מְכַבְּדִים אוֹתוֹ, שֶׁהֲרֵי עַל יְדֵי הַתּוֹרָה לוֹמֵד בֶּן אָדָם עֲבוֹדַת קוֹנוֹ וּמְכַבֵּד אוֹתוֹ לְהַקָּדוֹשׁ בָּרוּךְ הוּא. וּמִפְּנֵי כֵּן כַּבֵּד אֶת אָבִיךְ הוּא כְּנֶגֶד מֹשֶׁה.</p>\n<p>דָּבָר אַחֵר כַּבֵּד אֶת אָבִיךְ - זוֹ תוֹרָה שֶׁבִּכְתָב. וְאֶת אִמֶּךְ - זוֹ תוֹרָה שֶׁבְּעַל פֶּה. שֶׁכְּמוֹ שֶׁאַבָּא נוֹתֵן שֶׁפַע לְאִמָּא, כָּךְ גַּם הַתּוֹרָה שֶׁבִּכְתָב נוֹתֶנֶת שֶׁפַע לַתּוֹרָה שֶׁבְּעַל פֶּה.</p>\n<p>לֹא תִרְצַח - כְּנֶגֶד דַּרְגָּה שֶׁל הַהוֹ\"ד שֶׁאָחוּז בָּהּ אַהֲרֹן, וּמִשּׁוּם כָּךְ לֹא תִרְצַח. מִשּׁוּם שֶׁכַּאֲשֶׁר הוֹרְגִים לוֹ לְבֶן אָדָם, אוֹתוֹ זִיו וְהוֹד עֶלְיוֹן שֶׁעָלָיו לוֹקְחִים מִמֶּנּוּ. זֶהוּ שֶׁכָּתוּב (דניאל י) וְהוֹדִי נֶהְפַּךְ עָלַי וְגוֹ', וּמִשּׁוּם כָּךְ מַזְהִיר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְנֵי אָדָם, שֶׁאוֹתוֹ יֹפִי עֶלְיוֹן שֶׁנָּתַן עֲלֵיהֶם, שֶׁלֹּא יִקְחוּ אוֹתוֹ מֵהֶם, וְהוּא גַּם כֵּן סוֹד הַשָּׁלוֹם. וּמִשּׁוּם כָּךְ עוֹמֵד אַהֲרֹן לְכַפֵּר וְלִשְׁחֹט שְׁחִיטַת קָדָשִׁים, וְעַל פִּיו כַּפֵּר לְעַמְּךְ יִשְׂרָאֵל.</p>\n<p>לֹא תִנְאָף - בְּסוֹד שֶׁל צַדִּיק שֶׁאָחוּז בָּהּ מִי שֶׁאוֹחֵז בָּהּ, וְהוּא סוֹד שֶׁל הַחָכְמָה, שֶׁהֲרֵי כְּנֶסֶת יִשְׂרָאֵל לֹא מִתְחַבֶּרֶת אֶלָּא בְּאוֹתוֹ שֶׁרָאוּי לוֹ בַּיְסוֹד שֶׁל הָעוֹלָם - וְצַדִּיק יְסוֹד עוֹלָם. דָּבָר אַחֵר, כָּךְ לָמַדְנוּ בְּסוֹד הָאֱמוּנָה, כַּבֵּ\"ד - כְּנֶגֶד כְּנֶסֶת יִשְׂרָאֵל. לֹא תִרְצַח - כְּנֶגֶד דַּרְגַּת הַנֵּצַ\"ח. לֹא תִנְאָף - כְּנֶגֶד דַּרְגַּת הַהוֹ\"ד.</p>\n<p>דָּבָר אַחֵר, כַּבֵּד - כְּנֶגֶד (בראשית א) יְהִי מְאֹרֹת שֶׁל מַעֲשֵׂה בְרֵאשִׁית. לֹא תִרְצַח - כְּנֶגֶד (שם) יִשְׁרְצוּ הַמַּיִם שֶׁרֶץ נֶפֶשׁ חַיָּה, מִשּׁוּם כָּךְ נֶפֶשׁ חַיָּה לֹא תִרְצַח. לֹא תִנְאָף - כְּנֶגֶד (שם) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ, מִשּׁוּם כָּךְ לֹא תִנְאַף בְּאִשָּׁה שֶׁלֹּא מִינְךְ, שֶׁהִיא לֹא בַת זוּגְךְ.</p>\n<p>דָּבָר אַחֵר - הוּא סִיּוּם שֶׁל עֲשָׂרָה דִבְּרוֹת הַתּוֹרָה, כְּנֶגֶד עַתִּיק הָעַתִּיקִים רֵאשִׁית הַכֹּל, לְחַבֵּר סוֹף בָּרֹאשׁ, לִהְיוֹת הַכֹּל אֶחָד. וְזֶה שֶׁלֹּא הִתְחִיל בָּהֶם בַּהַתְחָלָה לְלַמֵּד סוֹד עֶלְיוֹן עַד אֵיזֶה מָקוֹם נִתְּנָה לוֹ רְשׁוּת לְמֹשֶׁה, וּמֵאֵיזֶה מָקוֹם קִבֵּל תּוֹרָה מִזְּעֵיר אַנְפִּין,</p>\n<p>אָמַר שִׁבְעָה דִבְּרוֹת, כְּנֶגֶד שֶׁבַע מַדְרֵגוֹת עֶלְיוֹנוֹת שֶׁרְמוּזוֹת בְּפָסוּק לְךְ ה' הַגְּדֻלָּה וְגוֹ', וְעַד הַמָּקוֹם הַהוּא הִסְתַּכֵּל מֹשֶׁה, שֶׁכָּתוּב פָּנִים בְּפָנִים דִּבֵּר ה' עִם מֹשֶׁה. פָּנִים - זֶה בֵּן הַקָּדוֹשׁ. בְּפָנִים - זוֹ הַבַּת.</p>\n<p>פָּנִים - זוֹ הַבְּרִית, בְּפָנִים - זֶה הָאָרוֹן. וְכֵיוָן שֶׁהִתְחַבְּרוּ, דִּבֵּר ה'. וּמִי אֵלּוּ? שִׁבְעָה הַדִּבְּרוֹת. שֶׁאֵלּוּ (והן) שָׁלֹשׁ מַדְרֵגוֹת עֶלְיוֹנוֹת שֶׁל הָעַתִּיק הַקָּדוֹשׁ, נֶאֶמְרוּ כְּנֶגְדָּן שְׁלֹשָׁה דִבְּרוֹת אַחֲרוֹנִים וְעוֹלִים מִמַּטָּה לְמַעְלָה.</p>\n<p>לֹא תִגְנֹב - כְּנֶגֶד אִמָּא עֶלְיוֹנָה, בִּינָה, שֶׁיּוֹנֶקֶת מֵחָכְמָה. וּמִי שֶׁיֵּשׁ בּוֹ בִּינָה, נִקְרָא מֵבִין דָּבָר מִתּוֹךְ דָּבָר, כְּמִי שֶׁגּוֹנֵב וְלוֹקֵחַ מַה שֶּׁיֵּשׁ בְּלִבּוֹ שֶׁל הֶחָכָם שֶׁלִּמֵּד אוֹתוֹ חָכְמָה. וְהַתּוֹרָה, אַף עַל גַּב שֶׁהֻתְּרָה אֵצֶל הַבִּינָה לִינֹק מֵהַחָכְמָה, גְּנֵבָה יֵשׁ מֵהַצַּד הָאַחֵר שֶׁאָסוּר, וְאָמַר לֹא תִגְנֹב - סְתָם.</p>\n<p>לֹא תַעֲנֶה בְרֵעֲךְ - כְּנֶגֶד מַדְרֵגָה עֶלְיוֹנָה שֶׁל הַחָכְמָה, שֶׁהֲרֵי בֶּן אָדָם לֹא יָכוֹל לְהָשִׁיב דָּבָר אֶלָּא מִשּׁוּם מַדְרֵגָה שֶׁל רוּחַ עֶלְיוֹנָה שֶׁל הַחָכְמָה שֶׁיֵּשׁ בּוֹ. זֶהוּ שֶׁכָּתוּב (איוב טו) הֶחָכָם יַעֲנֶה דַעַת רוּחַ. וְאַף עַל גַּב שֶׁזּוֹ עֲנִיָּה, שֶׁהוּא עונֶה, יֵשׁ בָּזֶה הַעֲמָדַת הָעוֹלָם וְעֶזְרָה לָעוֹלָם לָדַעַת לְקוֹנוֹ, וְהוּא בְּסוֹד הָאֱמוּנָה. וְיֵשׁ עֲנִיָּה מִצַּד הָאַחֵר שֶׁאָסוּר, זֶהוּ שֶׁכָּתוּב לֹא תַעֲנֶה וְגוֹ'.</p>\n<p>לֹא תַחְמֹד - כְּנֶגֶד מַדְרֵגָה סְתוּמָה עֶלְיוֹנָה שֶׁכָּל הַמַּחֲשָׁבוֹת בָּהּ תְּלוּיוֹת, וְאֵין בָּעוֹלָם שֶׁיֵּדַע הַמַּדְרֵגָה הַהִיא, מִשּׁוּם שֶׁהוּא סְתוּם הַסְּתוּמִים. וְכַאֲשֶׁר עָלָה בְמַחֲשָׁבָה עֶלְיוֹנָה נִסְתֶּרֶת, בָּרָא עוֹלָם הָעֶלְיוֹן וְעוֹלָם הַתַּחְתּוֹן בְּרֶגַע אֶחָד, זֶהוּ שֶׁכָּתוּב (ישעיה מח) יַעַמְדוּ יַחְדָּו, וְהַהִיא מַחֲשָׁבָה סְתוּמָה.</p>\n<p>וּבֶן אָדָם יֵשׁ לוֹ מַחֲשָׁבָה סְתוּמָה, שֶׁאֵין שֶׁיּוֹדֵעַ בָּהּ אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא בְּעַצְמוֹ, וְנוֹתֵן בּוֹ בַּבֶּן אָדָם לַחְשּב דִּבְרֵי תוֹרָה, דִּבְרֵי מִצְוָה, כְּדֵי (שאותה) שֶׁאוֹתָהּ מַחֲשָׁבָה עֶלְיוֹנָה תַּמְשִׁיךְ נְבִיעוֹת שֶׁלָּהּ לִמְקוֹם הַחָכְמָה וְלֹא יִפָּרֵד כְּלָל. וּמִזּוֹ הַחָכְמָה הָעֶלְיוֹנָה יוֹצֵאת תּוֹרָה, וְנִמְשָׁךְ הַשֶּׁפַע שֶׁלָּהּ עַד הַמָּקוֹם הַהוּא שֶׁל הַחָכְמָה הַתַּחְתּוֹנָה שֶׁנִּקְרֵאת מִצְוָה.</p>\n<p>וְעַל זֶה מִי שֶׁחוֹשֵׁב לַעֲשׂוֹת מִצְוָה, כְּאִלּוּ עֲשָׂאָהּ, מִשּׁוּם שֶׁגּוֹרֵם לְהָבִיא שֶׁפַע שֶׁל בְּרָכוֹת מֵהַמַּחֲשָׁבָה הָעֶלְיוֹנָה הַהִיא עַד מָקוֹם שֶׁנִּקְרָא מִצְוָה. וּכְאִלּוּ עֲשָׂאָהּ, כְּמוֹ שֶׁנֶּאֱמַר (במדבר טו) וַעֲשִׂיתֶם אֹתָם. וּמַחֲשָׁבָה זוֹ רֹאשׁ שֶׁל הַכֹּל. וְאַף עַל גַּב שֶׁמִּצַּד הַמַּחֲשָׁבָה הָעֶלְיוֹנָה נִתָּן לוֹ רְשׁוּת לִדְבָרִים שֶׁל מִצְוָה, דְּבָרִים שֶׁאֵינָם שֶׁל מִצְוָה אֲסוּרִים. זֶהוּ שֶׁכָּתוּב לֹא תַחְמֹד.</p>\n<p>וּבֹא רְאֵה, מַה טַּעַם כָּל הַדִּבְּרוֹת כְּנֶגֶד כָּל כֶּתֶר וְכֶתֶר? מִצְווֹת עֲשֵׂה בְּמָקוֹם הָרָאוּי לָהֶן, וּמִצְווֹת לֹא תַעֲשֶׂה בְּמָקוֹם שֶׁרָאוּי לָהֶן. וְאֵלּוּ שְׁלֹשָׁה אַחֲרוֹנִים, אֵלּוּ לֹא תַעֲשֶׂה מִכְּלַל עֲשֵׂה, כְּמוֹ שֶׁבֵּאַרְנוּ בְכֻלָּם. אַף עַל גַּב שֶׁזֶּה מֻתָּר - זֶה אָסוּר, מִפְּנֵי שֶׁאֵלּוּ כְּנֶגֶד עַתִּיק הָעַתִּיקִים שֶׁחֶסֶד וְרַחֲמִים גְּדוֹלִים תְּלוּיִים בּוֹ, וְלֹא רְאוּיִים אֶלָּא לְמִצְווֹת עֲשֵׂה. מִפְּנֵי כֵן דִּיֵּק מֵהֶם שֶׁלֹּא יִפְנֶה בֶּן אָדָם (כהן גדול) לְצַד אַחֵר, וְסִמֵּן אוֹתָם בְּמִצְווֹת לֹא תַעֲשֶׂה</p>\n<p>וְהִזְהִיר אוֹתָם לִבְנֵי אָדָם בְּלָאו עַל זֶה הַדִּבֵּר הָאַחֲרוֹן, שֶׁהִיא כְּלָלוּת הַתּוֹרָה. וּמִי שֶׁעוֹבֵר עַל זֶה כְּאִלּוּ עָבַר עַל כָּל הַתּוֹרָה, מִשּׁוּם שֶׁהוּא לְמַעְלָה רֵאשִׁית שֶׁל הַכֹּל, כְּלָלוּת הַכֹּל. וְאִם בֶּן אָדָם עָבַר עַל זֶה וְהִטָּה מַחֲשַׁבְתּוֹ מִדַּרְכֵי הַתּוֹרָה, אָז נִדְבָּק בַּצַּד הָאַחֵר שֶׁל שֶׁקֶר, וְאָז בָּא לִידֵי לֹא תַעֲנֶה בְרֵעֲךְ וְגוֹ', כְּמוֹ שֶׁמָּצָאנוּ אֵצֶל אַחְאָב שֶׁחָמַד הַכֶּרֶם שֶׁל נָבוֹת וְאָז הֵעִידוּ עָלָיו שֶׁקֶר. וּמִכָּאן בָּא בֶּן אָדָם לַעֲבֹר עַל כָּל הַדִּבְּרוֹת.</p>\n<p>אֲבָל כַּאֲשֶׁר הוּא הוֹלֵךְ בְּדַרְכֵי הַתּוֹרָה וְחוֹשֵׁב בַּתּוֹרָה וּבְמִצְווֹתֶיהָ, אָז מִתְפַּשֶּׁטֶת הַמַּחֲשָׁבָה הַהִיא בְּכָל הַמַּדְרֵגוֹת מִצַּד הָאֱמֶת, מִצַּד הָאֱמוּנָה הָעֶלְיוֹנָה.</p>\n<p>וּבֹא רְאֵה שֶׁהֲרֵי קְבִיעוּת כָּל הַדִּבְּרוֹת שֶׁלֹּא יַטֶּה מַחֲשַׁבְתּוֹ וּרְצוֹנוֹ לַצַּד הָאַחֵר. וְכַאֲשֶׁר בֶּן אָדָם נִדְבָּק בָּזֶה, אָז כָּל הָעוֹלָמוֹת מִתְמַלְּאִים בְּרָכוֹת עֶלְיוֹנוֹת שֶׁנִּמְשָׁכוֹת מֵעַתִּיקָא סְתִימָא שֶׁלָּהּ: (עד כאן מההשמטות)</p>"],[9522012732,"<p>וְשֵׁם שֶׁלּוֹ נִקְרָא זָהָב יְרַקְרַק, וְסוֹד זֶה בֵּאֲרוּהוּ הַחֲבֵרִים. אֶסְתֵּר יְרַקְרֹקֶת הָיְתָה, צֶבַע הָאֶתְרוֹג. וְהַכֹּל אֶחָד. זָהָב, זֶהוּ הָרֹאשׁ הַנֶּעְלָם, אַף עַל גַּב שֶׁהוּא בְּגִלּוּי לְגַבֵּי הַזָּהָב הָעֶלְיוֹן, עַד שֶׁיִּמָּשֵׁךְ וְיִשְׁרֶה עַל רֹאשׁ גַּבְרִיאֵל כְּמוֹ שֶׁבֵּאַרְנוּ. וּבִגְלַל זֶה הַכֹּל הוּא בַּסּוֹד הָעֶלְיוֹן, וְנִמְשָׁךְ אוֹתוֹ הַסּוֹד לְמַטָּה הַכֹּל כְּדֻגְמָא אַחַת.</p>\n<p>וְעָשִׂיתָ כַּפֹּרֶת וְגוֹ'. רַבִּי שִׁמְעוֹן אָמַר, בְּכָל פָּרָשָׁה זוֹ מָצָאנוּ שֶׁנִּמְסְרָה הָעֲבוֹדָה בְּיַד מֹשֶׁה, חוּץ מִשְּׁתַיִם. בְּכֻלָּם כָּתוּב וְעָשִׂיתָ וְעָשִׂיתָ, וּבָאָרוֹן וּבָאֵפוֹד כָּתוּב וְעָשׂוּ וְעָשׂוּ, וְלֹא כָתוּב וְעָשִׂיתָ. מָה הַטַּעַם בָּאָרוֹן לֹא? בִּגְלַל שֶׁהָאָרוֹן כָּלַל אֶת מֹשֶׁה בְּתוֹכוֹ לְהָאִיר מִמֶּנּוּ, וְצָרִיךְ אֲחֵרִים לְתַקֵּן - - - - - תִּקּוּן וְיֹפִי שֶׁלּוֹ לַעֲלוֹת אוֹתוֹ אֶצְלוֹ.</p>\n<p>בָּאֵפוֹד, לֹא שֶׁלּוֹ הוּא, וְלֹא הִשְׁתַּמֵּשׁ בּוֹ וְלֹא הִצְטָרְכָה לוֹ לְמֹשֶׁה לַעֲשׂוֹת עֲבוֹדָה שֶׁל אָחִיו, שֶׁהֲרֵי מֹשֶׁה הוּא כְּמֶלֶךְ, וְאַהֲרֹן שׁוֹשְׁבִין הַמֶּלֶךְ.</p>\n<p>וְאִם תֹּאמַר, וַהֲרֵי כָּתוּב (שמות כט) וְהִלְבַּשְׁתָּ אֶת אַהֲרֹן, וְאָפַדְתָּ לוֹ, וְנָתַתָּ עָלָיו, וְשַׂמְתָּ עָלָיו. הֲרֵי כָּל זֶה עֲבוֹדָתוֹ שֶׁל מֹשֶׁה וּכְבוֹדוֹ שֶׁל אַהֲרֹן הוּא - לֹא כָּךְ. אֶלָּא כְּבוֹדוֹ שֶׁל מֹשֶׁה הוּא, שֶׁהֲרֵי הַקָּבָּ\"ה לֹא רָצָה בַּעֲבוֹדָתוֹ שֶׁל אַהֲרֹן אֶלָּא עַל יְדֵי מֹשֶׁה, וְאַהֲרֹן לֹא יָכֹל לְהִתְקַדֵּשׁ אֶלָּא עַל יְדֵי מֹשֶׁה, וּבַכֹּל צָרִיךְ אַהֲרֹן לְמֹשֶׁה, וְכָל זֶה כְּבוֹדוֹ שֶׁל מֹשֶׁה הוּא. וְעָשִׂיתָ כַּפֹּרֶת.</p>\n<p>בֹּא רְאֵה, כָּתוּב בְּפָרָשָׁה זוֹ מַעֲשֵׂה שָׁמַיִם וָאָרֶץ וְכָל אוֹתָם הַחֲיָלוֹת שֶׁשָּׁם, שֶׁהֲרֵי הַקָבָּ\"ה לֹא צִוָּה לַעֲשׂוֹת הַמִּשְׁכָּן אֶלָּא כְּמַעֲשֵׂה שָׁמַיִם וָאָרֶץ לִהְיוֹת כְּדֻגְמַת הַדִּירָה שֶׁל מַעְלָה וּלְהִתְחַבֵּר זֶה בָּזֶה, כְּדֻגְמַת הַנְּשָׁמָה וְהַגּוּף לִהְיוֹת הַכֹּל אֶחָד.</p>\n<p>כָּתוּב בְּרֵאשִׁית בָּרָא וְגוֹ'. בְּרֵאשִׁית כְּבָר בֵּאֲרוּהוּ, אֲבָל סוֹד שֶׁל מַעֲשֵׂה הַכַּפֹּרֶת בָּא כָּאן בְּרֶמֶז שֶׁל מַעְלָה שַׁרְשֶׁרֶת שֶׁל מטטרו\"ן, סִתְרֵי הַמִּשְׁכָּן, לְהָרִים מַעֲלַת הַקְּדֻשָּׁה לְמַעְלָה וּמַטָּה.</p>\n<p>בְּרֵאשִׁית, רֵאשִׁית הָעֶלְיוֹנָה הַכַּפֹּרֶת הַשְּׁמוּרָה וְהַנִּסְתֶּרֶת שֶׁנִּמְצֵאת מִסּוֹד נְקֻדָּה רִאשׁוֹנָה (הגעלמת) סְתִימוּת הָעֶלְיוֹנָה, וְנִפְרָשׂ מָסָךְ עֶלְיוֹן לְהָאִיר (להתטהר) תּוֹךְ טְהִירוּ, נֶעְלָם תּוֹךְ הַכּפֹּרֶת, מטטרו\"ן שֶׁנֶּאֱחָז מִמַּטָּה לְמַעְלָה</p>\n<p>מִתּוֹךְ יִרְאָה שֶׁהוֹלֶכֶת בֶּאֱמֶת תּוֹךְ הָאָרֶץ הָיָה נִמְצָא הָאוֹר שֶׁאִבֵּד אָדָם הָרִאשׁוֹן, וְנֶעְלַם הָאוֹר הַהוּא בְּגַן עֵדֶן. הִסְתַּלֵּק לְמַעְלָה וְלֹא הִתְיַשֵּׁב בִּמְקוֹמוֹ, שֶׁהֲרֵי לֹא הָיָה נִשְׁלָם מִכָּל הַצְּדָדִים, שְׁלֵמוּת שֶׁל מַטָּה הָיָה נֶחְסָר, שֶׁהֲרֵי נַעֲשָׂה בְחֶטְאוֹ שֶׁל אָדָם הָרִאשׁוֹן, יָרַד לְמַטָּה, נֶחְבָּא תּוֹךְ אִילָנוֹת הַגָּן, הִתְפַּשֵּׁט שָׁם בְּכָל צְדָדֵי הַגָּן, עַד שֶׁנּוֹלַד חֲנוֹךְ בֶּן יֶרֶד.</p>\n<p>כֵּיוָן שֶׁנּוֹלַד, הָיָה נִמְצָא סָמוּךְ לַגָּן. הִתְחִיל הָאוֹר הַהוּא לְהָאִיר בְּתוֹכָם, הִתְרַבָּה בְּרִבּוּי הַקְּדֻשָּׁה וְשָׁרָה עֲלֵיהֶם אוֹר הַמִּתְנוֹצֵץ. נִכְנַס לְגַן עֵדֶן, מָצָא שָׁם עֵץ הַחַיִּים וַעֲנָפָיו וּפֵרוֹתָיו שֶׁל הָאִילָן, הֵרִיחַ בּוֹ וְהִתְיַשֵּׁב תּוֹךְ רוּחַ שֶׁל אוֹר הַחַיִּים.</p>\n<p>בָּאוּ שְׁלִיחִים מַלְאָכִים עֶלְיוֹנִים, לִמְּדוּ אוֹתוֹ חָכְמָה עֶלְיוֹנָה, נָתְנוּ לוֹ סֵפֶר שֶׁהָיָה נִסְתָּר תּוֹךְ עֵץ הַחַיִּים, וְלָמַד מִמֶּנּוּ וְיָדַע דְּרָכָיו שֶׁל הַקָּבָּ\"ה וְהִשְׁתַּדֵּל אַחֲרָיו. זֶהוּ שֶׁכָּתוּב (בראשית ה) וַיִּתְהַלֵּךְ חֲנוֹךְ אֶת הָאֱלֹהִים. עַד שֵׁאוֹתוֹ הָאוֹר נִשְׁלַם בְּתוֹכוֹ.</p>\n<p>כֵּיוָןֹ שֶׁאוֹתוֹ הָאוֹר נִשְׁלַם לְמַטָּה, רָצָה לַעֲלוֹת לִמְקוֹמוֹ וּכְדֵי לְהַרְאוֹת אוֹתוֹ הַשְּׁלֵמוּת בְּסוֹד שֶׁל חֲנוֹךְ. יוֹם אֶחָד נִכְנַס תּוֹךְ גַּן עֵדֶן וְהֶרְאוּ לוֹ נִסְתְּרוֹת הַגָּן, וְהִנִּיחַ אוֹתוֹ סֵפֶר וְכָל מַה שֶּׁרָאָה בַּחוּץ וְהוּא מֻצְנָע בֵּין הַחֲבֵרִים.</p>\n<p>אַחַר כָּךְ הִתְלַבֵּשׁ אוֹתוֹ הָאוֹר תּוֹךְ אוֹתוֹ הַלְּבוּשׁ, לְהַרְאוֹת לְמַעְלָה וְלִהְיוֹת בּוּשָׁה עִמּוֹ לְכָל אוֹתָם שֶׁעָשׂוּ קִטְרוּג בְּרִבּוֹנָם שֶׁלֹּא יִבָּרֵא הָאָדָם בָּעוֹלָם.</p>\n<p>זֶהוּ שֶׁכָּתוּב (שם) וְאֵינֶנּוּ כִּי לָקַח אֹתוֹ אֱלֹהִים. וְאֵינֶנּוּ בָּעוֹלָם הַזֶּה, וְאֵינֶנּוּ כְּמוֹ שֶׁהָיָה בָּעוֹלָם הַזֶּה, כִּי לָקַח אֹתוֹ אֱלֹהִים, לְצוּרָה אַחֶרֶת בָּזֶה הוּא נַעַר תָּמִיד. וְסוֹד זֶה בֵּאַרְנוּ, חֲנֹךְ לַנַּעַר עַל פִּי דַרְכּוֹ, לְהַנְהִיג הָעוֹלָמוֹת כֻּלָּם. גַּם כִּי יַזְקִין לֹא יָסוּר מִמֶּנָּה, שֶׁהֲרֵי הָיָה בּוֹ וְנַעֲשָׂה נַעַר.</p>\n<p>בַּחֲנוֹךְ נִכְלָל צוּרָה שֶׁל הָעוֹלָם הָעֶלְיוֹן, הוּא כִּסֵּא שֶׁל אֲדוֹנוֹ. עוֹשֶׂה שְׁלִיחוּת בָּעוֹלָם כַּאֲשֶׁר הָעוֹלָם יוֹצֵא בְדִין, וְנִקְרָא מטטרו\"ן, שַׂר עַל כָּל חֲיָלוֹת הָעֶלְיוֹנִים וְזָקֵן הוּא. נַעַר, עוֹלֶה מֵעוֹלָם לְעוֹלָם וּמִתְיַשֵּׁב הָרֹגֶז.</p>\n<p>צוּרָה זוֹ נִפְרְסָה בִּפְרִיסַת הַכַּפֹּרֶת וְהִצְטַיְּרוּ בוֹ בְּאוֹתוֹ מָסָךְ שְׁתֵּי צוּרוֹת, אַחַת זָכָר וְאַחַת נְקֵבָה, וְעוֹמְדִים שְׁנֵי תִינוֹקוֹת עֲלָמִים אוֹהֲבִים דְּבוּקִים זֶה בָּזֶה. וְסוֹד זֶה בְּרֵאשִׁית בָּרָא אֱלֹהִים, פְּרִיסַת כַּפֹּרֶת סְתוּמָה.</p>\n<p>אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ - שְׁנֵי כְרוּבִים עוֹמְדִים בִּדְבֵקוּת שֶׁל חֲבִיבוּת. שָׁמַיִם וָאָרֶץ לֹא כָתוּב, אֶלָּא אֵת, לְרַבּוֹת שְׁנֵי כְרוּבִים כְּאֶחָד. כַּפֹּרֶת זוֹ פְּרוּסָה פְּנִימָה בְּסִתְרֵי הַהֵיכָל, וּבִשְׁנֵי צְדָדִים עוֹמְדִים שְׁנֵי אֵלּוּ, בְּרֵאשִׁית עוֹלֶה לְמַעְלָה, וְסוֹד שֶׁלּוֹ יוֹרֵד לְמַטָּה.</p>\n<p>כְּדֻגְמַת הַסּוֹד הַהוּא שֶׁל בְּרֵאשִׁית עוֹלֶה לְמַעְלָה לְמַעְלָה וְלֹא נִרְשָׁם בְּסִימָן, יוֹצֵא רֹשֶׁם לְמַטָּה וְנַעֲשֵׂית מִמֶּנּוּ כַּפֹּרֶת עֶלְיוֹנָה רְשׁוּמָה בִּשְׁלֹשָׁה רִשּׁוּמִים בְּסוֹד יְהֹוָ\"ה אֱלֹהֵינ\"וּ יְהֹוָ\"ה. מֵאֵלּוּ הַשְּׁלֹשָׁה יָצְאוּ שְׁלֹשָׁה אֲחֵרִים, וְהֵם שִׁשָּׁה. וְזֶהוּ בָּרָ\"א שִׁית.</p>\n<p>וְנִפְרְסָה כַּפֹּרֶת זוֹ לְצַד דָּרוֹם וּמַעֲרָב, וְהוֹצִיא שְׁנֵי כְרוּבִים כְּאֶחָד, זָכָר וּנְקֵבָה, שֶׁנִּמְצָאִים זֶה לְעֻמַּת זֶה. דָּרוֹם הוּא רֹאשׁ, כֹּהֵן בָּרֹאשׁ וְהוּא זָכָר. מַעֲרָב הוּא נְקֵבָה, בַּת יְחִידָה. בַּת הָיְתָה לְאַבְרָהָם, וַדַּאי. וְזֶה בְּסוֹד שֶׁל בְּרֵאשִׁית, בַּ\"ת רֹאשׁ י', כַּפֹּרֶת שֶׁלֹּא נוֹדַעַת עַד שֶׁנִּפְרְסָה בִּפְרִיסָה וְהוֹצִיאָה שְׁנֵי אֵלּוּ. כְּדֻגְמַת זֶה אוֹת ה', וְעַל זֶה בַּת, בַּ\"ת רֹא\"שׁ, בַּת לְאַבְרָהָם. י' כַּפֹּרֶת שֶׁנִּפְרֶסֶת.</p>\n<p>וְחוזֶרֶת הַכַּפֹּרֶת מִמַּעֲרָב לְצָפוֹן וְנִפְרֶסֶת בִּפְרִיסָה, וּמִתְגַּלֶּה זָכָר שֶׁאָחוּז בְּצַד הַכַּפֹּרֶת וּנְקֵבָה שֶׁמִּסְתַּתֶּרֶת לְמַטָּה וְנַעֲשֵׂית בְּאֵר הַצָּפוֹן. וְסוֹד זֶה בְּרֵאשִׁית, בַּ\"ת אֵ\"שׁ, י' הִיא הַכַּפֹּרֶת, ר' (י') הִיא הַפְּרִיסָה שֶׁנִּפְרֶסֶת וְנִרְאֵית אֶחָד וְלֹא שְׁנַיִם, שֶׁהֲרֵי הַנְּקֵבָה נִכְנַעַת לְמַטָּה. וְאִם תֹּאמַר, הָאוֹת ר' הַכֹּל פְּרִיסָה אַחַת לְמַעְלָה וּלְמַטָּה - כָּךְ הוּא, שֶׁלֹּא נִפְרָד הַשֵּׁם הַזֶּה מִזֶּה, הַכֹּל הוּא אֱלֹהִים.</p>\n<p>חָזְרָה הַכַּפֹּרֶת מִמַּעֲרָב לַמִּזְרָח, נִפְרְסָה פְּרִיסָתָהּ לִשְׁנֵי צְדָדִים, בְּצַד הַמִּזְרָח וּבְצַד הַמַּעֲרָב. כֵּיוָן שֶׁהַכַּפֹּרֶת עוֹמֶדֶת בַּמִּזְרָח וּבַמַּעֲרָב, אֲזַי שִׂמְחָה נִמְצֵאת וְחִבּוּר כָּרָאוּי, וּבַת זוֹ נִכְלֶלֶת בְּעַטְרוֹתֶיהָ כָּרָאוּי וְעוֹמֶדֶת בִּשְׁלֵמוּתָהּ. וְאָז הוּא בַּסּוֹד שֶׁלּוֹ, בְּרֵאשִׁית, בְּלֹא פֵרוּד כְּלָל.</p>\n<p>וּכְנֶגֶד שְׁלֹשָׁה זְמַנִּים אֵלּוּ עוֹלִים יִשְׂרָאֵל שְׁלֹשָׁה זְמַנִּים לָחֹג חַגָּם. בְּפֶסַח חוֹזֶרֶת הַכַּפֹּרֶת בְּצַד דָּרוֹם וּמַעֲרָב, וְאָז אוֹתָהּ בַּת עוֹמֶדֶת בְּאַבְרָהָם וְהִיא בַּ\"ת רֹא\"שׁ, וְשָׁם הַלֵּל וְלֹא הַלֵּל גָּמוּר, שֶׁהֲרֵי שְׁנֵי כְרוּבִים אֵלּוּ אֵינָם בִּשְׁלֵמוּת כָּרָאוּי, שֶׁהֲרֵי יִשְׁמָעֵאל יוֹצֵא וּמְקַטְרֵג.</p>\n<p>וּמִיּוֹם רֹאשׁ הַשָּׁנָה וְעַד יְמֵי סֻכּוֹת חוֹזֶרֶת הַכַּפֹּרֶת מִצָּפוֹן לְמַעֲרָב, אָז אוֹתָהּ בַּת נִכְנַעַת וְעוֹמֶדֶת בְּיִצְחָק וְלֹא בְשִׂמְחָה, וְהִיא בַּ\"ת אֵ\"שׁ, וְהֵם אֵינָם בִּשְׁלֵמוּת. וְעַל זֶה אֵין שָׁם הַלֵּל כְּלָל, שֶׁהֲרֵי עֵשָׂו יוֹצֵא וּמְקַטְרֵג. בְּסֻכּוֹת עוֹלָה בַּת זוֹ וְנִשְׁלֶמֶת בּוֹ בְּיִצְחָק וּמִתְחַבְּרִים זֶה בָּזֶה, וְאָז הַלֵּל גָּמוּר, עַד שֶׁנִּרְגָּע הָרֹגֶז וְהַחִבּוּר נִמְצָא.</p>\n<p>בְּשָׁבוּעוֹת, עֲצֶרֶת, חוֹזֶרֶת הַכַּפֹּרֶת בְּצַד מִזְרָח וּמַעֲרָב וְאָז שְׁלֵמוּת נִמְצֵאת, וַחֲבִיבוּת וּדְבֵקוּת הִיא בְּכָל הַצְּדָדִים וְשִׂמְחָה שֶׁל עֶלְיוֹנִים וְתַחְתּוֹנִים. וְאָז, (תהלים מט) תּוֹרַת ה' תְמִימָה מְשִׁיבַת נָפֶשׁ. וּבִשְׁלֹשָׁה זְמַנִּים אֵלּוּ חוֹזֶרֶת הַכַּפֹּרֶת בִּצְדָדֶיהָ כָּרָאוּי.</p>\n<p>כַּפֹּרֶת זוֹ נִפְרֶסֶת לְמַעְלָה תּוֹךְ אוֹתָהּ נְקֻדָּה נֶעְלֶמֶת בָּאוֹר הָרִאשׁוֹן שֶׁנִּפְרָס, וְאַחַר כָּךְ נִפְרֶסֶת בִּשְׁלֵמוּת וְשׁוֹרָה עַל הַפְּרִיסָה הָרִאשׁוֹנָה. וְכַאֲשֶׁר סוֹכְכִים כַּנְפֵי הַכְּרוּבִים עַל כַּפֹּרֶת זוֹ כְּדֵי לְסוֹכֵךְ עַל הַכַּפֹּרֶת שֶׁלֹּא תִהְיֶה בְּגִלּוּי,</p>\n<p>כַּפּוֹרֶת - כַּפֹּרֶת כָּתוּב. וְכַאֲשֶׁר בָּא הָאוֹר הָעֶלְיוֹן, אוֹתָם הַכְּרוּבִים מַכִּים בְּכַנְפֵיהֶם וּמַעֲלִים אוֹתָם לְמַעְלָה, וְאוֹמְרִים שִׁירָה מֵרִבּוּי הַשִּׂמְחָה הַהִיא שֶׁל אוֹתוֹ הָאוֹר.</p>\n<p>וּכְדֻגְמַת זֶה הוּא לְמַטָּה, וְהַכַּפֹּרֶת חוֹזֶרֶת, וּמֵאוֹתָם הַשְּׁלֹשָׁה וְהָאֶחָד הָיוּ כְּרוּבִים יָמִין וּשְׂמֹאל. הַיָּמִין שׁוֹרָה בּוֹ רוּחַ שֶׁל מַעְלָה מֵאוֹתוֹ צַד. וְהַשְּׂמָאלִי שֶׁהָיָה לַמַּעֲרָב בַּחֲזָרַת הַכַּפֹּרֶת, עוֹמֵד אֶצְלוֹ בְּצַד שְׂמֹאלוֹ, וְשׁוֹרָה בּוֹ רוּחַ נְקֵבָה, וּמִתְחַבְּרִים זֶה בָּזֶה בַּחֲבִיבוּת שֶׁל זָכָר וּנְקֵבָה. וְכֵן לְכָל הַצְּדָדִים בְּסִבּוּב הַכַּפֹּרֶת, וּלְעוֹלָם הֵם שְׁנַיִם, זָכָר וּנְקֵבָה, לְמַטָּה בָּעוֹלָם הַזֶּה הֵם שְׁנַיִם וְלֹא יוֹתֵר.</p>\n<p>וְאִם תֹּאמַר לְמַעְלָה, הוֹאִיל (ולא) צָרִיךְ דְּבֵקוּת בַּכַּפֹּרֶת אֵיךְ תַּחֲזֹר הַכַּפֹּרֶת? וַדַּאי בְּאוֹתָהּ הַחֲזָרָה מִתְדַּבְּקִים זֶה בָּזֶה וְתָמִיד נִדְבָּק בָּהּ. וּכְדֻגְמַת הַכְּרוּבִים שֶׁהֵם לְמַעְלָה, כָּךְ עוֹמְדִים עַל אוֹת וְנֵס, וַהֲרֵי בֵּאַרְנוּ הַסּוֹד שֶׁכָּתוּב פֹּרְשֵׂי כְנָפַיִם סֹכֲכִים, וְלֹא כָתוּב פְּרוּשֵׂי כְנָפַיִם סְכוּכִים. אֶלָּא עַל אוֹת וְנֵס הָיוּ עוֹמְדִים.</p>\n<p>זְמַנִּים יְדוּעִים הָיוּ מַעֲלִים כַּנְפֵיהֶם וּפוֹרְשִׂים אוֹתָם לְמַעְלָה בְּכָל יוֹם, וְהָיוּ מִסְתַּדְּרִים וּמְחַפִּים עַל הַכַּפֹּרֶת, וְעַל זֶה בְּאוֹת וְנֵס הָיוּ עוֹמְדִים. בְּכָל מָקוֹם שֶׁרוּחַ עֶלְיוֹנָה הָיְתָה בָּאָה וְשׁוֹרָה, וַדַּאי בְּאוֹתוֹ מָקוֹם שֶׁשּׁוֹרָה יֵשׁ בּוֹ מַמָּשׁוּת וְעוֹמֵד בְּאוֹת וְנֵס. בֶּן אָדָם שֶׁהוּא מֵעָפָר, וְעַד שֶׁלֹּא שׁוֹרֶה בּוֹ נִיצוֹץ שֶׁל רוּחַ שֶׁל מַעְלָה - אֵין בּוֹ מַמָּשׁ. כֵּיוָן שֶׁשּׁוֹרֶה עָלָיו, יֵשׁ בּוֹ מַמָּשׁוּת וְקָם עַל עָמְדּוֹ.</p>\n<p>וְאִם תֹּאמַר, זֶה לְבַדּוֹ? בֹּא רְאֵה מִמַּטֵּה אַהֲרֹן שֶׁהוּא עֵץ בְּלֹא מַמָּשׁוּת כְּלָל, כֵּיוָן שֶׁשָּׁלַח בּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא מְעַט רוּחַ, קָם עַל עָמְדּוֹ וְנֶעֶשְׂתָה מִמֶּנּוּ בְּרִיָּה מַמָּשׁ. וּמָה עֵץ שֶׁאֵין דַּרְכּוֹ בְּכָךְ, כֵּיוָן שֶׁשָּׁלַח הַקָּדוֹשׁ בָּרוּךְ הוּא בּוֹ מְעַט רוּחַ, עָמַד עַל עָמְדּוֹ וְהָיָה בּוֹ מַמָּשׁ - כְּרוּבִים שֶׁהֵם קְדוֹשִׁים וְעוֹמְדִים בִּקְדֻשָּׁה כְּדֻגְמַת מַעְלָה עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>בְּכָל זְמַן שֶׁיִּשְׂרָאֵל הָיוּ זַכָּאִים, הַכְּרוּבִים הָיוּ דְבוּקִים בְּדִבּוּק פָּנִים בְּפָנִים. כֵּיוָן שֶׁסָּרְחוּ, הָיוּ חוֹזְרִים פְּנֵיהֶם זֶה מִזֶּה. מִנַּיִן הָיוּ יוֹדְעִים? כָּאן נֶחְלְקוּ עַמּוּדֵי הָעוֹלָם. אֲבָל בֶּעָשָׁן שֶׁל הַקָּרְבָּנוֹת וּבַקָּרְבָּנוֹת עַל גַּבֵּי הַמִּזְבֵּחַ וְהַכֹּהֲנִים כַּאֲשֶׁר מְבָרְכִים אֶת הָעָם - בְּאֵלּוּ הַשְּׁלֹשָׁה הָיוּ יוֹדְעִים סוֹד הַכְּרוּבִים שֶׁמַּחֲזִירִים פָּנִים זֶה מִזֶּה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בִּתְשׁוּבַת בָּנָיו.</p>\n<p>בַּעָשַׁן הַקָּרְבָּנוֹת, כַּאֲשֶׁר הָיוּ יִשְׂרָאֵל זַכָּאִים, עָנָן הָיָה עוֹלֶה לְמַעְלָה בְּדֶרֶךְ יְשְׁרָה כְּמַקֵּל מְעֻטָּר, אִם לְצַד מִזְרָח אִם לְצַד מַעֲרָב אוֹ בְּכָל קַצְוֵי הָעוֹלָם - בְּדֶרֶךְ יְשָׁרָה הָיָה עוֹלֶה. וְכַאֲשֶׁר לֹא נָטָה לְיָמִין אוֹ לִשְׂמֹאל, אָז רָצוֹן נִמְצָא לְמַעְלָה וּמַטָּה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא רָצָה בְּמַעֲשֵׂיהֶם שֶׁל יִשְׂרָאֵל בְּאַהֲבָה יְתֵרָה.</p>\n<p>בַּקָּרְבָּן שֶׁעַל הַמִּזְבֵּחַ, כַּאֲשֶׁר הָיוּ יִשְׂרָאֵל זַכָּאִים, הָיְתָה נִרְאֵית עַל גַּבֵּי אֵשׁ הַמִּזְבֵּחַ דְּמוּת שֶׁל אַרְיֵה שֶׁאוֹכֵל קָרְבָּנוֹת עַל הַמִּזְבֵּחַ. וְכַאֲשֶׁר לֹא הָיוּ זַכָּאִים, הָיוּ רוֹאִים דְּמוּת כֶּלֶב רוֹבֵץ עַל הַמִּזְבֵּחַ.</p>\n<p>הַכֹּהֵן כַּאֲשֶׁר הָיָה מְבָרֵךְ אֶת הָעָם בְּשָׁעָה שֶׁהָיָה זוֹקֵף יָדָיו, כַּאֲשֶׁר הָיוּ יִשְׂרָאֵל זַכָּאִים וּרְאוּיִים לִבְרָכָה, יָדָיו הָיוּ זְקוּפוֹת בִּזְקִיפָה בְּלִי טִרְחָה כְּלָל וְהִתְרוֹמְמוּ בְּשִׂמְחָה וּבְרָצוֹן. אָז הַשְּׁכִינָה הָיְתָה שׁוֹרָה עֲלֵיהֶן וּמִזְדַּקְּפוֹת אֵלּוּ מֵעַצְמָן, וְאָז הָיָה יוֹדֵעַ הַכֹּהֵן שֶׁרְאוּיִים יִשְׂרָאֵל לִבְרָכָה וּמְבָרֵךְ אוֹתָם בִּרְצוֹן הַלֵּב.</p>\n<p>וְכַאֲשֶׁר יָדָיו הָיוּ כְּבֵדִים וּבְטֹרַח רַב הִזְדַּקְּפוּ וְלֹא יָכֹל לְהָרִים אוֹתָן אֶלָּא בְּהַרְבֵּה טֹרַח, אָז הָיָה יוֹדֵעַ שֶׁהַשְּׁכִינָה לֹא שׁוֹרָה עַל יָדָיו וְיִשְׂרָאֵל לֹא רְאוּיִים לִבְרָכָה.</p>\n<p>בִּגְלַל שֶׁבְּשָׁעָה שֶׁהַשְּׁכִינָה הָיְתָה בָּאָה לִשְׁרוֹת עַל יָדָיו, כָּל אוֹתָן אֶצְבָּעוֹת שֶׁהֵן כַּצּוּרָה הָעֶלְיוֹנָה, הָיוּ שְׂמֵחוֹת בְּשִׂמְחָה לְקַבֵּל אֶת הַשְּׁכִינָה עֲלֵיהֶן, וּפוֹרְחוֹת לְהִזְדַּקֵּף לְמַעְלָה כְּמוֹ שֶׁהָיוּ שְׂמֵחִים הַכְּרוּבִים שֶׁל עוֹלָם הַזֶּה, וְכָל שֶׁכֵּן לְמַעְלָה, כְּדֵי לְקַבֵּל הַשְּׁכִינָה עֲלֵיהֶם.</p>\n<p>וְסוֹד זֶה (שמות יז) וִידֵי מֹשֶׁה כְּבֵדִים וְגוֹ'. מָה הַטַּעַם? בִּגְלַל שֶׁאוֹתָהּ שָׁעָה יִשְׂרָאֵל לֹא הָיוּ זַכָּאִים, וִידֵי מֹשֶׁה כָּבְדוּ וְלֹא יָכֹל לִזְקֹף אוֹתָן, שֶׁכָּתוּב לְמַעְלָה (שם) עַל רִיב בְּנֵי יִשְׂרָאֵל וְגוֹ', וְאָז נֶאֱמַר וַיָּבֹא עֲמָלֵק, וְכָבְדוּ יָדָיו וְלֹא הָיָה יָכוֹל לִזְקֹף אוֹתָן עַד שֶׁקִּבֵּל עֹנֶשׁ, שֶׁכָּתוּב וַיִּקְחוּ אֶבֶן וְגוֹ' וְהָיָה כַּאֲשֶׁר וְגוֹ'. כְּמוֹ זֶה גַּם לוּחוֹת הָאֶבֶן כְּמוֹ הַכֹּהֵן,</p>\n<p>וְעַל זֶה הַכְּרוּבִים, בַּזְּמַן הַהוּא שֶׁהָיוּ יִשְׂרָאֵל זַכָּאִים, הָיוּ פָּנִים בְּפָנִים מִתְדַּבְּקִים זֶה בָּזֶה. וְכַאֲשֶׁר לֹא הָיוּ זַכָּאִים, הָיוּ מַחֲזִירִים פָּנִים אֵלּוּ מֵאֵלּוּ (זה מזה), וְעַל סוֹדוֹת אֵלּוּ הָיוּ יוֹדְעִים אִם יִשְׂרָאֵל זַכָּאִים אוֹ לֹא.</p>\n<p>כְּרוּבִים - תִּינוֹקוֹת, וְהַכֹּל עוֹמֵד בְּסוֹד אֶחָד, שֶׁכָּתוּב (הושע יא) כִּי נַעַר יִשְׂרָאֵל וָאֹהֲבֵהוּ. וּבִגְלַל זֶה הַכֹּל בְּחִדּוּשׁ הַיָּרֵחַ תָּלוּי. כְּמוֹ שֶׁמִּתְחַדֵּשׁ זֶה בְּחִדּוּשׁוֹ, כָּךְ הוּא הַכֹּל. וּמִשּׁוּם כָּךְ הַנַּעַר, הֵם נְעָרִים, וְזֶה סוֹד אֵשֶׁת נְעוּרִים, שֶׁעוֹמֶדֶת עַל שְׁנֵי נְעָרִים בְּחִדּוּשׁ עֶלְיוֹן.</p>\n<p>כְּרוּבִים - פָּנִים גְּדוֹלוֹת וּפָנִים קְטַנּוֹת, וַדַּאי כָּךְ הֵם. פָּנִים נִסְתָּרִים לְמַעְלָה שֶׁלֹּא מִתְגַּלִּים, וּבִגְלָלָם חִדּוּשׁ הַלְּבָנָה וּמִלּוּי שֶׁלָּהּ.</p>\n<p>פָּנִים קְטַנּוֹת לְמַטָּה, כְּמוֹ שֶׁבֵּאַרְנוּ בַּכַּפֹּרֶת, לְמַעְלָה וּמַטָּה בְּסוֹד אֶחָד עוֹמְדִים. אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ, אֵלּוּ הֵם סוֹד שֶׁל שְׁנֵי כְרוּבִים, אֶחָד זָכָר וְאֶחָד נְקֵבָה, לִהְיוֹת דְּבוּקִים אֵלּוּ בְּאֵלּוּ בַּחֲבִיבוּת, כְּמוֹ שֶׁנִּתְבָּאֵר אֵת - לְרַבּוֹת מַעְלָה וּמַטָּה כְּאֶחָד, לִהְיוֹת סוֹד הַכְּרוּבִים בִּכְלָל אֶחָד.</p>\n<p>כָּתוּב (תהלים ק) עִבְדוּ אֶת ה' בְּשִׂמְחָה, שִׂמְחָה שֶׁל שְׁנֵי הַכְּרוּבִים. שֶׁהֲרֵי תִּינוֹקוֹת, כָּל מַה (מי) שֶּׁנִּמְצָא בֵינֵיהֶם, חוֹזְרוֹת פָּנָיו כְּתִינוֹק וְשָׂמֵחַ עִמְּהֶם. וְסוֹד זֶה, כֵּיוָן שֶׁשּׁוֹרֶה עֲלֵיהֶם מִי שֶׁשּׁוֹרֶה, חוֹזֵר נַעַר בְּשִׂמְחָה שֶׁל הַכֹּל וּבְרָצוֹן. אַף עַל גַּב שֶׁחוֹזֵר בְּדִין עַל הָעוֹלָם, כֵּיוָן שֶׁשּׁוֹרֶה עֲלֵיהֶם, חוֹזֵר בְּשִׂמְחָה, נַעַר קָשׁוּר בְּשִׂמְחָה, וְהָעוֹלָם חוֹזֵר בְּרַחֲמִים (ברגז).</p>\n<p>מִי שֶׁהוּא בְּרֹגֶז, יָבִיאוּ אֶצְלוֹ תִּינוֹק וְיִשְׁקֹט רָגְזוֹ, וְיַחֲזֹר בְּשִׂמְחָה וְיַעֲשֶׂה עַצְמוֹ כְּתִינוֹק, וְאָז הַכֹּל בְּשִׂמְחָה. וְעַל סוֹד זֶה נֶאֱמַר כִּי נַעַר יִשְׂרָאֵל וָאֹהֲבֵהוּ. אֵין אַהֲבָה וַחֲבִיבוּת, רַק בְּנַעַר.</p>\n<p>כָּתוּב (שמות לג) וִיהוֹשֻׁעַ בִּן נוּן נַעַר לֹא יָמִישׁ. הָיָה עוֹמֵד תּוֹךְ הַמִּשְׁכָּן שֶׁל מֹשֶׁה, בִּגְלַל שֶׁאוֹתוֹ אֹהֶל הָיָה אֹהֶל מֹשֶׁה, וּבְשָׁעָה שֶׁהַשְּׁכִינָה הָיְתָה בָּאָה, נִמְצָא שָׁם יְהוֹשֻׁעַ שֶׁהוּא נַעַר, וּמִיָּד הָיָה בְּשִׂמְחָה וּבְרָצוֹן שֶׁל הַשִּׂמְחָה, וִיהוֹשֻׁעַ שֶׁפָּנָיו הֵם כַּלְּבָנָה בַּכֹּל, בְּכָל הַסּוֹדוֹת שֶׁלּוֹ כָּךְ הָיָה.</p>\n<p>וְכֵיוָן שֶׁנִּבְנָה הַמִּשְׁכָּן, לֹא הָיָה צָרִיךְ יְהוֹשֻׁעַ לִהְיוֹת שָׁם, אֶלָּא כְּרוּבִים הָיוּ שָׁם וְנִמְצָאִים בַּחֲבִיבוּת זֶה בָּזֶה, פָּנִים בְּפָנִים כִּנְעָרִים בְּשִׂמְחָה. וְכֵיוָן שֶׁשּׁוֹרֶה עֲלֵיהֶם, מִיָּד הַכֹּל בְּשִׂמְחָה וְדִין לֹא נִמְצָא כְּלָל. בִּגְלַל זֶה הַקָּבָּ\"ה, שֶׁרְצוֹנוֹ בְּעַם יִשְׂרָאֵל, רָצָה לְהַרְאוֹת מַעֲשֶׂה לְמַטָּה, לְעוֹרֵר רַחֲמִים וּלְהַעֲבִיר דִּין שֶׁלֹּא יִשְׁלֹט עֲלֵיהֶם כְּלָל, וְיִהְיוּ תָמִיד בְּשִׂמְחָה עִמּוֹ. זַכָּאִים הֵם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>כָּתוּב (שמואל א ג) וְהַנַּעַר שְׁמוּאֵל מְשָׁרֵת וְגוֹ'. כָּתוּב נַעַר, וְכָתוּב (תהלים צט) וּשְׁמוּאֵל בְּקֹרְאֵי שְׁמוֹ, וְלָמַדְנוּ, שָׁקוּל הָיָה מֹשֶׁה כְּנֶגֶד מֹשֶׁה וְאַהֲרֹן. אִם שָׁקוּל כְּמֹשֶׁה וְאַהֲרֹן, מַדּוּעַ כָּתוּב נַעַר, שֶׁהֲרֵי כַּמָּה מַדְרֵגוֹת הֵן, וְלֹא הָיָה מַגִּיעַ אֲפִלּוּ לְמַדְרֵגָה קְטַנָּה שֶׁל מֹשֶׁה, כָּל שֶׁכֵּן לִהְיוֹת שָׁקוּל כִּשְׁנֵיהֶם?</p>\n<p>(שם) מֹשֶׁה וְאַהֲרֹן בְּכֹהֲנָיו, מֹשֶׁה הוּא נָבִיא נֶאֱמָן עֶלְיוֹן עַל כָּל שְׁאָר הַנְּבִיאִים. אַהֲרֹן בְּכֹהֲנָיו, וְהוּא כֹּהֵן עֶלְיוֹן עַל כָּל כֹּהֲנֵי הָעוֹלָם. שֶׁלֹּא הָיָה כֹּהֵן גָּדוֹל שֶׁעוֹלֶה בְּמַדְרֵגָה עֶלְיוֹנָה כְּאַהֲרֹן. זָכָה אַהֲרֹן לִכְהֻנָּה וּנְבוּאָה, נָבִיא וְכֹהֵן, מַה שֶּׁלֹּא זָכָה כֹּהֵן אַחֵר. וְאִם תֹּאמַר, הֲרֵי זְכַרְיָה כֹּהֵן וְנָבִיא הָיָה - הַנְּבוּאָה הַהִיא הָיְתָה לְשָׁעָה. (עד כאן מההשמטות),</p>"],[9522012733,"<p>רַבִּי יְהוּדָה וְרַבִּי יִצְחָק הָיוּ הוֹלְכִים בַּדֶרֶךְ. בְּעוֹד שֶׁהָיוּ הוֹלְכִים, פָּגְשׁוּ בְּאוֹתוֹ תִינוֹק שֶׁהָיָה הוֹלֵךְ וְהָיָה עָיֵף. אָמַר לוֹ, אֲנִי עָיֵף שֶׁלֹּא אָכַלְתִּי הַיּוֹם הַזֶּה. הוֹצִיאוּ לֶחֶם וְנָתְנוּ לוֹ. הִתְרַחֵשׁ לָהֶם נֵס, וּמָצְאוּ מַעְיָן דַּק שֶׁל מַיִם (תחת האילן) תַּחְתֵּיהֶם, וְשָׁתוּ מִמֶּנּוּ וְיָשְׁבוּ.</p>\n<p>פָּתַח אוֹתוֹ תִינוֹק וְאָמַר, וַיִּקְרָא אֶל מֹשֶׁה, לָמָּה כָּאן א' זְעִירָה? מִשּׁוּם שֶׁהַקְּרִיאָה הַזּוֹ לֹא הָיְתָה בִּשְׁלֵמוּת. מָה הַטַּעַם? שֶׁלֹּא הָיָה אֶלָּא בַּמִּשְׁכָּן וּבְאֶרֶץ אַחֶרֶת, מִשּׁוּם שֶׁאֵין שְׁלֵמוּת נִמְצֵאת אֶלָּא בָּאָרֶץ הַקְּדוֹשָׁה.</p>\n<p>עוֹד כָּאן שְׁכִינָה, שָׁם שְׁלֵמוּת שֶׁל זָכָר וּנְקֵבָה, (דברי הימים א א) אָדָם, שֵׁת, אֱנוֹשׁ. אָדָם שְׁלֵמוּת שֶׁל זָכָר וּנְקֵבָה. כָּאן נְקֵבָה. עוֹד, סוֹף הַכָּתוּב, וַיְדַבֵּר ה' אֵלָיו מֵאֹהֶל מוֹעֵד לֵאמֹר, מִשּׁוּם כָּךְ א' זְעִירָה,</p>\n<p>וְעוֹד א' זְעִירָה. מָשָׁל לְמֶלֶךְ שֶׁהָיָה יוֹשֵׁב בְּכִסֵּא, וְכֶתֶר מַלְכוּת עָלָיו, וְנִקְרָא מֶלֶךְ עֶלְיוֹן. כְּשֶׁיּוֹרֵד וְהוֹלֵךְ לְבֵית עַבְדּוֹ, נִקְרָא מֶלֶךְ קָטָן. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא, כָּל זְמַן שֶׁהוּא לְמַעְלָה עַל הַכֹּל, נִקְרָא מֶלֶךְ עֶלְיוֹן. כֵּיוָן שֶׁהוֹרִיד אֶת מְדוֹרוֹ לְמַטָּה, הוּא מֶלֶךְ, אֲבָל לֹא עֶלְיוֹן כְּמוֹ בַּתְּחִלָּה, מִשּׁוּם כָּךְ א' זְעִירָה.</p>\n<p>וַיִּקְרָא, כָּךְ שָׁנִינוּ, הִזְמִין אוֹתוֹ לְהֵיכָלוֹ. מֵאֹהֶל מוֹעֵד, מִיהוּ אֹהֶל מוֹעֵד? אֹהֶל שֶׁבּוֹ תְּלוּיִים מוֹעֵד וְחַג וְשַׁבָּת לִמְנוֹת, כְּמוֹ שֶׁנֶּאֱמַר (בראשית א) וְהָיוּ לְאתת וּלְמועֲדִים, וּבו מַתְחִילִים לִמְנות אֶת הַחֶשְׁבּוֹן, וּמִיהוּ? הַלְּבָנָה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה לג) אֹהֶל בַּל יִצְעָן בַּל יִסַּע יְתֵדתָיו לָנֶצַח.</p>\n<p>לֵאמֹר, מַה זֶּה לֵאמֹר? כְּדֵי לְגַלּוֹת, אֲבָל הַכֹּל אֶחָד וְיָפֶה הוּא, מִשּׁוּם שֶׁשְּׁלֵמוּת הוּא מָקוֹם לְגַלּוֹת מַה שֶּׁהָיָה נִסְתָּר בִּפְנִים, וּבְכָל מָקוֹם לֵאמֹר, כְּמוֹ שֶׁנֶּאֱמַר וַיְדַבֵּר ה' אֶל מֹשֶׁה לֵאמֹר, וַיְדַבֵּר ה' אֵלָיו מֵאֹהֶל מוֹעֵד לֵאמֹר. שֶׁנִּתְּנָה רְשׁוּת לְגַלּוֹת, שֶׁהֲרֵי הָיָה צִוּוּי לַלְּבָנָה אוֹתוֹ הַדָּבָר מֵהַמָּקוֹם שֶׁעָמַד מֹשֶׁה. וַיְדַבֵּר ה' - לְמַעְלָה, אֶל מֹשֶׁה - בָּאֶמְצַע, לֵאמֹר - בַּחוּץ (בסוף), הַמָּקוֹם שֶׁיֵּשׁ רְשׁוּת לְגַלּוֹת.</p>\n<p>עוֹד וַיִּקְרָא אֶל מֹשֶׁה, מַה כָּתוּב לְמַעְלָה? (שמות לט) וַיָּבִיאוּ אֶת הַמִּשְׁכָּן אֶל מֹשֶׁה וְגוֹ'. לָמָּה אֶל מֹשֶׁה? כָּךְ אָמְרוּ, מִשּׁוּם שֶׁמֹּשֶׁה רָאָה אוֹתוֹ בָּהָר, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הֶרְאָה לוֹ בְּמַרְאֵה הָעַיִן, כְּמוֹ שֶׁנֶּאֱמַר (שם כז) כַּאֲשֶׁר הֶרְאָה אֹתְךְ בָּהָר. כַּמַּרְאֶה אֲשֶׁר הֶרְאָה ה' אֶת מֹשֶׁה וְגוֹ'. וְכָתוּב וּרְאֵה וַעֲשֵׂה בְּתַבְנִיתָם אֲשֶׁר אַתָּה מָרְאֶה בָּהָר. עַכְשָׁו שֶׁהֵבִיאוּ לוֹ כְּדֵי שֶׁיִּרְאֶה אִם הוּא כְּמוֹ אוֹתוֹ הַמִּשְׁכָּן שֶׁרָאָה (כדי שיראה הוא אותו משכן שראה).</p>\n<p>אֲבָל לָמָּה וַיָּבִיאוּ אֶת הַמִּשְׁכָּן אֶל מֹשֶׁה? אֶלָּא, לְמֶלֶךְ שֶׁרָצָה לִבְנוֹת פַּלְטֵרִין לַגְּבִירָה, צִוָּה לָאֻמָּנִים: הַהֵיכָל הַזֶּה בְּמָקוֹם פְּלוֹנִי, וְהַהֵיכָל הַזֶּה בְּמָקוֹם פְּלוֹנִי, כָּאן הַמָּקוֹם לְמִטָּתָהּ, וְכָאן הַמָּקוֹם לִמְנוּחָה. כֵּיוָן שֶׁעָשׂוּ אוֹתָם הָאֻמָּנִים, הֶרְאוּ לַמֶּלֶךְ. כָּךְ וַיָּבִיאוּ אֶת הַמִּשְׁכָּן אֶל מֹשֶׁה, בַּעַל הַבַּיִת אִישׁ הָאֱלֹהִים. כֵּיוָן שֶׁנִּתְקַן הַהֵיכָל לַגְּבִירָה, הִזְמִינָה אֶת הַמֶּלֶךְ לֶאֱכֹל, הִזְמִינָה אֶת בַּעְלָהּ עִמָּהּ. מִשּׁוּם כָּךְ וַיִּקְרָא אֶל מֹשֶׁה,</p>\n<p>וּמִשּׁוּם שֶׁמֹּשֶׁה הוּא בַּעַל הַבַּיִת, מַה כָּתוּב? (שם לג) וּמֹשֶׁה יִקַּח אֶת הָאֹהֶל וְנָטָה לוֹ מִחוּץ לַמַּחֲנֶה. מֹשֶׁה שֶׁהוּא בַּעַל הַבַּיִת עָשָׂה כָּךְ, (מה) שֶׁאֵין רְשׁוּת לְאָדָם אַחֵר לַעֲשׂוֹת כָּךְ.</p>\n<p>וַיְדַבֵּר ה' אֵלָיו, דַּרְגָּה אַחֶרֶת עֶלְיוֹנָה. וְאָז, בְּשָׁעָה שֶׁהִזְדַּמֵּן מֹשֶׁה לְהִכָּנֵס, אָז פָּתַח וְאָמַר, אָדָם כִּי יַקְרִיב מִכֶּם. מָה אָדָם כָּאן? אֶלָּא כְּשֶׁמִּתְחַבְּרִים הַשֶּׁמֶשׁ וְהַלְּבָנָה כְּאֶחָד, פָּתַח וְאָמַר אָדָם, כְּמוֹ שֶׁכָּתוּב שֶׁמֶשׁ יָרֵחַ עָמַד זְבֻלָה. עָמַד וְלֹא עָמְדוּ.</p>\n<p>כִּי יַקְרִיב מִכֶּם, כָּאן נִרְמָז, מִי שֶׁיַּעֲשֶׂה אֶת הַקָּרְבָּן שָׁלֵם, שֶׁיִּמָּצְאוּ זָכָר וּנְקֵבָה, מַשְׁמָע מִכֶּם, שֶׁנִּמְצָא כְּמוֹ הַמַּרְאֶה שֶׁלָּכֶם. קָרְבָּן לַה', שֶׁיַּקְרִיב הַכֹּל לְהִתְאַחֵד כְּאֶחָד מַעְלָה וּמַטָּה. מִן הַבְּהֵמָה, לְהַרְאוֹת אָדָם וּבְהֵמָה, וְהַכֹּל כְּאֶחָד.</p>\n<p>מִן הַבָּקָר וּמִן הַצֹּאן, אֵלּוּ הַמֶּרְכָּבוֹת שֶׁהֵן טְהוֹרוֹת. כֵּיוָן שֶׁאָמַר מִן הַבְּהֵמָה, יָכוֹל מֵהַכֹּל, בֵּין טְהוֹרִים בֵּין טְמֵאִים? חָזַר וְאָמַר, מִן הַבָּקָר וּמִן הַצֹּאן וְגוֹ'.</p>\n<p>קָרְבַּנְכֶם?! קָרְבָּנִי הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה קָרְבַּנְכֶם? אֶלָּא בָּרִאשׁוֹנָה קָרְבָּן לַה', וְעַכְשָׁו קָרְבַּנְכֶם, קָרְבָּן לַה' אָדָם, קָרְבַּנְכֶם מִן הַבָּקָר וּמִן הַצֹאן, לְהַרְאוֹת יִחוּד מִמַּעְלָה לְמַטָּה. מִמַּטָּה לְמַעְלָה הַיְנוּ קָרְבָּן לַה'. מִמַּעְלָה לְמַטָּה הַיְנוּ קָרְבַּנְכֶם.</p>\n<p>מָשָׁל לְמֶלֶךְ שֶׁהוּא יוֹשֵׁב בְּגַג עֶלְיוֹן לְמַעְלָה, וְכִסְאוֹ מְתֻקָּן עַל אוֹתוֹ הַגַּג, וְהַמֶּלֶךְ הָעֶלְיוֹן עַל הַכֹּל. אָדָם שֶׁמַּקְרִיב קָרְבָּן (דורון) לַמֶּלֶךְ, צָרִיךְ לַעֲלוֹת מִדַּרְגָּה לְדַרְגָּה, עַד שֶׁעוֹלֶה מִמַּטָּה לְמַעְלָה, לְמָקוֹם שֶׁהַמֶּלֶךְ יוֹשֵׁב עֶלְיוֹן עַל הַכֹּל, וְאָז יוֹדְעִים שֶׁהֲרֵי מַעֲלִים דּוֹרוֹן לַמֶּלֶךְ, וְאוֹתוֹ דוֹרוֹן (של המלך) מִן הַמֶּלֶךְ הוּא. יוֹרֵד דּוֹרוֹן מִמַּעְלָה לְמַטָּה, הֲרֵי יוֹדְעִים שֶׁאוֹתוֹ דוֹרוֹן יוֹרֵד מִלְמַעְלָה לַאֲהוּב הַמֶּלֶךְ שֶׁהוּא לְמַטָּה.</p>\n<p>כָּךְ בַּתְּחִלָּה אָדָם, עוֹלֶה בְדַרְגוֹתָיו מִמַּטָּה לְמַעְלָה, וְזֶה קָרְבָּן לַה' מִן הַבְּהֵמָה מִן הַבָּקָר. יוֹרֵד בְּדַרְגוֹתָיו מִמַּעְלָה לְמַטָּה, וְאָז קָרְבַּנְכֶם. מִשּׁוּם כָּךְ, (שיר השירים ה) אָכַלְתִּי יַעְרִי עִם דִּבְשִׁי וְגוֹ'. הַיְנוּ אָדָם קָרְבָּן לַה', אִכְלוּ רֵעִים, הַיְנוּ מִן הַבְּהֵמָה וּמִן הַצּאן, וְאָז תַּקְרִיבוּ אֶת קָרְבַּנְכֶם.</p>\n<p>בָּאוּ רַבִּי יְהוּדָה וְרַבִּי יִצְחָק וּנְשָׁקוּהוּ. אָמְרוּ, בָּרוּךְ הָרַחֲמָן שֶׁזָּכִינוּ לִשְׁמֹעַ אֶת זֶה. אָמַר רַבִּי יְהוּדָה, נָאֶה הוּא לְאוֹתוֹ תִינוֹק שֶׁלֹּא יָדַע אֶת כָּל זֶה, וַאֲנִי פּוֹחֵד עָלָיו אִם יִתְקַיֵּם בָּעוֹלָם בִּגְלַל זֶה. אָמַר רַבִּי יִצְחָק, וְלָמָּה? אָמַר לוֹ, שֶׁהֲרֵי יָכוֹל לְהִסְתַּכֵּל בְּמָקוֹם שֶׁאֵין רְשׁוּת לְאָדָם לְהִסְתַּכֵּל בּוֹ, וַאֲנִי פּוֹחֵד עָלָיו, שֶׁטֶּרֶם יַגִּיעַ לְפִרְקוֹ יִתְבּוֹנֵן וְיַשְׁגִּיחַ וְיַעֲנִישׁוּ אוֹתוֹ.</p>\n<p>שָׁמַע אוֹתוֹ הַתִּינוֹק, אָמַר, אֵינִי פּוֹחֵד מֵעֹנֶשׁ לְעוֹלָמִים, שֶׁהֲרֵי בְּשָׁעָה שֶׁהִסְתַּלֵּק אָבִי מִן הָעוֹלָם, בֵּרַךְ אוֹתִי וְהִתְפַּלֵּל עָלַי, וְיוֹדֵעַ אֲנִי שֶׁזְּכוּת אָבִי תָּגֵן עָלַי. אָמְרוּ לוֹ, מִי הוּא אָבִיךְ? אָמַר, בְּנוֹ שֶׁל רַב הַמְנוּנָא סָבָא. לָקְחוּ אוֹתוֹ וְהִרְכִּיבוּ אוֹתוֹ עַל כִּתְפֵיהֶם שְׁלֹשָׁה מִילִין. הָלְכוּ וְסִדְּרוּ אֶת הַדְּבָרִים לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר לָהֶם, וַדַּאי יְרֻשַּׁת הַתּוֹרָה הוּא יָרַשׁ, וְאִלְמָלֵא זְכוּת אָבִיו, הָיָה נֶעֱנָשׁ מִלְּמַעְלָה, אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא, לְאוֹתָם שֶׁהוֹלְכִים אַחַר הַתּוֹרָה, מוֹרִישׁ אוֹתָהּ לָהֶם וְלִבְנֵיהֶם לְעוֹלָמִים. (ע\"כ מההשמטות).</p>"],[9522012734,"<p>שָׁמוֹר אֶת יוֹם הַשַּׁבָּת, הַהוּא בְּמִדָּה שְׁבִיעִית נֶאֱמַר, שֶׁכָּתוּב אֶת שַׁבְּתֹתַי תִּשְׁמֹרוּ וּמִקְדָּשִׁי תִירָאוּ. מַה זּוֹ מִדָּה שְׁבִיעִית? הֱוֵה אוֹמֵר, זוֹ מִדַּת טוּבוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמָה הַטַּעַם אָמַר שַׁבְּתֹתַי וְלֹא אָמַר שַׁבַּתִּי? מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְמֶלֶךְ שֶׁהָיְתָה לוֹ אִשָּׁה נָאָה, וְכָל שָׁבוּעַ וְשָׁבוּעַ מַזְמִינָהּ יוֹם אֶחָד לִהְיוֹת עִמּוֹ, וְהַמֶּלֶךְ יֵשׁ לוֹ בָּנִים נָאִים וְאוֹהֲבָם, וְאָמַר לָהֶם: הוֹאִיל וְכֵן הוּא, שִׂמְחוּ גַּם אַתֶּם בְּיוֹם שִׂמְחָתִי, כִּי אֲנִי בְּשֶׁלָּכֶם אֲנִי מִשְׁתַּדֵּל, וְגַם אַתֶּם הַדְּרוּ אוֹתִי. וּמָה הַטַּעַם זָכוֹר וְשָׁמוֹר? זָכוֹר לַזָּכָר, וְשָׁמוֹר לַכַּלָּה. וּמָה הַטַּעַם וּמִקְדָּשִׁי תִירָאוּ? שִׁמְרוּ עַצְמְכֶם מִן הַהִרְהוּר, כִּי מִקְדָּשִׁי קָדוֹשׁ הוּא, לָמָּה? כִּי אֲנִי ה' בְּכָל צַד: (ע\"כ מההשמטות).</p>"],[9522012735,"<p>אָמַר רַבִּי רְחוּמַאי, מַהוּ שֶׁכָּתוּב וַיִּשָּׂא אַהֲרֹן אֶת יָדָו אֶל הָעָם וַיְבָרֲכֵם וַיֵּרֶד, וַהֲרֵיִ כְּבָר יָרַד? אֶלָּא וַיֵּרֶד מֵעֲשֹׂת הַחַטָּאת וְהָעֹלָה, וְאַחַר כָּךְ וַיִּשָּׂא אַהֲרֹן אֶת יָדָו אֶל הָעָם! נְשִׂיאוּת זוֹ לָמָּה? לְפִי שֶׁהִקְרִיב קָרְבָּן וְנִתְרַצָּה לִפְנֵי אֲבִיהֶם שֶׁבַּשָּׁמַיִם. כְּמוֹ שֶׁאָמַר, צָרִיךְ אוֹתוֹ שֶׁמְּקָרְבָם לָעֶלְיוֹנִים וּמְיַחֲדָם, לְיַחֵד בִּכְלָלָם אֵלּוּ. וּמַהוּ אֶל הָעָם? בַּעֲבוּר הָעָם. וּמָה הַטַּעַם בִּנְשִׂיאוּת לְבָרֵךְ אוֹתָם בִּבְרָכָה? אֶלָּא מִשּׁוּם שֶׁיֵּשׁ בָּאָדָם עֶשֶׂר אֶצְבָּעוֹת, רֶמֶז לְעֶשֶׂר סְפִירוֹת שֶׁנֶּחְתְּמוּ בָהֶן שָׁמַיִם וָאָרֶץ: (ע\"כ מההשמטות).</p>"],[9522012736,"<p>פָּתַח רַבִּי נְהוֹרַאי בְּפָרָשַׁת צִיצִית וְדָרַשׁ, וְעָשׂוּ לָהֶם צִיצִת וְגוֹ'. כָּאן כָּתוּב לְדרֹתָם, וְגַבֵּי שַׁבָּת לְדרֹתָם, שֶׁכָּתוּב לַעֲשׂוֹת אֶת הַשַּׁבָּת לְדרֹתָם, (חסר). שֶׁשָּׁנִינוּ, תִּקְּנוּ פָּרָשַׁת צִיצִית בִּקְרִיַּת שְׁמַע, וּבְדִירָתוֹ שֶׁל אָדָם נִמְצָא קְרִיַּת שְׁמַע, חוּץ מִפָּרָשַׁת צִיצִית שֶׁחֲסֵרָה מִשָּׁם. בַּמֶּה נִשְׁלָם? אֶלָּא כְּשֶׁהָאָדָם מִתְעַטֵּף בְּצִיצִית וְיוֹצֵא בּוֹ לְפֶתַח דִּירָתוֹ שָׁלֶם. וְהַקָּדוֹשׁ בָּרוּךָ הוּא שָׂמֵחַ, וּמַלְאָךְ הַמַּוֶת זָז מִשָּׁם, וְנִצּוֹל הָאָדָם מִכָּל נֵזֶק וּמִכָּל מַשְׁחִית. וְהַיְנוּ לְדרֹתָם, בִּשְׁבִיל דִּירָתָם. שֶׁהָיָה שָׁם שָׁלֵם וְיָצָא מִפֶּתַח בֵּיתוֹ בְּמִצְות, מַלְאָךְ הַמַּשְׁחִית זָז מִשָּׁם, וְנִצּוֹל הָאָדָם מִכָּל נֵזֶק וּמִכָּל מַשְׁחִית. מִנַּיִן לָנוּ? מִמַּה שֶּׁכָּתוּב מְזֻזוֹת. מֵהָאוֹתִיּוֹת מַשְׁמָע - זָ\"ז מָוֶ\"ת, שֶׁלֹּא נִתָּן רְשׁוּת לַמַּשְׁחִית לְחַבֵּל וְזָז מִפִּתְח וֹ.</p>\n<p>בְּשַׁבָּת שֶׁכָּתוּב לְדרֹתָם, מָה הַטַּעַם? כֵּיוָן שֶׁקָּדַשׁ הַיּוֹם, דִּירָתָם שֶׁל יִשְׂרָאֵל צְרִיכָה לִהְיוֹת בְּנֵר דּוֹלֵק וְשֻׁלְחָן עָרוּךְ וּמִטָּה מֻצַּעַת, וְדִירָתוֹ מְתֻקֶּנֶת כְּדִירַת חָתָן לְקַבֵּל בּוֹ הַכַּלָּה. וּמִי הִיא? הַשַּׁבָּת הִיא כַּלָּה, וּלְעוֹלָם אֵין מַכְנִיסִין אוֹתָהּ אֶלָּא בְּדִירָה מְתֻקֶּנֶת לִכְבוֹדָהּ כְּפִי הָרָאוּי לָהּ, וְעַל זֶה כָּתוּב לַעֲשׂוֹת אֶת הַשַּׁבָּת. וְכָתוּב לְדרֹתָם? לְהַכְנִיס בָּהּ כַּלָּה קְדוֹשָׁה לְדִירָתָהּ וְלִהְיוֹת בְּתוֹכָהּ. בְּשָׁעָה שֶׁקָּדַשׁ הַיּוֹם, וְאִם כַּלָּה זוֹ בָּאָה וְאֵינָהּ מוֹצְאָה דִירָה מְתֻקֶּנֶת וְשֻׁלְחָן עָרוּךְ וְנֵר דּוֹלֵק - כַּלָּה זוֹ אוֹמֶרֶת: אֵין דִּירָה זוֹ מִיִּשְׂרָאֵל. כָּתוּב בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל. אֵין זֶה מִיִּשְׂרָאֵל, אֵין דִּירָתוֹ לִקְדֻשָּׁה. וְעַל כֵּן צָרִיךְ כָּאן קְדֻשָּׁה לְדִירַת יִשְׂרָאֵל, וְעַל זֶה כָּתוּב לְדרֹתָם - בְּשַׁבָּת וּבְצִיצִית.</p>\n<p>אָמַר רַבִּי נְהוֹרַאי, מֵעִיד אֲנִי עָלַי, מִי שֶׁיּוֹצֵא מִשַּׁעַר בֵּיתוֹ בְּעִטּוּף שֶׁל מִצְוָה וּתְפִלִּין בְּרֹאשׁוֹ, בְּשָׁעָה שֶׁיּוֹצֵא מִבֵּין שְׁנֵי שְׁעָרִים מִזְדַּמֶּנֶת עָלָיו הַשְּׁכִינָה, וּשְׁנֵי מַלְאָכִים שֶׁעוֹמְדִים עָלָיו, אֶחָד מִימִינוֹ וְאֶחָד מִשְּׂמֹאלוֹ, כֻּלָּם מְלַוִּים אוֹתוֹ עַד בֵּית הַכְּנֶסֶת וּמְבָרְכִים אוֹתוֹ. מְקַטְרֵג אֶחָד שֶׁעוֹמֵד לִפְנֵי הַפֶּתַח שֶׁל הָאָדָם הוֹלֵךְ אַחֲרֵיהֶם, וְעַל כָּרְחוֹ מֵשִׁיב וְאוֹמֵר אָמֵן: ע\"כ מההשמטות.</p>"],[9522012737,"<p>מָה הַטַּעַם אָנוּ מַטִּילִים תְּכֵלֶת בַּצִּיצִית, וּמָה הַטַּעַם שְׁלֹשׁים וּשְׁנַיִם? מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְמֶלֶךְ שֶׁהָיָה לוֹ גַּן נָאֶה וְלוֹ שְׁלֹשִׁים וּשְׁתַּיִם נְתִיבוֹת, וְשָׂם שׁוֹמֵר עֲלֵיהֶן, וְהוֹדִיעוֹ לְבַדּוֹ אוֹתָן הַנְּתִיבוֹת. אָמַר לוֹ: שָׁמְרֵם וְלֵךְ בָּהֶם בְּכָל יוֹם, וּבְכָל זְמַן שֶׁתַּדְרִיכֵם שָׁלוֹם לָךְ.</p>\n<p>מֶה עָשָׂה הַשּׁוֹמֵר? אָמַר: אִם אֲנִי אֶהְיֶה לְבַדִּי בְּאֵלֶּה הַנְּתִיבוֹת, אֵי אֶפְשָׁר לְשׁוֹמֵר אֶחָד לְקַיֵּם אֵלּוּ הַנְּתִיבוֹת, וְעוֹד, כִּי יֹאמְרוּ הָעוֹלָם, כִּילַי הוּא מֶלֶךְ זֶה וְשׁוֹמֵר זֶה. לְכָךְ שָׂם שׁוֹמֵר זֶה שׁוֹמְרִים אֲחֵרִים עַל הַנְּתִיבוֹת, אֵלֶּה הֵן שְׁלֹשִׁים וּשְׁתַּיִם נְתִיבוֹת.</p>\n<p>וּמָה הַטַּעַם שֶׁל הַתְּכֵלֶת? אָמַר הַשּׁוֹמֵר: שֶׁמָּא יֹאמְרוּ הַשּׁוֹמְרִים הַגָּן שֶׁלִּי הוּא. נָתַן לָהֶם סִימָן וְאָמַר: רְאוּ הַסִּימָן לַמֶּלֶךְ שֶׁהוּא שֶׁלּוֹ, שֶׁהַגָּן הַזֶּה וְאֵלֶּה הַנְּתִיבוֹת הוּא תִּקְּנָם, וְאֵינָם שֶׁלִּי, וְהִנֵּה חוֹתָמוֹ.</p>\n<p>מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְמֶלֶךְ וּבִתּוֹ שֶׁהָיוּ לָהֶם עֲבָדִים, בִּקְשׁוּ לֵילֵךְ מֵרָחוֹק - פָּחֲדוּ מִן אֵימַת הַמֶּלֶךְ, נָתַן לָהֶם הַמֶּלֶךְ סִימָנוֹ. פָּחֲדוּ מִן הַבַּת, וְנָתְנָה לָהֶם סִימָן. אָמְרוּ: מֵעַתָּה בִּשְׁנֵי סִימָנִים אֵלּוּ - (תהלים קכא) ה' יִשְׁמָרְךְ מִכָּל רָע, יִשְׁמֹר אֶת נַפְשֶׁךְ.</p>\n<p>וּמַה הִיא? אֶרֶץ שֶׁנֶּחְצְבָה מִמֶּנָּה שָׁמַיִם, וְהִיא כִּסְאוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהִיא אֶבֶן יְקָרָה, וְהִיא יָם הַחָכְמָה, וּכְנֶגְדָּהּ תְּכֵלֶת בְּטַלִּית צִיצִית. שֶׁאָמַר רַבִּי מֵאִיר, מַה נִּשְׁתַּנָּה (שאמר) תְּכֵלֶת מִכָּל מִינֵי צִבְעוֹנִין? מִפְּנֵי שֶׁתְּכֵלֶת דּוֹמֶה לַיָּם, וְהַיָּם דּוֹמֶה לָרָקִיעַ, וְהָרָקִיעַ דּוֹמֶה לְכִסֵּא הַכָּבוֹד, שֶׁנֶּאֱמַר (שמות כד) וַיִּרְאוּ אֵת אֱלֹהֵי יִשְׂרָאֵל וְתַחַת רַגְלָיו כְּמַעֲשֵׂה לִבְנַת הַסַּפִּיר וּכְעֶצֶם הַשָּׁמַיִם לָטֹהַר. וְכָתוּב (יחזקאל א) כְּמַרְאֵה אֶבֶן סַפִּיר דְּמוּת כִּסֵּא: ע\"כ מההשמטות.</p>"],[9522012738,"<p>שֶׁכָּתוּב תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה, נֶפֶשׁ שֶׁל אוֹתָהּ חַיָּה עֶלְיוֹנָה, וּמִשּׁוּם שֶׁהַנֶּפֶשׁ חַיָּה הַזּוֹ הִיא קְדוֹשָׁה עֶלְיוֹנָה, כְּשֶׁהָאָרֶץ הַקְּדוֹשָׁה מוֹשֶׁכֶת אוֹתָהּ לְתוֹכָהּ וְנִכְלֶלֶת בָּהּ, אֲזַי קוֹרְאִים לָהּ נְשָׁמָה. וּבֹא רְאֵה, בְּכָל זְמַן שֶׁאָדָם הוֹלֵךְ בְּדֶרֶךְ אֱמֶת, וּפִיו וּלְשׁוֹנוֹ מְדַבְּרִים דְּבָרִים קְדוֹשִׁים, בִּתְפִלָּה וּבְתוֹרָה, הַנְּשָׁמָה הַזּוֹ נִדְבֶּקֶת בּוֹ, הוּא אָהוּב שֶׁל רִבּוֹנוֹ, כַּמָּה שׁוֹמְרִים שּׁוֹמְרִים עָלָיו מִכָּל הַצְּדָדִים, רָשׁוּם הוּא לְטוֹב לְמַעְלָה וּלְמַטָּה, וְהַשְּׁכִינָה הַקְּדוֹשָׁה שׁוֹרָה עָלָיו. וְזוֹהִי שֶׁעוֹלָה לְמַעְלָה וּמְדַבֶּרֶת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, וְנִכְנֶסֶת לְכָל הַשְּׁעָרִים, וְאֵין מִי שֶׁיִּמְחֶה בְיָדָהּ. וְעַל זֶה נִקְרֵאת רוּחַ מְדַבֶּרֶת, שֶׁהֲרֵי לְכָל שְׁאָר הַנְּפָשׁוֹת (נפשותינו) אֵין רְשׁוּת לְדַבֵּר לִפְנֵי הַמֶּלֶךְ פְּרָט לָזוֹ.</p>\n<p>וּבִזְמַן שֶׁהוּא מַסְטֶה אֶת דְּרָכָיו, וְשִׂפְתוֹתָיו וּלְשׁוֹנוֹ מְדַבְּרִים דִּבּוּרִים רָעִים, הַשְּׁכִינָה מִסְתַּלֶּקֶת מִמֶּנּוּ, וְהַנְּשָׁמָה הַקְּדוֹשָׁה עוֹבֶרֶת מִמֶּנּוּ וְלֹא נִדְבֶּקֶת בּוֹ. וּמִצַּד שֶׁל הַנָּחָשׁ הָרָע הַקָּשֶׁה מִתְעוֹרֶרֶת רוּחַ אַחַת שֶׁמְּשׁוֹטֶטֶת וְאוֹכֶלֶת בָּעוֹלָם, שֶׁאֵין שׁוֹרָה אֶלָּא בְּמָקוֹם שֶׁקְּדֻשָּׁה עֶלְיוֹנָה הִסְתַּלְּקָה מִשָּׁם.</p>\n<p>וְאוֹתָם דִּבּוּרִים עוֹלִים לִמְקוֹם הַנָּחָשׁ הָרָע, שֶׁהַכֹּל חוֹזֵר לִמְקוֹמוֹ. וּבְשָׁעָה שֶׁמַּעֲלִים, הַכֹּל מַכְרִיזִים וְאוֹמְרִים: הִסְתַּלְּקוּ מִסְּבִיבוֹ שֶׁל הַדִּבּוּר הָרָע שֶׁל פְּלוֹנִי! פַּנּוּ מָקוֹם לְדַרְכּוֹ שֶׁל הַנָּחָשׁ הַקָּשֶׁה! וְאוֹתָהּ נְשָׁמָה עוֹלָה בְּבוּשָׁה וּבְצָרַת הַכֹּל, וְלֹא נוֹתְנִים לָהּ מָקוֹם לְדַבֵּר כְּמִקֹּדֶם, וְאָז מִזְדַּמֵּן הַנָּחָשׁ.</p>\n<p>וּכְשֶׁאוֹתוֹ הַדִּבּוּר הָרָע עוֹלֶה בִּדְרָכִים יְדוּעוֹת וְשׁוֹרֶה לִפְנֵי הַנָּחָשׁ הַקָּשֶׁה, כַּמָּה רוּחוֹת מִתְעוֹרְרוֹת בָּעוֹלָם, וְרוּחַ יוֹרֶדֶת מֵאוֹתוֹ הַצַּד, וּמוֹצֵאת שֶׁאוֹתוֹ אָדָם עוֹרֵר אוֹתָהּ בְּדִבּוּר רָע, וַהֲרֵי הָרוּחַ הַמְדַבֶּרֶת הַקְּדוֹשָׁה עָבְרָה מִמֶּנּוּ, אָז שׁוֹרָה עָלָיו וּמְטַמֵּאת אוֹתוֹ, וְאָז הוּא סָגוּר, וְנִפְגָּם בְּשָׂרוֹ בְּמַרְאֵה פָנָיו בַּכֹּל,</p>\n<p>וְעַל זֶה כָּתוּב שֹׁמֵר פִּיו וּלְשׁוֹנוֹ שֹׁמֵר מִצָּרוֹת נַפְשׁוֹ, נַפְשׁוֹ וַדַּאי. אוֹתָהּ שֶׁהָיְתָה מְדַבֶּרֶת, נֶעֶשְׂתָה מְשֻׁתֶּקֶת מִשּׁוּם דִּבּוּר רָע. וּכְמוֹ שֶׁעָנְשׁוֹ שֶׁל אָדָם בָּזֶה מִשּׁוּם אוֹתוֹ דִבּוּר רָע, כָּךְ עָנְשׁוֹ בִּגְלַל דִּבּוּר טוֹב (שבא לידו שיכל לדבר ולא דבר). ע\"כ מההשמטות.</p>"],[9522012739,"<p>וְכִי בְכָל עֵת יָכוֹל אָדָם לַעֲשׂוֹת צְדָקָה? אִם כֵּן, שְׁתֵּים עֶשְׂרֵה שָׁעוֹת בְּיוֹם מִי יָכוֹל?! אֶלָּא כָּךְ לָמַדְנוּ, מִי שֶׁעוֹשֶׂה צְדָקָה בְּכָל עֵת. מַהוּ בְּכָל עֵת? כְּמוֹ שֶׁנֶּאֱמַר (ויקרא טז) וְאַל יָבא בְכָל עֵת אֶל הַקֹּדֶשׁ, וּבֵאֲרוּהָ.</p>\n<p>וְלֹא תֹאמַר בִּכְנֶסֶת יִשְׂרָאֵל לְבַדָּהּ, שֶׁהִיא עֵת רָצוֹן קָדוֹשׁ בְּצַדִּיק, אֶלָּא אֲפִלּוּ בְכָל עֵת שֶׁלְּמַטָּה מַרְבֶּה צְדָקָה עֲלֵיהֶם, וּמִתְעוֹרֶרֶת צְדָקָה בְּכֻלָּם, בְּעֶלְיוֹנִים וְתַחְתּוֹנִים. מִפְּנֵי כֵן יָשִׂים אָדָם לִבּוֹ וּרְצוֹנוֹ וְיִדְבַּק בּוֹ בַּקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>כֵּיוָן שֶׁהִגִּיעוּ לִפְנֵי רַבִּי שִׁמְעוֹן, סִפְּרוּ לוֹ הַמַּעֲשֶׂה. אָמַר, וּמַה זֶּה בְּעַצְמוֹ, אֲפִלּוּ כָּל מִי שֶׁמַּחֲזִיק לְאִילַן (באילן) הַחַיִּים נִצּוֹל בָּעוֹלָם הַזֶּה, וַאֲפִלּוּ מִן מִיתַת הָעוֹלָם מִשְּׁאָר בְּנֵי אָדָם, כָּל שֶׁכֵּן מֵאַחֵר.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, בְּכֻלָּם מְעוֹרֶרֶת הַצְדָקָה אֶת אִילַן הַחַיִּים, וּמָקוֹם זֶה הוּא הַמָּזוֹן לַכֹּל, וּלְתַלְמִידֵי הַחֲכָמִים מַה מַּעֲשֵׂיהֶם? שֶׁהֲרֵי כָּל בְּנֵי הָעוֹלָם לֹא יְכוֹלִים לְעוֹרֵר צְדָקָה עֲלֵיהֶם, שֶׁהֲרֵי הֵם אֲחוּזִים בִּצְדָקָה, וְכָל בְּנֵי הָעוֹלָם נִזּוֹנִים בִּזְכוּתָם, בָּהֶם מַמָּשׁ. וְהֵם לֹא יְכוֹלִים לְהִתְפַּרְנֵס מֵהֶם מַמָּשׁ, מִפְּנֵי שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, מִשְׁתַּדֵּל בְּאִילַן הַחַיִּים שֶׁכָּל בְּנֵי הָעוֹלָם מִתְפַּרְנְסִים מִמֶּנּוּ. נִמְצָא שֶׁהַתַּלְמִידֵי חֲכָמִים מְעוֹרְרִים מָזוֹן לָעוֹלָם וְשָׁלוֹם.</p>\n<p>אִם לְכָל בְּנֵי הָעוֹלָם מִתְעוֹרֵר מָזוֹן, מַדּוּעַ לָהֶם לֹא מִתְעוֹרֵר? אֶלָּא תַּלְמִיד חָכָם הוּא אִילַן הַחַיִּים מַמָּשׁ, וְאִילַן הַחַיִּים לֹא נִזּוֹן אֶלָּא מִן הָעוֹלָם הַבָּא, וְהָעוֹלָם הַבָּא לֹא נִמְצָא בָּעוֹלָם הַזֶּה, אֶלָּא לְאַחַר שֶׁעוֹלֶה לָעוֹלָם הַהוּא, אָז נִזּוֹן מִמֶּנּוּ וְנִשְׁרָשׁ שָׁרָשָׁיו עָלָיו.</p>\n<p>עַכְשָׁו אוֹכְלִים מִפְּרִי עֵץ הַחַיִּים. וּמַה הוּא? אוֹתוֹ מָקוֹם שֶׁנִּמְצָא אֵצֶל הָעֲנִיִּים, וְהוּא נִקְרָא (בראשית ג) פְּרִי הָעֵץ אֲשֶׁר בְּתוֹךְ הַגָּן. וְעַל זֶה אוֹכְלִים מֵהַפְּרִי הוּא בָּעוֹלָם הַזֶּה.</p>\n<p>וְעַל זֶה לָמַדְנוּ, הֵם נִזּוֹנִים בִּזְרוֹעַ. מַהִי הַזְּרוֹעַ? זוֹ גְבוּרָה. וְהֵם מְזֻמָּנִים לָעוֹלָם הַבָּא. שֶׁמְּזוֹן הָעוֹלָם הַבָּא אֵינוֹ בָּעוֹלָם הַזֶּה, אֶלָּא צִמְצוּם קָטָן שֶׁל הַכֹּחַ שֶׁלּוֹ שֶׁנִּמְצָא בִּמְתִיקוּת הַתּוֹרָה. וְזֶה טַעֲמוֹ עַל הַפְּרִי הַהוּא שֶׁל הָעֵץ הַתַּחְתּוֹן, וְזוֹ שִׂמְחָה שֶׁל הַתַּלְמִידֵי חֲכָמִים וּמָזוֹן הָעֶלְיוֹן שֶׁלָּהֶם.</p>\n<p>כֵּיוָן שֶׁיַּעַבְרוּ מֵהָעוֹלָם הַזֶּה, כַּמָּה נְחָלִים עֶלְיוֹנִים שֶׁל עוֹלָם הַבָּא מַקִּיפִים לִמְקוֹמָם, וְיִשְׁתָּרְשׁוּ בוֹ וְיַעֲלוּ לְמַעְלָה לְמַעְלָה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה סד) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ יַעֲשֶׂה לִמְחַכֵּה לוֹ. מַהוּ יַעֲשֶׂה? זֶה הַיּוֹבֵל, זֶה שֶׁנִּקְרָא עוֹלָם הַבָּא. לִמְחַכֵּה לוֹ, וַדַּאי. שֶׁלֹּא רוֹצִים מָזוֹן לָעוֹלָם הַזֶּה עַד שֶׁיַּגִּיעוּ (שיתקן) לַמָּזוֹן שֶׁלָּהֶם. וּמַהוּ הַמָּזוֹן שֶׁלָּהֶם? הָעוֹלָם הַבָּא. וְעַל זֶה זַכָּאִים בַּכֹּל, שֶׁעֲלֵיהֶם כָּתוּב עַיִן לֹא רָאָתָה אֱלֹהִים וְגוֹ': (עד כאן מההשמטות). שִׁבְעָה יָמִים עֶלְיוֹנִים בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָם, וַעֲלֵיהֶם שָׁתַל וּבָנָה עוֹלָמוֹת. זֶהוּ שֶׁכָּתוּב כִּי שֵׁשֶׁת יָמִים עָשָׂה ה', וְלֹא כָתוּב בְּשֵׁשֶׁת.</p>"],[9522012740,"<p>וּכְנֶגֶד אוֹתָם שִׁבְעָה יָמִים עֶלְיוֹנִים בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאָרֶץ שִׁבְעָה צַדִּיקֵי אֱמֶת, לְהַעֲמִידָם וּלְהָאִיר לָהֶם כָּל אֶחָד וְאֶחָד כְּנֶגֶד יוֹמוֹ, וְשָׁתַל אוֹתָם כָּל אֶחָד וְאֶחָד בְּדוֹר שֶׁרָאוּי, וְהֵם אֲבוֹת הָעוֹלָם, אַבְרָהָם יִצְחָק וְיַעֲקֹב יוֹסֵף מֹשֶׁה אַהֲרֹן דָּוִד.</p>\n<p>וְהֵם נִקְרָאִים הָרִים, הַרְרֵי קֶדֶם, שֶׁהֵם תְּלוּיִים מֵאוֹתָם שִׁבְעָה יָמִים עֶלְיוֹנִים, וְהַשְּׁבִיעִי שֶׁעוֹמֵד לִפְנֵיהֶם, זֶהוּ שֶׁכָּתוּב (זכריהיב) וּבֵית דָּוִיד כֵּאלֹהִים כְּמַלְאַךְ ה' לִפְנֵיהֶם. וְאַף עַל גַּב שֶׁהוּא שְׁבִיעִי, ..., כְּשֶׁנִּכְלָל בּוֹ בְּיוֹסֵף וְנוֹתֵן לוֹ תַּפְנוּק מִבֵּית הַמֶּלֶךְ, נִקְרָא גַּם הוּא שְׁבִיעִי.</p>\n<p>וְכֻלָּם אֲחוּזִים בַּשְּׁכִינָה בְּסוֹד שֶׁל שִׁבְעָה, מִשּׁוּם שֶׁהַשְּׁכִינָה נִקְרֵאת בַּת שֶׁבַע, בַּת מֵאֵם הָעֶלְיוֹנָה, שֶׁהִיא כְּלַל שֶׁבַע דְּרָגוֹת שֶׁעִמּוֹ, וְהִיא דַּרְגָּה שֶׁל צֶדֶק הָעֲשִׂירִי, שֶׁהֵן סְפִירוֹת שֶׁנִּקְרָא בָהֶן הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>וְנִקְרָא שְׁבִיעִי בַּכָּתוּב, שֶׁכָּתוּב (דברי הימים א כט) לְךְ ה' הַגְּדֻלָּ\"ה וְהַגְּבוּרָ\"ה וְהַתִּפְאֶרֶ\"ת וְהַנֵּצַ\"ח וְהַהוֹ\"ד כִּי כֹל וְכוּ', עַד הַמַּמְלָכָה. וּמָה הַטַּעַם? וַהֲרֵי הִיא רְבִיעִית לַיָּמִים! אֶלָּא בִּגְלַל נְטִיעָה אַחֲרוֹנָה וְנִכְלֶלֶת בַּשְּׁבִיעִית, מִשּׁוּם כָּךְ לָקְחָה שְׁמוֹ, וְהַכֹּל אֶחָד.</p>\n<p>וְכָל אֶחָד וְאֶחָד מֵהָאָבוֹת יָדַע אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא מִתּוֹךְ דַּרְגָּתוֹ וְאָחַז בּוֹ בְּאוֹתָהּ דַּרְגָּה. אַבְרָהָם יָדַע אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא מִתּוֹךְ אַסְפַּקְלַרְיָה שֶׁלּוֹ, שֶׁהִיא מִדַּת הַגְּדֻלָּה, מִדַּת הַחֶסֶד, שֶׁהִיא יְמִין הַמֶּלֶךְ, וְעַל כָּךְ הוּא אָחַז בָּהּ וְלֹא עָזַב אוֹתָהּ לְעוֹלָמִים, וְעָשָׂה טוֹב עִם כָּל בְּנֵי הָעוֹלָם, וּפֵרְשׁוּהָ שֶׁהֲרֵי מַעֲשָׂיו הֶעֱלוּהוּ לַדַּרְגָּה הַזֹּאת.</p>\n<p>יִצְחָק יָדַע אוֹתוֹ בְּדַרְגַּת הַגְּבוּרָה, שֶׁנִּקְרֵאת פַּחַד יִצְחָק, וּפָחַד מִמֶּנּוּ לְעוֹלָמִים. יַעֲקֹב יָדַע אוֹתוֹ מִתּוֹךְ דַּרְגַּת הַתִּפְאֶרֶת, שֶׁהוּא כָּלוּל מֵחֶסֶד וּמִפַּחַד, וְנִקְרָא אֱמֶת, וְאָחַז אוֹתָהּ, זֶהוּ שֶׁכָּתוּב תִּתֵּן אֱמֶת לְיַעֲקֹב.</p>\n<p>יוֹסֵף יָדַע אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא מִתּוֹךְ אוֹתָהּ אַסְפַּקְלַרְיָה שֶׁנִּקְרֵאת כֹּל, וְנִקְרָא יְסוֹד, וְעַל זֶה נִקְרָא יוֹסֵף כַּלְכֹּ\"ל, שֶׁכָּתוּב וַיְכַלְכֵּל יוֹסֵף, וְכָתוּב וְנִקְרָא יְסוֹד עוֹלָם.</p>\n<p>מֹשֶׁה וְאַהֲרֹן הֵם שְׁנֵי כְרוּבִים שֶׁנִּשְׁמַע קוֹל שֶׁל מַעְלָה מִבֵּינֵיהֶם, וְעַל זֶה נִתְּנָה תוֹרָה עַל יָדָם, זֶהוּ שֶׁכָּתוּב וְנוֹעַדְתִּי לְךְ שָׁם וְדִבַּרְתִּי אִתְּךְ, וְהֵם שְׁנֵי כְרוּבִים שֶׁלְּמַעְלָה, וְהֵם נֵצַ\"ח וְהוֹ\"ד, וְהֵם שְׁנֵי הָעַמּוּדִים שֶׁל הַגּוּף.</p>\n<p>כְּמוֹ זֶה יֵשׁ לַמַּלְכָּה לְמַטָּה שְׁנֵי כְרוּבִים תַּחְתֶּיהָ שֶׁיּוֹנְקִים מִמֶּנָּה, וְהֵם וַדַּאי עֶלְיוֹנִים, עַל אֲרוֹן הָעֵדֻת, שֶׁנִּקְרָא צֶדֶק, אֲרוֹן הָעֵדוּת. וּמִי עֵדוּת? זֶה יוֹסֵף, זֶהוּ שֶׁכָּתוּב עֵדוּת בִּיהוֹסֵף שָׂמוֹ, וְנִקְרָא תּוֹרָה שֶׁבִּכְתָב, וְאָרוֹן זֶה תּוֹרָה שֶׁבְּעַל פֶּה.</p>\n<p>בֹּא רְאֵה, כָּל אוֹתָם אָבוֹת עֶלְיוֹנִים שֶׁאֲחוּזִים לְמַעְלָה, כֻּלָּם רְמוּזִים בַּתּוֹרָה שֶׁבִּכְתָב. וְדָוִד שֶׁאָחוּז בָּאַחֲרוֹנָה, שֶׁהִיא תּוֹרָה שֶׁבְּעַל פֶּה, רְמוּזָה בְּדִבְרֵי קַבָּלָה, וּמִשּׁוּם כָּךְ נִקְרֵאת קַבָּלָה, שֶׁמְּקַבֶּלֶת אוֹר מִתּוֹרָה שֶׁבִּכְתָב.</p>\n<p>וְאוֹתָם שְׁנֵי כְרוּבִים עֶלְיוֹנִים עוֹמְדִים עַל אוֹתוֹ עֵדוּת וְאָרוֹן, זֶהוּ שֶׁכָּתוּב וְהַנֵּצַח וְהַהוֹד כִּי כֹל בַּשָּׁמַיִם וּבָאָרֶץ. וְזֶהוּ סִיּוּם הַשָּׁמַיִם, וּמְזַוֵּג אֶת הָאָרֶץ הַזּוֹ.</p>\n<p>וְכָךָ הוּא, שֶׁכָּל מַה שֶּׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה - בָּרָא כְּנֶגְדּוֹ לְמַטָּה. וְיוֹסֵף נִקְרָא עֵדוּת, זֶהוּ שֶׁכָּתוּב עֵדוּת בִּיהוֹסֵף שָׂמוֹ, וְעַל זֶה שְׁמוֹ שֶׁל יוֹסֵף שָׁלֵם בַּכֹּל, לְמַעְלָה וּלְמַטָּה.</p>\n<p>וְעַל זֶה שָׁנִינוּ שֶׁיּוֹסֵף וְהָאָרוֹן וְהַשְּׁכִינָה הָיוּ הוֹלְכִים בַּמִּדְבָּר בְּיַחַד, וְכָל הָעוֹלָם הָיוּ אוֹמְרִים: מַה טִּיבָן שֶׁל שְׁנֵי אֲרוֹנוֹת הַלָּלוּ? וּמְשִׁיבִים לָהֶם: קִיֵּם זֶה מַה שֶּׁכָּתוּב בָּזֶה. קִיֵּם בְּוַדַּאי. זֶהוּ שֶׁכָּתוּב וְצַדִּיק יְסוֹד עוֹלָם, הוּא קִיּוּם הָעוֹלָם.</p>\n<p>בָּא דָוִד, שֶׁהוּא שְׁבִיעִי שֶׁל הָאָבוֹת, אָחַז בָּהּ בְּבַת שֶׁבַע הַזֹּאת, שֶׁהִיא מַמְלָכָה, וְלֹא עֲזָבָהּ לְעוֹלָמִים. זֶהוּ שֶׁכָּתוּב (יחזקאל לז) וְדָוִד עַבְדִּי נָשִׂיא לָהֶם לְעוֹלָם, וְכָתוּב (תהלים פט) כִּסְאוֹ כַשֶּׁמֶשׁ נֶגְדִּי. וְכָל זֶה לִמְּדַתְנוּ הַתּוֹרָה, שֶׁכֻּלָּם אֲחוּזִים בַּשְּׁכִינָה בְּסוֹד שֶׁל שֶׁבַע.</p>\n<p>בֹּא וּרְאֵה, אַבְרָהָם נֵר רִאשׁוֹן קָדוֹשׁ שֶׁל הָעוֹלָם, כְּשֶׁרָצָה לְהִתְקָרֵב לְדַרְגָּתוֹ, לֹא יָכֹל, עַד שֶׁעָלָה וְנוֹדַע בְּאוֹתָן שָׁלֹשׁ דְּרָגוֹת עֶלְיוֹנוֹת שֶׁעָלָיו, שֶׁהוּא חֵלֶק שֶׁלּוֹ.</p>\n<p>כֵּיוָן שֶׁעָלָה וְהִתְוַדַּע לוֹ לַקָּדוֹשׁ-בָּרוּךְ- הוּא מִתּוֹךְ אוֹתָן שָׁלֹשׁ דְּרָגוֹת, שֶׁעִם אוֹתָן שֶׁבַע, וְשָׁלֹשׁ דְּרָגוֹת, הֵן כֶּתֶר עֶלְיוֹן חָכְמָה בִּינָה, וְהֵן שְׁלֵמוּת עֶשֶׂר סְפִירוֹת שֶׁנִּקְרָא בָּהֶן הַקָּדוֹשׁ בָּרוּךְ הוּא. וְכֵיוָן שֶׁעָלָה אַחַר כָּךְ בְּאוֹתָן שָׁלֹשׁ, שֶׁהֵן עַתִּיק וְאַבָּא וְאִמָּא, שֶׁשּׁוֹפֵעַ מֵהֶן אוֹר לְמַטָּה, אָז אָחַז לְחֶלְקוֹ אוֹתָהּ דַּרְגָּה שֶׁתַּחַת אוֹתָן שָׁלֹשׁ, שֶׁנִּקְרָא חֶסֶד.</p>\n<p>שֶׁאֶת כֻּלָּן הוּא הִדְבִּיק מִתּוֹךְ אוֹתָהּ אַסְפַּקְלַרְיָה שֶׁשּׁוֹלֶטֶת בַּלַּיְלָה, שֶׁבָּהֶן וַדַּאי לֹא הָיָה אָדָם שֶׁיָּדַע כְּלוּם. וְעַל זֶה שָׁנִינוּ בֶּן שָׁלֹשׁ שָׁנִים הִכִּיר אַבְרָהָם אֶת בּוֹרְאוֹ, דַּוְקָא בֶּן שָׁלֹשׁ.</p>\n<p>וּבֹא רְאֵה סוֹד שֶׁל שָׁלֹשׁ שָׁנִים אֵלּוּ וְלֹא חָסֵר, מִשּׁוּם שֶׁשְּׁכִינָה נִקְרֵאת בַּת שֶׁבַע, וְלֹא יָכֹל לְהִתְקָרֵב אֵלֶיהָ עַד שֶׁעָלָה לְהִוָּדַע מִתּוֹכָהּ וְלִהְיוֹת מוּאָר וּלְהָאִיר לַכֹּל, מַה שֶּׁהוּא לְמַטָּה בְּאוֹתָן דְּרָגוֹת עֶלְיוֹנוֹת עִם אוֹתָן שֶׁבַע וְשָׁלֹשׁ, הֲרֵי עֶשֶׂר דְּרָגוֹת עֶלְיוֹנוֹת סוֹד שֶׁל שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>וְכֵיוָן שֶׁהָיָה נָאוֹר בְּאוֹתָן שָׁלֹשׁ, רָצָה לְהַעֲלוֹת בְּאוֹתָן שֶׁבַע בְּסוֹד הַכָּתוּב (בראשית כא) וַיַּצֵּב אַבְרָהָם אֶת שֶׁבַע כִּבְשׂת הַצֹאן. וְסוֹד זֶה רֶמֶז לַאֲבִימֶלֶךְ שֶׁלֹּא יִפָּרְעוּ מֵהֶם, עַד שֶׁיִּשְׁתַּלְּמוּ אוֹתָם שִׁבְעָה צַדִּיקֵי אֱמֶת בְּיִשְׂרָאֵל. כְּנֶגֶד אוֹתָן שֶׁבַע דְּרָגוֹת שֶׁלְּמַעְלָה.</p>\n<p>כֵּיוָן שֶׁהִשְׁתַּלְּמוּ, יִהְיֶה הָעוֹלָם הַתַּחְתּוֹן כְּמוֹ הָעוֹלָם הָעֶלְיוֹן בְּקִיּוּם שָׁלֵם, וְיָבֹא דָוִד, שֶׁהוּא שְׁבִיעִי, וִיעוֹרֵר אֶת אוֹתָהּ בַּת שֶׁבַע שֶׁלְּמַעְלָה, שֶׁהִיא נוֹקֶמֶת נִקְמוֹת יִשְׂרָאֵל, וְתִפְרַע מֵהֶם.</p>\n<p>זְהִוּ שֶׁכָּתוּב (שמואל ב ח) וַיְהִי אַחֲרֵי כֵן וַיַּךְ דָּוִד אֶת פְּלִשְׁתִּים וַיַּכְנִיעֵם וַיִּקַּח דָּוִד אֶת מֶתֶג הָאַמָּה מִיַּד פְּלִשְׁתִּים. מַה זֶּה וַיְהִי אַחֲרֵי כֵן? אַחַר שֶׁנִּשְׁתַּלְּמוּ יִשְׂרָאֵל וְהָיוּ כְּמוֹ לְמַעְלָה, אָז וַיַּךְ דָּוִד אֶת פְּלִשְׁתִּים וַיַּכְנִיעֵם. שֶׁהֲרֵי עַד עַכְשָׁו לֹא יָכְלוּ יִשְׂרָאֵל לִשְׁבֹּר אֶת כֹּחָם, שֶׁהֲרֵי הִתְעוֹרְרוּ הַחֲבֵרִים בְּאוֹתוֹ מֶתֶג הָאַמָּה, וּפֵרְשׁוּהָ.</p>\n<p>וּבֹא וּרְאֵה, זֶה שֶׁרָמַז לוֹ אַבְרָהָם בְּכִבְשׂוֹת הַצֹאן וְלֹא בְעִזִּים וְלֹא בְדָבָר אַחֵר, מִשּׁוּם שֶׁהֵם מִצַּד הַחֶסֶד, שֶׁמֵּאוֹתָם מְמֻנִּים שֶׁיּוֹנְקִים מִצַּד הַחֶסֶד יוֹנְקִים לְמַטָּה אוֹתָם כְּבָשִׂים שֶׁתַּחַת שִׁלְטוֹנָם, וְאַבְרָהָם אָחַז לְחֶלְקוֹ מִדַּת הַחֶסֶד, וְהַכֹּל בְּסוֹד הַחָכְמָה. וְעַל זֶה שָׁנִינוּ, מִי שֶׁשָּׁרוּי בְּתוֹךְ צֹאן לֹא מִסְתַּכֵּן לְעוֹלָמִים. וְאִם הוּא שָׁרוּי בְּתוֹךְ עִזִּים וְרוֹעֶה אוֹתָם, כַּמָּה שׁוֹמְרֵי הַחֻקִּים יוֹשְׁבִים כְּנֶגְדּוֹ לְהַסְטוֹתוֹ, בִּגְלַל שֶׁהֵם מִצַּד שֶׁל הַדִּין הַקָּשֶׁה.</p>\n<p>אֲבָל כְּשֶׁבָּא יִצְחָק לִכְרֹת אִתּוֹ בְּרִית, כָּרַת אִתּוֹ בְּשִׁבְעָה שֶׁנִּגְלָה מִתּוֹךְ אוֹתוֹ בְּאֵר, שֶׁכָּתוּב (בראשית כו) וַיִּקְרָא אֹתָהּ שִׁבְעָה. בֹּא וּרְאֵה, אַבְרָהָם קָרָא לְאוֹתָהּ בְּאֵר מַיִם נוֹבְעִים בְּאֵר שֶׁבַע, וְיִצְחָק קָרָא לָהּ שִׁבְעָה. מַה בֵּין זֶה לָזֶה? אֶלָּא מִשּׁוּם שֶׁיִּצְחָק אָחַז לְחֶלְקוֹ דַּרְגָּה שֶׁל פַּחַד, שֶׁהוּא דִּין, וְעַל זֶה הוֹסִיף בָּהּ ה'. וְה' בְּכָל מָקוֹם הִיא מִדַּת הַדִּין. וְסִימָנְךְ - (יחזקאל טז) הֵא דַּרְכֵּךְ בְּרֹאשׁ נָתַתִּי. זֶהוּ שֶׁכָּתוּב וַיִּקְרָא אֹתָהּ שִׁבְעָה. שֶׁלֹּא עָשָׂה בַּכְּבָשִׂים כְּמוֹ שֶׁעָשָׂה אָבִיו, וְהַכֹּל בְּסוֹד הַחָכְמָה, וְהוֹסִיף בָּהּ ה', לְהַרְאוֹת שֶׁהִיא חֶלְקוֹ.</p>\n<p>בֹּא וּרְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, בָּרָא אוֹתוֹ בְּדִין. כֵּיוָן שֶׁרָאָה שֶׁלֹּא מִתְקַיֵּם, שִׁתֵּף בּוֹ חֶסֶד, זֶהוּ שֶׁכָּתוּב (שם ב) בְּיוֹם עֲשׂוֹת ה' אֱלֹהִים, וּפֵרְשׁוּהָ בְּאַבְרָהָם הִתְקַיֵּם הָעוֹלָם. בִּגְלַל כָּךְ הַבְּאֵר הַזֹּאת בֵּית הָעוֹלָם עַל שְׁמָהּ נִקְרָא, זֶהוּ שֶׁכָּתוּב עַל כֵּן קָרָא שֵׁם הָעִיר בְּאֵר שָׁבַע. אַף עַל גַּב שֶׁהַבְּאֵר הַזּוֹ נִדְבְּקָה בְיִצְחָק, שֶׁכָּתוּב וַיִּקְרָא אֹתָהּ שִׁבְעָה - שְׁמָהּ בְּאֵר שֶׁבַע צַד שֶׁל אַבְרָהָם, וְלֹא בְּאֵר שִׁבְעָה, זֶהוּ שֶׁכָּתוּב (שיר השירים ב) וִימִינוֹ תְּחַבְּקֵנִי.</p>\n<p>וּבֹא וּרְאֵה, אַרְבָּעָה מֵאוֹתָם שִׁבְעָה צַדִּיקֵי הָאֱמֶת, כְּשֶׁרָצוּ לְהִתְקָרֵב לַשְּׁכִינָה בְּסוֹד שֶׁל שֶׁבַע, כֻּלָּם פָּגְשׁוּ בַּבְּאֵר הַזּוֹ שֶׁלֹּא פוֹסְקִים מֵימֶיהָ לְעוֹלָמִים.</p>\n<p>אַבְרָהָם כָּרָה אֶת הַבְּאֵר הַזֹּאת מִשּׁוּם שֶׁהוּא לִמֵּד אֶת כָּל בְּנֵי הָעוֹלָם לַעֲבֹד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכֵיוָן שֶׁכָּרָה אוֹתָהּ, הוֹצִיא מַיִם נוֹבְעִים שֶׁלֹּא פוֹסְקִים לְעוֹלָמִים.</p>\n<p>וְכֵיוָן שֶׁמֵּת אַבְרָהָם מַה כָּתוּב? (בראשית כו) וְכָל הַבְּאֵרֹת אֲשֶׁר חָפְרוּ עַבְדֵי אָבִיו בִּימֵי אַבְרָהָם. כָּתוּב בְּאֵרֹת, וְרַק אַחַת הָיְתָה, שֶׁכָּתוּב בְּאֵר שָׁבַע, וְקוֹרְאִים בְּאֵרוֹת, מַשְׁמָע שֶׁרַבִּים הָיוּ, מִשּׁוּם שֶׁהַבְּאֵר הַזֹּאת נִרְאֵית לָאָבוֹת בְּכָל מָקוֹם שֶׁהָיוּ הוֹלְכִים, הָיְתָה נִרְאֵית לָהֶם גְּדוֹלִים וְכַבִּירִים.</p>\n<p>כֵּיוָן שֶׁמִּלְאוּהָ הַפְּלִשְׁתִּים עָפָר, סוֹד שֶׁחָזְרוּ בְּנֵי הָעוֹלָם לָעֲבוֹדָה זָרָה, וְהָעוֹלָם הָיָה שָׁמֵם, שֶׁאֵין מִי שֶׁיּוֹדֵעַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא. כֵּיוָן שֶׁבָּא יִצְחָק מַה כָּתוּב? (שם) וַיָּשָׁב יִצְחָק וַיַּחְפֹּר אֶת בְּאֵרֹת הַמַּיִם אֲשֶׁר חָפְרוּ בִּימֵי אַבְרָהָם אָבִיו. מַה זֶּה וַיָּשָׁב? אֶלָּא שֶׁהֵשִׁיב אֶת הָעוֹלָם לְתִקּוּנוֹ וְלִמֵּד אֶת בְּנֵי הָעוֹלָם שֶׁיֵּדְעוּ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, זֶהוּ שֶׁכָּתוּב (שם כה) וַיְהִי אַחֲרֵי מוֹת אַבְרָהָם וַיְבָרֶךְ אֱלֹהִים אֶת יִצְחָק בְּנוֹ. בְּאֵר זוֹ מִמִּי הָיְתָה? מִמִּי שֶׁכָּל חַיֵּי הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים תְּלוּיִים בּוֹ וְרוֹאֶה הַכֹּל, זֶהוּ שֶׁכָּתוּב (דניאל ב) יוֹדֵעַ מַה שֶּׁבַּחֹשֶׁךְ וְאוֹר שָׁרוּי עִמּוֹ.</p>\n<p>וּבֹא וּרְאֵה, אוֹתָם עַבְדֵי יִצְחָק, מִשּׁוּם שֶׁהֵם מִצַּד הַדִּין הַקָּשֶׁה, כְּשֶׁחָפְרוּ אוֹתָהּ מַה כָּתוּב? שִׁטְנָה, וַהֲרֵי פֵּרְשׁוּהָ, עַד שֶׁהוּא בָּא וַיַּחְפֹּר בְּאֵר אַחֶרֶת וַיִּקְרָא שְׁמָהּ רְחוֹבוֹת וַדַּאי. אֲבָל עַבְדֵי אָבִיו, מִשּׁוּם שֶׁכֻּלָּם בָּאִים מִצַּד הַיָּמִין, וְלֹא הָיְתָה שִׂטְנָה בָּעוֹלָם, וְלֹא יָצָא דִין מֵהַבְּאֵר הַזֹּאת לְהַסְטִין עֲלֵיהֶם כְּשֶׁמַּעֲשֵׂיהֶם לֹא הָיוּ כְשֵׁרִים.</p>\n<p>וּמֵהַבְּאֵר הַזֹּאת הוּא הַפֶּתַח לָדַעַת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, זֶהוּ שֶׁכָּתוּב (תהלים קיח) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק אָבֹא בָם אוֹדֶה יָהּ. וְעַד שֶׁלֹּא הִסְתַּלֵּק מֵהָעוֹלָם, בֵּרַךְ אֶת יַעֲקֹב וּשְׁלָחוֹ לְחָרָן לְהִזְדַּוֵּג. וּכְשֶׁהָלַךְ לְחָרָן מַה כָּתוּב? (בראשית כט) וַיַּרְא וְהִנֵּה בְאֵר בַּשָּׂדֶה. כֵּיוָן שֶׁרָאָה יַעֲקֹב אֶת כְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא מִתּוֹךְ אוֹתָהּ בְּאֵר שֶׁנִּקְרֵאת בְּאֵר שֶׁבַע, אָז אָמַר לְלָבָן, (שם) אֶעֱבָדְךְ שֶׁבַע שָׁנִים בְּרָחֵל בִּתְּךְ הַקְּטַנָּה, דַּוְקָא הַקְּטַנָּה.</p>\n<p>בֹּא וּרְאֵה, כְּנֶגֶד אוֹתָם שִׁבְעָה צַדִּיקִים צִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא בַּתּוֹרָה לְהַקְרִיב קָרְבַּן מוּסָף שֶׁבַע פְּעָמִים בַּשָּׁנָה, כְּדֵי לְהוֹסִיף לָהֶם תַּפְנוּקִים וְעִדּוּנִים מִבֵּית הַמֶּלֶךְ. הָאָבוֹת יִשְׂבְּעוּ בַּתְּחִלָּה, וְאַחַר כָּךְ הַבָּנִים, וְהֵם שֶׁבַע פְּעָמִים וְלֹא יוֹתֵר.</p>\n<p>בְּשַׁבָּת כְּנֶגֶד צַדִּיק יְסוֹד עוֹלָם שֶׁנִּקְרָא כֹּ\"ל, וְנִקְרָא מוּסָף שַׁבָּת, לְהוֹסִיף לוֹ עִדּוּנִים מֵהַמֹּחַ הַנִּסְתָּר. וּבְרֹאשׁ חֹדֶשׁ כְּנֶגֶד כְּנֶסֶת יִשְׂרָאֵל שֶׁנִּקְרֵאת לְבָנָה.</p>\n<p>וּמְחֲמִשָּׁה עָשָׂר יוֹם לְחֹדֶשׁ רִאשׁוֹן כְּנֶגֶד אַבְרָהָם אֲבִיהֶם שֶׁאָחוּז בְּמִדַּת הַחֶסֶד וְנִקְרָא רִאשׁוֹן. וּבַחֹדֶשׁ הַשְּׁלִישִׁי בַּעֲצֶרֶת שֶׁנִּתְּנָה בּוֹ תּוֹרָה בְּשִׁבְעָה קוֹלוֹת, כְּנֶגֶד יַעֲקֹב שֶׁהוּא שְׁלִישִׁי לָאָבוֹת וְאָחוּז בְּקוֹל, קוֹל יַעֲקֹב.</p>\n<p>וּבְרֹאשׁ הַשָּׁנָה כְּנֶגֶד יִצְחָק שֶׁנּוֹלַד בּוֹ, וְאָנוּ מַזְכִּירִים בּוֹ עֲקֵדַת יִצְחָק, וְהוּא יוֹם הַדִּין כְּנֶגֶד מִדַּת הַדִּין הָאֲחוּזָה בּוֹ. בְּיוֹם הַכִּפּוּרִים כְּנֶגֶד מֹשֶׁה, שֶׁבּוֹ קִבֵּל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת תְּפִלָּתוֹ וְחָס עַל יִשְׂרָאֵל וְהֶחֱזִיר לוֹ אֶת הַתּוֹרָה. בְּחַג הַסֻּכּוֹת כְּנֶגֶד אַהֲרֹן, שֶׁבִּזְכוּתוֹ הָלְכוּ אוֹתָם שִׁבְעָה עֲנָנִים שֶׁכִּסּוּ עַל יִשְׂרָאֵל כְּמוֹ סֻכָּה, וּמִשּׁוּם זֶה עוֹשִׂים סֻכָּה, וּבְכָל הַתּוֹרָה יֵשׁ כַּמָּה סוֹדוֹת עֶלְיוֹנִים נִסְתָּרִים בָּהּ. וּכְשֶׁשִּׁבְעַת אֵלֶּה מִתּוֹסְפִים בַּבְּרָכוֹת, כָּל הָעוֹלָם בִּשְׁלֵמוּת רַבָּה. ע\"כ מההשמטות.</p>"],[9522012741,"<p>וְהֵנִיף אַהֲרֹן אֶת הַלְוִיִּם תְּנוּפָה לִפְנֵי ה'. רַבִּי יְהוּדָה שָׁאַל אֶת רַבִּי אַבָּא, לָמָּה הָיָה הַכֹּהֵן מֵנִיף אֶת הַלְוִיִּם? אָמַר לוֹ, מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְתִינוֹק כְּשֶׁהוּא בּוֹכֶה וְכוֹעֵס, מָה עוֹשִׂין כְּדֵי לְפַיְּסוֹ? אָמַר לוֹ רַבִּי יְהוּדָה, מְנִיפִין אוֹתוֹ וּמְנַעְנְעִים אוֹתוֹ כְּדֵי לְשַׁתְּקוֹ. אָמַר לוֹ רַבִּי אַבָּא, יְהוּדָה יְהוּדָה, מִלָּה זֹּאת בָּאָה לְיָדְךְ וְלֹא חָקַרְתָּ בָּהּ?! וַהֲלֹא יִשְׁמְעוּ אָזְנֶיךְ מַה שֶּׁפִּיךְ מְדַבֵּר!</p>\n<p>כָּךְ הִיא מִדַּת הַגְּבוּרָה, כּוֹעֶסֶת וְרוֹגֶזֶת, שֶׁכָּתוּב (בראשית מט) שִׁמְעוֹן וְלֵוִי אַחִים כְּלֵי חָמָס מְכֵרֹתֵיהֶם, וְכָתוּב אָרוּר אַפָּם כִּי עָז וְעֶבְרָתָם כִּי קָשָׁתָה, לְפִי שֶׁהֵם מִתְגַּבְּרִים וּמִתְקַשִּׁים בְּאַפָּם וְעֶבְרָתָם לָצֵאת לַעֲשׂוֹת דִּין לְכַלּוֹת וּלְהַכְרִית בְּנֵי הָעוֹלָם, אֲזַי הַכֹּהֵן, שֶׁהוּא הַחֶסֶד הָעֶלְיוֹן, מֵנִיף אוֹתוֹ הַצַּד שֶׁל הַלְוִיִּם, שֶׁהוּא מִדַּת הַגְּבוּרָה, כְּדֵי לְשַׁכֵּךְ וּלְשַׁקֵּט רָגְזָהּ וְכַעֲסָהּ, כְּדֵי שֶׁיִּשְׁתַּבְּרוּ הַשְּׂעָרוֹת מִכָּל שׁוּלֵיהֶן וְלֹא יִתְגַּבְּרוּ וְלֹא יִתְחַזְּקוּ, כְּעֵין דֻּגְמָא זוֹ הַכֹּהֵן שֶׁמֵּנִיף אֶת הַלְוִיִּם תְּנוּפָה כְּדֵי שֶׁיִּשְׁקֹט הַצַּד שֶׁל הַגְּבוּרָה שֶׁלָּהֶן, כְּדֵי שֶׁלֹּא יִתְעוֹרֵר הַדִּין בָּעוֹלָם.</p>\n<p>בָּא רַבִּי יְהוּדָה וְנָשַׁק אֶת יָדָיו. וּכְשֶׁיִּתְעוֹרְרוּ הַדִּינִין בָּעוֹלָם, כָּל הַדִּינִים הַנִּמְצָאִים בְּכָל יוֹם וָיוֹם, אַבְרָהָם אָבִינוּ עָלָיו הַשָּׁלוֹם הוּא דּוֹחֶה אוֹתָם לַחוּץ וְאֵינָם עוֹמְדִים לְפָנָיו, זֶהוּ שֶׁכָּתוּב וְאֵל זֹּעֵם בְּכָל יוֹם: ע\"כ מההשמטות.</p>"]]});
